{
  "name": "Ballistic Trajectory Master",
  "description": "A visual ballistics calculator for projectile games. Features real-time trajectory simulation, auto-calculation of force based on target coordinates, and wind adjustment."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Point {
  x: number;
  y: number;
}

export enum GameMode {
  AUTO_AIM = 'AUTO_AIM', // "Free/Calculation Mode": Auto calculates power for target
  MANUAL = 'MANUAL'      // "Manual Mode": User controls power
}

export interface SimulationResult {
  power: number | null;
  trajectory: Point[];
  impactPoint: Point | null;
  error: string | null;
}

export const PHYSICS_CONSTANTS = {
  G: 157.96290,
  K: 1.12800,
  // Derived constants
  G_K: 157.96290 / 1.12800,
  // Screen scales (Physics units)
  MAX_X: 12,
  MAX_Y: 7.2,
};

import { Point, PHYSICS_CONSTANTS } from '../types';

const { G, K, G_K } = PHYSICS_CONSTANTS;

/**
 * Root finding algorithm (Bisection method) to replace scipy.optimize.brentq
 * Finds x where f(x) = 0 within [min, max]
 */
function brentq(f: (val: number) => number, min: number, max: number, tol = 1e-5, maxIter = 100): number | null {
  let a = min;
  let b = max;
  let fa = f(a);
  let fb = f(b);

  if (fa * fb > 0) {
    // Root is not bracketed. 
    // In the context of this physics engine, it usually means unreachable.
    return null;
  }

  for (let i = 0; i < maxIter; i++) {
    const c = (a + b) / 2;
    const fc = f(c);

    if (Math.abs(fc) < tol || (b - a) / 2 < tol) {
      return c;
    }

    if (fa * fc < 0) {
      b = c;
      fb = fc;
    } else {
      a = c;
      fa = fc;
    }
  }

  return (a + b) / 2;
}

/**
 * Calculates the trajectory points for a given power, angle, and wind.
 * Returns an array of points (x, y) until the projectile hits the ground (y < 0) or goes out of bounds.
 */
export const calculateTrajectory = (
  start: Point,
  power: number,
  angle: number,
  wind: number,
  dt: number = 0.05
): Point[] => {
  const rad = (angle * Math.PI) / 180;
  const v_wind = wind / K;
  const vx_init = power * Math.cos(rad);
  const vy_init = power * Math.sin(rad);

  const points: Point[] = [];
  let t = 0;

  // Limit simulation to 20 seconds or reasonable bounds
  while (t < 20) {
    // x(t) = ((vx - v_wind)/K) * (1 - e^-Kt) + v_wind*t
    const term1_x = (vx_init - v_wind) / K;
    const term2 = 1 - Math.exp(-K * t);
    const term3_x = v_wind * t;
    const x = start.x + (term1_x * term2 + term3_x);

    // y(t) = ((vy + G_K)/K) * (1 - e^-Kt) - G_K*t
    const term1_y = (vy_init + G_K) / K;
    const term3_y = G_K * t;
    const y = start.y + (term1_y * term2 - term3_y);

    points.push({ x, y });

    if (y < -5 || x > 30 || x < -5) break; // Out of bounds check
    t += dt;
  }

  return points;
};

/**
 * Solves for the required power to hit a target (dist, height) given angle and wind.
 * Corresponds to the Python `get_power` function.
 */
export const solvePower = (
  dist: number,
  height: number,
  angle: number,
  wind: number
): number | null => {
  const rad = (angle * Math.PI) / 180;
  const v_wind = wind / K;

  // Internal error function: returns (simulated_height - target_height) for a given velocity v
  const height_error_at_v = (v: number): number => {
    const vx = v * Math.cos(rad);
    const vy = v * Math.sin(rad);

    // Step 1: Find time t where x(t) = dist
    const x_dist_func = (t: number): number => {
      const term1 = (vx - v_wind) / K;
      const term2 = 1 - Math.exp(-K * t);
      const term3 = v_wind * t;
      return term1 * term2 + term3 - dist;
    };

    // Try to find impact time between 0.01s and 20s
    const t_impact = brentq(x_dist_func, 0.01, 20.0);

    if (t_impact === null) {
      // Logic from python: if we can't reach the X distance, return a large negative 
      // to indicate we need more power (assuming monotonic relationship for simple cases)
      // However, brentq returning null means we didn't bracket zero.
      // If x(20) < dist, we definitely didn't reach it.
      // If x(0.01) > dist, we overshot instantly (unlikely).
      const x_at_max = x_dist_func(20.0);
      if (x_at_max < 0) return -99999; // Too weak
      return 99999; // Too strong or weird math error
    }

    // Step 2: Calculate height at that time
    const y_sim = ((vy + G_K) / K) * (1 - Math.exp(-K * t_impact)) - G_K * t_impact;

    return y_sim - height;
  };

  // Main solver: find v in [0.5, 200]
  // We check bounds first to avoid bisection errors if solution is outside
  try {
    const final_v = brentq(height_error_at_v, 0.5, 200); // 200 as max power
    return final_v;
  } catch (e) {
    return null;
  }
};

import React, { useRef, useMemo, useState, useEffect } from 'react';
import { Point, PHYSICS_CONSTANTS } from '../types';
import { Target, Crosshair } from 'lucide-react';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  screenSize: { width: number; height: number };
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint
}) => {
  const svgRef = useRef<SVGSVGElement>(null);

  // Physics World Bounds
  const VIEWBOX_WIDTH = PHYSICS_CONSTANTS.MAX_X * 100; // Scale 100x for clearer SVG coords
  const VIEWBOX_HEIGHT = PHYSICS_CONSTANTS.MAX_Y * 100;

  // Helper to convert Physics (x, y) to SVG (x, y)
  // Physics: Y is Up, X is Right. Origin (0,0).
  // SVG: Y is Down, X is Right. Origin Top-Left.
  const toSvg = (p: Point) => ({
    x: (p.x / PHYSICS_CONSTANTS.MAX_X) * VIEWBOX_WIDTH,
    y: VIEWBOX_HEIGHT - (p.y / PHYSICS_CONSTANTS.MAX_Y) * VIEWBOX_HEIGHT
  });

  const fromSvg = (svgX: number, svgY: number): Point => ({
    x: (svgX / VIEWBOX_WIDTH) * PHYSICS_CONSTANTS.MAX_X,
    y: ((VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT) * PHYSICS_CONSTANTS.MAX_Y
  });

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!svgRef.current) return;
    const rect = svgRef.current.getBoundingClientRect();

    // Calculate scale factor in case SVG is resized via CSS
    const scaleX = VIEWBOX_WIDTH / rect.width;
    const scaleY = VIEWBOX_HEIGHT / rect.height;

    const clickX = (e.clientX - rect.left) * scaleX;
    const clickY = (e.clientY - rect.top) * scaleY;

    const physicsPoint = fromSvg(clickX, clickY);

    // Clamp to bounds
    const clampedX = Math.max(0, Math.min(physicsPoint.x, PHYSICS_CONSTANTS.MAX_X));
    const clampedY = Math.max(0, Math.min(physicsPoint.y, PHYSICS_CONSTANTS.MAX_Y));

    onSetTarget({ x: clampedX, y: clampedY });
  };

  // Convert trajectory to SVG Path
  const trajectoryPath = useMemo(() => {
    if (trajectory.length === 0) return '';
    const start = toSvg(trajectory[0]);
    let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;

    for (let i = 1; i < trajectory.length; i++) {
      const p = toSvg(trajectory[i]);
      path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
    }
    return path;
  }, [trajectory]);

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  // Grid lines
  const gridLines = useMemo(() => {
    const lines = [];
    // Vertical lines for every unit of distance
    for (let i = 1; i < PHYSICS_CONSTANTS.MAX_X; i++) {
        const x = (i / PHYSICS_CONSTANTS.MAX_X) * VIEWBOX_WIDTH;
        lines.push(<line key={`v-${i}`} x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} stroke="#1e293b" strokeWidth="2" />);
    }
    // Horizontal lines
    for (let i = 1; i < PHYSICS_CONSTANTS.MAX_Y; i++) {
        const y = VIEWBOX_HEIGHT - (i / PHYSICS_CONSTANTS.MAX_Y) * VIEWBOX_HEIGHT;
        lines.push(<line key={`h-${i}`} x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} stroke="#1e293b" strokeWidth="2" />);
    }
    return lines;
  }, [VIEWBOX_WIDTH, VIEWBOX_HEIGHT]);

  return (
    <div className="relative w-full h-full bg-slate-900 rounded-xl overflow-hidden shadow-2xl border border-slate-700 select-none cursor-crosshair">
      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Tactical View</h2>
        <div className="text-[10px] text-slate-600">DIST: {PHYSICS_CONSTANTS.MAX_X} | HEIGHT: {PHYSICS_CONSTANTS.MAX_Y}</div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className="w-full h-full block"
        onPointerDown={handlePointerDown}
        preserveAspectRatio="none" // Stretch to fill container
      >
        {/* Grid */}
        {gridLines}

        {/* Ground */}
        <line x1="0" y1={VIEWBOX_HEIGHT} x2={VIEWBOX_WIDTH} y2={VIEWBOX_HEIGHT} stroke="#334155" strokeWidth="10" />

        {/* Trajectory */}
        <path 
            d={trajectoryPath} 
            fill="none" 
            stroke="#38bdf8" 
            strokeWidth="4" 
            strokeDasharray="10,10"
            className="opacity-80"
        />

        {/* Tank / Player */}
        <circle cx={tankSvg.x} cy={tankSvg.y} r="15" fill="#e2e8f0" stroke="#475569" strokeWidth="4" />
        <text x={tankSvg.x} y={tankSvg.y - 25} textAnchor="middle" fill="white" fontSize="24" fontWeight="bold">YOU</text>

        {/* Target Marker */}
        <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
          <circle r="20" fill="rgba(239, 68, 68, 0.2)" stroke="#ef4444" strokeWidth="2" className="animate-pulse" />
          <line x1="-25" y1="0" x2="25" y2="0" stroke="#ef4444" strokeWidth="2" />
          <line x1="0" y1="-25" x2="0" y2="25" stroke="#ef4444" strokeWidth="2" />
          <text x="0" y="-35" textAnchor="middle" fill="#ef4444" fontSize="20" fontWeight="bold">TARGET</text>
        </g>

        {/* Impact Point (if available) */}
        {impactSvg && (
             <circle cx={impactSvg.x} cy={impactSvg.y} r="8" fill="#fbbf24" />
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

import React from 'react';
import { GameMode, Point } from '../types';
import { Wind, Crosshair, Zap, RotateCcw, MousePointer2 } from 'lucide-react';

interface ControlsProps {
  angle: number;
  setAngle: (v: number) => void;
  wind: number;
  setWind: (v: number) => void;
  power: number;
  setPower: (v: number) => void;
  mode: GameMode;
  setMode: (m: GameMode) => void;
  target: Point;
  tankPos: Point;
  calculationResult: number | null;
  error: string | null;
}

const Controls: React.FC<ControlsProps> = ({
  angle,
  setAngle,
  wind,
  setWind,
  power,
  setPower,
  mode,
  setMode,
  target,
  tankPos,
  calculationResult,
  error
}) => {
  const dist = Math.abs(target.x - tankPos.x).toFixed(2);
  const heightDiff = (target.y - tankPos.y).toFixed(2);

  const handleModeToggle = (newMode: GameMode) => {
    setMode(newMode);
    if (newMode === GameMode.AUTO_AIM && calculationResult) {
      setPower(calculationResult);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 border-l border-slate-700 p-6 shadow-xl w-full max-w-sm overflow-y-auto">
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-white mb-1 flex items-center gap-2">
          <Crosshair className="text-sky-400" />
          Ballistic Master
        </h1>
        <p className="text-slate-400 text-sm">Trajectory Calculation System</p>
      </div>

      {/* Mode Switcher */}
      <div className="grid grid-cols-2 gap-2 p-1 bg-slate-800 rounded-lg mb-8">
        <button
          onClick={() => handleModeToggle(GameMode.AUTO_AIM)}
          className={`flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium transition-all ${
            mode === GameMode.AUTO_AIM
              ? 'bg-sky-600 text-white shadow-lg'
              : 'text-slate-400 hover:text-white hover:bg-slate-700'
          }`}
        >
          <Zap size={16} />
          Auto-Aim
        </button>
        <button
          onClick={() => handleModeToggle(GameMode.MANUAL)}
          className={`flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium transition-all ${
            mode === GameMode.MANUAL
              ? 'bg-orange-600 text-white shadow-lg'
              : 'text-slate-400 hover:text-white hover:bg-slate-700'
          }`}
        >
          <MousePointer2 size={16} />
          Manual
        </button>
      </div>

      <div className="space-y-8 flex-1">
        {/* Target Info */}
        <div className="bg-slate-800/50 p-4 rounded-lg border border-slate-700">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">Target Data</h3>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <div className="text-slate-400 text-xs mb-1">Distance</div>
              <div className="text-xl font-mono text-white">{dist}</div>
            </div>
            <div>
              <div className="text-slate-400 text-xs mb-1">Height Diff</div>
              <div className="text-xl font-mono text-white">{heightDiff}</div>
            </div>
          </div>
        </div>

        {/* Inputs */}
        <div className="space-y-6">
          {/* Angle */}
          <div>
            <div className="flex justify-between items-end mb-2">
              <label className="text-sm font-medium text-sky-200">Angle</label>
              <span className="text-2xl font-bold font-mono text-white">{angle}°</span>
            </div>
            <input
              type="range"
              min="0"
              max="180"
              step="1"
              value={angle}
              onChange={(e) => setAngle(Number(e.target.value))}
              className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-sky-500"
            />
            <div className="flex justify-between text-xs text-slate-500 mt-1">
              <span>0°</span>
              <span>90°</span>
              <span>180°</span>
            </div>
          </div>

          {/* Wind */}
          <div>
            <div className="flex justify-between items-end mb-2">
              <label className="text-sm font-medium text-emerald-200 flex items-center gap-1">
                <Wind size={14} /> Wind
              </label>
              <span className="text-2xl font-bold font-mono text-white">{wind}</span>
            </div>
             <div className="relative pt-1">
                <input
                type="range"
                min="-50"
                max="50"
                step="0.1"
                value={wind}
                onChange={(e) => setWind(Number(e.target.value))}
                className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                />
                <div className="absolute top-0 left-1/2 w-0.5 h-4 bg-slate-500 -translate-x-1/2 -translate-y-1"></div>
             </div>
            <div className="flex justify-between text-xs text-slate-500 mt-1">
              <span>Against (-50)</span>
              <span>No Wind</span>
              <span>With (+50)</span>
            </div>
          </div>

          {/* Power */}
          <div className={`transition-opacity duration-300 ${mode === GameMode.AUTO_AIM ? 'opacity-80 pointer-events-none grayscale' : 'opacity-100'}`}>
            <div className="flex justify-between items-end mb-2">
              <label className="text-sm font-medium text-orange-200">Power</label>
              <span className="text-2xl font-bold font-mono text-white">{power.toFixed(1)}</span>
            </div>
             <div className="relative">
                <input
                type="range"
                min="0"
                max="100"
                step="0.1"
                value={power}
                onChange={(e) => {
                    setPower(Number(e.target.value));
                    setMode(GameMode.MANUAL); // Switch to manual if user touches slider
                }}
                className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-orange-500"
                />
                 {mode === GameMode.AUTO_AIM && (
                    <div className="absolute inset-0 bg-slate-900/10 z-10 flex items-center justify-center">
                        <span className="text-xs bg-slate-800 text-sky-400 px-2 py-0.5 rounded border border-sky-900">Auto-Calculated</span>
                    </div>
                 )}
             </div>
          </div>
        </div>
      </div>

      {/* Status Footer */}
      <div className="mt-8 pt-6 border-t border-slate-800">
        {error ? (
           <div className="bg-red-900/20 border border-red-900/50 p-3 rounded text-red-400 text-sm flex items-center gap-2">
             <span className="font-bold">ERROR:</span> {error}
           </div>
        ) : (
            <div className="flex items-center justify-between text-sm">
                 <span className="text-slate-500">System Status</span>
                 <span className="text-emerald-400 font-mono flex items-center gap-1.5">
                    <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                    READY
                 </span>
            </div>
        )}
      </div>
    </div>
  );
};

export default Controls;

import React, { useState, useEffect, useMemo } from 'react';
import GameCanvas from './components/GameCanvas';
import Controls from './components/Controls';
import { GameMode, Point, SimulationResult, PHYSICS_CONSTANTS } from './types';
import { solvePower, calculateTrajectory } from './services/physicsEngine';

// Tank position in Physics Units (x, y)
// Placing it slightly inset so we can see the start of the arc
const TANK_POS: Point = { x: 1, y: 2 }; 
const INITIAL_TARGET: Point = { x: 9, y: 2 };

function App() {
  const [mode, setMode] = useState<GameMode>(GameMode.AUTO_AIM);

  // Inputs
  const [angle, setAngle] = useState(65);
  const [wind, setWind] = useState(0);
  const [manualPower, setManualPower] = useState(50);
  const [target, setTarget] = useState<Point>(INITIAL_TARGET);

  // Derived State
  const [calculatedPower, setCalculatedPower] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Screen Size (Used for Aspect Ratio calculation mainly)
  const [screenSize, setScreenSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    const handleResize = () => {
      setScreenSize({ width: window.innerWidth, height: window.innerHeight });
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // 1. Logic Loop: Handle Physics Calculation
  useEffect(() => {
    // Relative distance components
    const dist = target.x - TANK_POS.x;
    const height = target.y - TANK_POS.y;

    if (dist <= 0) {
        setError("Target must be to the right of the player");
        setCalculatedPower(null);
        return;
    }

    // Try to solve for power
    const neededPower = solvePower(dist, height, angle, wind);

    if (neededPower === null) {
       setError("Target unreachable with current angle/wind");
       setCalculatedPower(null);
    } else if (neededPower === -99999) {
        setError("Force insufficient (Out of range or strong headwind)");
        setCalculatedPower(null);
    } else {
        setError(null);
        setCalculatedPower(neededPower);

        // If in Auto-Aim, sync manual power for smoother transition
        if (mode === GameMode.AUTO_AIM) {
            // Check bounds
            if (neededPower > 100) {
               setError("Required power exceeds limit (100)");
               // Still set it so we can see the attempt? 
               // No, better to clamp for visual, but warn user
               setManualPower(100); 
            } else {
               setManualPower(neededPower);
            }
        }
    }
  }, [target, angle, wind, mode]);

  // 2. Logic Loop: Generate Trajectory Points
  // We always visualize based on `manualPower` (which is auto-updated in Auto mode)
  // This allows the user to switch to manual and immediately see the last auto-path
  const trajectory = useMemo(() => {
    return calculateTrajectory(TANK_POS, manualPower, angle, wind);
  }, [manualPower, angle, wind]);

  // Find where it hits ground or target height
  const impactPoint = useMemo(() => {
      if (trajectory.length === 0) return null;
      return trajectory[trajectory.length - 1];
  }, [trajectory]);

  return (
    <div className="flex h-screen w-screen bg-slate-950 overflow-hidden">
        {/* Main Canvas Area */}
        <div className="flex-1 h-full p-4 flex flex-col items-center justify-center relative">
            <div className="w-full h-full max-w-6xl max-h-[80vh] aspect-[12/7.2]">
                <GameCanvas 
                    trajectory={trajectory}
                    target={target}
                    tankPos={TANK_POS}
                    onSetTarget={setTarget}
                    impactPoint={impactPoint}
                    screenSize={screenSize}
                />
            </div>
             <div className="mt-4 text-slate-500 text-sm">
                Click map to move target • Drag sliders to adjust physics
            </div>
        </div>

        {/* Sidebar Controls */}
        <Controls 
            angle={angle}
            setAngle={setAngle}
            wind={wind}
            setWind={setWind}
            power={manualPower}
            setPower={setManualPower}
            mode={mode}
            setMode={setMode}
            target={target}
            tankPos={TANK_POS}
            calculationResult={calculatedPower}
            error={error}
        />
    </div>
  );
}

export default App;

export interface Point {
  x: number;
  y: number;
}

export type ThemeMode = 'day' | 'night';

export enum GameMode {
  AUTO_AIM = 'AUTO_AIM', // "Free/Calculation Mode": Auto calculates power for target
  MANUAL = 'MANUAL'      // "Manual Mode": User controls power
}

export interface SimulationResult {
  power: number | null;
  trajectory: Point[];
  impactPoint: Point | null;
  error: string | null;
}

export const PHYSICS_CONSTANTS = {
  G: 157.96290,
  K: 1.12800,
  // Derived constants
  G_K: 157.96290 / 1.12800,
  // Screen scales (Physics units)
  MAX_X: 12,
  MAX_Y: 7.2,
};

import React, { useState, useEffect, useMemo } from 'react';
import GameCanvas from './components/GameCanvas';
import Controls from './components/Controls';
import { GameMode, Point, PHYSICS_CONSTANTS, ThemeMode } from './types';
import { solvePower, calculateTrajectory } from './services/physicsEngine';

// Tank position in Physics Units (x, y)
const TANK_POS: Point = { x: 1, y: 2 }; 
const INITIAL_TARGET: Point = { x: 9, y: 2 };

function App() {
  const [mode, setMode] = useState<GameMode>(GameMode.AUTO_AIM);
  const [isNight, setIsNight] = useState(true);
  const [zoom, setZoom] = useState(1.0); // 1.0 = Normal (12 width), 2.0 = Wide (24 width)

  // Inputs
  const [angle, setAngle] = useState(65);
  const [wind, setWind] = useState(0);
  const [manualPower, setManualPower] = useState(50);
  const [target, setTarget] = useState<Point>(INITIAL_TARGET);

  // Derived State
  const [calculatedPower, setCalculatedPower] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Screen Size (Used for Aspect Ratio calculation mainly)
  const [screenSize, setScreenSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    const handleResize = () => {
      setScreenSize({ width: window.innerWidth, height: window.innerHeight });
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // 1. Logic Loop: Handle Physics Calculation
  useEffect(() => {
    // Relative distance components
    const dist = target.x - TANK_POS.x;
    const height = target.y - TANK_POS.y;

    if (dist <= 0) {
        setError("Target must be to the right of the player");
        setCalculatedPower(null);
        return;
    }

    // Try to solve for power
    const neededPower = solvePower(dist, height, angle, wind);

    if (neededPower === null) {
       setError("Target unreachable with current angle/wind");
       setCalculatedPower(null);
    } else if (neededPower === -99999) {
        setError("Force insufficient (Out of range or strong headwind)");
        setCalculatedPower(null);
    } else {
        setError(null);
        setCalculatedPower(neededPower);

        // If in Auto-Aim, sync manual power for smoother transition
        if (mode === GameMode.AUTO_AIM) {
            // Check bounds
            if (neededPower > 100) {
               setError("Required power exceeds limit (100)");
               setManualPower(100); 
            } else {
               setManualPower(neededPower);
            }
        }
    }
  }, [target, angle, wind, mode]);

  // 2. Logic Loop: Generate Trajectory Points
  const trajectory = useMemo(() => {
    return calculateTrajectory(TANK_POS, manualPower, angle, wind);
  }, [manualPower, angle, wind]);

  // Find where it hits ground or target height
  const impactPoint = useMemo(() => {
      if (trajectory.length === 0) return null;
      return trajectory[trajectory.length - 1];
  }, [trajectory]);

  return (
    <div className={`flex h-screen w-screen overflow-hidden transition-colors duration-500 ${isNight ? 'bg-slate-950' : 'bg-slate-100'}`}>
        {/* Main Canvas Area */}
        <div className="flex-1 h-full p-4 flex flex-col items-center justify-center relative">
            <div className="w-full h-full max-w-7xl max-h-[85vh] relative flex items-center justify-center">
                {/* Maintain aspect ratio of the physics world, adapted by zoom */}
                <div 
                  className="w-full h-full shadow-2xl rounded-xl overflow-hidden"
                  // We let the SVG handle aspect ratio internally via viewBox, 
                  // but we want the container to be responsive.
                >
                    <GameCanvas 
                        trajectory={trajectory}
                        target={target}
                        tankPos={TANK_POS}
                        onSetTarget={setTarget}
                        impactPoint={impactPoint}
                        angle={angle}
                        setAngle={setAngle}
                        zoom={zoom}
                        isNight={isNight}
                    />
                </div>
            </div>
             <div className={`mt-4 text-sm ${isNight ? 'text-slate-500' : 'text-slate-400'}`}>
                Click map to move target • Drag angle pointer to aim • Zoom to see more
            </div>
        </div>

        {/* Sidebar Controls */}
        <Controls 
            angle={angle}
            setAngle={setAngle}
            wind={wind}
            setWind={setWind}
            power={manualPower}
            setPower={setManualPower}
            mode={mode}
            setMode={setMode}
            target={target}
            tankPos={TANK_POS}
            calculationResult={calculatedPower}
            error={error}
            isNight={isNight}
            setIsNight={setIsNight}
            zoom={zoom}
            setZoom={setZoom}
        />
    </div>
  );
}

