import React, { useState, useEffect, useMemo } from 'react';
import GameCanvas from './components/GameCanvas';
import Controls from './components/Controls';
import { GameMode, Point, PHYSICS_CONSTANTS, ThemeMode } from './types';
import { solvePower, calculateTrajectory } from './services/physicsEngine';

// Tank position in Physics Units (x, y)
const TANK_POS: Point = { x: 1, y: 2 }; 
const INITIAL_TARGET: Point = { x: 9, y: 2 };

function App() {
  const [mode, setMode] = useState<GameMode>(GameMode.AUTO_AIM);
  const [isNight, setIsNight] = useState(true);
  const [zoom, setZoom] = useState(1.0); // 1.0 = Normal (12 width), 2.0 = Wide (24 width)

  // Inputs
  const [angle, setAngle] = useState(65);
  const [wind, setWind] = useState(0);
  const [manualPower, setManualPower] = useState(50);
  const [target, setTarget] = useState<Point>(INITIAL_TARGET);

  // Derived State
  const [calculatedPower, setCalculatedPower] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Screen Size (Used for Aspect Ratio calculation mainly)
  const [screenSize, setScreenSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    const handleResize = () => {
      setScreenSize({ width: window.innerWidth, height: window.innerHeight });
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // 1. Logic Loop: Handle Physics Calculation
  useEffect(() => {
    // Relative distance components
    const dist = target.x - TANK_POS.x;
    const height = target.y - TANK_POS.y;

    if (dist <= 0) {
        setError("Target must be to the right of the player");
        setCalculatedPower(null);
        return;
    }

    // Try to solve for power
    const neededPower = solvePower(dist, height, angle, wind);

    if (neededPower === null) {
       setError("Target unreachable with current angle/wind");
       setCalculatedPower(null);
    } else if (neededPower === -99999) {
        setError("Force insufficient (Out of range or strong headwind)");
        setCalculatedPower(null);
    } else {
        setError(null);
        setCalculatedPower(neededPower);

        // If in Auto-Aim, sync manual power for smoother transition
        if (mode === GameMode.AUTO_AIM) {
            // Check bounds
            if (neededPower > 100) {
               setError("Required power exceeds limit (100)");
               setManualPower(100); 
            } else {
               setManualPower(neededPower);
            }
        }
    }
  }, [target, angle, wind, mode]);

  // 2. Logic Loop: Generate Trajectory Points
  const trajectory = useMemo(() => {
    return calculateTrajectory(TANK_POS, manualPower, angle, wind);
  }, [manualPower, angle, wind]);

  // Find where it hits ground or target height
  const impactPoint = useMemo(() => {
      if (trajectory.length === 0) return null;
      return trajectory[trajectory.length - 1];
  }, [trajectory]);

  return (
    <div className={`flex h-screen w-screen overflow-hidden transition-colors duration-500 ${isNight ? 'bg-slate-950' : 'bg-slate-100'}`}>
        {/* Main Canvas Area */}
        <div className="flex-1 h-full p-4 flex flex-col items-center justify-center relative">
            <div className="w-full h-full max-w-7xl max-h-[85vh] relative flex items-center justify-center">
                {/* Maintain aspect ratio of the physics world, adapted by zoom */}
                <div 
                  className="w-full h-full shadow-2xl rounded-xl overflow-hidden"
                  // We let the SVG handle aspect ratio internally via viewBox, 
                  // but we want the container to be responsive.
                >
                    <GameCanvas 
                        trajectory={trajectory}
                        target={target}
                        tankPos={TANK_POS}
                        onSetTarget={setTarget}
                        impactPoint={impactPoint}
                        angle={angle}
                        setAngle={setAngle}
                        zoom={zoom}
                        isNight={isNight}
                        wind={wind}
                        setWind={setWind}
                    />
                </div>
            </div>
             <div className={`mt-4 text-sm ${isNight ? 'text-slate-500' : 'text-slate-400'}`}>
                Click map to move target • Drag angle pointer to aim • Zoom to see more
            </div>
        </div>

        {/* Sidebar Controls */}
        <Controls 
            angle={angle}
            setAngle={setAngle}
            wind={wind}
            setWind={setWind}
            power={manualPower}
            setPower={setManualPower}
            mode={mode}
            setMode={setMode}
            target={target}
            tankPos={TANK_POS}
            calculationResult={calculatedPower}
            error={error}
            isNight={isNight}
            setIsNight={setIsNight}
            zoom={zoom}
            setZoom={setZoom}
        />
    </div>
  );
}

export default App;

import React, { useRef, useMemo, useState } from 'react';
import { Point, PHYSICS_CONSTANTS } from '../types';
import { Wind } from 'lucide-react';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  isNight,
  wind,
  setWind
}) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const [isDraggingKnob, setIsDraggingKnob] = useState(false);

  // Physics World Bounds (Dynamic based on zoom)
  const MAX_X = PHYSICS_CONSTANTS.MAX_X * zoom;
  const MAX_Y = PHYSICS_CONSTANTS.MAX_Y * zoom;

  // SVG Coordinate System (Fixed resolution for rendering quality)
  const VIEWBOX_WIDTH = MAX_X * 100; 
  const VIEWBOX_HEIGHT = MAX_Y * 100;

  // Helper to convert Physics (x, y) to SVG (x, y)
  // Physics: Y is Up, X is Right. Origin (0,0) (Bottom-Left visually)
  const toSvg = (p: Point) => ({
    x: (p.x / MAX_X) * VIEWBOX_WIDTH,
    y: VIEWBOX_HEIGHT - (p.y / MAX_Y) * VIEWBOX_HEIGHT
  });

  const fromSvg = (svgX: number, svgY: number): Point => ({
    x: (svgX / VIEWBOX_WIDTH) * MAX_X,
    y: ((VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT) * MAX_Y
  });

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!svgRef.current) return;

    const rect = svgRef.current.getBoundingClientRect();
    const scaleX = VIEWBOX_WIDTH / rect.width;
    const scaleY = VIEWBOX_HEIGHT / rect.height;
    const clickX = (e.clientX - rect.left) * scaleX;
    const clickY = (e.clientY - rect.top) * scaleY;

    // Check if clicked near the angle knob handle
    const tankSvg = toSvg(tankPos);
    // Calculate Knob Position
    const knobRadius = 80; // Fixed radius in SVG units
    const rad = (angle * Math.PI) / 180;
    const knobX = tankSvg.x + knobRadius * Math.cos(rad); // cos for x
    const knobY = tankSvg.y - knobRadius * Math.sin(rad); // -sin for y (svg inverted)

    const distToKnob = Math.hypot(clickX - knobX, clickY - knobY);

    if (distToKnob < 40) { // Hit radius for knob
        setIsDraggingKnob(true);
        (e.target as Element).setPointerCapture(e.pointerId);
        return;
    }

    // Otherwise, set target
    const physicsPoint = fromSvg(clickX, clickY);
    const clampedX = Math.max(0, Math.min(physicsPoint.x, MAX_X));
    const clampedY = Math.max(0, Math.min(physicsPoint.y, MAX_Y));
    onSetTarget({ x: clampedX, y: clampedY });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!svgRef.current) return;

    if (isDraggingKnob) {
        const rect = svgRef.current.getBoundingClientRect();
        const scaleX = VIEWBOX_WIDTH / rect.width;
        const scaleY = VIEWBOX_HEIGHT / rect.height;
        const pointerX = (e.clientX - rect.left) * scaleX;
        const pointerY = (e.clientY - rect.top) * scaleY;

        const tankSvg = toSvg(tankPos);
        const dx = pointerX - tankSvg.x;
        const dy = pointerY - tankSvg.y; // Positive dy is DOWN in SVG

        // Atan2(y, x). SVG Y is down, so Up is negative Y.
        // We want 0 degrees to be right, 90 degrees to be up.
        // Math.atan2(y, x) -> 0 is right, positive angles are clockwise (down).
        // So we want -dy.
        let newAngle = Math.atan2(-dy, dx) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;

        // Clamp to 0-180 for this game
        if (newAngle > 180) newAngle = 180;

        setAngle(Math.round(newAngle));
    } else if (e.buttons === 1) {
        // Dragging to move target
        const rect = svgRef.current.getBoundingClientRect();
        const scaleX = VIEWBOX_WIDTH / rect.width;
        const scaleY = VIEWBOX_HEIGHT / rect.height;
        const pointerX = (e.clientX - rect.left) * scaleX;
        const pointerY = (e.clientY - rect.top) * scaleY;
        const physicsPoint = fromSvg(pointerX, pointerY);

        const clampedX = Math.max(0, Math.min(physicsPoint.x, MAX_X));
        const clampedY = Math.max(0, Math.min(physicsPoint.y, MAX_Y));
        onSetTarget({ x: clampedX, y: clampedY });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setIsDraggingKnob(false);
    (e.target as Element).releasePointerCapture(e.pointerId);
  };

  // Convert trajectory to SVG Path
  const trajectoryPath = useMemo(() => {
    if (trajectory.length === 0) return '';
    const start = toSvg(trajectory[0]);
    let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;

    for (let i = 1; i < trajectory.length; i++) {
      const p = toSvg(trajectory[i]);
      path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
    }
    return path;
  }, [trajectory, zoom]); 

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  // Grid lines based on 1.0 unit
  const gridLines = useMemo(() => {
    const lines = [];
    const maxXInt = Math.ceil(MAX_X);
    const maxYInt = Math.ceil(MAX_Y);

    const strokeColor = isNight ? "#1e293b" : "#e2e8f0";

    for (let i = 1; i < maxXInt; i++) {
        const x = (i / MAX_X) * VIEWBOX_WIDTH;
        lines.push(<line key={`v-${i}`} x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} stroke={strokeColor} strokeWidth="2" />);
        // Add text labels every 5 units
        if (i % 5 === 0) {
             lines.push(<text key={`tv-${i}`} x={x + 5} y={VIEWBOX_HEIGHT - 10} fill={strokeColor} fontSize="20">{i}</text>);
        }
    }
    for (let i = 1; i < maxYInt; i++) {
        const y = VIEWBOX_HEIGHT - (i / MAX_Y) * VIEWBOX_HEIGHT;
        lines.push(<line key={`h-${i}`} x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} stroke={strokeColor} strokeWidth="2" />);
    }
    return lines;
  }, [VIEWBOX_WIDTH, VIEWBOX_HEIGHT, MAX_X, MAX_Y, isNight]);

  // Angle Knob Visualization
  const knobRadius = 80; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // 12x7.2 Reference Box Calculations
  const refBoxTopLeft = toSvg({ x: 0, y: 7.2 });
  const refBoxBottomRight = toSvg({ x: 12, y: 0 });
  const refBoxWidth = refBoxBottomRight.x - refBoxTopLeft.x;
  const refBoxHeight = refBoxBottomRight.y - refBoxTopLeft.y;

  return (
    <div className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none cursor-crosshair`}>
      {/* Top Center Wind Control Widget */}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-slate-800/80 backdrop-blur p-3 rounded-xl border border-slate-600 shadow-xl flex flex-col items-center w-64 z-20">
        <div className="text-xs font-bold text-slate-300 mb-1 w-full flex justify-between items-center">
            <span className="text-[10px] text-slate-500">WEST</span>
            <span className={`flex items-center gap-1 ${wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                <Wind size={12} />
                WIND: {Math.abs(wind).toFixed(1)}
            </span>
            <span className="text-[10px] text-slate-500">EAST</span>
        </div>
        <div className="relative w-full h-6 flex items-center">
             {/* Center Marker Line */}
            <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>

            <input 
                type="range" 
                min="-150" 
                max="150" 
                step="0.5"
                value={wind}
                onChange={(e) => setWind(Number(e.target.value))}
                className="w-full h-2 bg-slate-700/50 rounded-lg appearance-none cursor-pointer accent-sky-400 z-10 relative"
            />
        </div>
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Tactical View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            RANGE: {MAX_X.toFixed(1)}m x {MAX_Y.toFixed(1)}m
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className="w-full h-full block touch-none"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        preserveAspectRatio="xMidYMid meet"
      >
        {/* Grid */}
        {gridLines}

        {/* Ground */}
        <line x1="0" y1={VIEWBOX_HEIGHT} x2={VIEWBOX_WIDTH} y2={VIEWBOX_HEIGHT} stroke={isNight ? "#334155" : "#94a3b8"} strokeWidth="10" />

        {/* Reference Frame Box (12x7.2) */}
        <rect 
            x={refBoxTopLeft.x} 
            y={refBoxTopLeft.y} 
            width={refBoxWidth} 
            height={refBoxHeight} 
            fill="none" 
            stroke="black" 
            strokeWidth="4"
        />
        {/* Secondary dash for visibility on black bg */}
        <rect 
            x={refBoxTopLeft.x} 
            y={refBoxTopLeft.y} 
            width={refBoxWidth} 
            height={refBoxHeight} 
            fill="none" 
            stroke="white" 
            strokeWidth="2"
            strokeDasharray="10,10"
            opacity="0.5"
        />

        {/* Trajectory */}
        <path 
            d={trajectoryPath} 
            fill="none" 
            stroke={isNight ? "#38bdf8" : "#0284c7"} 
            strokeWidth="4" 
            strokeDasharray="10,10"
            className="opacity-80"
        />

        {/* ANGLE DIAL UI */}
        <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> {/* Pointer events handled by parent, but visual is here */}
            {/* Dashed arc for reference */}
            <path 
                d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`}
                fill="none"
                stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"}
                strokeWidth="2"
                strokeDasharray="4,4"
            />
            {/* The line representing the barrel/angle */}
            <line 
                x1={tankSvg.x} 
                y1={tankSvg.y} 
                x2={knobHandleX} 
                y2={knobHandleY} 
                stroke={isNight ? "#38bdf8" : "#0284c7"} 
                strokeWidth="4" 
            />
            {/* The Knob Handle */}
            <circle 
                cx={knobHandleX} 
                cy={knobHandleY} 
                r={isDraggingKnob ? 12 : 8}
                fill={isNight ? "#38bdf8" : "#0284c7"}
                stroke="white"
                strokeWidth="2"
                className="transition-all duration-100 ease-in-out hover:r-12"
            />
            {/* Angle Text label near knob */}
            <text 
                x={knobHandleX + 15} 
                y={knobHandleY - 15} 
                fill={isNight ? "#38bdf8" : "#0284c7"} 
                fontSize="16" 
                fontWeight="bold"
            >
                {angle}°
            </text>
        </g>

        {/* Tank / Player */}
        <circle cx={tankSvg.x} cy={tankSvg.y} r="15" fill={isNight ? "#e2e8f0" : "#475569"} stroke={isNight ? "#475569" : "#1e293b"} strokeWidth="4" />
        <text x={tankSvg.x} y={tankSvg.y + 40} textAnchor="middle" fill={isNight ? "white" : "#1e293b"} fontSize="20" fontWeight="bold">YOU</text>

        {/* Target Marker */}
        <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
          <circle r="20" fill="rgba(239, 68, 68, 0.2)" stroke="#ef4444" strokeWidth="2" className="animate-pulse" />
          <line x1="-25" y1="0" x2="25" y2="0" stroke="#ef4444" strokeWidth="2" />
          <line x1="0" y1="-25" x2="0" y2="25" stroke="#ef4444" strokeWidth="2" />
          <text x="0" y="-35" textAnchor="middle" fill="#ef4444" fontSize="20" fontWeight="bold">TARGET</text>
        </g>

        {/* Impact Point (if available) */}
        {impactSvg && (
             <circle cx={impactSvg.x} cy={impactSvg.y} r="8" fill="#fbbf24" stroke="white" strokeWidth="1" />
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useMemo, useState } from 'react';
import { Point, PHYSICS_CONSTANTS } from '../types';
import { Wind } from 'lucide-react';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  isNight,
  wind,
  setWind
}) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const [isDraggingKnob, setIsDraggingKnob] = useState(false);

  // Physics World Bounds (Dynamic based on zoom)
  const MAX_X = PHYSICS_CONSTANTS.MAX_X * zoom;
  const MAX_Y = PHYSICS_CONSTANTS.MAX_Y * zoom;

  // SVG Coordinate System (Fixed resolution for rendering quality)
  const VIEWBOX_WIDTH = MAX_X * 100; 
  const VIEWBOX_HEIGHT = MAX_Y * 100;

  // Helper to convert Physics (x, y) to SVG (x, y)
  // Physics: Y is Up, X is Right. Origin (0,0) (Bottom-Left visually)
  const toSvg = (p: Point) => ({
    x: (p.x / MAX_X) * VIEWBOX_WIDTH,
    y: VIEWBOX_HEIGHT - (p.y / MAX_Y) * VIEWBOX_HEIGHT
  });

  const fromSvg = (svgX: number, svgY: number): Point => ({
    x: (svgX / VIEWBOX_WIDTH) * MAX_X,
    y: ((VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT) * MAX_Y
  });

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!svgRef.current) return;

    const rect = svgRef.current.getBoundingClientRect();
    const scaleX = VIEWBOX_WIDTH / rect.width;
    const scaleY = VIEWBOX_HEIGHT / rect.height;
    const clickX = (e.clientX - rect.left) * scaleX;
    const clickY = (e.clientY - rect.top) * scaleY;

    // Check if clicked near the angle knob handle
    const tankSvg = toSvg(tankPos);
    // Calculate Knob Position
    const knobRadius = 80; // Fixed radius in SVG units
    const rad = (angle * Math.PI) / 180;
    const knobX = tankSvg.x + knobRadius * Math.cos(rad); // cos for x
    const knobY = tankSvg.y - knobRadius * Math.sin(rad); // -sin for y (svg inverted)

    const distToKnob = Math.hypot(clickX - knobX, clickY - knobY);

    if (distToKnob < 40) { // Hit radius for knob
        setIsDraggingKnob(true);
        (e.target as Element).setPointerCapture(e.pointerId);
        return;
    }

    // Otherwise, set target
    const physicsPoint = fromSvg(clickX, clickY);
    const clampedX = Math.max(0, Math.min(physicsPoint.x, MAX_X));
    const clampedY = Math.max(0, Math.min(physicsPoint.y, MAX_Y));
    onSetTarget({ x: clampedX, y: clampedY });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!svgRef.current) return;

    if (isDraggingKnob) {
        const rect = svgRef.current.getBoundingClientRect();
        const scaleX = VIEWBOX_WIDTH / rect.width;
        const scaleY = VIEWBOX_HEIGHT / rect.height;
        const pointerX = (e.clientX - rect.left) * scaleX;
        const pointerY = (e.clientY - rect.top) * scaleY;

        const tankSvg = toSvg(tankPos);
        const dx = pointerX - tankSvg.x;
        const dy = pointerY - tankSvg.y; // Positive dy is DOWN in SVG

        // Atan2(y, x). SVG Y is down, so Up is negative Y.
        // We want 0 degrees to be right, 90 degrees to be up.
        // Math.atan2(y, x) -> 0 is right, positive angles are clockwise (down).
        // So we want -dy.
        let newAngle = Math.atan2(-dy, dx) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;

        // Clamp to 0-180 for this game
        if (newAngle > 180) newAngle = 180;

        setAngle(Math.round(newAngle));
    } else if (e.buttons === 1) {
        // Dragging to move target
        const rect = svgRef.current.getBoundingClientRect();
        const scaleX = VIEWBOX_WIDTH / rect.width;
        const scaleY = VIEWBOX_HEIGHT / rect.height;
        const pointerX = (e.clientX - rect.left) * scaleX;
        const pointerY = (e.clientY - rect.top) * scaleY;
        const physicsPoint = fromSvg(pointerX, pointerY);

        const clampedX = Math.max(0, Math.min(physicsPoint.x, MAX_X));
        const clampedY = Math.max(0, Math.min(physicsPoint.y, MAX_Y));
        onSetTarget({ x: clampedX, y: clampedY });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setIsDraggingKnob(false);
    (e.target as Element).releasePointerCapture(e.pointerId);
  };

  // Convert trajectory to SVG Path
  const trajectoryPath = useMemo(() => {
    if (trajectory.length === 0) return '';
    const start = toSvg(trajectory[0]);
    let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;

    for (let i = 1; i < trajectory.length; i++) {
      const p = toSvg(trajectory[i]);
      path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
    }
    return path;
  }, [trajectory, zoom]); 

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  // Distances for Label
  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = Math.abs(target.y - tankPos.y).toFixed(2);

  // Grid lines based on 1.0 unit
  const gridLines = useMemo(() => {
    const lines = [];
    const maxXInt = Math.ceil(MAX_X);
    const maxYInt = Math.ceil(MAX_Y);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#475569" : "#cbd5e1";

    // Vertical Lines (X axis)
    for (let i = 1; i < maxXInt; i++) {
        const x = (i / MAX_X) * VIEWBOX_WIDTH;
        const isMajor = i % 12 === 0;

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isMajor ? highlightColor : baseColor} 
                strokeWidth={isMajor ? "4" : "2"} 
            />
        );
        // Add text labels
        if (isMajor || i % 5 === 0) {
             lines.push(
                <text 
                    key={`tv-${i}`} 
                    x={x + 5} 
                    y={VIEWBOX_HEIGHT - 10} 
                    fill={isMajor ? highlightColor : baseColor} 
                    fontSize={isMajor ? "24" : "20"}
                    fontWeight={isMajor ? "bold" : "normal"}
                >
                    {i}
                </text>
            );
        }
    }

    // Horizontal Lines (Y axis)
    for (let i = 1; i < maxYInt; i++) {
        const y = VIEWBOX_HEIGHT - (i / MAX_Y) * VIEWBOX_HEIGHT;
        const isMajor = i % 6 === 0;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isMajor ? highlightColor : baseColor} 
                strokeWidth={isMajor ? "4" : "2"} 
            />
        );

        if (isMajor) {
             lines.push(
                <text 
                    key={`th-${i}`} 
                    x={10} 
                    y={y - 5} 
                    fill={highlightColor} 
                    fontSize="24"
                    fontWeight="bold"
                >
                    {i}
                </text>
            );
        }
    }
    return lines;
  }, [VIEWBOX_WIDTH, VIEWBOX_HEIGHT, MAX_X, MAX_Y, isNight]);

  // Angle Knob Visualization
  const knobRadius = 80; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // 12x6 Reference Box Calculations (Adjusted from 7.2 to 6)
  const refBoxTopLeft = toSvg({ x: 0, y: 6 });
  const refBoxBottomRight = toSvg({ x: 12, y: 0 });
  const refBoxWidth = refBoxBottomRight.x - refBoxTopLeft.x;
  const refBoxHeight = refBoxBottomRight.y - refBoxTopLeft.y;

  return (
    <div className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none cursor-crosshair`}>
      {/* Top Center Wind Control Widget */}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-slate-800/80 backdrop-blur p-3 rounded-xl border border-slate-600 shadow-xl flex flex-col items-center w-64 z-20">
        <div className="text-xs font-bold text-slate-300 mb-1 w-full flex justify-between items-center">
            <span className="text-[10px] text-slate-500">WEST</span>
            <span className={`flex items-center gap-1 ${wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                <Wind size={12} />
                WIND: {Math.abs(wind).toFixed(1)}
            </span>
            <span className="text-[10px] text-slate-500">EAST</span>
        </div>
        <div className="relative w-full h-6 flex items-center">
             {/* Center Marker Line */}
            <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>

            <input 
                type="range" 
                min="-150" 
                max="150" 
                step="0.5"
                value={wind}
                onChange={(e) => setWind(Number(e.target.value))}
                className="w-full h-2 bg-slate-700/50 rounded-lg appearance-none cursor-pointer accent-sky-400 z-10 relative"
            />
        </div>
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Tactical View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            RANGE: {MAX_X.toFixed(1)}m x {MAX_Y.toFixed(1)}m
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className="w-full h-full block touch-none"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        preserveAspectRatio="xMidYMid meet"
      >
        {/* Grid */}
        {gridLines}

        {/* Ground */}
        <line x1="0" y1={VIEWBOX_HEIGHT} x2={VIEWBOX_WIDTH} y2={VIEWBOX_HEIGHT} stroke={isNight ? "#334155" : "#94a3b8"} strokeWidth="10" />

        {/* Reference Frame Box (12x6) */}
        <rect 
            x={refBoxTopLeft.x} 
            y={refBoxTopLeft.y} 
            width={refBoxWidth} 
            height={refBoxHeight} 
            fill="none" 
            stroke="black" 
            strokeWidth="4"
        />
        {/* Secondary dash for visibility on black bg */}
        <rect 
            x={refBoxTopLeft.x} 
            y={refBoxTopLeft.y} 
            width={refBoxWidth} 
            height={refBoxHeight} 
            fill="none" 
            stroke="white" 
            strokeWidth="2"
            strokeDasharray="10,10"
            opacity="0.5"
        />

        {/* Trajectory */}
        <path 
            d={trajectoryPath} 
            fill="none" 
            stroke={isNight ? "#38bdf8" : "#0284c7"} 
            strokeWidth="4" 
            strokeDasharray="10,10"
            className="opacity-80"
        />

        {/* ANGLE DIAL UI */}
        <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
            {/* Dashed arc for reference */}
            <path 
                d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`}
                fill="none"
                stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"}
                strokeWidth="2"
                strokeDasharray="4,4"
            />
            {/* The line representing the barrel/angle */}
            <line 
                x1={tankSvg.x} 
                y1={tankSvg.y} 
                x2={knobHandleX} 
                y2={knobHandleY} 
                stroke={isNight ? "#38bdf8" : "#0284c7"} 
                strokeWidth="4" 
            />
            {/* The Knob Handle */}
            <circle 
                cx={knobHandleX} 
                cy={knobHandleY} 
                r={isDraggingKnob ? 12 : 8}
                fill={isNight ? "#38bdf8" : "#0284c7"}
                stroke="white"
                strokeWidth="2"
                className="transition-all duration-100 ease-in-out hover:r-12"
            />
            {/* Angle Text label near knob */}
            <text 
                x={knobHandleX + 15} 
                y={knobHandleY - 15} 
                fill={isNight ? "#38bdf8" : "#0284c7"} 
                fontSize="16" 
                fontWeight="bold"
            >
                {angle}°
            </text>
        </g>

        {/* Tank / Player */}
        <circle cx={tankSvg.x} cy={tankSvg.y} r="15" fill={isNight ? "#e2e8f0" : "#475569"} stroke={isNight ? "#475569" : "#1e293b"} strokeWidth="4" />
        <text x={tankSvg.x} y={tankSvg.y + 40} textAnchor="middle" fill={isNight ? "white" : "#1e293b"} fontSize="20" fontWeight="bold">YOU</text>

        {/* Target Marker */}
        <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
          <circle r="20" fill="rgba(239, 68, 68, 0.2)" stroke="#ef4444" strokeWidth="2" className="animate-pulse" />
          <line x1="-25" y1="0" x2="25" y2="0" stroke="#ef4444" strokeWidth="2" />
          <line x1="0" y1="-25" x2="0" y2="25" stroke="#ef4444" strokeWidth="2" />
          <text x="0" y="-35" textAnchor="middle" fill="#ef4444" fontSize="20" fontWeight="bold">TARGET</text>

          {/* Distance Info Label */}
          <rect x="-60" y="-85" width="120" height="40" rx="4" fill={isNight ? "rgba(15, 23, 42, 0.8)" : "rgba(255, 255, 255, 0.8)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
          <text x="0" y="-68" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="12" fontWeight="bold">
            Dist: {dx}
          </text>
          <text x="0" y="-53" textAnchor="middle" fill={isNight ? "#94a3b8" : "#475569"} fontSize="10">
            H: {dy}
          </text>
        </g>

        {/* Impact Point (if available) */}
        {impactSvg && (
             <circle cx={impactSvg.x} cy={impactSvg.y} r="8" fill="#fbbf24" stroke="white" strokeWidth="1" />
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

export interface Point {
  x: number;
  y: number;
}

export type ThemeMode = 'day' | 'night';

export enum GameMode {
  AUTO_AIM = 'AUTO_AIM', // "Free/Calculation Mode": Auto calculates power for target
  MANUAL = 'MANUAL'      // "Manual Mode": User controls power
}

export interface SimulationResult {
  power: number | null;
  trajectory: Point[];
  impactPoint: Point | null;
  error: string | null;
}

export interface SavedTrajectory {
  id: string;
  power: number;
  angle: number;
  wind: number;
  target: Point;
  visible: boolean;
  timestamp: number;
}

export const PHYSICS_CONSTANTS = {
  G: 157.96290,
  K: 1.12800,
  // Derived constants
  G_K: 157.96290 / 1.12800,
  // Screen scales (Physics units)
  MAX_X: 12,
  MAX_Y: 7.2,
};

import React, { useState, useEffect, useMemo } from 'react';
import GameCanvas from './components/GameCanvas';
import Controls from './components/Controls';
import { GameMode, Point, PHYSICS_CONSTANTS, ThemeMode, SavedTrajectory } from './types';
import { solvePower, calculateTrajectory } from './services/physicsEngine';

// Tank position in Physics Units (x, y)
const TANK_POS: Point = { x: 1, y: 2 }; 
const INITIAL_TARGET: Point = { x: 9, y: 2 };

function App() {
  const [mode, setMode] = useState<GameMode>(GameMode.AUTO_AIM);
  const [isNight, setIsNight] = useState(true);
  const [zoom, setZoom] = useState(1.0); // 1.0 = Normal (12 width), 2.0 = Wide (24 width)
  const [snapToGrid, setSnapToGrid] = useState(false);

  // Inputs
  const [angle, setAngle] = useState(65);
  const [wind, setWind] = useState(0);
  const [manualPower, setManualPower] = useState(50);
  const [target, setTarget] = useState<Point>(INITIAL_TARGET);

  // Memory / History
  const [savedTrajectories, setSavedTrajectories] = useState<SavedTrajectory[]>([]);

  // Derived State
  const [calculatedPower, setCalculatedPower] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Screen Size (Used for Aspect Ratio calculation mainly)
  const [screenSize, setScreenSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    const handleResize = () => {
      setScreenSize({ width: window.innerWidth, height: window.innerHeight });
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // 1. Logic Loop: Handle Physics Calculation
  useEffect(() => {
    // Relative distance components
    const dist = target.x - TANK_POS.x;
    const height = target.y - TANK_POS.y;

    if (dist <= 0) {
        setError("Target must be to the right of the player");
        setCalculatedPower(null);
        return;
    }

    // Try to solve for power
    const neededPower = solvePower(dist, height, angle, wind);

    if (neededPower === null) {
       setError("Target unreachable with current angle/wind");
       setCalculatedPower(null);
    } else if (neededPower === -99999) {
        setError("Force insufficient (Out of range or strong headwind)");
        setCalculatedPower(null);
    } else {
        setError(null);
        setCalculatedPower(neededPower);

        // If in Auto-Aim, sync manual power for smoother transition
        if (mode === GameMode.AUTO_AIM) {
            // Check bounds
            if (neededPower > 100) {
               setError("Required power exceeds limit (100)");
               setManualPower(100); 
            } else {
               setManualPower(neededPower);
            }
        }
    }
  }, [target, angle, wind, mode]);

  // 2. Logic Loop: Generate Trajectory Points
  const trajectory = useMemo(() => {
    return calculateTrajectory(TANK_POS, manualPower, angle, wind);
  }, [manualPower, angle, wind]);

  // Find where it hits ground or target height
  const impactPoint = useMemo(() => {
      if (trajectory.length === 0) return null;
      return trajectory[trajectory.length - 1];
  }, [trajectory]);

  // --- Memory Functions ---
  const saveCurrentTrajectory = () => {
      const newEntry: SavedTrajectory = {
          id: Date.now().toString(),
          power: manualPower,
          angle: angle,
          wind: wind,
          target: { ...target },
          visible: true,
          timestamp: Date.now()
      };
      setSavedTrajectories(prev => [newEntry, ...prev]);
  };

  const deleteTrajectory = (id: string) => {
      setSavedTrajectories(prev => prev.filter(t => t.id !== id));
  };

  const toggleTrajectoryVisibility = (id: string) => {
      setSavedTrajectories(prev => prev.map(t => 
        t.id === id ? { ...t, visible: !t.visible } : t
      ));
  };

  return (
    <div className={`flex h-screen w-screen overflow-hidden transition-colors duration-500 ${isNight ? 'bg-slate-950' : 'bg-slate-100'}`}>
        {/* Main Canvas Area */}
        <div className="flex-1 h-full p-4 flex flex-col items-center justify-center relative">
            <div className="w-full h-full max-w-7xl max-h-[85vh] relative flex items-center justify-center">
                {/* Maintain aspect ratio of the physics world, adapted by zoom */}
                <div 
                  className="w-full h-full shadow-2xl rounded-xl overflow-hidden"
                  // We let the SVG handle aspect ratio internally via viewBox, 
                  // but we want the container to be responsive.
                >
                    <GameCanvas 
                        trajectory={trajectory}
                        target={target}
                        tankPos={TANK_POS}
                        onSetTarget={setTarget}
                        impactPoint={impactPoint}
                        angle={angle}
                        setAngle={setAngle}
                        zoom={zoom}
                        isNight={isNight}
                        wind={wind}
                        setWind={setWind}
                        snapToGrid={snapToGrid}
                        savedTrajectories={savedTrajectories}
                    />
                </div>
            </div>
             <div className={`mt-4 text-sm ${isNight ? 'text-slate-500' : 'text-slate-400'}`}>
                Click map to move target • Drag angle pointer to aim • Zoom to see more
            </div>
        </div>

        {/* Sidebar Controls */}
        <Controls 
            angle={angle}
            setAngle={setAngle}
            wind={wind}
            setWind={setWind}
            power={manualPower}
            setPower={setManualPower}
            mode={mode}
            setMode={setMode}
            target={target}
            tankPos={TANK_POS}
            calculationResult={calculatedPower}
            error={error}
            isNight={isNight}
            setIsNight={setIsNight}
            zoom={zoom}
            setZoom={setZoom}
            snapToGrid={snapToGrid}
            setSnapToGrid={setSnapToGrid}
            onSaveTrajectory={saveCurrentTrajectory}
            savedTrajectories={savedTrajectories}
            onDeleteTrajectory={deleteTrajectory}
            onToggleVisibility={toggleTrajectoryVisibility}
        />
    </div>
  );
}

export default App;

