                strokeWidth="4" 
            />
            {/* The Knob Handle */}
            <circle 
                cx={knobHandleX} 
                cy={knobHandleY} 
                r={isDraggingKnob ? 12 : 8}
                fill={isNight ? "#38bdf8" : "#0284c7"}
                stroke="white"
                strokeWidth="2"
                className="transition-all duration-100 ease-in-out hover:r-12"
            />
            {/* Angle Text label near knob */}
            <text 
                x={knobHandleX + 15} 
                y={knobHandleY - 15} 
                fill={isNight ? "#38bdf8" : "#0284c7"} 
                fontSize="16" 
                fontWeight="bold"
