interface ControlsProps {
  angle: number;
  setAngle: (v: number) => void;
  wind: number;
  setWind: (v: number) => void;
  power: number;
  setPower: (v: number) => void;
  mode: GameMode;
  setMode: (m: GameMode) => void;
  target: Point;
  tankPos: Point;
  calculationResult: number | null;
  error: string | null;
  isNight: boolean;
  setIsNight: (v: boolean) => void;
  zoom: number;
  setZoom: (v: number) => void;
  snapToGrid: boolean;
  setSnapToGrid: (v: boolean) => void;
  // Memory props
  onSaveTrajectory: () => void;
  savedTrajectories: SavedTrajectory[];
  onDeleteTrajectory: (id: string) => void;
  onToggleVisibility: (id: string) => void;
}

const Controls: React.FC<ControlsProps> = ({
  angle,
  setAngle,
  wind,
  setWind,
  power,
  setPower,
  mode,
  setMode,
  target,
  tankPos,
  calculationResult,
  error,
  isNight,
  setIsNight,
  zoom,
  setZoom,
  snapToGrid,
  setSnapToGrid,
  onSaveTrajectory,
  savedTrajectories,
  onDeleteTrajectory,
  onToggleVisibility
}) => {
  const dist = Math.abs(target.x - tankPos.x).toFixed(2);
  const heightDiff = (target.y - tankPos.y).toFixed(2);

  const handleModeToggle = (newMode: GameMode) => {
    setMode(newMode);
    if (newMode === GameMode.AUTO_AIM && calculationResult) {
      setPower(calculationResult);
    }
  };

  const adjustAngle = (delta: number) => {
    setAngle(Math.min(180, Math.max(0, angle + delta)));
  };

  const adjustWind = (delta: number) => {
    setWind(Number((Math.min(150, Math.max(-150, wind + delta))).toFixed(1)));
  };

  const adjustPower = (delta: number) => {
     setMode(GameMode.MANUAL);
     setPower(Number((Math.min(100, Math.max(0, power + delta))).toFixed(1)));
  };

  const themeClasses = isNight 
    ? {
      bg: 'bg-slate-900',
      border: 'border-slate-700',
      text: 'text-white',
      subText: 'text-slate-400',
      inputBg: 'bg-slate-700',
      btnBg: 'bg-slate-800 hover:bg-slate-700',
      panelBg: 'bg-slate-800'
    } 
    : {
      bg: 'bg-white',
      border: 'border-slate-200',
      text: 'text-slate-900',
      subText: 'text-slate-500',
      inputBg: 'bg-slate-200',
      btnBg: 'bg-slate-100 hover:bg-slate-200',
      panelBg: 'bg-slate-50'
    };

  return (
    <div className={`flex flex-col h-full ${themeClasses.bg} border-l ${themeClasses.border} shadow-xl w-full max-w-sm overflow-hidden transition-colors duration-500`}>
      {/* Scrollable Content */}
      <div className="flex-1 overflow-y-auto p-6 space-y-8">
        <div className="flex justify-between items-start">
            <div>
                <h1 className={`text-2xl font-bold ${themeClasses.text} mb-1 flex items-center gap-2`}>
                <Crosshair className="text-sky-500" />
                Ballistic Master
                </h1>
                <p className={`${themeClasses.subText} text-sm`}>Trajectory Calculation System</p>
            </div>
            <button 
                onClick={() => setIsNight(!isNight)}
                className={`p-2 rounded-full ${isNight ? 'bg-slate-800 text-yellow-400 hover:bg-slate-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'} transition-colors`}
            >
                {isNight ? <Moon size={20} /> : <Sun size={20} />}
            </button>
        </div>

        {/* Mode Switcher */}
        <div className={`grid grid-cols-2 gap-2 p-1 ${isNight ? 'bg-slate-800' : 'bg-slate-200'} rounded-lg`}>
            <button
            onClick={() => handleModeToggle(GameMode.AUTO_AIM)}
            className={`flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium transition-all ${
                mode === GameMode.AUTO_AIM
                ? 'bg-sky-600 text-white shadow-lg'
                : `${themeClasses.subText} hover:${themeClasses.text} hover:bg-white/10`
            }`}
            >
            <Zap size={16} />
            Auto-Aim
            </button>
            <button
            onClick={() => handleModeToggle(GameMode.MANUAL)}
            className={`flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium transition-all ${
                mode === GameMode.MANUAL
                ? 'bg-orange-600 text-white shadow-lg'
                : `${themeClasses.subText} hover:${themeClasses.text} hover:bg-white/10`
            }`}
            >
            <MousePointer2 size={16} />
            Manual
            </button>
        </div>

        {/* Target Info & Zoom */}
        <div className="space-y-4">
            <div className={`${isNight ? 'bg-slate-800/50 border-slate-700' : 'bg-slate-50 border-slate-200'} p-4 rounded-lg border`}>
                <div className="flex justify-between items-center mb-3">
                    <h3 className={`text-xs font-bold ${themeClasses.subText} uppercase tracking-wider`}>Target Data</h3>
                    <button
                        onClick={() => setSnapToGrid(!snapToGrid)}
                        className={`text-xs flex items-center gap-1 px-2 py-1 rounded border transition-colors ${
                            snapToGrid 
                            ? 'bg-indigo-600 border-indigo-500 text-white' 
                            : `${isNight ? 'bg-slate-900 border-slate-600' : 'bg-white border-slate-300'} ${themeClasses.subText}`
                        }`}
                        title="Snap to nearest integer coordinate"
                    >
                        <Magnet size={12} />
                        {snapToGrid ? 'Snap ON' : 'Snap OFF'}
                    </button>
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                    <div className={`${themeClasses.subText} text-xs mb-1`}>Distance</div>
                    <div className={`text-xl font-mono ${themeClasses.text}`}>{dist}</div>
                    </div>
                    <div>
                    <div className={`${themeClasses.subText} text-xs mb-1`}>Height Diff</div>
                    <div className={`text-xl font-mono ${themeClasses.text}`}>{heightDiff}</div>
                    </div>
                </div>
            </div>

            {/* Global Zoom */}
            <div>
                <div className="flex justify-between items-end mb-2">
                <label className={`text-sm font-medium ${isNight ? 'text-indigo-200' : 'text-indigo-600'} flex items-center gap-2`}>
                    <ZoomOut size={14} /> View Range <ZoomIn size={14} />
                </label>
                <span className={`text-sm font-bold font-mono ${themeClasses.text}`}>{(zoom * 100).toFixed(0)}%</span>
                </div>
                <input
                type="range"
                min="1"
                max="2.5"
                step="0.1"
                value={zoom}
                onChange={(e) => setZoom(Number(e.target.value))}
                className={`w-full h-2 ${themeClasses.inputBg} rounded-lg appearance-none cursor-pointer accent-indigo-500`}
                />
            </div>
        </div>

        {/* Inputs */}
        <div className="space-y-6">
            {/* Angle */}
            <div>
                <div className="flex justify-between items-end mb-2">
                    <label className={`text-sm font-medium ${isNight ? 'text-sky-200' : 'text-sky-600'}`}>Angle</label>
                    <span className={`text-2xl font-bold font-mono ${themeClasses.text}`}>{angle}°</span>
                </div>
                <div className="flex items-center gap-2">
                    <button onClick={() => adjustAngle(-1)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}>
                        <Minus size={16} />
                    </button>
                    <input
                        type="range"
                        min="0"
                        max="180"
                        step="1"
                        value={angle}
                        onChange={(e) => setAngle(Number(e.target.value))}
                        className={`flex-1 h-2 ${themeClasses.inputBg} rounded-lg appearance-none cursor-pointer accent-sky-500`}
                    />
                     <button onClick={() => adjustAngle(1)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}>
                        <Plus size={16} />
                    </button>
                </div>
            </div>

            {/* Wind */}
            <div>
                <div className="flex justify-between items-end mb-2">
                    <label className={`text-sm font-medium ${isNight ? 'text-emerald-200' : 'text-emerald-700'} flex items-center gap-1`}>
                        <Wind size={14} /> Wind
                    </label>
                    <span className={`text-2xl font-bold font-mono ${themeClasses.text}`}>{wind}</span>
                </div>
                <div className="flex items-center gap-2 mb-2">
                    <button onClick={() => adjustWind(-0.5)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}>
                        <Minus size={16} />
                    </button>
                    <div className="relative pt-1 flex-1">
                        <input
                            type="range"
                            min="-150"
                            max="150"
                            step="0.5"
                            value={wind}
                            onChange={(e) => setWind(Number(e.target.value))}
                            className={`w-full h-2 ${themeClasses.inputBg} rounded-lg appearance-none cursor-pointer accent-emerald-500`}
                        />
                        <div className="absolute top-0 left-1/2 w-0.5 h-4 bg-slate-400 -translate-x-1/2 -translate-y-1"></div>
                    </div>
                    <button onClick={() => adjustWind(0.5)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}>
                        <Plus size={16} />
                    </button>
                </div>
                <div className={`flex justify-between text-xs ${themeClasses.subText} mt-1`}>
                    <span>Against (-150)</span>
                    <span>0</span>
                    <span>With (+150)</span>
                </div>
            </div>

            {/* Power */}
            <div className={`transition-opacity duration-300 ${mode === GameMode.AUTO_AIM ? 'opacity-80 pointer-events-none grayscale' : 'opacity-100'}`}>
                <div className="flex justify-between items-end mb-2">
                    <label className={`text-sm font-medium ${isNight ? 'text-orange-200' : 'text-orange-600'}`}>Power</label>
                    <span className={`text-2xl font-bold font-mono ${themeClasses.text}`}>{power.toFixed(1)}</span>
                </div>
                <div className="relative flex items-center gap-2">
                     <button onClick={() => adjustPower(-1)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}>
                        <Minus size={16} />
                    </button>
                    <div className="flex-1 relative">
                        <input
                        type="range"
                        min="0"
                        max="100"
                        step="0.1"
                        value={power}
                        onChange={(e) => {
                            setPower(Number(e.target.value));
                            setMode(GameMode.MANUAL);
                        }}
                        className={`w-full h-2 ${themeClasses.inputBg} rounded-lg appearance-none cursor-pointer accent-orange-500`}
                        />
                         {mode === GameMode.AUTO_AIM && (
                            <div className="absolute inset-0 z-10 flex items-center justify-center">
                                <span className={`text-xs ${isNight ? 'bg-slate-800 border-sky-900' : 'bg-white border-sky-200'} text-sky-500 px-2 py-0.5 rounded border shadow-sm`}>Auto-Calculated</span>
                            </div>
                        )}
                    </div>
                     <button onClick={() => adjustPower(1)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}>
                        <Plus size={16} />
                    </button>
                </div>
            </div>
        </div>

        {/* Memory / Saved Trajectories */}
        <div>
            <div className="flex justify-between items-center mb-3">
                <h3 className={`text-xs font-bold ${themeClasses.subText} uppercase tracking-wider`}>Memory Bank</h3>
                <button 
                    onClick={onSaveTrajectory}
                    className="flex items-center gap-1 text-xs bg-purple-600 hover:bg-purple-500 text-white px-2 py-1 rounded transition-colors"
                >
                    <Save size={12} /> Save
                </button>
            </div>

            <div className={`max-h-48 overflow-y-auto space-y-2 pr-1 ${isNight ? 'scrollbar-track-slate-800 scrollbar-thumb-slate-600' : ''}`}>
                {savedTrajectories.length === 0 ? (
                    <div className={`text-xs ${themeClasses.subText} text-center py-4 italic`}>
                        No saved trajectories
                    </div>
                ) : (
                    savedTrajectories.map(t => (
                        <div key={t.id} className={`p-2 rounded text-xs flex items-center justify-between group ${isNight ? 'bg-slate-800 border-slate-700' : 'bg-slate-100 border-slate-200'} border`}>
                             <div className="flex flex-col gap-0.5">
                                 <div className="font-mono text-[10px] text-purple-400">
                                     P:{t.power.toFixed(1)} A:{t.angle}° W:{t.wind}
                                 </div>
                                 <div className={`${themeClasses.subText} text-[10px]`}>
                                     Target: ({t.target.x.toFixed(1)}, {t.target.y.toFixed(1)})
                                 </div>
                             </div>
                             <div className="flex items-center gap-1 opacity-60 group-hover:opacity-100 transition-opacity">
                                 <button onClick={() => onToggleVisibility(t.id)} className={`p-1 hover:bg-white/10 rounded ${t.visible ? 'text-sky-400' : 'text-slate-500'}`}>
                                     {t.visible ? <Eye size={14} /> : <EyeOff size={14} />}
                                 </button>
                                 <button onClick={() => onDeleteTrajectory(t.id)} className="p-1 hover:bg-white/10 rounded text-red-400 hover:text-red-500">
                                     <Trash2 size={14} />
                                 </button>
                             </div>
                        </div>
                    ))
                )}
            </div>
        </div>

      </div>

      {/* Status Footer */}
      <div className={`p-6 border-t ${themeClasses.border}`}>
        {error ? (
           <div className="bg-red-500/10 border border-red-500/30 p-3 rounded text-red-500 text-sm flex items-center gap-2">
             <span className="font-bold">ERROR:</span> {error}
           </div>
        ) : (
            <div className="flex items-center justify-between text-sm">
                 <span className={themeClasses.subText}>System Status</span>
                 <span className="text-emerald-500 font-mono flex items-center gap-1.5">
                    <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                    READY
                 </span>
            </div>
        )}
      </div>
    </div>
  );
};

export default Controls;

export interface Point {
  x: number;
  y: number;
}

export type ThemeMode = 'day' | 'night';

export enum GameMode {
  AUTO_AIM = 'AUTO_AIM', // "Free/Calculation Mode": Auto calculates power for target
  MANUAL = 'MANUAL'      // "Manual Mode": User controls power
}

export interface SimulationResult {
  power: number | null;
  trajectory: Point[];
  impactPoint: Point | null;
  error: string | null;
}

export interface SavedTrajectory {
  id: string;
  power: number;
  angle: number;
  wind: number;
  target: Point;
  visible: boolean;
  timestamp: number;
}

export const PHYSICS_CONSTANTS = {
  G: 157.96290,
  K: 1.12800,
  // Derived constants
  G_K: 157.96290 / 1.12800,
  // Screen scales (Physics units) - Expanded for analysis
  MAX_X: 24,
  MAX_Y: 24,
};

import { Point, PHYSICS_CONSTANTS } from '../types';

const { G, K, G_K } = PHYSICS_CONSTANTS;

/**
 * Root finding algorithm (Bisection method) to replace scipy.optimize.brentq
 * Finds x where f(x) = 0 within [min, max]
 */
function brentq(f: (val: number) => number, min: number, max: number, tol = 1e-5, maxIter = 100): number | null {
  let a = min;
  let b = max;
  let fa = f(a);
  let fb = f(b);

  if (fa * fb > 0) {
    // Root is not bracketed. 
    // In the context of this physics engine, it usually means unreachable.
    return null;
  }

  for (let i = 0; i < maxIter; i++) {
    const c = (a + b) / 2;
    const fc = f(c);

    if (Math.abs(fc) < tol || (b - a) / 2 < tol) {
      return c;
    }

    if (fa * fc < 0) {
      b = c;
      fb = fc;
    } else {
      a = c;
      fa = fc;
    }
  }

  return (a + b) / 2;
}

/**
 * Calculates the trajectory points for a given power, angle, and wind.
 * Returns an array of points (x, y) until the projectile hits the ground (y < 0) or goes out of bounds.
 */
export const calculateTrajectory = (
  start: Point,
  power: number,
  angle: number,
  wind: number,
  dt: number = 0.05
): Point[] => {
  const rad = (angle * Math.PI) / 180;
  const v_wind = wind / K;
  const vx_init = power * Math.cos(rad);
  const vy_init = power * Math.sin(rad);

  const points: Point[] = [];
  let t = 0;

  // Limit simulation to 20 seconds or reasonable bounds
  while (t < 20) {
    // x(t) = ((vx - v_wind)/K) * (1 - e^-Kt) + v_wind*t
    const term1_x = (vx_init - v_wind) / K;
    const term2 = 1 - Math.exp(-K * t);
    const term3_x = v_wind * t;
    const x = start.x + (term1_x * term2 + term3_x);

    // y(t) = ((vy + G_K)/K) * (1 - e^-Kt) - G_K*t
    const term1_y = (vy_init + G_K) / K;
    const term3_y = G_K * t;
    const y = start.y + (term1_y * term2 - term3_y);

    points.push({ x, y });

    // Expanded bounds for 24x24 analysis view
    if (y < -15 || x > 100 || x < -20) break; // Out of bounds check
    t += dt;
  }

  return points;
};

/**
 * Solves for the required power to hit a target (dist, height) given angle and wind.
 * Corresponds to the Python `get_power` function.
 */
export const solvePower = (
  dist: number,
  height: number,
  angle: number,
  wind: number
): number | null => {
  const rad = (angle * Math.PI) / 180;
  const v_wind = wind / K;

  // Internal error function: returns (simulated_height - target_height) for a given velocity v
  const height_error_at_v = (v: number): number => {
    const vx = v * Math.cos(rad);
    const vy = v * Math.sin(rad);

    // Step 1: Find time t where x(t) = dist
    const x_dist_func = (t: number): number => {
      const term1 = (vx - v_wind) / K;
      const term2 = 1 - Math.exp(-K * t);
      const term3 = v_wind * t;
      return term1 * term2 + term3 - dist;
    };

    // Try to find impact time between 0.01s and 20s
    const t_impact = brentq(x_dist_func, 0.01, 20.0);

    if (t_impact === null) {
      // Logic from python: if we can't reach the X distance, return a large negative 
      // to indicate we need more power (assuming monotonic relationship for simple cases)
      // However, brentq returning null means we didn't bracket zero.
      // If x(20) < dist, we definitely didn't reach it.
      // If x(0.01) > dist, we overshot instantly (unlikely).
      const x_at_max = x_dist_func(20.0);
      if (x_at_max < 0) return -99999; // Too weak
      return 99999; // Too strong or weird math error
    }

    // Step 2: Calculate height at that time
    const y_sim = ((vy + G_K) / K) * (1 - Math.exp(-K * t_impact)) - G_K * t_impact;

    return y_sim - height;
  };

  // Main solver: find v in [0.5, 200]
  // We check bounds first to avoid bisection errors if solution is outside
  try {
    const final_v = brentq(height_error_at_v, 0.5, 200); // 200 as max power
    return final_v;
  } catch (e) {
    return null;
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import GameCanvas from './components/GameCanvas';
import Controls from './components/Controls';
import { GameMode, Point, PHYSICS_CONSTANTS, ThemeMode, SavedTrajectory } from './types';
import { solvePower, calculateTrajectory } from './services/physicsEngine';

// Tank position in Physics Units (x, y) - moved to Origin for analysis
const TANK_POS: Point = { x: 0, y: 0 }; 
const INITIAL_TARGET: Point = { x: 12, y: 5 };

function App() {
  const [mode, setMode] = useState<GameMode>(GameMode.AUTO_AIM);
  const [isNight, setIsNight] = useState(true);
  const [zoom, setZoom] = useState(1.0); // 1.0 = Normal (24 width), larger = wider view
  const [snapToGrid, setSnapToGrid] = useState(false);

  // Inputs
  const [angle, setAngle] = useState(65);
  const [wind, setWind] = useState(0);
  const [manualPower, setManualPower] = useState(50);
  const [target, setTarget] = useState<Point>(INITIAL_TARGET);

  // Memory / History
  const [savedTrajectories, setSavedTrajectories] = useState<SavedTrajectory[]>([]);

  // Derived State
  const [calculatedPower, setCalculatedPower] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Screen Size (Used for Aspect Ratio calculation mainly)
  const [screenSize, setScreenSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    const handleResize = () => {
      setScreenSize({ width: window.innerWidth, height: window.innerHeight });
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // 1. Logic Loop: Handle Physics Calculation
  useEffect(() => {
    // Relative distance components
    const dist = target.x - TANK_POS.x;
    const height = target.y - TANK_POS.y;

    if (dist <= 0) {
        setError("Target must be to the right of the player");
        setCalculatedPower(null);
        return;
    }

    // Try to solve for power
    const neededPower = solvePower(dist, height, angle, wind);

    if (neededPower === null) {
       setError("Target unreachable with current angle/wind");
       setCalculatedPower(null);
    } else if (neededPower === -99999) {
        setError("Force insufficient (Out of range or strong headwind)");
        setCalculatedPower(null);
    } else {
        setError(null);
        setCalculatedPower(neededPower);

        // If in Auto-Aim, sync manual power for smoother transition
        if (mode === GameMode.AUTO_AIM) {
            // Check bounds
            if (neededPower > 100) {
               setError("Required power exceeds limit (100)");
               setManualPower(100); 
            } else {
               setManualPower(neededPower);
            }
        }
    }
  }, [target, angle, wind, mode]);

  // 2. Logic Loop: Generate Trajectory Points
  const trajectory = useMemo(() => {
    return calculateTrajectory(TANK_POS, manualPower, angle, wind);
  }, [manualPower, angle, wind]);

  // Find where it hits ground or target height
  const impactPoint = useMemo(() => {
      if (trajectory.length === 0) return null;
      return trajectory[trajectory.length - 1];
  }, [trajectory]);

  // --- Memory Functions ---
  const saveCurrentTrajectory = () => {
      const newEntry: SavedTrajectory = {
          id: Date.now().toString(),
          power: manualPower,
          angle: angle,
          wind: wind,
          target: { ...target },
          visible: true,
          timestamp: Date.now()
      };
      setSavedTrajectories(prev => [newEntry, ...prev]);
  };

  const deleteTrajectory = (id: string) => {
      setSavedTrajectories(prev => prev.filter(t => t.id !== id));
  };

  const toggleTrajectoryVisibility = (id: string) => {
      setSavedTrajectories(prev => prev.map(t => 
        t.id === id ? { ...t, visible: !t.visible } : t
      ));
  };

  return (
    <div className={`flex h-screen w-screen overflow-hidden transition-colors duration-500 ${isNight ? 'bg-slate-950' : 'bg-slate-100'}`}>
        {/* Main Canvas Area */}
        <div className="flex-1 h-full p-4 flex flex-col items-center justify-center relative">
            <div className="w-full h-full max-w-7xl max-h-[85vh] relative flex items-center justify-center">
                {/* Maintain aspect ratio of the physics world, adapted by zoom */}
                <div 
                  className="w-full h-full shadow-2xl rounded-xl overflow-hidden"
                  // We let the SVG handle aspect ratio internally via viewBox, 
                  // but we want the container to be responsive.
                >
                    <GameCanvas 
                        trajectory={trajectory}
                        target={target}
                        tankPos={TANK_POS}
                        onSetTarget={setTarget}
                        impactPoint={impactPoint}
                        angle={angle}
                        setAngle={setAngle}
                        zoom={zoom}
                        isNight={isNight}
                        wind={wind}
                        setWind={setWind}
                        snapToGrid={snapToGrid}
                        savedTrajectories={savedTrajectories}
                    />
                </div>
            </div>
             <div className={`mt-4 text-sm ${isNight ? 'text-slate-500' : 'text-slate-400'}`}>
                Click map to move target • Drag angle pointer to aim • Zoom to see more
            </div>
        </div>

        {/* Sidebar Controls */}
        <Controls 
            angle={angle}
            setAngle={setAngle}
            wind={wind}
            setWind={setWind}
            power={manualPower}
            setPower={setManualPower}
            mode={mode}
            setMode={setMode}
            target={target}
            tankPos={TANK_POS}
            calculationResult={calculatedPower}
            error={error}
            isNight={isNight}
            setIsNight={setIsNight}
            zoom={zoom}
            setZoom={setZoom}
            snapToGrid={snapToGrid}
            setSnapToGrid={setSnapToGrid}
            onSaveTrajectory={saveCurrentTrajectory}
            savedTrajectories={savedTrajectories}
            onDeleteTrajectory={deleteTrajectory}
            onToggleVisibility={toggleTrajectoryVisibility}
        />
    </div>
  );
}

export default App;

import React, { useRef, useMemo, useState } from 'react';
import { Point, PHYSICS_CONSTANTS, SavedTrajectory } from '../types';
import { Wind } from 'lucide-react';
import { calculateTrajectory } from '../services/physicsEngine';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
  snapToGrid: boolean;
  savedTrajectories: SavedTrajectory[];
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  isNight,
  wind,
  setWind,
  snapToGrid,
  savedTrajectories
}) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const [isDraggingKnob, setIsDraggingKnob] = useState(false);

  // Physics World Bounds (Dynamic based on zoom)
  const MAX_X = PHYSICS_CONSTANTS.MAX_X * zoom;
  const MAX_Y = PHYSICS_CONSTANTS.MAX_Y * zoom;

  // SVG Coordinate System (Fixed resolution for rendering quality)
  const VIEWBOX_WIDTH = MAX_X * 100; 
  const VIEWBOX_HEIGHT = MAX_Y * 100;

  // Helper to convert Physics (x, y) to SVG (x, y)
  // Physics: Y is Up, X is Right. Origin (0,0) (Bottom-Left visually)
  const toSvg = (p: Point) => ({
    x: (p.x / MAX_X) * VIEWBOX_WIDTH,
    y: VIEWBOX_HEIGHT - (p.y / MAX_Y) * VIEWBOX_HEIGHT
  });

  const fromSvg = (svgX: number, svgY: number): Point => ({
    x: (svgX / VIEWBOX_WIDTH) * MAX_X,
    y: ((VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT) * MAX_Y
  });

  // Accurate coordinate mapping using CTM (Current Transformation Matrix)
  // This solves offset issues caused by aspect ratio preservation
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    // Create an SVGPoint for the click coordinates
    let point = new DOMPoint(clientX, clientY);
    // Transform to SVG coordinates using the inverse of the screen CTM
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!svgRef.current) return;

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);

    // Check if clicked near the angle knob handle
    const tankSvg = toSvg(tankPos);
    // Calculate Knob Position
    const knobRadius = 80; // Fixed radius in SVG units
    const rad = (angle * Math.PI) / 180;
    const knobX = tankSvg.x + knobRadius * Math.cos(rad); // cos for x
    const knobY = tankSvg.y - knobRadius * Math.sin(rad); // -sin for y (svg inverted)

    const distToKnob = Math.hypot(clickX - knobX, clickY - knobY);

    if (distToKnob < 40) { // Hit radius for knob
        setIsDraggingKnob(true);
        (e.target as Element).setPointerCapture(e.pointerId);
        return;
    }

    // Otherwise, set target
    const physicsPoint = fromSvg(clickX, clickY);
    let clampedX = Math.max(0, Math.min(physicsPoint.x, MAX_X));
    let clampedY = Math.max(0, Math.min(physicsPoint.y, MAX_Y));

    if (snapToGrid) {
        clampedX = Math.round(clampedX);
        clampedY = Math.round(clampedY);
    }

    onSetTarget({ x: clampedX, y: clampedY });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!svgRef.current) return;

    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    if (isDraggingKnob) {
        const tankSvg = toSvg(tankPos);
        const dx = pointerX - tankSvg.x;
        const dy = pointerY - tankSvg.y; // Positive dy is DOWN in SVG

        // Atan2(y, x). SVG Y is down, so Up is negative Y.
        // We want 0 degrees to be right, 90 degrees to be up.
        // Math.atan2(y, x) -> 0 is right, positive angles are clockwise (down).
        // So we want -dy.
        let newAngle = Math.atan2(-dy, dx) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;

        // Clamp to 0-180 for this game
        if (newAngle > 180) newAngle = 180;

        setAngle(Math.round(newAngle));
    } else if (e.buttons === 1) {
        // Dragging to move target
        const physicsPoint = fromSvg(pointerX, pointerY);

        let clampedX = Math.max(0, Math.min(physicsPoint.x, MAX_X));
        let clampedY = Math.max(0, Math.min(physicsPoint.y, MAX_Y));

        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }

        onSetTarget({ x: clampedX, y: clampedY });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setIsDraggingKnob(false);
    (e.target as Element).releasePointerCapture(e.pointerId);
  };

  // Helper to generate path string from points
  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  // Convert active trajectory to SVG Path
  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, zoom]); 

  // Compute Saved Trajectories
  const savedPaths = useMemo(() => {
    return savedTrajectories.filter(t => t.visible).map(t => {
       const points = calculateTrajectory(tankPos, t.power, t.angle, t.wind);
       return { id: t.id, d: pointsToPath(points) };
    });
  }, [savedTrajectories, tankPos, zoom]);


  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  // Distances for Label
  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = Math.abs(target.y - tankPos.y).toFixed(2);

  // Grid lines
  const gridLines = useMemo(() => {
    const lines = [];
    const maxXInt = Math.ceil(MAX_X);
    const maxYInt = Math.ceil(MAX_Y);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const minorColor = isNight ? "rgba(51, 65, 85, 0.5)" : "rgba(203, 213, 225, 0.8)";
    const textColor = isNight ? "#94a3b8" : "#64748b";

    // Vertical Lines (X axis)
    for (let i = 1; i < maxXInt; i++) {
        const x = (i / MAX_X) * VIEWBOX_WIDTH;
        const isMajor = i % 12 === 0;

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isMajor ? highlightColor : minorColor} 
                strokeWidth={isMajor ? "4" : "1"} 
                strokeDasharray={isMajor ? "" : "4,2"}
            />
        );
        // Add text labels for ALL integers
        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + 5} 
                y={VIEWBOX_HEIGHT - 10} 
                fill={isMajor ? highlightColor : textColor} 
                fontSize={isMajor ? "24" : "16"}
                fontWeight={isMajor ? "bold" : "normal"}
                opacity={isMajor ? 1 : 0.7}
            >
                {i}
            </text>
        );
    }

    // Horizontal Lines (Y axis)
    for (let i = 1; i < maxYInt; i++) {
        const y = VIEWBOX_HEIGHT - (i / MAX_Y) * VIEWBOX_HEIGHT;
        const isMajor = i % 6 === 0;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isMajor ? highlightColor : minorColor} 
                strokeWidth={isMajor ? "4" : "1"} 
                strokeDasharray={isMajor ? "" : "4,2"}
            />
        );

        // Label for all integers
        lines.push(
            <text 
                key={`th-${i}`} 
                x={10} 
                y={y - 5} 
                fill={isMajor ? highlightColor : textColor} 
                fontSize={isMajor ? "24" : "16"}
                fontWeight={isMajor ? "bold" : "normal"}
                opacity={isMajor ? 1 : 0.7}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [VIEWBOX_WIDTH, VIEWBOX_HEIGHT, MAX_X, MAX_Y, isNight]);

  // Angle Knob Visualization
  const knobRadius = 80; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // 12x6 Reference Box Calculations (Adjusted from 7.2 to 6)
  // Currently showing a box, let's keep it 12x6 as a standard ref within the larger world
  const refBoxTopLeft = toSvg({ x: 0, y: 6 });
  const refBoxBottomRight = toSvg({ x: 12, y: 0 });
  const refBoxWidth = refBoxBottomRight.x - refBoxTopLeft.x;
  const refBoxHeight = refBoxBottomRight.y - refBoxTopLeft.y;

  return (
    <div className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none cursor-crosshair`}>
      {/* Top Center Wind Control Widget */}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-slate-800/90 backdrop-blur p-4 rounded-xl border border-slate-600 shadow-xl flex flex-col items-center w-72 z-20">
        <div className="text-xs font-bold text-slate-300 mb-2 w-full flex justify-between items-center">
            <span className="text-[10px] text-slate-500">WEST</span>
            <span className={`flex items-center gap-1 ${wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                <Wind size={12} />
                WIND: {Math.abs(wind).toFixed(1)}
            </span>
            <span className="text-[10px] text-slate-500">EAST</span>
        </div>

        {/* Quick Adjust Wind UI */}
        <div className="flex items-center w-full gap-2">
            <button 
                onClick={() => setWind(Number((wind - 0.5).toFixed(1)))}
                className="w-8 h-8 flex items-center justify-center bg-slate-700 hover:bg-slate-600 text-white rounded font-bold text-lg"
            >-</button>
            <div className="relative flex-1 h-6 flex items-center mx-1">
                <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                <input 
                    type="range" 
                    min="-150" 
                    max="150" 
                    step="0.5"
                    value={wind}
                    onChange={(e) => setWind(Number(e.target.value))}
                    className="w-full h-2 bg-slate-700/50 rounded-lg appearance-none cursor-pointer accent-sky-400 z-10 relative"
                />
            </div>
            <button 
                onClick={() => setWind(Number((wind + 0.5).toFixed(1)))}
                className="w-8 h-8 flex items-center justify-center bg-slate-700 hover:bg-slate-600 text-white rounded font-bold text-lg"
            >+</button>
        </div>
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Tactical View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            RANGE: {MAX_X.toFixed(1)}m x {MAX_Y.toFixed(1)}m
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className="w-full h-full block touch-none"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        preserveAspectRatio="xMidYMid meet"
      >
        {/* Grid */}
        {gridLines}

        {/* Ground */}
        <line x1="0" y1={VIEWBOX_HEIGHT} x2={VIEWBOX_WIDTH} y2={VIEWBOX_HEIGHT} stroke={isNight ? "#334155" : "#94a3b8"} strokeWidth="10" />

        {/* Reference Frame Box (12x6) - Keeping it as a reference for standard shots */}
        <rect 
            x={refBoxTopLeft.x} 
            y={refBoxTopLeft.y} 
            width={refBoxWidth} 
            height={refBoxHeight} 
            fill="none" 
            stroke="black" 
            strokeWidth="4"
        />
        <rect 
            x={refBoxTopLeft.x} 
            y={refBoxTopLeft.y} 
            width={refBoxWidth} 
            height={refBoxHeight} 
            fill="none" 
            stroke="white" 
            strokeWidth="2"
            strokeDasharray="10,10"
            opacity="0.5"
        />

        {/* Saved Trajectories (Memory) */}
        {savedPaths.map((sp) => (
            <path 
                key={sp.id}
                d={sp.d} 
                fill="none" 
                stroke="#a855f7" // Purple
                strokeWidth="2" 
                strokeDasharray="5,5"
                className="opacity-60"
            />
        ))}

        {/* Active Trajectory */}
        <path 
            d={trajectoryPath} 
            fill="none" 
            stroke={isNight ? "#38bdf8" : "#0284c7"} 
            strokeWidth="4" 
            strokeDasharray="10,10"
            className="opacity-80"
        />

        {/* ANGLE DIAL UI */}
        <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
            {/* Dashed arc for reference */}
            <path 
                d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`}
                fill="none"
                stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"}
                strokeWidth="2"
                strokeDasharray="4,4"
            />
            {/* The line representing the barrel/angle */}
            <line 
                x1={tankSvg.x} 
                y1={tankSvg.y} 
                x2={knobHandleX} 
                y2={knobHandleY} 
                stroke={isNight ? "#38bdf8" : "#0284c7"} 
                strokeWidth="4" 
            />
            {/* The Knob Handle */}
            <circle 
                cx={knobHandleX} 
                cy={knobHandleY} 
                r={isDraggingKnob ? 12 : 8}
                fill={isNight ? "#38bdf8" : "#0284c7"}
                stroke="white"
                strokeWidth="2"
                className="transition-all duration-100 ease-in-out hover:r-12"
            />
            {/* Angle Text label near knob */}
            <text 
                x={knobHandleX + 15} 
                y={knobHandleY - 15} 
                fill={isNight ? "#38bdf8" : "#0284c7"} 
                fontSize="16" 
                fontWeight="bold"
            >
                {angle}°
            </text>
        </g>

        {/* Tank / Player - Now at 0,0 */}
        <circle cx={tankSvg.x} cy={tankSvg.y} r="15" fill={isNight ? "#e2e8f0" : "#475569"} stroke={isNight ? "#475569" : "#1e293b"} strokeWidth="4" />
        <text x={tankSvg.x + 20} y={tankSvg.y - 20} textAnchor="start" fill={isNight ? "white" : "#1e293b"} fontSize="20" fontWeight="bold">YOU</text>

        {/* Target Marker */}
        <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
          <circle r="20" fill="rgba(239, 68, 68, 0.2)" stroke="#ef4444" strokeWidth="2" className="animate-pulse" />
          <line x1="-25" y1="0" x2="25" y2="0" stroke="#ef4444" strokeWidth="2" />
          <line x1="0" y1="-25" x2="0" y2="25" stroke="#ef4444" strokeWidth="2" />
          <text x="0" y="-35" textAnchor="middle" fill="#ef4444" fontSize="20" fontWeight="bold">TARGET</text>

          {/* Distance Info Label */}
          <rect x="-60" y="-85" width="120" height="40" rx="4" fill={isNight ? "rgba(15, 23, 42, 0.8)" : "rgba(255, 255, 255, 0.8)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
          <text x="0" y="-68" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="12" fontWeight="bold">
            Dist: {dx}
          </text>
          <text x="0" y="-53" textAnchor="middle" fill={isNight ? "#94a3b8" : "#475569"} fontSize="10">
            H: {dy}
          </text>
        </g>

        {/* Impact Point (if available) */}
        {impactSvg && (
             <circle cx={impactSvg.x} cy={impactSvg.y} r="8" fill="#fbbf24" stroke="white" strokeWidth="1" />
        )}
      </svg>
    </div>
  );
};

