};

export default Controls;

export interface Point {
  x: number;
  y: number;
}

export type ThemeMode = 'day' | 'night';

export enum GameMode {
  AUTO_AIM = 'AUTO_AIM', // "Free/Calculation Mode": Auto calculates power for target
  MANUAL = 'MANUAL'      // "Manual Mode": User controls power
}

export interface SimulationResult {
  power: number | null;
  trajectory: Point[];
  impactPoint: Point | null;
  error: string | null;
}

export interface SavedTrajectory {
  id: string;
  power: number;
  angle: number;
  wind: number;
  target: Point;
  visible: boolean;
  timestamp: number;
}

export const PHYSICS_CONSTANTS = {
  G: 157.96290,
  K: 1.12800,
  // Derived constants
  G_K: 157.96290 / 1.12800,
  // Viewport bounds (Physics Units)
  // Tank is at (0,0). 
  // We want 18 units up, 18 units down.
  MIN_Y: -18,
  MAX_Y: 18,
  // We want the tank on the left side. 
  // Give a bit of negative X padding (-4) and plenty of positive X (36)
  MIN_X: -4,
  MAX_X: 36,
};

import { Point, PHYSICS_CONSTANTS } from '../types';

const { G, K, G_K } = PHYSICS_CONSTANTS;

/**
 * Root finding algorithm (Bisection method) to replace scipy.optimize.brentq
 * Finds x where f(x) = 0 within [min, max]
 */
function brentq(f: (val: number) => number, min: number, max: number, tol = 1e-5, maxIter = 100): number | null {
  let a = min;
  let b = max;
  let fa = f(a);
  let fb = f(b);

  if (fa * fb > 0) {
    // Root is not bracketed. 
    return null;
  }

  for (let i = 0; i < maxIter; i++) {
    const c = (a + b) / 2;
    const fc = f(c);

    if (Math.abs(fc) < tol || (b - a) / 2 < tol) {
      return c;
    }

    if (fa * fc < 0) {
      b = c;
      fb = fc;
    } else {
      a = c;
      fa = fc;
    }
  }

  return (a + b) / 2;
}

/**
 * Calculates the trajectory points.
 */
export const calculateTrajectory = (
  start: Point,
  power: number,
  angle: number,
  wind: number,
  dt: number = 0.05
): Point[] => {
  const rad = (angle * Math.PI) / 180;
  const v_wind = wind / K;
  const vx_init = power * Math.cos(rad);
  const vy_init = power * Math.sin(rad);

  const points: Point[] = [];
  let t = 0;

  // Limit simulation to 20 seconds or reasonable bounds
  while (t < 20) {
    // x(t) = ((vx - v_wind)/K) * (1 - e^-Kt) + v_wind*t
    const term1_x = (vx_init - v_wind) / K;
    const term2 = 1 - Math.exp(-K * t);
    const term3_x = v_wind * t;
    const x = start.x + (term1_x * term2 + term3_x);

    // y(t) = ((vy + G_K)/K) * (1 - e^-Kt) - G_K*t
    const term1_y = (vy_init + G_K) / K;
    const term3_y = G_K * t;
    const y = start.y + (term1_y * term2 - term3_y);

    points.push({ x, y });

    // Expanded bounds for deep analysis (allows falling way below 0)
    // Using -20 allows visualizing shots into the "negative" 18 zone
    if (y < -20 || x > 100 || x < -20) break; 
    t += dt;
  }

  return points;
};

/**
 * Solves for the required power to hit a target.
 */
export const solvePower = (
  dist: number,
  height: number,
  angle: number,
  wind: number
): number | null => {
  const rad = (angle * Math.PI) / 180;
  const v_wind = wind / K;

  // Internal error function: returns (simulated_height - target_height) for a given velocity v
  const height_error_at_v = (v: number): number => {
    const vx = v * Math.cos(rad);
    const vy = v * Math.sin(rad);

    // Step 1: Find time t where x(t) = dist
    const x_dist_func = (t: number): number => {
      const term1 = (vx - v_wind) / K;
      const term2 = 1 - Math.exp(-K * t);
      const term3 = v_wind * t;
      return term1 * term2 + term3 - dist;
    };

    // Try to find impact time between 0.01s and 20s
    const t_impact = brentq(x_dist_func, 0.01, 20.0);

    if (t_impact === null) {
      const x_at_max = x_dist_func(20.0);
      if (x_at_max < 0) return -99999; // Too weak
      return 99999; 
    }

    // Step 2: Calculate height at that time
    const y_sim = ((vy + G_K) / K) * (1 - Math.exp(-K * t_impact)) - G_K * t_impact;

    return y_sim - height;
  };

  try {
    const final_v = brentq(height_error_at_v, 0.5, 200); 
    return final_v;
  } catch (e) {
    return null;
  }
};

import React, { useRef, useMemo, useState } from 'react';
import { Point, PHYSICS_CONSTANTS, SavedTrajectory } from '../types';
import { Wind } from 'lucide-react';
import { calculateTrajectory } from '../services/physicsEngine';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
  snapToGrid: boolean;
  savedTrajectories: SavedTrajectory[];
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  isNight,
  wind,
  setWind,
  snapToGrid,
  savedTrajectories
}) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const [isDraggingKnob, setIsDraggingKnob] = useState(false);

  // Apply Zoom to the viewing range
  // Zoom > 1 expands the view (seeing more), Zoom < 1 shrinks it (zooming in)
  // Wait, typically Zoom 2.0 means objects look 2x larger, so ViewBox should be smaller.
  // But previously logic was MAX_X * zoom, which means viewing MORE area. 
  // Let's stick to the user's "zoom to see more" logic: Higher scale value = Larger Field of View.

  const widthRange = PHYSICS_CONSTANTS.MAX_X - PHYSICS_CONSTANTS.MIN_X;
  const heightRange = PHYSICS_CONSTANTS.MAX_Y - PHYSICS_CONSTANTS.MIN_Y;

  const currentMinX = PHYSICS_CONSTANTS.MIN_X * zoom;
  const currentMaxX = PHYSICS_CONSTANTS.MAX_X * zoom;
  const currentMinY = PHYSICS_CONSTANTS.MIN_Y * zoom;
  const currentMaxY = PHYSICS_CONSTANTS.MAX_Y * zoom;

  const currentWidth = currentMaxX - currentMinX;
  const currentHeight = currentMaxY - currentMinY;

  // Fixed SVG Resolution (Pixels per unit * total units)
  const PIXELS_PER_UNIT = 40; 
  const VIEWBOX_WIDTH = currentWidth * PIXELS_PER_UNIT; 
  const VIEWBOX_HEIGHT = currentHeight * PIXELS_PER_UNIT;

  // Helper to convert Physics (x, y) to SVG (x, y)
  // Physics Y up, SVG Y down.
  const toSvg = (p: Point) => {
    // Normalize p.x relative to current view
    const percentX = (p.x - currentMinX) / currentWidth;
    const percentY = (p.y - currentMinY) / currentHeight;

    return {
        x: percentX * VIEWBOX_WIDTH,
        y: VIEWBOX_HEIGHT - (percentY * VIEWBOX_HEIGHT)
    };
  };

  const fromSvg = (svgX: number, svgY: number): Point => {
    const percentX = svgX / VIEWBOX_WIDTH;
    const percentY = (VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT; // Invert Y back

    return {
        x: currentMinX + percentX * currentWidth,
        y: currentMinY + percentY * currentHeight
    };
  };

  // Accurate coordinate mapping using CTM
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    let point = new DOMPoint(clientX, clientY);
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!svgRef.current) return;

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);

    // Angle Knob Check
    const tankSvg = toSvg(tankPos);
    const knobRadius = 80;
    const rad = (angle * Math.PI) / 180;
    const knobX = tankSvg.x + knobRadius * Math.cos(rad); 
    const knobY = tankSvg.y - knobRadius * Math.sin(rad); 

    const distToKnob = Math.hypot(clickX - knobX, clickY - knobY);

    if (distToKnob < 40) { 
        setIsDraggingKnob(true);
        (e.target as Element).setPointerCapture(e.pointerId);
        return;
    }

    // Set Target
    const physicsPoint = fromSvg(clickX, clickY);
    // Clamp to bounds
    let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
    let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));

    if (snapToGrid) {
        clampedX = Math.round(clampedX);
        clampedY = Math.round(clampedY);
    }

    onSetTarget({ x: clampedX, y: clampedY });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!svgRef.current) return;

    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    if (isDraggingKnob) {
        const tankSvg = toSvg(tankPos);
        const dx = pointerX - tankSvg.x;
        const dy = pointerY - tankSvg.y; 

        // Math.atan2(y, x). SVG Y positive is down. 
        // We want angle relative to Tank, standard math angle (CCW from East).
        // dy in SVG = (tankY - pointerY) in Cartesian (since pointerY > tankY means below)
        // Wait: SVG Y increases downwards.
        // pointerY - tankY: +ve means below tank.
        // We want -dy for Cartesian Y difference.
        let newAngle = Math.atan2(-(pointerY - tankSvg.y), (pointerX - tankSvg.x)) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;

        if (newAngle > 180) newAngle = 180; // Cap at 180 for this game

        setAngle(Math.round(newAngle));
    } else if (e.buttons === 1) {
        const physicsPoint = fromSvg(pointerX, pointerY);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));

        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }

        onSetTarget({ x: clampedX, y: clampedY });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setIsDraggingKnob(false);
    (e.target as Element).releasePointerCapture(e.pointerId);
  };

  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, currentMinX, currentMinY, zoom]); 

  const savedPaths = useMemo(() => {
    return savedTrajectories.filter(t => t.visible).map(t => {
       const points = calculateTrajectory(tankPos, t.power, t.angle, t.wind);
       return { id: t.id, d: pointsToPath(points) };
    });
  }, [savedTrajectories, tankPos, zoom]);


  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = (target.y - tankPos.y).toFixed(2); // Signed height difference is useful

  // Generate Grid Lines
  const gridLines = useMemo(() => {
    const lines = [];

    // Bounds for loops
    const startX = Math.floor(currentMinX);
    const endX = Math.ceil(currentMaxX);
    const startY = Math.floor(currentMinY);
    const endY = Math.ceil(currentMaxY);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const axisColor = isNight ? "#94a3b8" : "#475569"; // Stronger color for 0 lines
    const minorColor = isNight ? "rgba(51, 65, 85, 0.4)" : "rgba(203, 213, 225, 0.6)";
    const textColor = isNight ? "#64748b" : "#94a3b8";

    // Vertical Lines (X axis ticks)
    for (let i = startX; i <= endX; i++) {
        const p = toSvg({ x: i, y: 0 }); // Y doesn't matter for vertical line X position
        const x = p.x;

        // Skip if out of view
        if (x < -1 || x > VIEWBOX_WIDTH + 1) continue;

        const isAxis = i === 0;
        const isMajor = i % 5 === 0; // Every 5 units

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? "3" : (isMajor ? "2" : "1")} 
                strokeDasharray={isAxis || isMajor ? "" : "4,2"}
            />
        );

        // Label
        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + 4} 
                y={VIEWBOX_HEIGHT - 10} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={isAxis ? "20" : "14"}
                fontWeight={isAxis ? "bold" : "normal"}
            >
                {i}
            </text>
        );
    }

    // Horizontal Lines (Y axis ticks)
    for (let i = startY; i <= endY; i++) {
        const p = toSvg({ x: 0, y: i }); 
        const y = p.y;

        if (y < -1 || y > VIEWBOX_HEIGHT + 1) continue;

        const isAxis = i === 0;
        const isMajor = i % 5 === 0;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? "3" : (isMajor ? "2" : "1")} 
                strokeDasharray={isAxis || isMajor ? "" : "4,2"}
            />
        );

        lines.push(
            <text 
                key={`th-${i}`} 
                x={10} 
                y={y - 4} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={isAxis ? "20" : "14"}
                fontWeight={isAxis ? "bold" : "normal"}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [currentMinX, currentMaxX, currentMinY, currentMaxY, VIEWBOX_WIDTH, VIEWBOX_HEIGHT, isNight, toSvg]);

  const knobRadius = 80; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  return (
    <div className={`relative w-full h-full ${isNight ? 'bg-slate-950' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none cursor-crosshair`}>
      {/* Top Center Wind Control Widget */}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-slate-800/90 backdrop-blur p-4 rounded-xl border border-slate-600 shadow-xl flex flex-col items-center w-72 z-20">
        <div className="text-xs font-bold text-slate-300 mb-2 w-full flex justify-between items-center">
            <span className="text-[10px] text-slate-500">WEST</span>
            <span className={`flex items-center gap-1 ${wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                <Wind size={12} />
                WIND: {Math.abs(wind).toFixed(1)}
            </span>
            <span className="text-[10px] text-slate-500">EAST</span>
        </div>
        <div className="flex items-center w-full gap-2">
            <button onClick={() => setWind(Number((wind - 0.5).toFixed(1)))} className="w-8 h-8 flex items-center justify-center bg-slate-700 hover:bg-slate-600 text-white rounded font-bold text-lg">-</button>
            <div className="relative flex-1 h-6 flex items-center mx-1">
                <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className="w-full h-2 bg-slate-700/50 rounded-lg appearance-none cursor-pointer accent-sky-400 z-10 relative"/>
            </div>
            <button onClick={() => setWind(Number((wind + 0.5).toFixed(1)))} className="w-8 h-8 flex items-center justify-center bg-slate-700 hover:bg-slate-600 text-white rounded font-bold text-lg">+</button>
        </div>
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Curve Analysis View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            X: {currentMinX.toFixed(0)} to {currentMaxX.toFixed(0)} | Y: {currentMinY.toFixed(0)} to {currentMaxY.toFixed(0)}
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className="w-full h-full block touch-none"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        preserveAspectRatio="xMidYMid meet"
      >
        {/* Grid Lines */}
        {gridLines}

        {/* Saved Trajectories */}
        {savedPaths.map((sp) => (
            <path key={sp.id} d={sp.d} fill="none" stroke="#a855f7" strokeWidth="2" strokeDasharray="5,5" className="opacity-60" />
        ))}

        {/* Active Trajectory */}
        <path d={trajectoryPath} fill="none" stroke={isNight ? "#38bdf8" : "#0284c7"} strokeWidth="4" strokeDasharray="10,10" className="opacity-80" />

        {/* Angle Indicator */}
        <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
            <path d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`} fill="none" stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"} strokeWidth="2" strokeDasharray="4,4"/>
            <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} stroke={isNight ? "#38bdf8" : "#0284c7"} strokeWidth="4" />
            <circle cx={knobHandleX} cy={knobHandleY} r={isDraggingKnob ? 12 : 8} fill={isNight ? "#38bdf8" : "#0284c7"} stroke="white" strokeWidth="2" className="transition-all duration-100 ease-in-out hover:r-12"/>
            <text x={knobHandleX + 15} y={knobHandleY - 15} fill={isNight ? "#38bdf8" : "#0284c7"} fontSize="16" fontWeight="bold">{angle}°</text>
        </g>

        {/* Tank / Player (At Origin) */}
        <circle cx={tankSvg.x} cy={tankSvg.y} r="15" fill={isNight ? "#e2e8f0" : "#475569"} stroke={isNight ? "#475569" : "#1e293b"} strokeWidth="4" />
        <text x={tankSvg.x + 20} y={tankSvg.y - 20} textAnchor="start" fill={isNight ? "white" : "#1e293b"} fontSize="20" fontWeight="bold">YOU (0,0)</text>

        {/* Target Marker */}
        <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
          <circle r="20" fill="rgba(239, 68, 68, 0.2)" stroke="#ef4444" strokeWidth="2" className="animate-pulse" />
          <line x1="-25" y1="0" x2="25" y2="0" stroke="#ef4444" strokeWidth="2" />
          <line x1="0" y1="-25" x2="0" y2="25" stroke="#ef4444" strokeWidth="2" />
          <text x="0" y="-35" textAnchor="middle" fill="#ef4444" fontSize="20" fontWeight="bold">TARGET</text>

          {/* Info Label */}
          <rect x="-60" y="-85" width="120" height="40" rx="4" fill={isNight ? "rgba(15, 23, 42, 0.8)" : "rgba(255, 255, 255, 0.8)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
          <text x="0" y="-68" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="12" fontWeight="bold">X Dist: {dx}</text>
          <text x="0" y="-53" textAnchor="middle" fill={isNight ? "#94a3b8" : "#475569"} fontSize="10">Y Diff: {dy}</text>
        </g>

        {/* Impact Point */}
        {impactSvg && (
             <circle cx={impactSvg.x} cy={impactSvg.y} r="8" fill="#fbbf24" stroke="white" strokeWidth="1" />
        )}
      </svg>
    </div>
  );
};

