      inputBg: 'bg-slate-700',
      btnBg: 'bg-slate-800 hover:bg-slate-700',
      panelBg: 'bg-slate-800'
    } 
    : {
      bg: 'bg-white',
      border: 'border-slate-200',
      text: 'text-slate-900',
      subText: 'text-slate-500',
      inputBg: 'bg-slate-200',
      btnBg: 'bg-slate-100 hover:bg-slate-200',
      panelBg: 'bg-slate-50'
    };

  return (
    <div className={`relative flex flex-col h-full border-r ${themeClasses.border} shadow-xl transition-all duration-300 ease-in-out ${isNight ? 'bg-slate-900' : 'bg-slate-50'} ${isOpen ? 'w-96' : 'w-0'}`}>

