/**
 * Solves for the required power to hit a target.
 */
export const solvePower = (
  dist: number,
  height: number,
  angle: number,
  wind: number
): number | null => {
  const rad = (angle * Math.PI) / 180;
  const v_wind = wind / K;

  // If target is at 0 distance, 0 power.
  if (Math.abs(dist) < 0.1) return 0.1;

  // Internal error function: returns (simulated_height - target_height) for a given velocity v
  const height_error_at_v = (v: number): number => {
    const vx = v * Math.cos(rad);
    const vy = v * Math.sin(rad);

    // Step 1: Find time t where x(t) = dist
    const x_dist_func = (t: number): number => {
      const term1 = (vx - v_wind) / K;
      const term2 = 1 - Math.exp(-K * t);
      const term3 = v_wind * t;
      return term1 * term2 + term3 - dist;
    };

    let t_upper = 20.0;

    // Handle headwind: Find turnaround time to restrict search range
    if (v_wind < 0 && vx > 0) {
        const denom = vx - v_wind;
        // Safety check to avoid division by zero (unlikely as vx > 0 and v_wind < 0)
        if (Math.abs(denom) > 1e-9) {
            const ratio = -v_wind / denom;
            if (ratio > 0) {
                 const t_turn = -Math.log(ratio) / K;
                 // Add a small buffer to t_turn to ensure we catch the peak
                 // But strictly, x(t) decreases after t_turn.
                 // We want the first intersection, which is before t_turn.
                 if (t_turn < 20.0 && t_turn > 0.01) {
                     t_upper = t_turn;
                 }
            }
        }
    }

    // Try to find impact time
    const t_impact = brentq(x_dist_func, 0.001, t_upper);

    if (t_impact === null) {
      // Analyze why we missed
      const x_at_max = x_dist_func(t_upper); // This is x_max - dist

      // If we couldn't even reach the distance horizontally
      if (x_at_max < 0) {
          // Return a large negative penalty that scales with how far short we are
          // This helps the solver gradient slightly better than a flat number
          return -1000 + x_at_max; 
      }

      // If x_at_max > 0 but we didn't find a root?
      // This implies x(0.001) and x(t_upper) are both positive (overshoot immediately?)
      // Should be impossible for normal dist > 0.
      return 99999; 
    }

    // Step 2: Calculate height at that time
    const y_sim = ((vy + G_K) / K) * (1 - Math.exp(-K * t_impact)) - G_K * t_impact;

    return y_sim - height;
  };

  try {
    // Extended search range for high power shots (strong headwind)
    const final_v = brentq(height_error_at_v, 0.1, 600); 

    if (final_v === null) return null;

    // Verify the solution
    // bisection can converge on a discontinuity (jump from -1000 to positive error)
    // We check if the calculated error is actually close to 0
    const final_error = height_error_at_v(final_v);
    if (Math.abs(final_error) > 1.0) {
        // The error is too large, likely a false positive from discontinuity
        // This happens when the minimum-range shot is already too high
        return null;
    }

    return final_v;
  } catch (e) {
    return null;
  }
};

