  const windTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [isZoomExpanded, setIsZoomExpanded] = useState(false);
  const zoomTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // --- Interaction Logic for Wind Widget ---
  const handleWindEnter = () => {
    if (windTimeoutRef.current) clearTimeout(windTimeoutRef.current);
    setIsWindExpanded(true);
  };

  const handleWindLeave = () => {
    windTimeoutRef.current = setTimeout(() => {
        setIsWindExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };

  // --- Interaction Logic for Zoom Widget ---
  const handleZoomEnter = () => {
    if (zoomTimeoutRef.current) clearTimeout(zoomTimeoutRef.current);
    setIsZoomExpanded(true);
  };

  const handleZoomLeave = () => {
    zoomTimeoutRef.current = setTimeout(() => {
        setIsZoomExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };


  useEffect(() => {
    if (!containerRef.current) return;

    const updateSize = () => {
        if (containerRef.current) {
            const { width, height } = containerRef.current.getBoundingClientRect();
            if (width > 0 && height > 0) {
                setContainerSize({ width, height });
            }
        }
    };

    // Initial size
    updateSize();

    const observer = new ResizeObserver(updateSize);
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  // Viewport State: Pan Offset in Physics Units
  const [pan, setPan] = useState({ x: 0, y: 0 }); 

  // Custom offsets for saved labels (SVG px relative to target)
  const [labelOffsets, setLabelOffsets] = useState<Record<string, Point>>({});

  // Interaction State Machine
  const [dragState, setDragState] = useState<DragState>({ 
      mode: 'IDLE', 
      startScreen: { x: 0, y: 0 }, 
      startPan: { x: 0, y: 0 } 
  });

  // --- Viewport Calculations ---
  // We anchor the Vertical range and the Left side (Min X) based on constants + zoom.
  // We expand the Right side (Max X) based on the aspect ratio of the container.

  const aspectRatio = containerSize.width / containerSize.height;

  // Base heights from constants
  const baseHeight = PHYSICS_CONSTANTS.MAX_Y - PHYSICS_CONSTANTS.MIN_Y;

  // Calculate visible range in physics units
  const currentHeight = baseHeight * zoom;
  const currentWidth = currentHeight * aspectRatio;

  const currentMinY = (PHYSICS_CONSTANTS.MIN_Y * zoom) + pan.y;
  const currentMaxY = currentMinY + currentHeight;

  // Anchor Left side to MIN_X
  const currentMinX = (PHYSICS_CONSTANTS.MIN_X * zoom) + pan.x;
  const currentMaxX = currentMinX + currentWidth;

  // Fixed SVG Resolution scaling
  const PIXELS_PER_UNIT = 40; 
  const VIEWBOX_WIDTH = currentWidth * PIXELS_PER_UNIT; 
  const VIEWBOX_HEIGHT = currentHeight * PIXELS_PER_UNIT;

  const toSvg = (p: Point) => {
    const percentX = (p.x - currentMinX) / currentWidth;
    const percentY = (p.y - currentMinY) / currentHeight;
    return {
        x: percentX * VIEWBOX_WIDTH,
        y: VIEWBOX_HEIGHT - (percentY * VIEWBOX_HEIGHT)
    };
  };

  const fromSvg = (svgX: number, svgY: number): Point => {
    const percentX = svgX / VIEWBOX_WIDTH;
    const percentY = (VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT; 
    return {
        x: currentMinX + percentX * currentWidth,
        y: currentMinY + percentY * currentHeight
    };
  };

  // Accurate SVG point from screen coordinates
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    let point = new DOMPoint(clientX, clientY);
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, currentMinX, currentMinY, currentWidth, currentHeight]); 

  // --- Saved Data Preparation ---
  // Pre-calculate positions for rendering and hit-testing
  const savedData = useMemo(() => {
    return savedTrajectories.filter(t => t.visible).map((t, i) => {
       const points = calculateTrajectory(tankPos, t.power, t.angle, t.wind);
       const d = pointsToPath(points);
       const targetSvg = toSvg(t.target);

       const dx = (t.target.x - tankPos.x).toFixed(1);
       const dy = (t.target.y - tankPos.y).toFixed(1);

       // Default Stacked Offset (upwards)
       const defaultOffset = { x: 0, y: -(45 + (i % 5) * 80) };

       // Use manual offset if available, else default
       const offset = labelOffsets[t.id] || defaultOffset;

       const labelPos = {
           x: targetSvg.x + offset.x,
           y: targetSvg.y + offset.y
       };

       return { 
           id: t.id, 
           d, 
           power: t.power,
           angle: t.angle, 
           wind: t.wind, 
           dx, dy, 
           targetPos: targetSvg,
           labelPos,
           offset // Store relative offset
       };
    });
  }, [savedTrajectories, tankPos, zoom, currentMinX, currentMinY, currentWidth, currentHeight, labelOffsets]);

  // --- Interaction Handlers ---

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!svgRef.current) return;
    (e.target as Element).setPointerCapture(e.pointerId);

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);
    const screenPt = { x: e.clientX, y: e.clientY };

    // 1. Check Angle Knob / Area (Only if active)
    const tankSvg = toSvg(tankPos);
    // Allow grabbing anywhere within the visual radius (80) plus a small buffer
    const distToTank = Math.hypot(clickX - tankSvg.x, clickY - tankSvg.y);
    const knobRadius = 80;

    // If click is within the angle control circle
    if (showCurrentTrajectory && distToTank < knobRadius + 10) {
        setDragState({ mode: 'KNOB', startScreen: screenPt, startPan: pan });
        return;
    }

    // 2. Check Saved Labels (Top-most first)
    // Reverse iterate to catch top-most visual elements first
    for (let i = savedData.length - 1; i >= 0; i--) {
        const item = savedData[i];
        // Rect hit test (110x70 centered at labelPos)
        if (
            clickX >= item.labelPos.x - 55 && clickX <= item.labelPos.x + 55 &&
            clickY >= item.labelPos.y - 35 && clickY <= item.labelPos.y + 35
        ) {
            setDragState({ 
                mode: 'LABEL', 
                startScreen: screenPt, 
                startPan: pan, 
                activeId: item.id
            });
            return;
        }
    }

    // 3. Check Active Target (Only if active)
    const targetSvg = toSvg(target);
    if (showCurrentTrajectory && Math.hypot(clickX - targetSvg.x, clickY - targetSvg.y) < 30) {
        setDragState({ mode: 'TARGET', startScreen: screenPt, startPan: pan });
        return;
    }

    // 4. Background -> Pan or Click
    setDragState({ 
        mode: 'AWAIT_PAN_OR_CLICK', 
        startScreen: screenPt, 
        startPan: pan,
        hasMoved: false
    });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!svgRef.current) return;
    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    // Calculate screen deltas
    const dxScreen = e.clientX - dragState.startScreen.x;
    const dyScreen = e.clientY - dragState.startScreen.y;

    if (dragState.mode === 'KNOB') {
        const tankSvg = toSvg(tankPos);
        // Angle calc
        let newAngle = Math.atan2(-(pointerY - tankSvg.y), (pointerX - tankSvg.x)) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;
        if (newAngle > 180) newAngle = 180; 
        setAngle(Math.round(newAngle));

    } else if (dragState.mode === 'LABEL' && dragState.activeId) {
        // Find the target associated with this label to calculate relative offset
        const associatedTraj = savedTrajectories.find(t => t.id === dragState.activeId);
        if (associatedTraj) {
            const targetSvg = toSvg(associatedTraj.target);

            let destX = pointerX;
            let destY = pointerY;

            // Snap center of label to grid points if snapToGrid is enabled
            if (snapToGrid) {
                 // Convert pointer to physics units
                 const physPoint = fromSvg(destX, destY);
                 // Snap to nearest integer
                 const snappedPhysX = Math.round(physPoint.x);
                 const snappedPhysY = Math.round(physPoint.y);

                 // Convert back to SVG coords
                 const snappedSvg = toSvg({ x: snappedPhysX, y: snappedPhysY });
                 destX = snappedSvg.x;
                 destY = snappedSvg.y;
            }

            setLabelOffsets(prev => ({
                ...prev,
                [dragState.activeId!]: {
                    x: destX - targetSvg.x,
                    y: destY - targetSvg.y
                }
            }));
        }

    } else if (dragState.mode === 'TARGET') {
        const physicsPoint = fromSvg(pointerX, pointerY);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });

    } else if (dragState.mode === 'PAN' || (dragState.mode === 'AWAIT_PAN_OR_CLICK' && Math.hypot(dxScreen, dyScreen) > 5)) {
        // Transition to PAN mode if threshold exceeded
        if (dragState.mode === 'AWAIT_PAN_OR_CLICK') {
            setDragState(prev => ({ ...prev, mode: 'PAN', hasMoved: true }));
        }

        // Pan Logic: Convert Screen Pixels to Physics Units
        // Get scale factor from CTM (Screen px / SVG px)
        const ctm = svgRef.current?.getScreenCTM();
        const scaleX = ctm ? ctm.a : 1; 

        // Physics Delta = Screen Delta / (Scale * PixelsPerUnit)
        // Dragging Right (positive dx) -> Move Camera Left (decrease minX) -> decrease pan
        // So we subtract dx
        const dxPhys = -dxScreen / (PIXELS_PER_UNIT * scaleX);
        const dyPhys = dyScreen / (PIXELS_PER_UNIT * scaleX); // Y inverted for physics

        setPan({
            x: dragState.startPan.x + dxPhys,
            y: dragState.startPan.y + dyPhys
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    (e.target as Element).releasePointerCapture(e.pointerId);

    // If we clicked background without moving much, treat as Set Target (only if path is visible/editable)
    if (showCurrentTrajectory && dragState.mode === 'AWAIT_PAN_OR_CLICK' && !dragState.hasMoved) {
        const { x, y } = getSvgPoint(e.clientX, e.clientY);
        const physicsPoint = fromSvg(x, y);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });
    }

    setDragState({ mode: 'IDLE', startScreen: {x:0, y:0}, startPan: {x:0, y:0} });
  };

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = (target.y - tankPos.y).toFixed(2); 

  // Generate Grid Lines
  const gridLines = useMemo(() => {
    const lines = [];
    const startX = Math.floor(currentMinX);
    const endX = Math.ceil(currentMaxX);
    const startY = Math.floor(currentMinY);
    const endY = Math.ceil(currentMaxY);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const axisColor = isNight ? "#94a3b8" : "#475569"; 
    const minorColor = isNight ? "rgba(51, 65, 85, 0.4)" : "rgba(203, 213, 225, 0.6)";
    const textColor = isNight ? "#64748b" : "#94a3b8";

    for (let i = startX; i <= endX; i++) {
        const p = toSvg({ x: i, y: 0 }); 
        const x = p.x;
        // Optimization: Only render if within viewBox
        if (x < -50 || x > VIEWBOX_WIDTH + 50) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 12 === 0; 

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? "3" : (isMajor ? "2" : "1")} 
                strokeDasharray={isAxis || isMajor ? "" : "4,2"}
            />
        );

        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + 4} 
                y={VIEWBOX_HEIGHT - 10} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={isAxis ? "20" : (isMajor ? "18" : "14")}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
            >
                {i}
            </text>
        );
    }

    for (let i = startY; i <= endY; i++) {
        const p = toSvg({ x: 0, y: i }); 
        const y = p.y;
        if (y < -50 || y > VIEWBOX_HEIGHT + 50) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 6 === 0;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? "3" : (isMajor ? "2" : "1")} 
                strokeDasharray={isAxis || isMajor ? "" : "4,2"}
            />
        );

        lines.push(
            <text 
                key={`th-${i}`} 
                x={10} 
                y={y - 4} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={isAxis ? "20" : (isMajor ? "18" : "14")}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [currentMinX, currentMaxX, currentMinY, currentMaxY, VIEWBOX_WIDTH, VIEWBOX_HEIGHT, isNight, toSvg]);

  const knobRadius = 80; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // Dynamic Styles for Wind Widget
  const windWidgetClasses = isNight 
    ? 'bg-slate-800/95 border-slate-600'
    : 'bg-white/95 border-slate-200';

  const windTextClasses = isNight ? 'text-slate-300' : 'text-slate-700';
  const windLabelClasses = isNight ? 'text-slate-500' : 'text-slate-500';
  const windBtnClasses = isNight 
    ? 'bg-slate-700 hover:bg-slate-600 text-white' 
    : 'bg-slate-200 hover:bg-slate-300 text-slate-800';

  const mainColor = isNight ? "#38bdf8" : "#0284c7";

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none`}
    >
      {/* Top Center Wind Control Widget */}
      <div 
        onMouseEnter={handleWindEnter}
        onMouseLeave={handleWindLeave}
        className={`absolute top-4 left-1/2 -translate-x-1/2 backdrop-blur rounded-xl border shadow-xl flex flex-col items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isWindExpanded ? 'w-60 p-2' : 'w-auto px-4 py-2 hover:w-60 hover:p-2 cursor-pointer'}`}
      >
        {isWindExpanded ? (
            <>
                <div className={`text-[10px] font-bold ${windTextClasses} mb-1 w-full flex justify-between items-center`}>
                    <span className={`text-[9px] ${windLabelClasses}`}>WEST</span>
                    <span className={`flex items-center gap-1 ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-400') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                        <Wind size={10} />
                        WIND: {Math.abs(wind).toFixed(1)}
                    </span>
                    <span className={`text-[9px] ${windLabelClasses}`}>EAST</span>
                </div>
                <div className="flex items-center w-full gap-2 opacity-100 transition-opacity duration-300 delay-100">
                    <button onClick={() => setWind(Number((wind - 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>-</button>
                    <div className="relative flex-1 h-5 flex items-center mx-1">
                        <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                        <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-sky-500 z-10 relative ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}/>
                    </div>
                    <button onClick={() => setWind(Number((wind + 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>+</button>
                </div>
            </>
        ) : (
             <div className="flex items-center gap-2">
                <Wind size={14} className={wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-500' : 'text-rose-500'} />
                <span className={`text-xs font-bold font-mono ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-500') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {wind.toFixed(1)}
                </span>
            </div>
        )}
      </div>

      {/* Bottom Right Zoom Control Widget */}
      <div 
        onMouseEnter={handleZoomEnter}
        onMouseLeave={handleZoomLeave}
        className={`absolute bottom-4 right-4 backdrop-blur rounded-xl border shadow-xl flex items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isZoomExpanded ? 'w-64 p-3 gap-3' : 'w-24 p-2 gap-2 cursor-pointer hover:w-64 hover:p-3 hover:gap-3'}`}
      >
        {isZoomExpanded ? (
            <>
                <button onClick={() => setZoom(Math.max(0.25, zoom - 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomOut size={12} />
                </button>
                <div className="flex-1 flex flex-col items-center">
                    <div className="flex justify-between w-full text-[10px] font-bold mb-1 opacity-80">
                         <span className={windLabelClasses}>VIEW RANGE</span>
                         <span className={isNight ? 'text-indigo-300' : 'text-indigo-600'}>{(zoom * 100).toFixed(0)}%</span>
                    </div>
                    <input
                        type="range"
                        min="0.25"
                        max="2.5"
                        step="0.1"
                        value={zoom}
                        onChange={(e) => setZoom(Number(e.target.value))}
                        className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                    />
                </div>
                <button onClick={() => setZoom(Math.min(2.5, zoom + 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomIn size={12} />
                </button>
            </>
        ) : (
            <>
                <input
                    type="range"
                    min="0.25"
                    max="2.5"
                    step="0.1"
                    value={zoom}
                    readOnly
                    className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                />
            </>
        )}
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Curve Analysis View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            X: {currentMinX.toFixed(0)} to {currentMaxX.toFixed(0)} | Y: {currentMinY.toFixed(0)} to {currentMaxY.toFixed(0)}
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className={`w-full h-full block touch-none ${
            dragState.mode === 'PAN' ? 'cursor-grabbing' : 
            dragState.mode === 'LABEL' ? 'cursor-move' : 
            dragState.mode === 'TARGET' ? 'cursor-crosshair' : 
            dragState.mode === 'KNOB' ? 'cursor-grab' : 'cursor-grab'
        }`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        preserveAspectRatio="none"
      >
        <defs>
            {/* Arrow Marker for Label Pointers */}
            <marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
                <path d="M0,0 L0,6 L9,3 z" fill="#a855f7" />
            </marker>
            {/* Radial Gradient for Angle Control Area */}
            <radialGradient id="angleGradient" cx="0.5" cy="0.5" r="0.5">
                <stop offset="0%" stopColor={mainColor} stopOpacity="0.25" />
                <stop offset="100%" stopColor={mainColor} stopOpacity="0" />
            </radialGradient>
        </defs>

        {/* Grid Lines */}
        {gridLines}

        {/* Saved Trajectories and Labels */}
        {savedData.map((sd) => (
            <g key={sd.id}>
                {/* Curve */}
                <path d={sd.d} fill="none" stroke="#a855f7" strokeWidth="2" strokeDasharray="5,5" className="opacity-60" />

                {/* Saved Target Marker */}
                <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                     {/* Purple Bold Circle for saved target */}
                     <circle r="6" fill="none" stroke="#a855f7" strokeWidth="3" />
                     <circle r="2" fill="#a855f7" />
                </g>

                {/* Connecting Arrow (From Label Center to Target) */}
                <line 
                    x1={sd.labelPos.x} y1={sd.labelPos.y} 
                    x2={sd.targetPos.x} y2={sd.targetPos.y} 
                    stroke="#a855f7" strokeWidth="1.5" 
                    strokeDasharray="4,2"
                    markerEnd="url(#arrow)"
                    opacity="0.8"
                />

                {/* Draggable Label Box */}
                <g transform={`translate(${sd.labelPos.x}, ${sd.labelPos.y})`} className="cursor-move"> 
                    {/* Box */}
                    <rect 
                        x="-55" y="-35" width="110" height="70" rx="4" 
                        fill={isNight ? "rgba(15, 23, 42, 0.95)" : "rgba(255, 255, 255, 0.95)"} 
                        stroke="#a855f7" strokeWidth="2" 
                    />

                    {/* Power & Angle - Round Font */}
                    <text x="0" y="-18" textAnchor="middle" fill="#a855f7" fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        P: {sd.power.toFixed(1)} • A: {sd.angle}°
                    </text>

                    {/* Coords - Round Font (No Monospace) */}
                    <text x="0" y="2" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        ({sd.dx}, {sd.dy})
                    </text>

                    {/* Wind - Round Font */}
                    <text x="0" y="20" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="11" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        Wind: {sd.wind}
                    </text>
                </g>
            </g>
        ))}

        {/* Active Elements - Only visible when Live Path is ON */}
        {showCurrentTrajectory && (
            <>
                {/* Visual Interaction Area for Angle Control */}
                <circle 
                    cx={tankSvg.x} 
                    cy={tankSvg.y} 
                    r={knobRadius} 
                    fill="url(#angleGradient)" 
                    className="cursor-pointer hover:opacity-100 transition-opacity"
                    style={{ opacity: 0.8 }}
                />

                {/* Active Trajectory */}
                <path d={trajectoryPath} fill="none" stroke={mainColor} strokeWidth="4" strokeDasharray="10,10" className="opacity-80" />

                {/* Angle Indicator */}
                <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
                    <path d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`} fill="none" stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"} strokeWidth="2" strokeDasharray="4,4"/>
                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} stroke={mainColor} strokeWidth="3" strokeLinecap="round" />
                    <circle cx={knobHandleX} cy={knobHandleY} r={dragState.mode === 'KNOB' ? 8 : 5} fill={mainColor} stroke="white" strokeWidth="2" className="transition-all duration-100 ease-in-out hover:r-8 pointer-events-auto"/>
                </g>

                {/* Tank / Player (At Origin) - Redesigned */}
                <g>
                    {/* Base Circle with Color Stroke */}
                    <circle 
                        cx={tankSvg.x} 
                        cy={tankSvg.y} 
                        r="18" 
                        fill={isNight ? "#0f172a" : "#ffffff"} 
                        stroke={mainColor} 
                        strokeWidth="3" 
                    />
                    {/* Angle Text in Center */}
                    <text 
                        x={tankSvg.x} 
                        y={tankSvg.y} 
                        dy="4" 
                        textAnchor="middle" 
                        fill={mainColor} 
                        fontSize="11" 
                        fontWeight="bold" 
                        fontFamily="'Varela Round', sans-serif"
                        className="pointer-events-none select-none"
                    >
                        {angle}°
                    </text>
                </g>

                {/* Target Marker */}
                <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
                    {/* Small solid dot (same color as trajectory) */}
                    <circle r="5" fill={mainColor} />
                    {/* Outer ring pulsing for visibility */}
                    <circle r="12" fill="none" stroke={mainColor} strokeWidth="1.5" opacity="0.6" className="animate-pulse" />

                    {/* Info Label - Compact and centered above the dot */}
                    <g transform="translate(0, -65)">
                        <rect x="-70" y="0" width="140" height="50" rx="6" fill={isNight ? "rgba(15, 23, 42, 0.9)" : "rgba(255, 255, 255, 0.9)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
                        <text x="0" y="20" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="16" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            ({dx}, {dy})
                        </text>
                        <text x="0" y="38" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            Wind: {wind}
                        </text>
                    </g>
                </g>

                {/* Impact Point */}
                {impactSvg && (
                    <circle cx={impactSvg.x} cy={impactSvg.y} r="8" fill="#fbbf24" stroke="white" strokeWidth="1" />
                )}
            </>
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useMemo, useState, useEffect } from 'react';
import { Point, PHYSICS_CONSTANTS, SavedTrajectory } from '../types';
import { Wind, ZoomIn, ZoomOut } from 'lucide-react';
import { calculateTrajectory } from '../services/physicsEngine';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  setZoom: (z: number) => void;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
  snapToGrid: boolean;
  savedTrajectories: SavedTrajectory[];
  showCurrentTrajectory: boolean;
}

interface DragState {
    mode: 'IDLE' | 'PAN' | 'TARGET' | 'KNOB' | 'LABEL' | 'AWAIT_PAN_OR_CLICK';
    startScreen: Point;
    startPan: Point; // Physics units
    activeId?: string;
    hasMoved?: boolean;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  setZoom,
  isNight,
  wind,
  setWind,
  snapToGrid,
  savedTrajectories,
  showCurrentTrajectory
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  // Track container size for responsive aspect ratio
  const [containerSize, setContainerSize] = useState({ width: 1, height: 1 });

  // Widget Hover States
  const [isWindExpanded, setIsWindExpanded] = useState(false);
  const windTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [isZoomExpanded, setIsZoomExpanded] = useState(false);
  const zoomTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // --- Interaction Logic for Wind Widget ---
  const handleWindEnter = () => {
    if (windTimeoutRef.current) clearTimeout(windTimeoutRef.current);
    setIsWindExpanded(true);
  };

  const handleWindLeave = () => {
    windTimeoutRef.current = setTimeout(() => {
        setIsWindExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };

  // --- Interaction Logic for Zoom Widget ---
  const handleZoomEnter = () => {
    if (zoomTimeoutRef.current) clearTimeout(zoomTimeoutRef.current);
    setIsZoomExpanded(true);
  };

  const handleZoomLeave = () => {
    zoomTimeoutRef.current = setTimeout(() => {
        setIsZoomExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };


  useEffect(() => {
    if (!containerRef.current) return;

    const updateSize = () => {
        if (containerRef.current) {
            const { width, height } = containerRef.current.getBoundingClientRect();
            if (width > 0 && height > 0) {
                setContainerSize({ width, height });
            }
        }
    };

    // Initial size
    updateSize();

    const observer = new ResizeObserver(updateSize);
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  // Viewport State: Pan Offset in Physics Units
  const [pan, setPan] = useState({ x: 0, y: 0 }); 

  // Custom offsets for saved labels (SVG px relative to target)
  const [labelOffsets, setLabelOffsets] = useState<Record<string, Point>>({});

  // Interaction State Machine
  const [dragState, setDragState] = useState<DragState>({ 
      mode: 'IDLE', 
      startScreen: { x: 0, y: 0 }, 
      startPan: { x: 0, y: 0 } 
  });

  // --- Viewport Calculations ---
  // We anchor the Vertical range and the Left side (Min X) based on constants + zoom.
  // We expand the Right side (Max X) based on the aspect ratio of the container.

  const aspectRatio = containerSize.width / containerSize.height;

  // Base heights from constants
  const baseHeight = PHYSICS_CONSTANTS.MAX_Y - PHYSICS_CONSTANTS.MIN_Y;

  // Calculate visible range in physics units
  const currentHeight = baseHeight * zoom;
  const currentWidth = currentHeight * aspectRatio;

  const currentMinY = (PHYSICS_CONSTANTS.MIN_Y * zoom) + pan.y;
  const currentMaxY = currentMinY + currentHeight;

  // Anchor Left side to MIN_X
  const currentMinX = (PHYSICS_CONSTANTS.MIN_X * zoom) + pan.x;
  const currentMaxX = currentMinX + currentWidth;

  // Fixed SVG Resolution scaling
  const PIXELS_PER_UNIT = 40; 
  const VIEWBOX_WIDTH = currentWidth * PIXELS_PER_UNIT; 
  const VIEWBOX_HEIGHT = currentHeight * PIXELS_PER_UNIT;

  const toSvg = (p: Point) => {
    const percentX = (p.x - currentMinX) / currentWidth;
    const percentY = (p.y - currentMinY) / currentHeight;
    return {
        x: percentX * VIEWBOX_WIDTH,
        y: VIEWBOX_HEIGHT - (percentY * VIEWBOX_HEIGHT)
    };
  };

  const fromSvg = (svgX: number, svgY: number): Point => {
    const percentX = svgX / VIEWBOX_WIDTH;
    const percentY = (VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT; 
    return {
        x: currentMinX + percentX * currentWidth,
        y: currentMinY + percentY * currentHeight
    };
  };

  // Accurate SVG point from screen coordinates
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    let point = new DOMPoint(clientX, clientY);
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, currentMinX, currentMinY, currentWidth, currentHeight]); 

  // --- Saved Data Preparation ---
  // Pre-calculate positions for rendering and hit-testing
  const savedData = useMemo(() => {
    return savedTrajectories.filter(t => t.visible).map((t, i) => {
       const points = calculateTrajectory(tankPos, t.power, t.angle, t.wind);
       const d = pointsToPath(points);
       const targetSvg = toSvg(t.target);

       const dx = (t.target.x - tankPos.x).toFixed(1);
       const dy = (t.target.y - tankPos.y).toFixed(1);

       // Default Stacked Offset (upwards)
       const defaultOffset = { x: 0, y: -(45 + (i % 5) * 80) };

       // Use manual offset if available, else default
       const offset = labelOffsets[t.id] || defaultOffset;

       const labelPos = {
           x: targetSvg.x + offset.x,
           y: targetSvg.y + offset.y
       };

       return { 
           id: t.id, 
           d, 
           power: t.power,
           angle: t.angle, 
           wind: t.wind, 
           dx, dy, 
           targetPos: targetSvg,
           labelPos,
           offset // Store relative offset
       };
    });
  }, [savedTrajectories, tankPos, zoom, currentMinX, currentMinY, currentWidth, currentHeight, labelOffsets]);

  // --- Interaction Handlers ---

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!svgRef.current) return;
    (e.target as Element).setPointerCapture(e.pointerId);

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);
    const screenPt = { x: e.clientX, y: e.clientY };

    // 1. Check Angle Knob / Area (Only if active)
    const tankSvg = toSvg(tankPos);
    // Allow grabbing anywhere within the visual radius (80) plus a small buffer
    const distToTank = Math.hypot(clickX - tankSvg.x, clickY - tankSvg.y);
    const knobRadius = 80;

    // If click is within the angle control circle
    if (showCurrentTrajectory && distToTank < knobRadius + 10) {
        setDragState({ mode: 'KNOB', startScreen: screenPt, startPan: pan });
        return;
    }

    // 2. Check Saved Labels (Top-most first)
    // Reverse iterate to catch top-most visual elements first
    for (let i = savedData.length - 1; i >= 0; i--) {
        const item = savedData[i];
        // Rect hit test (110x70 centered at labelPos)
        if (
            clickX >= item.labelPos.x - 55 && clickX <= item.labelPos.x + 55 &&
            clickY >= item.labelPos.y - 35 && clickY <= item.labelPos.y + 35
        ) {
            setDragState({ 
                mode: 'LABEL', 
                startScreen: screenPt, 
                startPan: pan, 
                activeId: item.id
            });
            return;
        }
    }

    // 3. Check Active Target (Only if active)
    const targetSvg = toSvg(target);
    if (showCurrentTrajectory && Math.hypot(clickX - targetSvg.x, clickY - targetSvg.y) < 30) {
        setDragState({ mode: 'TARGET', startScreen: screenPt, startPan: pan });
        return;
    }

    // 4. Background -> Pan or Click
    setDragState({ 
        mode: 'AWAIT_PAN_OR_CLICK', 
        startScreen: screenPt, 
        startPan: pan,
        hasMoved: false
    });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!svgRef.current) return;
    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    // Calculate screen deltas
    const dxScreen = e.clientX - dragState.startScreen.x;
    const dyScreen = e.clientY - dragState.startScreen.y;

    if (dragState.mode === 'KNOB') {
        const tankSvg = toSvg(tankPos);
        // Angle calc
        let newAngle = Math.atan2(-(pointerY - tankSvg.y), (pointerX - tankSvg.x)) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;
        if (newAngle > 180) newAngle = 180; 

        // Use 1 decimal precision instead of rounding to integer for smoother "tight" feel
        setAngle(Number(newAngle.toFixed(1)));

    } else if (dragState.mode === 'LABEL' && dragState.activeId) {
        // Find the target associated with this label to calculate relative offset
        const associatedTraj = savedTrajectories.find(t => t.id === dragState.activeId);
        if (associatedTraj) {
            const targetSvg = toSvg(associatedTraj.target);

            let destX = pointerX;
            let destY = pointerY;

            // Snap center of label to grid points if snapToGrid is enabled
            if (snapToGrid) {
                 // Convert pointer to physics units
                 const physPoint = fromSvg(destX, destY);
                 // Snap to nearest integer
                 const snappedPhysX = Math.round(physPoint.x);
                 const snappedPhysY = Math.round(physPoint.y);

                 // Convert back to SVG coords
                 const snappedSvg = toSvg({ x: snappedPhysX, y: snappedPhysY });
                 destX = snappedSvg.x;
                 destY = snappedSvg.y;
            }

            setLabelOffsets(prev => ({
                ...prev,
                [dragState.activeId!]: {
                    x: destX - targetSvg.x,
                    y: destY - targetSvg.y
                }
            }));
        }

    } else if (dragState.mode === 'TARGET') {
        const physicsPoint = fromSvg(pointerX, pointerY);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });

    } else if (dragState.mode === 'PAN' || (dragState.mode === 'AWAIT_PAN_OR_CLICK' && Math.hypot(dxScreen, dyScreen) > 5)) {
        // Transition to PAN mode if threshold exceeded
        if (dragState.mode === 'AWAIT_PAN_OR_CLICK') {
            setDragState(prev => ({ ...prev, mode: 'PAN', hasMoved: true }));
        }

        // Pan Logic: Convert Screen Pixels to Physics Units
        // Get scale factor from CTM (Screen px / SVG px)
        const ctm = svgRef.current?.getScreenCTM();
        const scaleX = ctm ? ctm.a : 1; 

        // Physics Delta = Screen Delta / (Scale * PixelsPerUnit)
        // Dragging Right (positive dx) -> Move Camera Left (decrease minX) -> decrease pan
        // So we subtract dx
        const dxPhys = -dxScreen / (PIXELS_PER_UNIT * scaleX);
        const dyPhys = dyScreen / (PIXELS_PER_UNIT * scaleX); // Y inverted for physics

        setPan({
            x: dragState.startPan.x + dxPhys,
            y: dragState.startPan.y + dyPhys
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    (e.target as Element).releasePointerCapture(e.pointerId);

    // If we clicked background without moving much, treat as Set Target (only if path is visible/editable)
    if (showCurrentTrajectory && dragState.mode === 'AWAIT_PAN_OR_CLICK' && !dragState.hasMoved) {
        const { x, y } = getSvgPoint(e.clientX, e.clientY);
        const physicsPoint = fromSvg(x, y);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });
    }

    setDragState({ mode: 'IDLE', startScreen: {x:0, y:0}, startPan: {x:0, y:0} });
  };

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = (target.y - tankPos.y).toFixed(2); 

  // Generate Grid Lines
  const gridLines = useMemo(() => {
    const lines = [];
    const startX = Math.floor(currentMinX);
    const endX = Math.ceil(currentMaxX);
    const startY = Math.floor(currentMinY);
    const endY = Math.ceil(currentMaxY);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const axisColor = isNight ? "#94a3b8" : "#475569"; 
    const minorColor = isNight ? "rgba(51, 65, 85, 0.4)" : "rgba(203, 213, 225, 0.6)";
    const textColor = isNight ? "#64748b" : "#94a3b8";

    for (let i = startX; i <= endX; i++) {
        const p = toSvg({ x: i, y: 0 }); 
        const x = p.x;
        // Optimization: Only render if within viewBox
        if (x < -50 || x > VIEWBOX_WIDTH + 50) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 12 === 0; 

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? "3" : (isMajor ? "2" : "1")} 
                strokeDasharray={isAxis || isMajor ? "" : "4,2"}
            />
        );

        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + 4} 
                y={VIEWBOX_HEIGHT - 10} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={isAxis ? "20" : (isMajor ? "18" : "14")}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
            >
                {i}
            </text>
        );
    }

    for (let i = startY; i <= endY; i++) {
        const p = toSvg({ x: 0, y: i }); 
        const y = p.y;
        if (y < -50 || y > VIEWBOX_HEIGHT + 50) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 6 === 0;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? "3" : (isMajor ? "2" : "1")} 
                strokeDasharray={isAxis || isMajor ? "" : "4,2"}
            />
        );

        lines.push(
            <text 
                key={`th-${i}`} 
                x={10} 
                y={y - 4} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={isAxis ? "20" : (isMajor ? "18" : "14")}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [currentMinX, currentMaxX, currentMinY, currentMaxY, VIEWBOX_WIDTH, VIEWBOX_HEIGHT, isNight, toSvg]);

  const knobRadius = 80; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // Dynamic Styles for Wind Widget
  const windWidgetClasses = isNight 
    ? 'bg-slate-800/95 border-slate-600'
    : 'bg-white/95 border-slate-200';

  const windTextClasses = isNight ? 'text-slate-300' : 'text-slate-700';
  const windLabelClasses = isNight ? 'text-slate-500' : 'text-slate-500';
  const windBtnClasses = isNight 
    ? 'bg-slate-700 hover:bg-slate-600 text-white' 
    : 'bg-slate-200 hover:bg-slate-300 text-slate-800';

  const mainColor = isNight ? "#38bdf8" : "#0284c7";

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none`}
    >
      {/* CSS Animation for Breathing Dot */}
      <style>{`
        @keyframes breathe {
          0%, 100% { transform: scale(1); opacity: 1; }
          50% { transform: scale(1.3); opacity: 0.8; }
        }
        .breathing-dot {
          transform-box: fill-box;
          transform-origin: center;
          animation: breathe 2s infinite ease-in-out;
        }
      `}</style>

      {/* Top Center Wind Control Widget */}
      <div 
        onMouseEnter={handleWindEnter}
        onMouseLeave={handleWindLeave}
        className={`absolute top-4 left-1/2 -translate-x-1/2 backdrop-blur rounded-xl border shadow-xl flex flex-col items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isWindExpanded ? 'w-60 p-2' : 'w-auto px-4 py-2 hover:w-60 hover:p-2 cursor-pointer'}`}
      >
        {isWindExpanded ? (
            <>
                <div className={`text-[10px] font-bold ${windTextClasses} mb-1 w-full flex justify-between items-center`}>
                    <span className={`text-[9px] ${windLabelClasses}`}>WEST</span>
                    <span className={`flex items-center gap-1 ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-400') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                        <Wind size={10} />
                        WIND: {Math.abs(wind).toFixed(1)}
                    </span>
                    <span className={`text-[9px] ${windLabelClasses}`}>EAST</span>
                </div>
                <div className="flex items-center w-full gap-2 opacity-100 transition-opacity duration-300 delay-100">
                    <button onClick={() => setWind(Number((wind - 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>-</button>
                    <div className="relative flex-1 h-5 flex items-center mx-1">
                        <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                        <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-sky-500 z-10 relative ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}/>
                    </div>
                    <button onClick={() => setWind(Number((wind + 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>+</button>
                </div>
            </>
        ) : (
             <div className="flex items-center gap-2">
                <Wind size={14} className={wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-500' : 'text-rose-500'} />
                <span className={`text-xs font-bold font-mono ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-500') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {wind.toFixed(1)}
                </span>
            </div>
        )}
      </div>

      {/* Bottom Right Zoom Control Widget */}
      <div 
        onMouseEnter={handleZoomEnter}
        onMouseLeave={handleZoomLeave}
        className={`absolute bottom-4 right-4 backdrop-blur rounded-xl border shadow-xl flex items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isZoomExpanded ? 'w-64 p-3 gap-3' : 'w-24 p-2 gap-2 cursor-pointer hover:w-64 hover:p-3 hover:gap-3'}`}
      >
        {isZoomExpanded ? (
            <>
                <button onClick={() => setZoom(Math.max(0.25, zoom - 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomOut size={12} />
                </button>
                <div className="flex-1 flex flex-col items-center">
                    <div className="flex justify-between w-full text-[10px] font-bold mb-1 opacity-80">
                         <span className={windLabelClasses}>VIEW RANGE</span>
                         <span className={isNight ? 'text-indigo-300' : 'text-indigo-600'}>{(zoom * 100).toFixed(0)}%</span>
                    </div>
                    <input
                        type="range"
                        min="0.25"
                        max="2.5"
                        step="0.1"
                        value={zoom}
                        onChange={(e) => setZoom(Number(e.target.value))}
                        className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                    />
                </div>
                <button onClick={() => setZoom(Math.min(2.5, zoom + 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomIn size={12} />
                </button>
            </>
        ) : (
            <>
                <input
                    type="range"
                    min="0.25"
                    max="2.5"
                    step="0.1"
                    value={zoom}
                    readOnly
                    className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                />
            </>
        )}
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Curve Analysis View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            X: {currentMinX.toFixed(0)} to {currentMaxX.toFixed(0)} | Y: {currentMinY.toFixed(0)} to {currentMaxY.toFixed(0)}
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className={`w-full h-full block touch-none ${
            dragState.mode === 'PAN' ? 'cursor-grabbing' : 
            dragState.mode === 'LABEL' ? 'cursor-move' : 
            dragState.mode === 'TARGET' ? 'cursor-crosshair' : 
            dragState.mode === 'KNOB' ? 'cursor-grab' : 'cursor-grab'
        }`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        preserveAspectRatio="none"
      >
        <defs>
            {/* Arrow Marker for Label Pointers */}
            <marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
                <path d="M0,0 L0,6 L9,3 z" fill="#a855f7" />
            </marker>
            {/* Radial Gradient for Angle Control Area */}
            <radialGradient id="angleGradient" cx="0.5" cy="0.5" r="0.5">
                <stop offset="0%" stopColor={mainColor} stopOpacity="0.25" />
                <stop offset="100%" stopColor={mainColor} stopOpacity="0" />
            </radialGradient>
        </defs>

        {/* Grid Lines */}
        {gridLines}

        {/* Saved Trajectories and Labels */}
        {savedData.map((sd) => (
            <g key={sd.id}>
                {/* Curve */}
                <path d={sd.d} fill="none" stroke="#a855f7" strokeWidth="2" strokeDasharray="5,5" className="opacity-60" />

                {/* Saved Target Marker */}
                <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                     {/* Purple Bold Circle for saved target */}
                     <circle r="6" fill="none" stroke="#a855f7" strokeWidth="3" />
                     <circle r="2" fill="#a855f7" />
                </g>

                {/* Connecting Arrow (From Label Center to Target) */}
                <line 
                    x1={sd.labelPos.x} y1={sd.labelPos.y} 
                    x2={sd.targetPos.x} y2={sd.targetPos.y} 
                    stroke="#a855f7" strokeWidth="1.5" 
                    strokeDasharray="4,2"
                    markerEnd="url(#arrow)"
                    opacity="0.8"
                />

                {/* Draggable Label Box */}
                <g transform={`translate(${sd.labelPos.x}, ${sd.labelPos.y})`} className="cursor-move"> 
                    {/* Box */}
                    <rect 
                        x="-55" y="-35" width="110" height="70" rx="4" 
                        fill={isNight ? "rgba(15, 23, 42, 0.95)" : "rgba(255, 255, 255, 0.95)"} 
                        stroke="#a855f7" strokeWidth="2" 
                    />

                    {/* Power & Angle - Round Font */}
                    <text x="0" y="-18" textAnchor="middle" fill="#a855f7" fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        P: {sd.power.toFixed(1)} • A: {sd.angle}°
                    </text>

                    {/* Coords - Round Font (No Monospace) */}
                    <text x="0" y="2" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        ({sd.dx}, {sd.dy})
                    </text>

                    {/* Wind - Round Font */}
                    <text x="0" y="20" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="11" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        Wind: {sd.wind}
                    </text>
                </g>
            </g>
        ))}

        {/* Active Elements - Only visible when Live Path is ON */}
        {showCurrentTrajectory && (
            <>
                {/* Visual Interaction Area for Angle Control */}
                <circle 
                    cx={tankSvg.x} 
                    cy={tankSvg.y} 
                    r={knobRadius} 
                    fill="url(#angleGradient)" 
                    className="cursor-pointer hover:opacity-100 transition-opacity"
                    style={{ opacity: 0.8 }}
                />

                {/* Active Trajectory */}
                <path d={trajectoryPath} fill="none" stroke={mainColor} strokeWidth="4" strokeDasharray="10,10" className="opacity-80" />

                {/* Angle Indicator */}
                <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
                    <path d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`} fill="none" stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"} strokeWidth="2" strokeDasharray="4,4"/>
                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} stroke={mainColor} strokeWidth="3" strokeLinecap="round" />

                    {/* Draggable Knob Dot with Breathing Animation */}
                    <circle 
                        cx={knobHandleX} 
                        cy={knobHandleY} 
                        r={dragState.mode === 'KNOB' ? 8 : 6} 
                        fill={mainColor} 
                        stroke="white" 
                        strokeWidth="2" 
                        className={`transition-all duration-100 ease-in-out pointer-events-auto ${dragState.mode !== 'KNOB' ? 'breathing-dot' : ''}`}
                    />
                </g>

                {/* Tank / Player (At Origin) - Redesigned */}
                <g>
                    {/* Base Circle with Color Stroke */}
                    <circle 
                        cx={tankSvg.x} 
                        cy={tankSvg.y} 
                        r="18" 
                        fill={isNight ? "#0f172a" : "#ffffff"} 
                        stroke={mainColor} 
                        strokeWidth="3" 
                    />
                    {/* Angle Text in Center */}
                    <text 
                        x={tankSvg.x} 
                        y={tankSvg.y} 
                        dy="4" 
                        textAnchor="middle" 
                        fill={mainColor} 
                        fontSize="11" 
                        fontWeight="bold" 
                        fontFamily="'Varela Round', sans-serif"
                        className="pointer-events-none select-none"
                    >
                        {angle.toFixed(1)}°
                    </text>
                </g>

                {/* Target Marker */}
                <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
                    {/* Small solid dot (same color as trajectory) */}
                    <circle r="5" fill={mainColor} />
                    {/* Outer ring pulsing for visibility */}
                    <circle r="12" fill="none" stroke={mainColor} strokeWidth="1.5" opacity="0.6" className="animate-pulse" />

                    {/* Info Label - Compact and centered above the dot */}
                    <g transform="translate(0, -65)">
                        <rect x="-70" y="0" width="140" height="50" rx="6" fill={isNight ? "rgba(15, 23, 42, 0.9)" : "rgba(255, 255, 255, 0.9)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
                        <text x="0" y="20" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="16" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            ({dx}, {dy})
                        </text>
                        <text x="0" y="38" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            Wind: {wind}
                        </text>
                    </g>
                </g>

                {/* Impact Point */}
                {impactSvg && (
                    <circle cx={impactSvg.x} cy={impactSvg.y} r="8" fill="#fbbf24" stroke="white" strokeWidth="1" />
                )}
            </>
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useMemo, useState, useEffect } from 'react';
import { Point, PHYSICS_CONSTANTS, SavedTrajectory } from '../types';
import { Wind, ZoomIn, ZoomOut } from 'lucide-react';
import { calculateTrajectory } from '../services/physicsEngine';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  setZoom: (z: number) => void;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
  snapToGrid: boolean;
  savedTrajectories: SavedTrajectory[];
  showCurrentTrajectory: boolean;
}

interface DragState {
    mode: 'IDLE' | 'PAN' | 'TARGET' | 'KNOB' | 'LABEL' | 'AWAIT_PAN_OR_CLICK';
    startScreen: Point;
    startPan: Point; // Physics units
    activeId?: string;
    hasMoved?: boolean;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  setZoom,
  isNight,
  wind,
  setWind,
  snapToGrid,
  savedTrajectories,
  showCurrentTrajectory
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  // Track container size for responsive aspect ratio
  const [containerSize, setContainerSize] = useState({ width: 1, height: 1 });

  // Widget Hover States
  const [isWindExpanded, setIsWindExpanded] = useState(false);
  const windTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [isZoomExpanded, setIsZoomExpanded] = useState(false);
  const zoomTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // --- Interaction Logic for Wind Widget ---
  const handleWindEnter = () => {
    if (windTimeoutRef.current) clearTimeout(windTimeoutRef.current);
    setIsWindExpanded(true);
  };

  const handleWindLeave = () => {
    windTimeoutRef.current = setTimeout(() => {
        setIsWindExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };

  // --- Interaction Logic for Zoom Widget ---
  const handleZoomEnter = () => {
    if (zoomTimeoutRef.current) clearTimeout(zoomTimeoutRef.current);
    setIsZoomExpanded(true);
  };

  const handleZoomLeave = () => {
    zoomTimeoutRef.current = setTimeout(() => {
        setIsZoomExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };


  useEffect(() => {
    if (!containerRef.current) return;

    const updateSize = () => {
        if (containerRef.current) {
            const { width, height } = containerRef.current.getBoundingClientRect();
            if (width > 0 && height > 0) {
                setContainerSize({ width, height });
            }
        }
    };

    // Initial size
    updateSize();

    const observer = new ResizeObserver(updateSize);
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  // Viewport State: Pan Offset in Physics Units
  const [pan, setPan] = useState({ x: 0, y: 0 }); 

  // Custom offsets for saved labels (SVG px relative to target)
  const [labelOffsets, setLabelOffsets] = useState<Record<string, Point>>({});

  // Interaction State Machine
  const [dragState, setDragState] = useState<DragState>({ 
      mode: 'IDLE', 
      startScreen: { x: 0, y: 0 }, 
      startPan: { x: 0, y: 0 } 
  });

  // --- Viewport Calculations ---
  // We anchor the Vertical range and the Left side (Min X) based on constants + zoom.
  // We expand the Right side (Max X) based on the aspect ratio of the container.

  const aspectRatio = containerSize.width / containerSize.height;

  // Base heights from constants
  const baseHeight = PHYSICS_CONSTANTS.MAX_Y - PHYSICS_CONSTANTS.MIN_Y;

  // Calculate visible range in physics units
  const currentHeight = baseHeight * zoom;
  const currentWidth = currentHeight * aspectRatio;

  const currentMinY = (PHYSICS_CONSTANTS.MIN_Y * zoom) + pan.y;
  const currentMaxY = currentMinY + currentHeight;

  // Anchor Left side to MIN_X
  const currentMinX = (PHYSICS_CONSTANTS.MIN_X * zoom) + pan.x;
  const currentMaxX = currentMinX + currentWidth;

  // Fixed SVG Resolution scaling
  const PIXELS_PER_UNIT = 40; 
  const VIEWBOX_WIDTH = currentWidth * PIXELS_PER_UNIT; 
  const VIEWBOX_HEIGHT = currentHeight * PIXELS_PER_UNIT;

  const toSvg = (p: Point) => {
    const percentX = (p.x - currentMinX) / currentWidth;
    const percentY = (p.y - currentMinY) / currentHeight;
    return {
        x: percentX * VIEWBOX_WIDTH,
        y: VIEWBOX_HEIGHT - (percentY * VIEWBOX_HEIGHT)
    };
  };

  const fromSvg = (svgX: number, svgY: number): Point => {
    const percentX = svgX / VIEWBOX_WIDTH;
    const percentY = (VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT; 
    return {
        x: currentMinX + percentX * currentWidth,
        y: currentMinY + percentY * currentHeight
    };
  };

  // Accurate SVG point from screen coordinates
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    let point = new DOMPoint(clientX, clientY);
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, currentMinX, currentMinY, currentWidth, currentHeight]); 

  // --- Saved Data Preparation ---
  // Pre-calculate positions for rendering and hit-testing
  const savedData = useMemo(() => {
    return savedTrajectories.filter(t => t.visible).map((t, i) => {
       const points = calculateTrajectory(tankPos, t.power, t.angle, t.wind);
       const d = pointsToPath(points);
       const targetSvg = toSvg(t.target);

       const dx = (t.target.x - tankPos.x).toFixed(1);
       const dy = (t.target.y - tankPos.y).toFixed(1);

       // Default Stacked Offset (upwards)
       const defaultOffset = { x: 0, y: -(45 + (i % 5) * 80) };

       // Use manual offset if available, else default
       const offset = labelOffsets[t.id] || defaultOffset;

       const labelPos = {
           x: targetSvg.x + offset.x,
           y: targetSvg.y + offset.y
       };

       return { 
           id: t.id, 
           d, 
           power: t.power,
           angle: t.angle, 
           wind: t.wind, 
           dx, dy, 
           targetPos: targetSvg,
           labelPos,
           offset // Store relative offset
       };
    });
  }, [savedTrajectories, tankPos, zoom, currentMinX, currentMinY, currentWidth, currentHeight, labelOffsets]);

  // --- Interaction Handlers ---

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!svgRef.current) return;
    (e.target as Element).setPointerCapture(e.pointerId);

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);
    const screenPt = { x: e.clientX, y: e.clientY };

    // 1. Check Angle Knob / Area (Only if active)
    const tankSvg = toSvg(tankPos);
    // Allow grabbing anywhere within the visual radius (80) plus a small buffer
    const distToTank = Math.hypot(clickX - tankSvg.x, clickY - tankSvg.y);
    const knobRadius = 80;

    // If click is within the angle control circle
    if (showCurrentTrajectory && distToTank < knobRadius + 10) {
        setDragState({ mode: 'KNOB', startScreen: screenPt, startPan: pan });
        return;
    }

    // 2. Check Saved Labels (Top-most first)
    // Reverse iterate to catch top-most visual elements first
    for (let i = savedData.length - 1; i >= 0; i--) {
        const item = savedData[i];
        // Rect hit test (110x70 centered at labelPos)
        if (
            clickX >= item.labelPos.x - 55 && clickX <= item.labelPos.x + 55 &&
            clickY >= item.labelPos.y - 35 && clickY <= item.labelPos.y + 35
        ) {
            setDragState({ 
                mode: 'LABEL', 
                startScreen: screenPt, 
                startPan: pan, 
                activeId: item.id
            });
            return;
        }
    }

    // 3. Check Active Target (Only if active)
    const targetSvg = toSvg(target);
    if (showCurrentTrajectory && Math.hypot(clickX - targetSvg.x, clickY - targetSvg.y) < 30) {
        setDragState({ mode: 'TARGET', startScreen: screenPt, startPan: pan });
        return;
    }

    // 4. Background -> Pan or Click
    setDragState({ 
        mode: 'AWAIT_PAN_OR_CLICK', 
        startScreen: screenPt, 
        startPan: pan,
        hasMoved: false
    });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!svgRef.current) return;
    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    // Calculate screen deltas
    const dxScreen = e.clientX - dragState.startScreen.x;
    const dyScreen = e.clientY - dragState.startScreen.y;

    if (dragState.mode === 'KNOB') {
        const tankSvg = toSvg(tankPos);
        // Angle calc
        let newAngle = Math.atan2(-(pointerY - tankSvg.y), (pointerX - tankSvg.x)) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;
        if (newAngle > 180) newAngle = 180; 

        // Snap to integer angle for cleaner UI
        setAngle(Math.round(newAngle));

    } else if (dragState.mode === 'LABEL' && dragState.activeId) {
        // Find the target associated with this label to calculate relative offset
        const associatedTraj = savedTrajectories.find(t => t.id === dragState.activeId);
        if (associatedTraj) {
            const targetSvg = toSvg(associatedTraj.target);

            let destX = pointerX;
            let destY = pointerY;

            // Snap center of label to grid points if snapToGrid is enabled
            if (snapToGrid) {
                 // Convert pointer to physics units
                 const physPoint = fromSvg(destX, destY);
                 // Snap to nearest integer
                 const snappedPhysX = Math.round(physPoint.x);
                 const snappedPhysY = Math.round(physPoint.y);

                 // Convert back to SVG coords
                 const snappedSvg = toSvg({ x: snappedPhysX, y: snappedPhysY });
                 destX = snappedSvg.x;
                 destY = snappedSvg.y;
            }

            setLabelOffsets(prev => ({
                ...prev,
                [dragState.activeId!]: {
                    x: destX - targetSvg.x,
                    y: destY - targetSvg.y
                }
            }));
        }

    } else if (dragState.mode === 'TARGET') {
        const physicsPoint = fromSvg(pointerX, pointerY);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });

    } else if (dragState.mode === 'PAN' || (dragState.mode === 'AWAIT_PAN_OR_CLICK' && Math.hypot(dxScreen, dyScreen) > 5)) {
        // Transition to PAN mode if threshold exceeded
        if (dragState.mode === 'AWAIT_PAN_OR_CLICK') {
            setDragState(prev => ({ ...prev, mode: 'PAN', hasMoved: true }));
        }

        // Pan Logic: Convert Screen Pixels to Physics Units
        // Get scale factor from CTM (Screen px / SVG px)
        const ctm = svgRef.current?.getScreenCTM();
        const scaleX = ctm ? ctm.a : 1; 

        // Physics Delta = Screen Delta / (Scale * PixelsPerUnit)
        // Dragging Right (positive dx) -> Move Camera Left (decrease minX) -> decrease pan
        // So we subtract dx
        const dxPhys = -dxScreen / (PIXELS_PER_UNIT * scaleX);
        const dyPhys = dyScreen / (PIXELS_PER_UNIT * scaleX); // Y inverted for physics

        setPan({
            x: dragState.startPan.x + dxPhys,
            y: dragState.startPan.y + dyPhys
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    (e.target as Element).releasePointerCapture(e.pointerId);

    // If we clicked background without moving much, treat as Set Target (only if path is visible/editable)
    if (showCurrentTrajectory && dragState.mode === 'AWAIT_PAN_OR_CLICK' && !dragState.hasMoved) {
        const { x, y } = getSvgPoint(e.clientX, e.clientY);
        const physicsPoint = fromSvg(x, y);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });
    }

    setDragState({ mode: 'IDLE', startScreen: {x:0, y:0}, startPan: {x:0, y:0} });
  };

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = (target.y - tankPos.y).toFixed(2); 

  // Generate Grid Lines
  const gridLines = useMemo(() => {
    const lines = [];
    const startX = Math.floor(currentMinX);
    const endX = Math.ceil(currentMaxX);
    const startY = Math.floor(currentMinY);
    const endY = Math.ceil(currentMaxY);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const axisColor = isNight ? "#94a3b8" : "#475569"; 
    const minorColor = isNight ? "rgba(51, 65, 85, 0.4)" : "rgba(203, 213, 225, 0.6)";
    const textColor = isNight ? "#64748b" : "#94a3b8";

    for (let i = startX; i <= endX; i++) {
        const p = toSvg({ x: i, y: 0 }); 
        const x = p.x;
        // Optimization: Only render if within viewBox
        if (x < -50 || x > VIEWBOX_WIDTH + 50) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 12 === 0; 

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? "3" : (isMajor ? "2" : "1")} 
                strokeDasharray={isAxis || isMajor ? "" : "4,2"}
            />
        );

        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + 4} 
                y={VIEWBOX_HEIGHT - 10} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={isAxis ? "20" : (isMajor ? "18" : "14")}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
            >
                {i}
            </text>
        );
    }

    for (let i = startY; i <= endY; i++) {
        const p = toSvg({ x: 0, y: i }); 
        const y = p.y;
        if (y < -50 || y > VIEWBOX_HEIGHT + 50) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 6 === 0;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? "3" : (isMajor ? "2" : "1")} 
                strokeDasharray={isAxis || isMajor ? "" : "4,2"}
            />
        );

        lines.push(
            <text 
                key={`th-${i}`} 
                x={10} 
                y={y - 4} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={isAxis ? "20" : (isMajor ? "18" : "14")}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [currentMinX, currentMaxX, currentMinY, currentMaxY, VIEWBOX_WIDTH, VIEWBOX_HEIGHT, isNight, toSvg]);

  const knobRadius = 80; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // Dynamic Styles for Wind Widget
  const windWidgetClasses = isNight 
    ? 'bg-slate-800/95 border-slate-600'
    : 'bg-white/95 border-slate-200';

  const windTextClasses = isNight ? 'text-slate-300' : 'text-slate-700';
  const windLabelClasses = isNight ? 'text-slate-500' : 'text-slate-500';
  const windBtnClasses = isNight 
    ? 'bg-slate-700 hover:bg-slate-600 text-white' 
    : 'bg-slate-200 hover:bg-slate-300 text-slate-800';

  const mainColor = isNight ? "#38bdf8" : "#0284c7";

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none`}
    >
      {/* CSS Animation for Breathing Dot */}
      <style>{`
        @keyframes breathe {
          0%, 100% { transform: scale(1); }
          50% { transform: scale(1.3); }
        }
        .breathing-dot {
          animation: breathe 2s infinite ease-in-out;
        }
      `}</style>

      {/* Top Center Wind Control Widget */}
      <div 
        onMouseEnter={handleWindEnter}
        onMouseLeave={handleWindLeave}
        className={`absolute top-4 left-1/2 -translate-x-1/2 backdrop-blur rounded-xl border shadow-xl flex flex-col items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isWindExpanded ? 'w-60 p-2' : 'w-auto px-4 py-2 hover:w-60 hover:p-2 cursor-pointer'}`}
      >
        {isWindExpanded ? (
            <>
                <div className={`text-[10px] font-bold ${windTextClasses} mb-1 w-full flex justify-between items-center`}>
                    <span className={`text-[9px] ${windLabelClasses}`}>WEST</span>
                    <span className={`flex items-center gap-1 ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-400') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                        <Wind size={10} />
                        WIND: {Math.abs(wind).toFixed(1)}
                    </span>
                    <span className={`text-[9px] ${windLabelClasses}`}>EAST</span>
                </div>
                <div className="flex items-center w-full gap-2 opacity-100 transition-opacity duration-300 delay-100">
                    <button onClick={() => setWind(Number((wind - 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>-</button>
                    <div className="relative flex-1 h-5 flex items-center mx-1">
                        <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                        <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-sky-500 z-10 relative ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}/>
                    </div>
                    <button onClick={() => setWind(Number((wind + 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>+</button>
                </div>
            </>
        ) : (
             <div className="flex items-center gap-2">
                <Wind size={14} className={wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-500' : 'text-rose-500'} />
                <span className={`text-xs font-bold font-mono ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-500') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {wind.toFixed(1)}
                </span>
            </div>
        )}
      </div>

      {/* Bottom Right Zoom Control Widget */}
      <div 
        onMouseEnter={handleZoomEnter}
        onMouseLeave={handleZoomLeave}
        className={`absolute bottom-4 right-4 backdrop-blur rounded-xl border shadow-xl flex items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isZoomExpanded ? 'w-64 p-3 gap-3' : 'w-24 p-2 gap-2 cursor-pointer hover:w-64 hover:p-3 hover:gap-3'}`}
      >
        {isZoomExpanded ? (
            <>
                <button onClick={() => setZoom(Math.max(0.25, zoom - 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomOut size={12} />
                </button>
                <div className="flex-1 flex flex-col items-center">
                    <div className="flex justify-between w-full text-[10px] font-bold mb-1 opacity-80">
                         <span className={windLabelClasses}>VIEW RANGE</span>
                         <span className={isNight ? 'text-indigo-300' : 'text-indigo-600'}>{(zoom * 100).toFixed(0)}%</span>
                    </div>
                    <input
                        type="range"
                        min="0.25"
                        max="2.5"
                        step="0.1"
                        value={zoom}
                        onChange={(e) => setZoom(Number(e.target.value))}
                        className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                    />
                </div>
                <button onClick={() => setZoom(Math.min(2.5, zoom + 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomIn size={12} />
                </button>
            </>
        ) : (
            <>
                <input
                    type="range"
                    min="0.25"
                    max="2.5"
                    step="0.1"
                    value={zoom}
                    readOnly
                    className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                />
            </>
        )}
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Curve Analysis View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            X: {currentMinX.toFixed(0)} to {currentMaxX.toFixed(0)} | Y: {currentMinY.toFixed(0)} to {currentMaxY.toFixed(0)}
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className={`w-full h-full block touch-none ${
            dragState.mode === 'PAN' ? 'cursor-grabbing' : 
            dragState.mode === 'LABEL' ? 'cursor-move' : 
            dragState.mode === 'TARGET' ? 'cursor-crosshair' : 
            dragState.mode === 'KNOB' ? 'cursor-grab' : 'cursor-grab'
        }`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        preserveAspectRatio="none"
      >
        <defs>
            {/* Arrow Marker for Label Pointers */}
            <marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
                <path d="M0,0 L0,6 L9,3 z" fill="#a855f7" />
            </marker>
            {/* Radial Gradient for Angle Control Area */}
            <radialGradient id="angleGradient" cx="0.5" cy="0.5" r="0.5">
                <stop offset="0%" stopColor={mainColor} stopOpacity="0.25" />
                <stop offset="100%" stopColor={mainColor} stopOpacity="0" />
            </radialGradient>
        </defs>

        {/* Grid Lines */}
        {gridLines}

        {/* Saved Trajectories and Labels */}
        {savedData.map((sd) => (
            <g key={sd.id}>
                {/* Curve */}
                <path d={sd.d} fill="none" stroke="#a855f7" strokeWidth="2" strokeDasharray="5,5" className="opacity-60" />

                {/* Saved Target Marker */}
                <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                     {/* Purple Bold Circle for saved target */}
                     <circle r="6" fill="none" stroke="#a855f7" strokeWidth="3" />
                     <circle r="2" fill="#a855f7" />
                </g>

                {/* Connecting Arrow (From Label Center to Target) */}
                <line 
                    x1={sd.labelPos.x} y1={sd.labelPos.y} 
                    x2={sd.targetPos.x} y2={sd.targetPos.y} 
                    stroke="#a855f7" strokeWidth="1.5" 
                    strokeDasharray="4,2"
                    markerEnd="url(#arrow)"
                    opacity="0.8"
                />

                {/* Draggable Label Box */}
                <g transform={`translate(${sd.labelPos.x}, ${sd.labelPos.y})`} className="cursor-move"> 
                    {/* Box */}
                    <rect 
                        x="-55" y="-35" width="110" height="70" rx="4" 
                        fill={isNight ? "rgba(15, 23, 42, 0.95)" : "rgba(255, 255, 255, 0.95)"} 
                        stroke="#a855f7" strokeWidth="2" 
                    />

                    {/* Power & Angle - Round Font */}
                    <text x="0" y="-18" textAnchor="middle" fill="#a855f7" fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        P: {sd.power.toFixed(1)} • A: {sd.angle}°
                    </text>

                    {/* Coords - Round Font (No Monospace) */}
                    <text x="0" y="2" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        ({sd.dx}, {sd.dy})
                    </text>

                    {/* Wind - Round Font */}
                    <text x="0" y="20" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="11" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        Wind: {sd.wind}
                    </text>
                </g>
            </g>
        ))}

        {/* Active Elements - Only visible when Live Path is ON */}
        {showCurrentTrajectory && (
            <>
                {/* Visual Interaction Area for Angle Control */}
                <circle 
                    cx={tankSvg.x} 
                    cy={tankSvg.y} 
                    r={knobRadius} 
                    fill="url(#angleGradient)" 
                    className="cursor-pointer hover:opacity-100 transition-opacity"
                    style={{ opacity: 0.8 }}
                />

                {/* Active Trajectory */}
                <path d={trajectoryPath} fill="none" stroke={mainColor} strokeWidth="4" strokeDasharray="10,10" className="opacity-80" />

                {/* Angle Indicator */}
                <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
                    <path d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`} fill="none" stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"} strokeWidth="2" strokeDasharray="4,4"/>
                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} stroke={mainColor} strokeWidth="3" strokeLinecap="round" />

                    {/* Draggable Knob Dot with Breathing Animation - Wrapped in Translated Group to fix Drifting */}
                    <g transform={`translate(${knobHandleX}, ${knobHandleY})`} style={{ pointerEvents: 'auto' }}>
                        <circle 
                            cx={0} 
                            cy={0} 
                            r={dragState.mode === 'KNOB' ? 8 : 6} 
                            fill={mainColor} 
                            stroke="white" 
                            strokeWidth="2" 
                            className={`transition-all duration-100 ease-in-out ${dragState.mode !== 'KNOB' ? 'breathing-dot' : ''}`}
                        />
                    </g>
                </g>

                {/* Tank / Player (At Origin) - Redesigned */}
                <g>
                    {/* Base Circle with Color Stroke */}
                    <circle 
                        cx={tankSvg.x} 
                        cy={tankSvg.y} 
                        r="18" 
                        fill={isNight ? "#0f172a" : "#ffffff"} 
                        stroke={mainColor} 
                        strokeWidth="3" 
                    />
                    {/* Angle Text in Center */}
                    <text 
                        x={tankSvg.x} 
                        y={tankSvg.y} 
                        dy="4" 
                        textAnchor="middle" 
                        fill={mainColor} 
                        fontSize="11" 
                        fontWeight="bold" 
                        fontFamily="'Varela Round', sans-serif"
                        className="pointer-events-none select-none"
                    >
                        {angle}°
                    </text>
                </g>

                {/* Target Marker */}
                <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
                    {/* Small solid dot (same color as trajectory) */}
                    <circle r="5" fill={mainColor} />
                    {/* Outer ring pulsing for visibility */}
                    <circle r="12" fill="none" stroke={mainColor} strokeWidth="1.5" opacity="0.6" className="animate-pulse" />

                    {/* Info Label - Compact and centered above the dot */}
                    <g transform="translate(0, -65)">
                        <rect x="-70" y="0" width="140" height="50" rx="6" fill={isNight ? "rgba(15, 23, 42, 0.9)" : "rgba(255, 255, 255, 0.9)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
                        <text x="0" y="20" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="16" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            ({dx}, {dy})
                        </text>
                        <text x="0" y="38" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            Wind: {wind}
                        </text>
                    </g>
                </g>

                {/* Impact Point */}
                {impactSvg && (
                    <circle cx={impactSvg.x} cy={impactSvg.y} r="8" fill="#fbbf24" stroke="white" strokeWidth="1" />
                )}
            </>
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useMemo, useState, useEffect } from 'react';
import { Point, PHYSICS_CONSTANTS, SavedTrajectory } from '../types';
import { Wind, ZoomIn, ZoomOut } from 'lucide-react';
import { calculateTrajectory } from '../services/physicsEngine';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  setZoom: (z: number) => void;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
  snapToGrid: boolean;
  savedTrajectories: SavedTrajectory[];
  showCurrentTrajectory: boolean;
}

interface DragState {
    mode: 'IDLE' | 'PAN' | 'TARGET' | 'KNOB' | 'LABEL' | 'AWAIT_PAN_OR_CLICK';
    startScreen: Point;
    startPan: Point; // Physics units
    activeId?: string;
    hasMoved?: boolean;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  setZoom,
  isNight,
  wind,
  setWind,
  snapToGrid,
  savedTrajectories,
  showCurrentTrajectory
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  // Track container size for responsive aspect ratio
  const [containerSize, setContainerSize] = useState({ width: 1, height: 1 });

  // Widget Hover States
  const [isWindExpanded, setIsWindExpanded] = useState(false);
  const windTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [isZoomExpanded, setIsZoomExpanded] = useState(false);
  const zoomTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // --- Interaction Logic for Wind Widget ---
  const handleWindEnter = () => {
    if (windTimeoutRef.current) clearTimeout(windTimeoutRef.current);
    setIsWindExpanded(true);
  };

  const handleWindLeave = () => {
    windTimeoutRef.current = setTimeout(() => {
        setIsWindExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };

  // --- Interaction Logic for Zoom Widget ---
  const handleZoomEnter = () => {
    if (zoomTimeoutRef.current) clearTimeout(zoomTimeoutRef.current);
    setIsZoomExpanded(true);
  };

  const handleZoomLeave = () => {
    zoomTimeoutRef.current = setTimeout(() => {
        setIsZoomExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };


  useEffect(() => {
    if (!containerRef.current) return;

    const updateSize = () => {
        if (containerRef.current) {
            const { width, height } = containerRef.current.getBoundingClientRect();
            if (width > 0 && height > 0) {
                setContainerSize({ width, height });
            }
        }
    };

    // Initial size
    updateSize();

    const observer = new ResizeObserver(updateSize);
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  // Viewport State: Pan Offset in Physics Units
  const [pan, setPan] = useState({ x: 0, y: 0 }); 

  // Custom offsets for saved labels (SVG px relative to target)
  const [labelOffsets, setLabelOffsets] = useState<Record<string, Point>>({});

  // Interaction State Machine
  const [dragState, setDragState] = useState<DragState>({ 
      mode: 'IDLE', 
      startScreen: { x: 0, y: 0 }, 
      startPan: { x: 0, y: 0 } 
  });

  // --- Viewport Calculations ---
  // We anchor the Vertical range and the Left side (Min X) based on constants + zoom.
  // We expand the Right side (Max X) based on the aspect ratio of the container.

  const aspectRatio = containerSize.width / containerSize.height;

  // Base heights from constants
  const baseHeight = PHYSICS_CONSTANTS.MAX_Y - PHYSICS_CONSTANTS.MIN_Y;

  // Calculate visible range in physics units
  const currentHeight = baseHeight * zoom;
  const currentWidth = currentHeight * aspectRatio;

  const currentMinY = (PHYSICS_CONSTANTS.MIN_Y * zoom) + pan.y;
  const currentMaxY = currentMinY + currentHeight;

  // Anchor Left side to MIN_X
  const currentMinX = (PHYSICS_CONSTANTS.MIN_X * zoom) + pan.x;
  const currentMaxX = currentMinX + currentWidth;

  // Fixed SVG Resolution scaling
  const PIXELS_PER_UNIT = 40; 
  const VIEWBOX_WIDTH = currentWidth * PIXELS_PER_UNIT; 
  const VIEWBOX_HEIGHT = currentHeight * PIXELS_PER_UNIT;

  const toSvg = (p: Point) => {
    const percentX = (p.x - currentMinX) / currentWidth;
    const percentY = (p.y - currentMinY) / currentHeight;
    return {
        x: percentX * VIEWBOX_WIDTH,
        y: VIEWBOX_HEIGHT - (percentY * VIEWBOX_HEIGHT)
    };
  };

  const fromSvg = (svgX: number, svgY: number): Point => {
    const percentX = svgX / VIEWBOX_WIDTH;
    const percentY = (VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT; 
    return {
        x: currentMinX + percentX * currentWidth,
        y: currentMinY + percentY * currentHeight
    };
  };

  // Accurate SVG point from screen coordinates
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    let point = new DOMPoint(clientX, clientY);
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, currentMinX, currentMinY, currentWidth, currentHeight]); 

  // --- Saved Data Preparation ---
  // Pre-calculate positions for rendering and hit-testing
  const savedData = useMemo(() => {
    return savedTrajectories.filter(t => t.visible).map((t, i) => {
       const points = calculateTrajectory(tankPos, t.power, t.angle, t.wind);
       const d = pointsToPath(points);
       const targetSvg = toSvg(t.target);

       const dx = (t.target.x - tankPos.x).toFixed(1);
       const dy = (t.target.y - tankPos.y).toFixed(1);

       // Default Stacked Offset (upwards). Tighter stack for new sleek labels.
       const defaultOffset = { x: 0, y: -(40 + (i % 5) * 55) };

       // Use manual offset if available, else default
       const offset = labelOffsets[t.id] || defaultOffset;

       const labelPos = {
           x: targetSvg.x + offset.x,
           y: targetSvg.y + offset.y
       };

       return { 
           id: t.id, 
           d, 
           power: t.power,
           angle: t.angle, 
           wind: t.wind, 
           dx, dy, 
           targetPos: targetSvg,
           labelPos,
           offset // Store relative offset
       };
    });
  }, [savedTrajectories, tankPos, zoom, currentMinX, currentMinY, currentWidth, currentHeight, labelOffsets]);

  // --- Interaction Handlers ---

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!svgRef.current) return;
    (e.target as Element).setPointerCapture(e.pointerId);

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);
    const screenPt = { x: e.clientX, y: e.clientY };

    // 1. Check Angle Knob / Area (Only if active)
    const tankSvg = toSvg(tankPos);
    // Allow grabbing anywhere within the visual radius (80) plus a small buffer
    const distToTank = Math.hypot(clickX - tankSvg.x, clickY - tankSvg.y);
    const knobRadius = 80;

    // If click is within the angle control circle
    if (showCurrentTrajectory && distToTank < knobRadius + 10) {
        setDragState({ mode: 'KNOB', startScreen: screenPt, startPan: pan });
        return;
    }

    // 2. Check Saved Labels (Top-most first)
    // Reverse iterate to catch top-most visual elements first
    for (let i = savedData.length - 1; i >= 0; i--) {
        const item = savedData[i];
        // Rect hit test for new Long Strip shape (170x42 centered at labelPos)
        // Bounds: x +/- 85, y +/- 21
        if (
            clickX >= item.labelPos.x - 85 && clickX <= item.labelPos.x + 85 &&
            clickY >= item.labelPos.y - 21 && clickY <= item.labelPos.y + 21
        ) {
            setDragState({ 
                mode: 'LABEL', 
                startScreen: screenPt, 
                startPan: pan, 
                activeId: item.id
            });
            return;
        }
    }

    // 3. Check Active Target (Only if active)
    const targetSvg = toSvg(target);
    if (showCurrentTrajectory && Math.hypot(clickX - targetSvg.x, clickY - targetSvg.y) < 30) {
        setDragState({ mode: 'TARGET', startScreen: screenPt, startPan: pan });
        return;
    }

    // 4. Background -> Pan or Click
    setDragState({ 
        mode: 'AWAIT_PAN_OR_CLICK', 
        startScreen: screenPt, 
        startPan: pan,
        hasMoved: false
    });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!svgRef.current) return;
    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    // Calculate screen deltas
    const dxScreen = e.clientX - dragState.startScreen.x;
    const dyScreen = e.clientY - dragState.startScreen.y;

    if (dragState.mode === 'KNOB') {
        const tankSvg = toSvg(tankPos);
        // Angle calc
        let newAngle = Math.atan2(-(pointerY - tankSvg.y), (pointerX - tankSvg.x)) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;
        if (newAngle > 180) newAngle = 180; 

        // Snap to integer angle for cleaner UI
        setAngle(Math.round(newAngle));

    } else if (dragState.mode === 'LABEL' && dragState.activeId) {
        // Find the target associated with this label to calculate relative offset
        const associatedTraj = savedTrajectories.find(t => t.id === dragState.activeId);
        if (associatedTraj) {
            const targetSvg = toSvg(associatedTraj.target);

            let destX = pointerX;
            let destY = pointerY;

            // Snap center of label to grid points if snapToGrid is enabled
            if (snapToGrid) {
                 // Convert pointer to physics units
                 const physPoint = fromSvg(destX, destY);
                 // Snap to nearest integer
                 const snappedPhysX = Math.round(physPoint.x);
                 const snappedPhysY = Math.round(physPoint.y);

                 // Convert back to SVG coords
                 const snappedSvg = toSvg({ x: snappedPhysX, y: snappedPhysY });
                 destX = snappedSvg.x;
                 destY = snappedSvg.y;
            }

            setLabelOffsets(prev => ({
                ...prev,
                [dragState.activeId!]: {
                    x: destX - targetSvg.x,
                    y: destY - targetSvg.y
                }
            }));
        }

    } else if (dragState.mode === 'TARGET') {
        const physicsPoint = fromSvg(pointerX, pointerY);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });

    } else if (dragState.mode === 'PAN' || (dragState.mode === 'AWAIT_PAN_OR_CLICK' && Math.hypot(dxScreen, dyScreen) > 5)) {
        // Transition to PAN mode if threshold exceeded
        if (dragState.mode === 'AWAIT_PAN_OR_CLICK') {
            setDragState(prev => ({ ...prev, mode: 'PAN', hasMoved: true }));
        }

        // Pan Logic: Convert Screen Pixels to Physics Units
        // Get scale factor from CTM (Screen px / SVG px)
        const ctm = svgRef.current?.getScreenCTM();
        const scaleX = ctm ? ctm.a : 1; 

        // Physics Delta = Screen Delta / (Scale * PixelsPerUnit)
        // Dragging Right (positive dx) -> Move Camera Left (decrease minX) -> decrease pan
        // So we subtract dx
        const dxPhys = -dxScreen / (PIXELS_PER_UNIT * scaleX);
        const dyPhys = dyScreen / (PIXELS_PER_UNIT * scaleX); // Y inverted for physics

        setPan({
            x: dragState.startPan.x + dxPhys,
            y: dragState.startPan.y + dyPhys
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    (e.target as Element).releasePointerCapture(e.pointerId);

    // If we clicked background without moving much, treat as Set Target (only if path is visible/editable)
    if (showCurrentTrajectory && dragState.mode === 'AWAIT_PAN_OR_CLICK' && !dragState.hasMoved) {
        const { x, y } = getSvgPoint(e.clientX, e.clientY);
        const physicsPoint = fromSvg(x, y);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });
    }

    setDragState({ mode: 'IDLE', startScreen: {x:0, y:0}, startPan: {x:0, y:0} });
  };

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = (target.y - tankPos.y).toFixed(2); 

  // Generate Grid Lines
  const gridLines = useMemo(() => {
    const lines = [];
    const startX = Math.floor(currentMinX);
    const endX = Math.ceil(currentMaxX);
    const startY = Math.floor(currentMinY);
    const endY = Math.ceil(currentMaxY);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const axisColor = isNight ? "#94a3b8" : "#475569"; 
    const minorColor = isNight ? "rgba(51, 65, 85, 0.4)" : "rgba(203, 213, 225, 0.6)";
    const textColor = isNight ? "#64748b" : "#94a3b8";

    for (let i = startX; i <= endX; i++) {
        const p = toSvg({ x: i, y: 0 }); 
        const x = p.x;
        // Optimization: Only render if within viewBox
        if (x < -50 || x > VIEWBOX_WIDTH + 50) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 12 === 0; 

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? "3" : (isMajor ? "2" : "1")} 
                strokeDasharray={isAxis || isMajor ? "" : "4,2"}
            />
        );

        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + 4} 
                y={VIEWBOX_HEIGHT - 10} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={isAxis ? "20" : (isMajor ? "18" : "14")}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
            >
                {i}
            </text>
        );
    }

    for (let i = startY; i <= endY; i++) {
        const p = toSvg({ x: 0, y: i }); 
        const y = p.y;
        if (y < -50 || y > VIEWBOX_HEIGHT + 50) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 6 === 0;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? "3" : (isMajor ? "2" : "1")} 
                strokeDasharray={isAxis || isMajor ? "" : "4,2"}
            />
        );

        lines.push(
            <text 
                key={`th-${i}`} 
                x={10} 
                y={y - 4} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={isAxis ? "20" : (isMajor ? "18" : "14")}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [currentMinX, currentMaxX, currentMinY, currentMaxY, VIEWBOX_WIDTH, VIEWBOX_HEIGHT, isNight, toSvg]);

  const knobRadius = 80; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // Dynamic Styles for Wind Widget
  const windWidgetClasses = isNight 
    ? 'bg-slate-800/95 border-slate-600'
    : 'bg-white/95 border-slate-200';

  const windTextClasses = isNight ? 'text-slate-300' : 'text-slate-700';
  const windLabelClasses = isNight ? 'text-slate-500' : 'text-slate-500';
  const windBtnClasses = isNight 
    ? 'bg-slate-700 hover:bg-slate-600 text-white' 
    : 'bg-slate-200 hover:bg-slate-300 text-slate-800';

  const mainColor = isNight ? "#38bdf8" : "#0284c7";

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none`}
    >
      {/* CSS Animation for Breathing Dot */}
      <style>{`
        @keyframes breathe {
          0%, 100% { transform: scale(1); }
          50% { transform: scale(1.3); }
        }
        .breathing-dot {
          animation: breathe 2s infinite ease-in-out;
        }
      `}</style>

      {/* Top Center Wind Control Widget */}
      <div 
        onMouseEnter={handleWindEnter}
        onMouseLeave={handleWindLeave}
        className={`absolute top-4 left-1/2 -translate-x-1/2 backdrop-blur rounded-xl border shadow-xl flex flex-col items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isWindExpanded ? 'w-60 p-2' : 'w-auto px-4 py-2 hover:w-60 hover:p-2 cursor-pointer'}`}
      >
        {isWindExpanded ? (
            <>
                <div className={`text-[10px] font-bold ${windTextClasses} mb-1 w-full flex justify-between items-center`}>
                    <span className={`text-[9px] ${windLabelClasses}`}>WEST</span>
                    <span className={`flex items-center gap-1 ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-400') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                        <Wind size={10} />
                        WIND: {Math.abs(wind).toFixed(1)}
                    </span>
                    <span className={`text-[9px] ${windLabelClasses}`}>EAST</span>
                </div>
                <div className="flex items-center w-full gap-2 opacity-100 transition-opacity duration-300 delay-100">
                    <button onClick={() => setWind(Number((wind - 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>-</button>
                    <div className="relative flex-1 h-5 flex items-center mx-1">
                        <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                        <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-sky-500 z-10 relative ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}/>
                    </div>
                    <button onClick={() => setWind(Number((wind + 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>+</button>
                </div>
            </>
        ) : (
             <div className="flex items-center gap-2">
                <Wind size={14} className={wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-500' : 'text-rose-500'} />
                <span className={`text-xs font-bold font-mono ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-500') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {wind.toFixed(1)}
                </span>
            </div>
        )}
      </div>

      {/* Bottom Right Zoom Control Widget */}
      <div 
        onMouseEnter={handleZoomEnter}
        onMouseLeave={handleZoomLeave}
        className={`absolute bottom-4 right-4 backdrop-blur rounded-xl border shadow-xl flex items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isZoomExpanded ? 'w-64 p-3 gap-3' : 'w-24 p-2 gap-2 cursor-pointer hover:w-64 hover:p-3 hover:gap-3'}`}
      >
        {isZoomExpanded ? (
            <>
                <button onClick={() => setZoom(Math.max(0.25, zoom - 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomOut size={12} />
                </button>
                <div className="flex-1 flex flex-col items-center">
                    <div className="flex justify-between w-full text-[10px] font-bold mb-1 opacity-80">
                         <span className={windLabelClasses}>VIEW RANGE</span>
                         <span className={isNight ? 'text-indigo-300' : 'text-indigo-600'}>{(zoom * 100).toFixed(0)}%</span>
                    </div>
                    <input
                        type="range"
                        min="0.25"
                        max="2.5"
                        step="0.1"
                        value={zoom}
                        onChange={(e) => setZoom(Number(e.target.value))}
                        className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                    />
                </div>
                <button onClick={() => setZoom(Math.min(2.5, zoom + 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomIn size={12} />
                </button>
            </>
        ) : (
            <>
                <input
                    type="range"
                    min="0.25"
                    max="2.5"
                    step="0.1"
                    value={zoom}
                    readOnly
                    className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                />
            </>
        )}
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Curve Analysis View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            X: {currentMinX.toFixed(0)} to {currentMaxX.toFixed(0)} | Y: {currentMinY.toFixed(0)} to {currentMaxY.toFixed(0)}
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className={`w-full h-full block touch-none ${
            dragState.mode === 'PAN' ? 'cursor-grabbing' : 
            dragState.mode === 'LABEL' ? 'cursor-move' : 
            dragState.mode === 'TARGET' ? 'cursor-crosshair' : 
            dragState.mode === 'KNOB' ? 'cursor-grab' : 'cursor-grab'
        }`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        preserveAspectRatio="none"
      >
        <defs>
            {/* Arrow Marker for Label Pointers */}
            <marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
                <path d="M0,0 L0,6 L9,3 z" fill="#a855f7" />
            </marker>
            {/* Radial Gradient for Angle Control Area */}
            <radialGradient id="angleGradient" cx="0.5" cy="0.5" r="0.5">
                <stop offset="0%" stopColor={mainColor} stopOpacity="0.25" />
                <stop offset="100%" stopColor={mainColor} stopOpacity="0" />
            </radialGradient>
            {/* Drop Shadow Filter */}
            <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
              <feDropShadow dx="0" dy="2" stdDeviation="2" floodColor="#000000" floodOpacity="0.3" />
            </filter>
        </defs>

        {/* Grid Lines */}
        {gridLines}

        {/* Saved Trajectories and Labels */}
        {savedData.map((sd) => (
            <g key={sd.id}>
                {/* Curve */}
                <path d={sd.d} fill="none" stroke="#a855f7" strokeWidth="2" strokeDasharray="5,5" className="opacity-60" />

                {/* Saved Target Marker */}
                <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                     {/* Purple Bold Circle for saved target */}
                     <circle r="6" fill="none" stroke="#a855f7" strokeWidth="3" />
                     <circle r="2" fill="#a855f7" />
                </g>

                {/* Connecting Arrow (From Label Center to Target) */}
                <line 
                    x1={sd.labelPos.x} y1={sd.labelPos.y} 
                    x2={sd.targetPos.x} y2={sd.targetPos.y} 
                    stroke="#a855f7" strokeWidth="1.5" 
                    strokeDasharray="4,2"
                    markerEnd="url(#arrow)"
                    opacity="0.8"
                />

                {/* Draggable Label - NEW SLEEK DESIGN */}
                <g transform={`translate(${sd.labelPos.x}, ${sd.labelPos.y})`} className="cursor-move"> 

                    {/* Main Container Rect (White/Dark) */}
                    <rect 
                        x="-85" y="-21" width="170" height="42" rx="6" 
                        fill={isNight ? "#1e293b" : "#ffffff"} 
                        stroke="#a855f7" strokeWidth="2" 
                        filter="url(#shadow)"
                    />

                    {/* Left Section (Power) - Purple Background */}
                    {/* Path traces the rounded corners on left and straight line on split */}
                    <path 
                        d="M -35 -21 L -79 -21 Q -85 -21 -85 -15 L -85 15 Q -85 21 -79 21 L -35 21 Z" 
                        fill="#a855f7" 
                    />

                    {/* Power Text */}
                    <text x="-60" y="-7" textAnchor="middle" fill="rgba(255,255,255,0.7)" fontSize="8" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        POWER
                    </text>
                    <text x="-60" y="10" textAnchor="middle" fill="white" fontSize="16" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        {sd.power.toFixed(1)}
                    </text>

                    {/* Right Section Details */}
                    {/* Row 1: Angle & Wind */}
                    <text x="-25" y="-5" textAnchor="start" fill={isNight ? "#94a3b8" : "#64748b"} fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        A: <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.angle}°</tspan>
                        <tspan dx="8">W: </tspan><tspan fontWeight="bold" fill={sd.wind === 0 ? (isNight ? "#94a3b8" : "#64748b") : (sd.wind > 0 ? "#10b981" : "#f43f5e")}>{sd.wind}</tspan>
                    </text>

                    {/* Row 2: Target Coordinates */}
                    <text x="-25" y="12" textAnchor="start" fill={isNight ? "#cbd5e1" : "#475569"} fontSize="11" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                        Target: ({sd.dx}, {sd.dy})
                    </text>
                </g>
            </g>
        ))}

        {/* Active Elements - Only visible when Live Path is ON */}
        {showCurrentTrajectory && (
            <>
                {/* Visual Interaction Area for Angle Control */}
                <circle 
                    cx={tankSvg.x} 
                    cy={tankSvg.y} 
                    r={knobRadius} 
                    fill="url(#angleGradient)" 
                    className="cursor-pointer hover:opacity-100 transition-opacity"
                    style={{ opacity: 0.8 }}
                />

                {/* Active Trajectory */}
                <path d={trajectoryPath} fill="none" stroke={mainColor} strokeWidth="4" strokeDasharray="10,10" className="opacity-80" />

                {/* Angle Indicator */}
                <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
                    <path d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`} fill="none" stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"} strokeWidth="2" strokeDasharray="4,4"/>
                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} stroke={mainColor} strokeWidth="3" strokeLinecap="round" />

                    {/* Draggable Knob Dot with Breathing Animation - Wrapped in Translated Group to fix Drifting */}
                    <g transform={`translate(${knobHandleX}, ${knobHandleY})`} style={{ pointerEvents: 'auto' }}>
                        <circle 
                            cx={0} 
                            cy={0} 
                            r={dragState.mode === 'KNOB' ? 8 : 6} 
                            fill={mainColor} 
                            stroke="white" 
                            strokeWidth="2" 
                            className={`transition-all duration-100 ease-in-out ${dragState.mode !== 'KNOB' ? 'breathing-dot' : ''}`}
                        />
                    </g>
                </g>

                {/* Tank / Player (At Origin) - Redesigned */}
                <g>
                    {/* Base Circle with Color Stroke */}
                    <circle 
                        cx={tankSvg.x} 
                        cy={tankSvg.y} 
                        r="18" 
                        fill={isNight ? "#0f172a" : "#ffffff"} 
                        stroke={mainColor} 
                        strokeWidth="3" 
                    />
                    {/* Angle Text in Center */}
                    <text 
                        x={tankSvg.x} 
                        y={tankSvg.y} 
                        dy="4" 
                        textAnchor="middle" 
                        fill={mainColor} 
                        fontSize="11" 
                        fontWeight="bold" 
                        fontFamily="'Varela Round', sans-serif"
                        className="pointer-events-none select-none"
                    >
                        {angle}°
                    </text>
                </g>

                {/* Target Marker */}
                <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
                    {/* Small solid dot (same color as trajectory) */}
                    <circle r="5" fill={mainColor} />
                    {/* Outer ring pulsing for visibility */}
                    <circle r="12" fill="none" stroke={mainColor} strokeWidth="1.5" opacity="0.6" className="animate-pulse" />

                    {/* Info Label - Compact and centered above the dot */}
                    <g transform="translate(0, -65)">
                        <rect x="-70" y="0" width="140" height="50" rx="6" fill={isNight ? "rgba(15, 23, 42, 0.9)" : "rgba(255, 255, 255, 0.9)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
                        <text x="0" y="20" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="16" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            ({dx}, {dy})
                        </text>
                        <text x="0" y="38" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            Wind: {wind}
                        </text>
                    </g>
                </g>

                {/* Impact Point */}
                {impactSvg && (
                    <circle cx={impactSvg.x} cy={impactSvg.y} r="8" fill="#fbbf24" stroke="white" strokeWidth="1" />
                )}
            </>
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

import React, { useState, useEffect, useMemo } from 'react';
import GameCanvas from './components/GameCanvas';
import Controls from './components/Controls';
import { GameMode, Point, PHYSICS_CONSTANTS, ThemeMode, SavedTrajectory } from './types';
import { solvePower, calculateTrajectory } from './services/physicsEngine';

// Tank position is fixed at origin for analysis view
const TANK_POS: Point = { x: 0, y: 0 }; 
// Initial target placed in a typical "shot" location (positive X, slight positive Y)
const INITIAL_TARGET: Point = { x: 15, y: 5 };

function App() {
  const [mode, setMode] = useState<GameMode>(GameMode.AUTO_AIM);
  const [isNight, setIsNight] = useState(false); // Default to Day mode
  const [zoom, setZoom] = useState(1.0); // 1.0 = Default view range defined in constants
  const [snapToGrid, setSnapToGrid] = useState(true); // Default to Snap ON
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [showCurrentTrajectory, setShowCurrentTrajectory] = useState(true); // New toggle state

  // Inputs
  const [angle, setAngle] = useState(65);
  const [wind, setWind] = useState(0);
  const [manualPower, setManualPower] = useState(50);
  const [target, setTarget] = useState<Point>(INITIAL_TARGET);

  // Memory / History
  const [savedTrajectories, setSavedTrajectories] = useState<SavedTrajectory[]>([]);

  // Derived State
  const [calculatedPower, setCalculatedPower] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  // 1. Logic Loop: Handle Physics Calculation
  useEffect(() => {
    // Relative distance components
    const dist = target.x - TANK_POS.x;
    const height = target.y - TANK_POS.y;

    if (dist <= 0) {
        setError("Target must be to the right of the player");
        setCalculatedPower(null);
        return;
    }

    // Try to solve for power
    const neededPower = solvePower(dist, height, angle, wind);

    if (neededPower === null) {
       setError("Target unreachable with current angle/wind");
       setCalculatedPower(null);
    } else if (neededPower === -99999) {
        setError("Force insufficient (Out of range or strong headwind)");
        setCalculatedPower(null);
    } else {
        setError(null);
        setCalculatedPower(neededPower);

        // If in Auto-Aim, sync manual power for smoother transition
        if (mode === GameMode.AUTO_AIM) {
            // Check bounds
            if (neededPower > 100) {
               setError("Required power exceeds limit (100)");
               setManualPower(100); 
            } else {
               setManualPower(neededPower);
            }
        }
    }
  }, [target, angle, wind, mode]);

  // 2. Logic Loop: Generate Trajectory Points
  const trajectory = useMemo(() => {
    return calculateTrajectory(TANK_POS, manualPower, angle, wind);
  }, [manualPower, angle, wind]);

  // Find where it hits ground or target height
  const impactPoint = useMemo(() => {
      if (trajectory.length === 0) return null;
      return trajectory[trajectory.length - 1];
  }, [trajectory]);

  // --- Memory Functions ---
  const saveCurrentTrajectory = () => {
      const newEntry: SavedTrajectory = {
          id: Date.now().toString(),
          power: manualPower,
          angle: angle,
          wind: wind,
          target: { ...target },
          visible: true,
          timestamp: Date.now()
      };
      setSavedTrajectories(prev => [newEntry, ...prev]);
  };

  const deleteTrajectory = (id: string) => {
      setSavedTrajectories(prev => prev.filter(t => t.id !== id));
  };

  const toggleTrajectoryVisibility = (id: string) => {
      setSavedTrajectories(prev => prev.map(t => 
        t.id === id ? { ...t, visible: !t.visible } : t
      ));
  };

  return (
    <div className={`fixed inset-0 w-full h-full flex overflow-hidden transition-colors duration-500 ${isNight ? 'bg-slate-950' : 'bg-slate-100'}`}>
        {/* Sidebar Controls (Left) */}
        <Controls 
            angle={angle}
            setAngle={setAngle}
            wind={wind}
            setWind={setWind}
            power={manualPower}
            setPower={setManualPower}
            mode={mode}
            setMode={setMode}
            target={target}
            tankPos={TANK_POS}
            calculationResult={calculatedPower}
            error={error}
            isNight={isNight}
            setIsNight={setIsNight}
            zoom={zoom}
            setZoom={setZoom}
            snapToGrid={snapToGrid}
            setSnapToGrid={setSnapToGrid}
            onSaveTrajectory={saveCurrentTrajectory}
            savedTrajectories={savedTrajectories}
            onDeleteTrajectory={deleteTrajectory}
            onToggleVisibility={toggleTrajectoryVisibility}
            isOpen={isSidebarOpen}
            onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
            showCurrentTrajectory={showCurrentTrajectory}
            onToggleCurrentTrajectory={() => setShowCurrentTrajectory(!showCurrentTrajectory)}
        />

        {/* Main Canvas Area */}
        <div className="flex-1 relative z-0 h-full p-4 flex flex-col items-center justify-center transition-all duration-300 ease-in-out">
            <div className="w-full h-full max-w-full max-h-[95vh] relative flex items-center justify-center">
                {/* Maintain aspect ratio of the physics world, adapted by zoom */}
                <div 
                  className="w-full h-full shadow-2xl rounded-xl overflow-hidden"
                >
                    <GameCanvas 
                        trajectory={trajectory}
                        target={target}
                        tankPos={TANK_POS}
                        onSetTarget={setTarget}
                        impactPoint={impactPoint}
                        angle={angle}
                        setAngle={setAngle}
                        zoom={zoom}
                        setZoom={setZoom}
                        isNight={isNight}
                        wind={wind}
                        setWind={setWind}
                        snapToGrid={snapToGrid}
                        savedTrajectories={savedTrajectories}
                        showCurrentTrajectory={showCurrentTrajectory}
                    />
                </div>
            </div>
             <div className={`mt-2 text-sm ${isNight ? 'text-slate-500' : 'text-slate-400'} ${!isSidebarOpen ? 'opacity-50' : 'opacity-100'} transition-opacity`}>
                Click map to move target • Drag angle pointer to aim • Zoom to see more
            </div>
        </div>
    </div>
  );
}

export default App;

