import React from 'react';
import { GameMode, Point, SavedTrajectory } from '../types';
import { Wind, Crosshair, Zap, MousePointer2, Sun, Moon, Magnet, Save, Trash2, Eye, EyeOff, Plus, Minus, ChevronRight, ChevronLeft, Activity } from 'lucide-react';

interface ControlsProps {
  angle: number;
  setAngle: (v: number) => void;
  wind: number;
  setWind: (v: number) => void;
  power: number;
  setPower: (v: number) => void;
