import React, { useState, useEffect, useMemo } from 'react';
import GameCanvas from './components/GameCanvas';
import Controls from './components/Controls';
import { GameMode, Point, PHYSICS_CONSTANTS, ThemeMode, SavedTrajectory } from './types';
import { solvePower, calculateTrajectory } from './services/physicsEngine';

// Tank position is fixed at origin for analysis view
const TANK_POS: Point = { x: 0, y: 0 }; 
// Initial target placed in a typical "shot" location (positive X, slight positive Y)
const INITIAL_TARGET: Point = { x: 15, y: 5 };

export const TRAJECTORY_COLORS = [
  '#a855f7', // Purple
  '#ef4444', // Red
  '#22c55e', // Green
  '#3b82f6', // Blue
  '#f97316', // Orange
  '#06b6d4', // Cyan
];

function App() {
  const [mode, setMode] = useState<GameMode>(GameMode.AUTO_AIM);
  const [isNight, setIsNight] = useState(false); // Default to Day mode
  const [zoom, setZoom] = useState(1.0); // 1.0 = Default view range defined in constants
  const [snapToGrid, setSnapToGrid] = useState(true); // Default to Snap ON
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [showCurrentTrajectory, setShowCurrentTrajectory] = useState(true); // New toggle state

  // Inputs
  const [angle, setAngle] = useState(65);
  const [wind, setWind] = useState(0);
  const [manualPower, setManualPower] = useState(50);
  const [target, setTarget] = useState<Point>(INITIAL_TARGET);

  // Memory / History
  const [savedTrajectories, setSavedTrajectories] = useState<SavedTrajectory[]>([]);

  // Derived State
  const [calculatedPower, setCalculatedPower] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  // 0. Theme Sync Effect: Ensure body background matches app theme to prevent "black bars"
  useEffect(() => {
    document.body.className = isNight 
        ? 'bg-slate-950 text-slate-100 overflow-hidden' 
        : 'bg-slate-100 text-slate-900 overflow-hidden';
  }, [isNight]);

  // 1. Logic Loop: Handle Physics Calculation
  useEffect(() => {
    // Relative distance components
    const dist = target.x - TANK_POS.x;
    const height = target.y - TANK_POS.y;

    if (dist <= 0) {
        setError("Target must be to the right of the player");
        setCalculatedPower(null);
        return;
    }

    // Try to solve for power
    const neededPower = solvePower(dist, height, angle, wind);

    if (neededPower === null) {
       setError("Target unreachable with current angle/wind");
       setCalculatedPower(null);
    } else if (neededPower === -99999) {
        setError("Force insufficient (Out of range or strong headwind)");
        setCalculatedPower(null);
    } else {
        setError(null);
        setCalculatedPower(neededPower);

        // If in Auto-Aim, sync manual power for smoother transition
        if (mode === GameMode.AUTO_AIM) {
            // Check bounds
            if (neededPower > 100) {
               setError("Required power exceeds limit (100)");
               setManualPower(100); 
            } else {
               setManualPower(neededPower);
            }
        }
    }
  }, [target, angle, wind, mode]);

  // 2. Logic Loop: Generate Trajectory Points
  const trajectory = useMemo(() => {
    return calculateTrajectory(TANK_POS, manualPower, angle, wind);
  }, [manualPower, angle, wind]);

  // Find where it hits ground or target height
  const impactPoint = useMemo(() => {
      if (trajectory.length === 0) return null;
      return trajectory[trajectory.length - 1];
  }, [trajectory]);

  // --- Memory Functions ---
  const saveCurrentTrajectory = () => {
      const newEntry: SavedTrajectory = {
          id: Date.now().toString(),
          power: manualPower,
          angle: angle,
          wind: wind,
          target: { ...target },
          visible: true,
          color: TRAJECTORY_COLORS[0], // Default to first color
          timestamp: Date.now()
      };
      setSavedTrajectories(prev => [newEntry, ...prev]);
  };

  const deleteTrajectory = (id: string) => {
      setSavedTrajectories(prev => prev.filter(t => t.id !== id));
  };

  const toggleTrajectoryVisibility = (id: string) => {
      setSavedTrajectories(prev => prev.map(t => 
        t.id === id ? { ...t, visible: !t.visible } : t
      ));
  };

  const updateTrajectoryColor = (id: string, newColor: string) => {
    setSavedTrajectories(prev => prev.map(t => {
        if (t.id !== id) return t;
        return { ...t, color: newColor };
    }));
  };

  const toggleColorVisibility = (color: string) => {
      setSavedTrajectories(prev => {
          // Check if all items of this color are currently visible
          const group = prev.filter(t => t.color === color);
          if (group.length === 0) return prev;

          const allVisible = group.every(t => t.visible);

          // If all visible -> hide all. Otherwise -> show all.
          return prev.map(t => {
              if (t.color === color) {
                  return { ...t, visible: !allVisible };
              }
              return t;
          });
      });
  };

  return (
    <div className={`fixed inset-0 w-full h-full flex overflow-hidden transition-colors duration-500 ${isNight ? 'bg-slate-950' : 'bg-slate-100'}`}>
        <style>{`
          /* Dynamic Scrollbar Theming */
          ::-webkit-scrollbar-thumb {
            background-color: ${isNight ? '#334155' : '#cbd5e1'};
          }
          ::-webkit-scrollbar-thumb:hover {
            background-color: ${isNight ? '#475569' : '#94a3b8'};
          }
          ::-webkit-scrollbar-track {
            background-color: transparent;
          }
        `}</style>

        {/* Sidebar Controls (Left) 
            - On Desktop (md+), this is relative and pushes content.
            - On Mobile, this is absolute/fixed and overlays content.
        */}
        <Controls 
            angle={angle}
            setAngle={setAngle}
            wind={wind}
            setWind={setWind}
            power={manualPower}
            setPower={setManualPower}
            mode={mode}
            setMode={setMode}
            target={target}
            tankPos={TANK_POS}
            calculationResult={calculatedPower}
            error={error}
            isNight={isNight}
            setIsNight={setIsNight}
            zoom={zoom}
            setZoom={setZoom}
            snapToGrid={snapToGrid}
            setSnapToGrid={setSnapToGrid}
            onSaveTrajectory={saveCurrentTrajectory}
            savedTrajectories={savedTrajectories}
            onDeleteTrajectory={deleteTrajectory}
            onToggleVisibility={toggleTrajectoryVisibility}
            onUpdateColor={updateTrajectoryColor}
            onToggleColorVisibility={toggleColorVisibility}
            isOpen={isSidebarOpen}
            onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
            showCurrentTrajectory={showCurrentTrajectory}
            onToggleCurrentTrajectory={() => setShowCurrentTrajectory(!showCurrentTrajectory)}
        />

        {/* Main Canvas Area */}
        <div className="flex-1 relative z-0 h-full w-full min-w-0 p-4 flex flex-col items-center justify-center transition-all duration-300 ease-in-out">
            <div className="w-full h-full max-w-full max-h-[95vh] relative flex items-center justify-center">
                {/* Maintain aspect ratio of the physics world, adapted by zoom */}
                <div 
                  className="w-full h-full shadow-2xl rounded-xl overflow-hidden"
                >
                    <GameCanvas 
                        trajectory={trajectory}
                        target={target}
                        tankPos={TANK_POS}
                        onSetTarget={setTarget}
                        impactPoint={impactPoint}
                        angle={angle}
                        setAngle={setAngle}
                        zoom={zoom}
                        setZoom={setZoom}
                        isNight={isNight}
                        wind={wind}
                        setWind={setWind}
                        snapToGrid={snapToGrid}
                        savedTrajectories={savedTrajectories}
                        showCurrentTrajectory={showCurrentTrajectory}
                    />
                </div>
            </div>
             <div className={`mt-2 text-sm ${isNight ? 'text-slate-500' : 'text-slate-400'} ${!isSidebarOpen ? 'opacity-50' : 'opacity-100'} transition-opacity text-center px-4`}>
                Click map to move target • Drag angle pointer to aim • Zoom to see more
            </div>
        </div>
    </div>
  );
}

export default App;

import React, { useMemo, useState } from 'react';
import { GameMode, Point, SavedTrajectory } from '../types';
import { Wind, Crosshair, Zap, MousePointer2, Sun, Moon, Magnet, Save, Trash2, Eye, EyeOff, Plus, Minus, ChevronRight, ChevronLeft, Activity, Filter, Palette } from 'lucide-react';
import { TRAJECTORY_COLORS } from '../App';

interface ControlsProps {
  angle: number;
  setAngle: (v: number) => void;
  wind: number;
  setWind: (v: number) => void;
  power: number;
  setPower: (v: number) => void;
  mode: GameMode;
  setMode: (m: GameMode) => void;
  target: Point;
  tankPos: Point;
  calculationResult: number | null;
  error: string | null;
  isNight: boolean;
  setIsNight: (v: boolean) => void;
  zoom: number;
  setZoom: (v: number) => void;
  snapToGrid: boolean;
  setSnapToGrid: (v: boolean) => void;
  // Memory props
  onSaveTrajectory: () => void;
  savedTrajectories: SavedTrajectory[];
  onDeleteTrajectory: (id: string) => void;
  onToggleVisibility: (id: string) => void;
  onUpdateColor: (id: string, color: string) => void;
  onToggleColorVisibility: (color: string) => void;
  // Sidebar State
  isOpen: boolean;
  onToggle: () => void;
  // Live Trajectory Toggle
  showCurrentTrajectory: boolean;
  onToggleCurrentTrajectory: () => void;
}

const Controls: React.FC<ControlsProps> = ({
  angle,
  setAngle,
  wind,
  setWind,
  power,
  setPower,
  mode,
  setMode,
  target,
  tankPos,
  calculationResult,
  error,
  isNight,
  setIsNight,
  zoom,
  setZoom,
  snapToGrid,
  setSnapToGrid,
  onSaveTrajectory,
  savedTrajectories,
  onDeleteTrajectory,
  onToggleVisibility,
  onUpdateColor,
  onToggleColorVisibility,
  isOpen,
  onToggle,
  showCurrentTrajectory,
  onToggleCurrentTrajectory
}) => {
  const [editingColorId, setEditingColorId] = useState<string | null>(null);

  const dist = Math.abs(target.x - tankPos.x).toFixed(2);
  const heightDiff = (target.y - tankPos.y).toFixed(2);

  const handleModeToggle = (newMode: GameMode) => {
    setMode(newMode);
    if (newMode === GameMode.AUTO_AIM && calculationResult) {
      setPower(calculationResult);
    }
  };

  const adjustAngle = (delta: number) => {
    setAngle(Math.min(180, Math.max(0, angle + delta)));
  };

  const adjustWind = (delta: number) => {
    setWind(Number((Math.min(150, Math.max(-150, wind + delta))).toFixed(1)));
  };

  const adjustPower = (delta: number) => {
     setMode(GameMode.MANUAL);
     setPower(Number((Math.min(100, Math.max(0, power + delta))).toFixed(1)));
  };

  // Determine which colors are currently used
  const activeColorStats = useMemo(() => {
    const stats: Record<string, { count: number, visibleCount: number }> = {};
    savedTrajectories.forEach(t => {
      if (!stats[t.color]) {
        stats[t.color] = { count: 0, visibleCount: 0 };
      }
      stats[t.color].count++;
      if (t.visible) stats[t.color].visibleCount++;
    });
    return stats;
  }, [savedTrajectories]);

  // Sort trajectories: Group by Color Index, then by Timestamp (Newest first)
  const sortedTrajectories = useMemo(() => {
      return [...savedTrajectories].sort((a, b) => {
          const colorIdxA = TRAJECTORY_COLORS.indexOf(a.color);
          const colorIdxB = TRAJECTORY_COLORS.indexOf(b.color);

          if (colorIdxA !== colorIdxB) {
              return colorIdxA - colorIdxB;
          }
          return b.timestamp - a.timestamp;
      });
  }, [savedTrajectories]);

  const themeClasses = isNight 
    ? {
      bg: 'bg-slate-900',
      border: 'border-slate-700',
      text: 'text-white',
