                  >
                      {isNight ? <Moon size={20} /> : <Sun size={20} />}
                  </button>
              </div>

              {/* Mode Switcher */}
              <div className={`grid grid-cols-2 gap-2 p-1 ${isNight ? 'bg-slate-800' : 'bg-slate-200'} rounded-lg`}>
