                  {activeTab !== 'ALL' && activeColorStats[activeTab]?.count > 0 && (
                      <div className={`flex items-center justify-between px-2 py-1.5 mb-2 rounded text-[10px] ${isNight ? 'bg-slate-800' : 'bg-slate-100'} animate-in fade-in slide-in-from-top-1`}>
                          <span className={themeClasses.subText}>Group Actions ({activeColorStats[activeTab].count} items)</span>
                          <button onClick={() => onToggleColorVisibility(activeTab)} className="flex items-center gap-1.5 hover:bg-white/10 px-1.5 py-0.5 rounded transition-colors" style={{ color: activeTab }}>
                              {activeColorStats[activeTab].visibleCount === activeColorStats[activeTab].count ? <><Eye size={12} /> Hide All</> : <><EyeOff size={12} /> Show All</>}
