                                className={`p-2 rounded text-xs flex flex-col gap-2 group border transition-all hover:shadow-sm cursor-pointer relative
                                ${selectedIds.includes(t.id) 
                                    ? (isNight ? 'bg-slate-800 border-sky-500 ring-1 ring-sky-500' : 'bg-white border-sky-500 ring-1 ring-sky-500') 
                                    : (isNight ? 'bg-slate-800 border-slate-700' : 'bg-slate-100 border-slate-200')}
                                `}
                              >
                                  <div className="flex items-center justify-between">
                                      <div className="flex items-center gap-2">
                                          {editingColorId === t.id ? (
                                              <div className={`flex items-center gap-1 p-1 rounded-full ${isNight ? 'bg-slate-700' : 'bg-slate-200'} animate-in slide-in-from-left-2 fade-in duration-200`}>
                                                  {TRAJECTORY_COLORS.map(c => (
                                                      <button key={c} onClick={(e) => { e.stopPropagation(); onUpdateColor(t.id, c); setEditingColorId(null); }} className={`w-3 h-3 rounded-full hover:scale-125 transition-transform border border-transparent hover:border-white/50`} style={{ backgroundColor: c }} />
                                                  ))}
                                              </div>
                                          ) : (
                                              <button onClick={(e) => {e.stopPropagation(); setEditingColorId(t.id)}} className="w-4 h-4 rounded-full hover:scale-110 transition-transform ring-2 ring-transparent hover:ring-offset-1 hover:ring-slate-400 shadow-sm" style={{ backgroundColor: t.color }} />
                                          )}

                                          <div className="flex flex-col gap-0.5">
                                            {/* Show visual indicator for selection order */}
                                            {selectedIds.includes(t.id) && (
                                                <div className="text-[9px] font-bold text-sky-500">
                                                    {selectedIds.indexOf(t.id) === 0 ? "1st Selection" : "2nd Selection"}
                                                </div>
                                            )}
                                            <div className="font-mono text-[10px] font-bold" style={{ color: t.color }}>
                                                P:{t.power.toFixed(1)} A:{t.angle}° W:{t.wind}
                                            </div>
                                            <div className={`${themeClasses.subText} text-[10px]`}>
                                                Target: ({t.target.x.toFixed(1)}, {t.target.y.toFixed(1)})
                                            </div>
                                          </div>
                                      </div>

                                      <div className="flex items-center gap-1">
                                          {selectedIds.includes(t.id) && (
                                              <CheckCircle2 size={14} className="text-sky-500 mr-1 animate-in zoom-in" />
                                          )}
                                          <div className="flex items-center gap-1 opacity-60 group-hover:opacity-100 transition-opacity">
                                            <button onClick={(e) => {e.stopPropagation(); onToggleVisibility(t.id)}} className={`p-1 hover:bg-white/10 rounded ${t.visible ? 'text-sky-400' : 'text-slate-500'}`}>
                                                {t.visible ? <Eye size={14} /> : <EyeOff size={14} />}
                                            </button>
                                            <button onClick={(e) => {e.stopPropagation(); onDeleteTrajectory(t.id)}} className="p-1 hover:bg-white/10 rounded text-red-400 hover:text-red-500">
                                                <Trash2 size={14} />
                                            </button>
                                          </div>
                                      </div>
                                  </div>
                              </div>
                          ))
                      )}
                  </div>
              </div>
          </div>
          <div className={`p-6 border-t ${themeClasses.border}`}>
              {error ? (
              <div className="bg-red-500/10 border border-red-500/30 p-3 rounded text-red-500 text-sm flex items-center gap-2">
                  <span className="font-bold">ERROR:</span> {error}
              </div>
              ) : (
                  <div className="flex items-center justify-between text-sm">
                      <span className={themeClasses.subText}>System Status</span>
                      <span className="text-emerald-500 font-mono flex items-center gap-1.5">
                          <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                          READY
                      </span>
                  </div>
              )}
          </div>
        </div>
      </div>
    </>
  );
};

export default Controls;

import React, { useRef, useMemo, useState, useEffect } from 'react';
import { Point, PHYSICS_CONSTANTS, SavedTrajectory, AnalysisItem } from '../types';
import { Wind, ZoomIn, ZoomOut, X } from 'lucide-react';
import { calculateTrajectory } from '../services/physicsEngine';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  setZoom: (z: number) => void;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
  snapToGrid: boolean;
  savedTrajectories: SavedTrajectory[];
  analysisItems?: AnalysisItem[]; // New prop for separately managed analysis items
  onDeleteAnalysis?: (id: string) => void; // Handler to delete analysis item
  showCurrentTrajectory: boolean;
}

interface DragState {
    mode: 'IDLE' | 'PAN' | 'TARGET' | 'KNOB' | 'LABEL' | 'AWAIT_PAN_OR_CLICK';
    startScreen: Point;
    startPan: Point; // Physics units
    activeId?: string;
    hasMoved?: boolean;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  setZoom,
  isNight,
  wind,
  setWind,
  snapToGrid,
  savedTrajectories,
  analysisItems = [],
  onDeleteAnalysis,
  showCurrentTrajectory
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  // Track container size for responsive aspect ratio
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

  // Widget Hover States
  const [isWindExpanded, setIsWindExpanded] = useState(false);
  const windTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [isZoomExpanded, setIsZoomExpanded] = useState(false);
  const zoomTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // --- Interaction Logic for Wind Widget ---
  const handleWindEnter = () => {
    if (windTimeoutRef.current) clearTimeout(windTimeoutRef.current);
    setIsWindExpanded(true);
  };

  const handleWindLeave = () => {
    windTimeoutRef.current = setTimeout(() => {
        setIsWindExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };

  // --- Interaction Logic for Zoom Widget ---
  const handleZoomEnter = () => {
    if (zoomTimeoutRef.current) clearTimeout(zoomTimeoutRef.current);
    setIsZoomExpanded(true);
  };

  const handleZoomLeave = () => {
    zoomTimeoutRef.current = setTimeout(() => {
        setIsZoomExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };


  useEffect(() => {
    if (!containerRef.current) return;

    const updateSize = () => {
        if (containerRef.current) {
            const { width, height } = containerRef.current.getBoundingClientRect();
            if (width > 0 && height > 0) {
                setContainerSize({ width, height });
            }
        }
    };

    // Initial size
    updateSize();

    const observer = new ResizeObserver(updateSize);
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  // Viewport State: Pan Offset in Physics Units
  const [pan, setPan] = useState({ x: 0, y: 0 }); 

  // Custom offsets for saved labels (SVG px relative to target)
  const [labelOffsets, setLabelOffsets] = useState<Record<string, Point>>({});

  // Interaction State Machine
  const [dragState, setDragState] = useState<DragState>({ 
      mode: 'IDLE', 
      startScreen: { x: 0, y: 0 }, 
      startPan: { x: 0, y: 0 } 
  });

  // --- Pinch Zoom State ---
  const pinchRef = useRef({
      active: false,
      initialDist: 0,
      initialZoom: 1,
      initialPan: { x: 0, y: 0 },
      centerX: 0.5, // normalized 0-1
      centerY: 0.5  // normalized 0-1
  });

  // --- Viewport Calculations ---
  // We anchor the Vertical range and the Left side (Min X) based on constants + zoom.
  // We expand the Right side (Max X) based on the aspect ratio of the container.

  const aspectRatio = containerSize.height > 0 ? containerSize.width / containerSize.height : 1;

  // Base heights from constants
  const baseHeight = PHYSICS_CONSTANTS.MAX_Y - PHYSICS_CONSTANTS.MIN_Y;

  // Calculate visible range in physics units
  const currentHeight = baseHeight * zoom;
  const currentWidth = currentHeight * aspectRatio;

  const currentMinY = (PHYSICS_CONSTANTS.MIN_Y * zoom) + pan.y;
  const currentMaxY = currentMinY + currentHeight;

  // Anchor Left side to MIN_X
  const currentMinX = (PHYSICS_CONSTANTS.MIN_X * zoom) + pan.x;
  const currentMaxX = currentMinX + currentWidth;

  // Fixed SVG Resolution scaling
  const PIXELS_PER_UNIT = 40; 
  const VIEWBOX_WIDTH = currentWidth * PIXELS_PER_UNIT; 
  const VIEWBOX_HEIGHT = currentHeight * PIXELS_PER_UNIT;

  // --- Scale Factor for UI Elements ---
  // Calculates how many SVG units correspond to 1 screen pixel.
  // This allows us to scale text/UI so they look constant size on screen.
  const pixelScale = useMemo(() => {
    if (containerSize.width <= 0) return 1;
    return VIEWBOX_WIDTH / containerSize.width;
  }, [VIEWBOX_WIDTH, containerSize.width]);

  const toSvg = (p: Point) => {
    const percentX = (p.x - currentMinX) / currentWidth;
    const percentY = (p.y - currentMinY) / currentHeight;
    return {
        x: percentX * VIEWBOX_WIDTH,
        y: VIEWBOX_HEIGHT - (percentY * VIEWBOX_HEIGHT)
    };
  };

  const fromSvg = (svgX: number, svgY: number): Point => {
    const percentX = svgX / VIEWBOX_WIDTH;
    const percentY = (VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT; 
    return {
        x: currentMinX + percentX * currentWidth,
        y: currentMinY + percentY * currentHeight
    };
  };

  // Accurate SVG point from screen coordinates
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    let point = new DOMPoint(clientX, clientY);
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, currentMinX, currentMinY, currentWidth, currentHeight]); 

  // --- Saved Data Preparation ---
  // Pre-calculate positions for rendering and hit-testing
  // Refactored to handle dependency chain (Standard Labels -> Analysis Labels)
  const savedData = useMemo(() => {
    // We mix SavedTrajectories and AnalysisItems into a single render list
    // Standard trajectories first, so Analysis can find them
    const sortedByTime = [...savedTrajectories].sort((a, b) => a.timestamp - b.timestamp);

    // Map to store calculated label positions for lookup
    const processedMap = new Map<string, any>();

    sortedByTime.forEach((t) => {
        if (!t.visible) return;

        const d = pointsToPath(calculateTrajectory(tankPos, t.power, t.angle, t.wind));
        const targetSvg = toSvg(t.target);
        const dx = (t.target.x - tankPos.x).toFixed(1);
        const dy = (t.target.y - tankPos.y).toFixed(1);

        // Standard Positioning
        const originalIndex = savedTrajectories.findIndex(st => st.id === t.id);
        const defaultOffsetPx = { x: 0, y: -(40 + (originalIndex % 5) * 45) };
        const defaultOffsetSvg = { 
            x: defaultOffsetPx.x * pixelScale, 
            y: defaultOffsetPx.y * pixelScale 
        };

        const offset = labelOffsets[t.id] || defaultOffsetSvg;
        const usedOffset = offset;
        const labelPos = { x: targetSvg.x + offset.x, y: targetSvg.y + offset.y };

        const data = { 
           id: t.id, 
           d, 
           power: t.power,
           angle: t.angle, 
           wind: t.wind, 
           dx, dy, 
           targetPos: targetSvg,
           labelPos,
           color: t.color,
           isAnalysis: false,
           offset: usedOffset
        };

        processedMap.set(t.id, data);
    });

    // Process Analysis Items
    analysisItems.forEach((item) => {
        if (!item.visible) return;

        let labelPos = { x: 0, y: 0 };
        let connectorStartPoints = undefined; // [ {x,y}, {x,y} ] - Coordinates of parent right edges
        let usedOffset = { x: 0, y: 0 };

        if (item.parentIds && item.parentIds.length === 2) {
             const p1 = processedMap.get(item.parentIds[0]);
             const p2 = processedMap.get(item.parentIds[1]);

             if (p1 && p2) {
                 // Dynamic Positioning: To the right of parents
                 // Standard Label Half-Width = 85 (Total 170)
                 const p1Right = p1.labelPos.x + (85 * pixelScale);
                 const p2Right = p2.labelPos.x + (85 * pixelScale);

                 // Base position is right of the furthest parent + gap
                 // We add a significant gap to allow for the polyline structure
                 const baseX = Math.max(p1Right, p2Right) + (80 * pixelScale);
                 const baseY = (p1.labelPos.y + p2.labelPos.y) / 2;

                 connectorStartPoints = [
                     { x: p1Right, y: p1.labelPos.y },
                     { x: p2Right, y: p2.labelPos.y }
                 ];

                 const offset = labelOffsets[item.id] || { x: 0, y: 0 };
                 usedOffset = offset;
                 labelPos = { x: baseX + offset.x, y: baseY + offset.y };
             } else {
                 // Fallback if parents missing
                 const targetSvg = toSvg(item.target);
                 const offset = labelOffsets[item.id] || { x: 0, y: -40 * pixelScale };
                 usedOffset = offset;
                 labelPos = { x: targetSvg.x + offset.x, y: targetSvg.y + offset.y };
             }
        }

        const data = {
            id: item.id,
            power: item.powerDiff, // Reuse power field for Diff
            labelPos,
            color: item.color,
            isAnalysis: true,
            connectorStartPoints,
            offset: usedOffset,
            targetPos: toSvg(item.target) // Just for hit testing proximity if needed
        };
         processedMap.set(item.id, data);
    });

    // Return array: Standard Trajectories followed by Analysis Items (so Analysis renders on top)
    const renderList = [
        ...sortedByTime.map(t => processedMap.get(t.id)),
        ...analysisItems.map(a => processedMap.get(a.id))
    ].filter(Boolean);

    return renderList;

  }, [savedTrajectories, analysisItems, tankPos, zoom, currentMinX, currentMinY, currentWidth, currentHeight, labelOffsets, pixelScale]);

  // --- Interaction Handlers ---

  const handleTouchStart = (e: React.TouchEvent) => {
      if (e.touches.length === 2) {
          e.preventDefault();
          const t1 = e.touches[0];
          const t2 = e.touches[1];

          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          // Calculate centroid relative to container
          const rect = containerRef.current?.getBoundingClientRect();
          if (!rect) return;

          const cx = ((t1.clientX + t2.clientX) / 2) - rect.left;
          const cy = ((t1.clientY + t2.clientY) / 2) - rect.top;

          pinchRef.current = {
              active: true,
              initialDist: dist,
              initialZoom: zoom,
              initialPan: { ...pan },
              centerX: cx / rect.width,
              centerY: cy / rect.height
          };

          // Cancel any active drag/pan
          setDragState(prev => ({ ...prev, mode: 'IDLE' }));
      }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      if (e.touches.length === 2 && pinchRef.current.active) {
          e.preventDefault();
          e.stopPropagation();

          const t1 = e.touches[0];
          const t2 = e.touches[1];
          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          if (pinchRef.current.initialDist > 10 && dist > 10) {
              const ratio = dist / pinchRef.current.initialDist;
              // Larger distance (spread) -> Smaller zoom value (Zoom In/Close up)
              let newZoom = pinchRef.current.initialZoom / ratio;
              newZoom = Math.max(0.25, Math.min(2.5, newZoom));

              // Calculate Pan compensation to zoom towards center
              // Formula: pan_new = pan_old + M * (z_old - z_new)
              const deltaZ = pinchRef.current.initialZoom - newZoom;

              // M_x = MIN_X + CenterX * Height * AR
              const Mx = PHYSICS_CONSTANTS.MIN_X + (pinchRef.current.centerX * baseHeight * aspectRatio);

              // M_y = MIN_Y + (1 - CenterY) * Height
              // Note: CenterY is 0 at top, 1 at bottom. Physics Y is 0 at bottom (relative to MIN_Y).
              const My = PHYSICS_CONSTANTS.MIN_Y + ((1 - pinchRef.current.centerY) * baseHeight);

              const newPanX = pinchRef.current.initialPan.x + (Mx * deltaZ);
              const newPanY = pinchRef.current.initialPan.y + (My * deltaZ);

              setZoom(newZoom);
              setPan({ x: newPanX, y: newPanY });
          }
      }
  };

  const handleTouchEnd = () => {
      pinchRef.current.active = false;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    // If pinch is active, ignore single pointer events
    if (pinchRef.current.active) return;

    if (!svgRef.current) return;
    (e.target as Element).setPointerCapture(e.pointerId);

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);
    const screenPt = { x: e.clientX, y: e.clientY };

    // 1. Check Angle Knob / Area (Only if active)
    const tankSvg = toSvg(tankPos);

    // Visual radius of the knob control (roughly 80px on screen)
    const knobRadius = 80 * pixelScale;
    const distToTank = Math.hypot(clickX - tankSvg.x, clickY - tankSvg.y);

    if (showCurrentTrajectory && distToTank < knobRadius + (10 * pixelScale)) {
        setDragState({ mode: 'KNOB', startScreen: screenPt, startPan: pan });
        return;
    }

    // 2. Check Saved Labels (Top-most first for hitting, so iterate reverse of render order?)
    // savedData is Old -> New (Render Order). 
    // Hit test should be New -> Old (Top -> Bottom).
    for (let i = savedData.length - 1; i >= 0; i--) {
        const item = savedData[i];

        // Define Hitbox size based on type
        // Analysis: 90x24 (Half 45x12)
        // Standard: 170x34 (Half 85x17)
        const halfW = item.isAnalysis ? 45 * pixelScale : 85 * pixelScale;
        const halfH = item.isAnalysis ? 12 * pixelScale : 17 * pixelScale;

        if (
            clickX >= item.labelPos.x - halfW && clickX <= item.labelPos.x + halfW &&
            clickY >= item.labelPos.y - halfH && clickY <= item.labelPos.y + halfH
        ) {
            setDragState({ 
                mode: 'LABEL', 
                startScreen: screenPt, 
                startPan: pan, 
                activeId: item.id
            });
            return;
        }
    }

    // 3. Check Active Target (Only if active)
    const targetSvg = toSvg(target);
    const targetHitRadius = 30 * pixelScale;
    if (showCurrentTrajectory && Math.hypot(clickX - targetSvg.x, clickY - targetSvg.y) < targetHitRadius) {
        setDragState({ mode: 'TARGET', startScreen: screenPt, startPan: pan });
        return;
    }

    // 4. Background -> Pan or Click
    setDragState({ 
        mode: 'AWAIT_PAN_OR_CLICK', 
        startScreen: screenPt, 
        startPan: pan, 
        hasMoved: false
    });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // If pinch active, ignore
    if (pinchRef.current.active) return;

    if (!svgRef.current) return;
    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    // Calculate screen deltas
    const dxScreen = e.clientX - dragState.startScreen.x;
    const dyScreen = e.clientY - dragState.startScreen.y;

    if (dragState.mode === 'KNOB') {
        const tankSvg = toSvg(tankPos);
        // Angle calc
        let newAngle = Math.atan2(-(pointerY - tankSvg.y), (pointerX - tankSvg.x)) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;
        if (newAngle > 180) newAngle = 180; 

        // Snap to integer angle for cleaner UI
        setAngle(Math.round(newAngle));

    } else if (dragState.mode === 'LABEL' && dragState.activeId) {
        const currentItem = savedData.find(sd => sd.id === dragState.activeId);
        if (currentItem && currentItem.offset) {
             const basePosX = currentItem.labelPos.x - currentItem.offset.x;
             const basePosY = currentItem.labelPos.y - currentItem.offset.y;

             let destX = pointerX;
             let destY = pointerY;

             // Snap logic
             if (snapToGrid) {
                 const physPoint = fromSvg(destX, destY);
                 const snappedPhysX = Math.round(physPoint.x);
                 const snappedPhysY = Math.round(physPoint.y);
                 const snappedSvg = toSvg({ x: snappedPhysX, y: snappedPhysY });
                 destX = snappedSvg.x;
                 destY = snappedSvg.y;
             }

             setLabelOffsets(prev => ({
                ...prev,
                [dragState.activeId!]: {
                    x: destX - basePosX,
                    y: destY - basePosY
                }
             }));
        }

    } else if (dragState.mode === 'TARGET') {
        const physicsPoint = fromSvg(pointerX, pointerY);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });

    } else if (dragState.mode === 'PAN' || (dragState.mode === 'AWAIT_PAN_OR_CLICK' && Math.hypot(dxScreen, dyScreen) > 5)) {
        if (dragState.mode === 'AWAIT_PAN_OR_CLICK') {
            setDragState(prev => ({ ...prev, mode: 'PAN', hasMoved: true }));
        }

        const ctm = svgRef.current?.getScreenCTM();
        const scaleX = ctm ? ctm.a : 1; 

        const dxPhys = -dxScreen / (PIXELS_PER_UNIT * scaleX);
        const dyPhys = dyScreen / (PIXELS_PER_UNIT * scaleX);

        setPan({
            x: dragState.startPan.x + dxPhys,
            y: dragState.startPan.y + dyPhys
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    (e.target as Element).releasePointerCapture(e.pointerId);

    if (showCurrentTrajectory && dragState.mode === 'AWAIT_PAN_OR_CLICK' && !dragState.hasMoved) {
        const { x, y } = getSvgPoint(e.clientX, e.clientY);
        const physicsPoint = fromSvg(x, y);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });
    }

    setDragState({ mode: 'IDLE', startScreen: {x:0, y:0}, startPan: {x:0, y:0} });
  };

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = (target.y - tankPos.y).toFixed(2); 

  // Generate Grid Lines
  const gridLines = useMemo(() => {
    const lines = [];
    const startX = Math.floor(currentMinX);
    const endX = Math.ceil(currentMaxX);
    const startY = Math.floor(currentMinY);
    const endY = Math.ceil(currentMaxY);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const axisColor = isNight ? "#94a3b8" : "#475569"; 
    const minorColor = isNight ? "rgba(51, 65, 85, 0.4)" : "rgba(203, 213, 225, 0.6)";
    const textColor = isNight ? "#64748b" : "#94a3b8";

    const strokeW = Math.max(1 * pixelScale, 1); 
    const fontSz = 12 * pixelScale; 

    const useSparseGrid = zoom > 1.5;

    for (let i = startX; i <= endX; i++) {
        const p = toSvg({ x: i, y: 0 }); 
        const x = p.x;
        if (x < -50 * pixelScale || x > VIEWBOX_WIDTH + 50 * pixelScale) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 12 === 0; 

        if (useSparseGrid && !isAxis && !isMajor) continue;

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? strokeW * 2 : strokeW} 
                strokeDasharray={isAxis || isMajor ? "" : `${4 * pixelScale},${2 * pixelScale}`}
            />
        );

        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + (4 * pixelScale)} 
                y={VIEWBOX_HEIGHT - (10 * pixelScale)} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={fontSz}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
                style={{ userSelect: 'none' }}
            >
                {i}
            </text>
        );
    }

    for (let i = startY; i <= endY; i++) {
        const p = toSvg({ x: 0, y: i }); 
        const y = p.y;
        if (y < -50 * pixelScale || y > VIEWBOX_HEIGHT + 50 * pixelScale) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 6 === 0;

        if (useSparseGrid && !isAxis && !isMajor) continue;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? strokeW * 2 : strokeW} 
                strokeDasharray={isAxis || isMajor ? "" : `${4 * pixelScale},${2 * pixelScale}`}
            />
        );

        lines.push(
            <text 
                key={`th-${i}`} 
                x={10 * pixelScale} 
                y={y - (4 * pixelScale)} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={fontSz}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
                style={{ userSelect: 'none' }}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [currentMinX, currentMaxX, currentMinY, currentMaxY, VIEWBOX_WIDTH, VIEWBOX_HEIGHT, isNight, toSvg, pixelScale, zoom]);

  const knobRadius = 80 * pixelScale; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // Dynamic Styles for Wind Widget
  const windWidgetClasses = isNight 
    ? 'bg-slate-800/95 border-slate-600'
    : 'bg-white/95 border-slate-200';

  const windTextClasses = isNight ? 'text-slate-300' : 'text-slate-700';
  const windLabelClasses = isNight ? 'text-slate-500' : 'text-slate-500';
  const windBtnClasses = isNight 
    ? 'bg-slate-700 hover:bg-slate-600 text-white' 
    : 'bg-slate-200 hover:bg-slate-300 text-slate-800';

  const mainColor = isNight ? "#38bdf8" : "#0284c7";

  if (containerSize.width === 0) return <div ref={containerRef} className="w-full h-full" />;

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none`}
    >
      {/* Wind Control Widget */}
      <div 
        onMouseEnter={handleWindEnter}
        onMouseLeave={handleWindLeave}
        className={`absolute top-4 left-1/2 -translate-x-1/2 backdrop-blur rounded-xl border shadow-xl flex flex-col items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isWindExpanded ? 'w-60 p-2' : 'w-auto px-4 py-2 hover:w-60 hover:p-2 cursor-pointer'}`}
      >
        {isWindExpanded ? (
            <>
                <div className={`text-[10px] font-bold ${windTextClasses} mb-1 w-full flex justify-between items-center`}>
                    <span className={`text-[9px] ${windLabelClasses}`}>WEST</span>
                    <span className={`flex items-center gap-1 ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-400') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                        <Wind size={10} />
                        WIND: {Math.abs(wind).toFixed(1)}
                    </span>
                    <span className={`text-[9px] ${windLabelClasses}`}>EAST</span>
                </div>
                <div className="flex items-center w-full gap-2 opacity-100 transition-opacity duration-300 delay-100">
                    <button onClick={() => setWind(Number((wind - 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>-</button>
                    <div className="relative flex-1 h-5 flex items-center mx-1">
                        <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                        <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-sky-500 z-10 relative ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}/>
                    </div>
                    <button onClick={() => setWind(Number((wind + 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>+</button>
                </div>
            </>
        ) : (
             <div className="flex items-center gap-2">
                <Wind size={14} className={wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-500' : 'text-rose-500'} />
                <span className={`text-xs font-bold font-mono ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-500') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {wind.toFixed(1)}
                </span>
            </div>
        )}
      </div>

      {/* Zoom Control Widget */}
      <div 
        onMouseEnter={handleZoomEnter}
        onMouseLeave={handleZoomLeave}
        className={`absolute bottom-4 right-4 backdrop-blur rounded-xl border shadow-xl flex items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isZoomExpanded ? 'w-64 p-3 gap-3' : 'w-24 p-2 gap-2 cursor-pointer hover:w-64 hover:p-3 hover:gap-3'}`}
      >
        {isZoomExpanded ? (
            <>
                <button onClick={() => setZoom(Math.max(0.25, zoom - 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomOut size={12} />
                </button>
                <div className="flex-1 flex flex-col items-center">
                    <div className="flex justify-between w-full text-[10px] font-bold mb-1 opacity-80">
                         <span className={windLabelClasses}>VIEW RANGE</span>
                         <span className={isNight ? 'text-indigo-300' : 'text-indigo-600'}>{(zoom * 100).toFixed(0)}%</span>
                    </div>
                    <input
                        type="range"
                        min="0.25"
                        max="2.5"
                        step="0.1"
                        value={zoom}
                        onChange={(e) => setZoom(Number(e.target.value))}
                        className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                    />
                </div>
                <button onClick={() => setZoom(Math.min(2.5, zoom + 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomIn size={12} />
                </button>
            </>
        ) : (
            <>
                <input
                    type="range"
                    min="0.25"
                    max="2.5"
                    step="0.1"
                    value={zoom}
                    readOnly
                    className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                />
            </>
        )}
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Curve Analysis View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            X: {currentMinX.toFixed(0)} to {currentMaxX.toFixed(0)} | Y: {currentMinY.toFixed(0)} to {currentMaxY.toFixed(0)}
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className={`w-full h-full block touch-none ${
            dragState.mode === 'PAN' ? 'cursor-grabbing' : 
            dragState.mode === 'LABEL' ? 'cursor-move' : 
            dragState.mode === 'TARGET' ? 'cursor-crosshair' : 
            dragState.mode === 'KNOB' ? 'cursor-grab' : 'cursor-grab'
        }`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}

        // Touch Events for Pinch Zoom
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onTouchCancel={handleTouchEnd}

        preserveAspectRatio="none"
      >
        <defs>
            <marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
                <path d="M0,0 L0,6 L9,3 z" fill="#a855f7" />
            </marker>
            <radialGradient id="angleGradient" cx="0.5" cy="0.5" r="0.5">
                <stop offset="0%" stopColor={mainColor} stopOpacity="0.25" />
                <stop offset="100%" stopColor={mainColor} stopOpacity="0" />
            </radialGradient>
            <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
              <feDropShadow dx="0" dy={2 * pixelScale} stdDeviation={2 * pixelScale} floodColor="#000000" floodOpacity="0.3" />
            </filter>
            <filter id="simpleBlur" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation={2 * pixelScale} />
            </filter>
        </defs>

        {/* Grid Lines */}
        {gridLines}

        {/* Saved Trajectories and Labels */}
        {savedData.map((sd) => (
            <g key={sd.id}>
                {/* Only draw path if it's NOT an analysis item */}
                {!sd.isAnalysis && (
                    <path d={sd.d} fill="none" stroke={sd.color} strokeWidth={2 * pixelScale} strokeDasharray={`${5*pixelScale},${5*pixelScale}`} className="opacity-60" />
                )}

                {/* Draw Analysis Connector Lines (Polylines/Manhattan) */}
                {sd.isAnalysis && sd.connectorStartPoints && (
                    <>
                        {sd.connectorStartPoints.map((pt: Point, idx: number) => {
                             // Analysis Label Left Edge is at labelPos.x - 45*scale
                             const endX = sd.labelPos.x - (45 * pixelScale);
                             const endY = sd.labelPos.y;

                             // Start Point (Parent Right Edge)
                             const startX = pt.x;
                             const startY = pt.y;

                             // Manhattan step: Horizontal -> Vertical -> Horizontal
                             // Move right 20 units (scaled) from start
                             const step1X = startX + (30 * pixelScale);

                             // Path: Start -> Step1 -> Vertical to endY -> End
                             const midX = startX + ((endX - startX) / 2); // Or use step1X if we want fixed corner

                             // Creating a Bracket look:
                             // Start -> Out a bit -> Go vertical to match end Y -> Go to End
                             const elbowX = midX;

                             return (
                                 <polyline 
                                    key={idx}
                                    points={`${startX},${startY} ${elbowX},${startY} ${elbowX},${endY} ${endX},${endY}`}
                                    fill="none"
                                    stroke={sd.color}
                                    strokeWidth={1.5 * pixelScale}
                                    strokeDasharray={`${3*pixelScale},${3*pixelScale}`}
                                    strokeLinejoin="round"
                                    opacity="0.6"
                                 />
                             );
                        })}
                    </>
                )}

                <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                     <circle r={sd.isAnalysis ? 3 * pixelScale : 6 * pixelScale} fill="none" stroke={sd.color} strokeWidth={sd.isAnalysis ? 1 * pixelScale : 3 * pixelScale} />
                     <circle r={2 * pixelScale} fill={sd.color} />
                </g>

                {!sd.isAnalysis && (
                    <line 
                        x1={sd.labelPos.x} y1={sd.labelPos.y} 
                        x2={sd.targetPos.x} y2={sd.targetPos.y} 
                        stroke={sd.color} strokeWidth={1.5 * pixelScale} 
                        strokeDasharray={`${4*pixelScale},${2*pixelScale}`}
                        opacity="0.8"
                    />
                )}

                {/* Draggable Label */}
                <g 
                    transform={`translate(${sd.labelPos.x}, ${sd.labelPos.y}) scale(${pixelScale})`} 
                    className="cursor-move group"
                > 

                    {sd.isAnalysis ? (
                        <>
                             {/* Compact Analysis Label Background - Reduced Size */}
                             <rect 
                                x="-45" y="-12" width="90" height="24" rx="4" 
                                fill={isNight ? "#1e293b" : "#ffffff"} 
                                stroke={sd.color} strokeWidth="2" 
                                filter="url(#shadow)"
                            />
                            {/* Decorative Left Edge */}
                            <path 
                                d="M -25 -12 L -41 -12 Q -45 -12 -45 -8 L -45 8 Q -45 12 -41 12 L -25 12 Z" 
                                fill={sd.color} 
                            />

                            <text x="-35" y="4" textAnchor="middle" fill="rgba(255,255,255,0.9)" fontSize="10" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                ΔP
                            </text>

                            {/* Main Value */}
                            <text x="10" y="5" textAnchor="middle" fill={isNight ? "#ffffff" : "#334155"} fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                {sd.power > 0 ? '+' : ''}{sd.power.toFixed(1)}
                            </text>

                            {/* Close Button (Shows on Hover or Touch) */}
                            {onDeleteAnalysis && (
                                <g 
                                    transform="translate(45, -12)" 
                                    className="cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity"
                                    onClick={(e) => {
                                        e.stopPropagation(); // Prevent drag start
                                        onDeleteAnalysis(sd.id);
                                    }}
                                    onPointerDown={(e) => e.stopPropagation()} // Prevent drag start on touch
                                >
                                    <circle cx="0" cy="0" r="8" fill="#ef4444" stroke="white" strokeWidth="1" />
                                    <line x1="-3" y1="-3" x2="3" y2="3" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
                                    <line x1="3" y1="-3" x2="-3" y2="3" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
                                </g>
                            )}
                        </>
                    ) : (
                        <>
                            {/* Standard Label Background - Height 34 */}
                            <rect 
                                x="-85" y="-17" width="170" height="34" rx="6" 
                                fill={isNight ? "#1e293b" : "#ffffff"} 
                                stroke={sd.color} strokeWidth="2" 
                                filter="url(#shadow)"
                            />
                            {/* Custom Left Decorative Shape */}
                            <path 
                                d="M -35 -17 L -79 -17 Q -85 -17 -85 -11 L -85 11 Q -85 17 -79 17 L -35 17 Z" 
                                fill={sd.color} 
                            />
                            {/* Standard Label Layout */}
                            <text x="-60" y="-4" textAnchor="middle" fill="rgba(255,255,255,0.7)" fontSize="8" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                POWER
                            </text>
                            <text x="-60" y="10" textAnchor="middle" fill="white" fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                {sd.power.toFixed(1)}
                            </text>

                            {/* Right Side: Data - Row 1: Angle & Wind */}
                            <text x="-25" y="-3" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>A:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.angle}°</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>W:</tspan> <tspan fontWeight="bold" fill={sd.wind === 0 ? (isNight ? "#94a3b8" : "#64748b") : (sd.wind > 0 ? "#10b981" : "#f43f5e")}>{sd.wind}</tspan>
                            </text>

                            {/* Right Side: Data - Row 2: Coordinates */}
                            <text x="-25" y="9" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>X:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.dx}</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>Y:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.dy}</tspan>
                            </text>
                        </>
                    )}
                </g>
            </g>
        ))}

        {/* Active Elements */}
        {showCurrentTrajectory && (
            <>
                <circle 
                    cx={tankSvg.x} 
                    cy={tankSvg.y} 
                    r={knobRadius} 
                    fill="url(#angleGradient)" 
                    className="cursor-pointer hover:opacity-100 transition-opacity"
                    style={{ opacity: 0.8 }}
                />

                <path d={trajectoryPath} fill="none" stroke={mainColor} strokeWidth={4 * pixelScale} strokeDasharray={`${10*pixelScale},${10*pixelScale}`} className="opacity-80" />

                <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
                    <path d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`} fill="none" stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"} strokeWidth={2 * pixelScale} strokeDasharray={`${4*pixelScale},${4*pixelScale}`}/>

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                        stroke="#dc2626" strokeWidth={8 * pixelScale} strokeLinecap="round" opacity="0.3" filter="url(#simpleBlur)" />

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                        stroke="#dc2626" strokeWidth={3 * pixelScale} strokeLinecap="round" />

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                         stroke="transparent" strokeWidth={20 * pixelScale} strokeLinecap="round" style={{ pointerEvents: 'auto' }} />
                </g>

                <g>
                    <circle 
                        cx={tankSvg.x} 
                        cy={tankSvg.y} 
                        r={18 * pixelScale} 
                        fill={isNight ? "#0f172a" : "#ffffff"} 
                        stroke={mainColor} 
                        strokeWidth={3 * pixelScale} 
                    />
                    <text 
                        x={tankSvg.x} 
                        y={tankSvg.y} 
                        dy={4 * pixelScale} 
                        textAnchor="middle" 
                        fill={mainColor} 
                        fontSize={11 * pixelScale} 
                        fontWeight="bold" 
                        fontFamily="'Varela Round', sans-serif"
                        className="pointer-events-none select-none"
                    >
                        {angle}°
                    </text>
                </g>

                <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
                    <circle r={5 * pixelScale} fill={mainColor} />
                    <circle r={12 * pixelScale} fill="none" stroke={mainColor} strokeWidth={1.5 * pixelScale} opacity="0.6" className="animate-pulse" />

                    {/* Tooltip scaled by pixelScale */}
                    <g transform={`translate(0, -${65 * pixelScale}) scale(${pixelScale})`}>
                        <rect x="-70" y="0" width="140" height="50" rx="6" fill={isNight ? "rgba(15, 23, 42, 0.9)" : "rgba(255, 255, 255, 0.9)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
                        <text x="0" y="20" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="16" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            ({dx}, {dy})
                        </text>
                        <text x="0" y="38" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            Wind: {wind}
                        </text>
                    </g>
                </g>

                {impactSvg && (
                    <circle cx={impactSvg.x} cy={impactSvg.y} r={8 * pixelScale} fill="#fbbf24" stroke="white" strokeWidth={1 * pixelScale} />
                )}
            </>
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useMemo, useState, useEffect } from 'react';
import { Point, PHYSICS_CONSTANTS, SavedTrajectory, AnalysisItem } from '../types';
import { Wind, ZoomIn, ZoomOut, X } from 'lucide-react';
import { calculateTrajectory } from '../services/physicsEngine';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  setZoom: (z: number) => void;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
  snapToGrid: boolean;
  savedTrajectories: SavedTrajectory[];
  analysisItems?: AnalysisItem[]; // New prop for separately managed analysis items
  onDeleteAnalysis?: (id: string) => void; // Handler to delete analysis item
  showCurrentTrajectory: boolean;
}

interface DragState {
    mode: 'IDLE' | 'PAN' | 'TARGET' | 'KNOB' | 'LABEL' | 'AWAIT_PAN_OR_CLICK';
    startScreen: Point;
    startPan: Point; // Physics units
    activeId?: string;
    hasMoved?: boolean;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  setZoom,
  isNight,
  wind,
  setWind,
  snapToGrid,
  savedTrajectories,
  analysisItems = [],
  onDeleteAnalysis,
  showCurrentTrajectory
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  // Track container size for responsive aspect ratio
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

  // Widget Hover States
  const [isWindExpanded, setIsWindExpanded] = useState(false);
  const windTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [isZoomExpanded, setIsZoomExpanded] = useState(false);
  const zoomTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // --- Interaction Logic for Wind Widget ---
  const handleWindEnter = () => {
    if (windTimeoutRef.current) clearTimeout(windTimeoutRef.current);
    setIsWindExpanded(true);
  };

  const handleWindLeave = () => {
    windTimeoutRef.current = setTimeout(() => {
        setIsWindExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };

  // --- Interaction Logic for Zoom Widget ---
  const handleZoomEnter = () => {
    if (zoomTimeoutRef.current) clearTimeout(zoomTimeoutRef.current);
    setIsZoomExpanded(true);
  };

  const handleZoomLeave = () => {
    zoomTimeoutRef.current = setTimeout(() => {
        setIsZoomExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };


  useEffect(() => {
    if (!containerRef.current) return;

    const updateSize = () => {
        if (containerRef.current) {
            const { width, height } = containerRef.current.getBoundingClientRect();
            if (width > 0 && height > 0) {
                setContainerSize({ width, height });
            }
        }
    };

    // Initial size
    updateSize();

    const observer = new ResizeObserver(updateSize);
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  // Viewport State: Pan Offset in Physics Units
  const [pan, setPan] = useState({ x: 0, y: 0 }); 

  // Custom offsets for saved labels (SVG px relative to target)
  const [labelOffsets, setLabelOffsets] = useState<Record<string, Point>>({});

  // Interaction State Machine
  const [dragState, setDragState] = useState<DragState>({ 
      mode: 'IDLE', 
      startScreen: { x: 0, y: 0 }, 
      startPan: { x: 0, y: 0 } 
  });

  // --- Pinch Zoom State ---
  const pinchRef = useRef({
      active: false,
      initialDist: 0,
      initialZoom: 1,
      initialPan: { x: 0, y: 0 },
      centerX: 0.5, // normalized 0-1
      centerY: 0.5  // normalized 0-1
  });

  // --- Viewport Calculations ---
  // We anchor the Vertical range and the Left side (Min X) based on constants + zoom.
  // We expand the Right side (Max X) based on the aspect ratio of the container.

  const aspectRatio = containerSize.height > 0 ? containerSize.width / containerSize.height : 1;

  // Base heights from constants
  const baseHeight = PHYSICS_CONSTANTS.MAX_Y - PHYSICS_CONSTANTS.MIN_Y;

  // Calculate visible range in physics units
  const currentHeight = baseHeight * zoom;
  const currentWidth = currentHeight * aspectRatio;

  const currentMinY = (PHYSICS_CONSTANTS.MIN_Y * zoom) + pan.y;
  const currentMaxY = currentMinY + currentHeight;

  // Anchor Left side to MIN_X
  const currentMinX = (PHYSICS_CONSTANTS.MIN_X * zoom) + pan.x;
  const currentMaxX = currentMinX + currentWidth;

  // Fixed SVG Resolution scaling
  const PIXELS_PER_UNIT = 40; 
  const VIEWBOX_WIDTH = currentWidth * PIXELS_PER_UNIT; 
  const VIEWBOX_HEIGHT = currentHeight * PIXELS_PER_UNIT;

  // --- Scale Factor for UI Elements ---
  // Calculates how many SVG units correspond to 1 screen pixel.
  // This allows us to scale text/UI so they look constant size on screen.
  const pixelScale = useMemo(() => {
    if (containerSize.width <= 0) return 1;
    return VIEWBOX_WIDTH / containerSize.width;
  }, [VIEWBOX_WIDTH, containerSize.width]);

  const toSvg = (p: Point) => {
    const percentX = (p.x - currentMinX) / currentWidth;
    const percentY = (p.y - currentMinY) / currentHeight;
    return {
        x: percentX * VIEWBOX_WIDTH,
        y: VIEWBOX_HEIGHT - (percentY * VIEWBOX_HEIGHT)
    };
  };

  const fromSvg = (svgX: number, svgY: number): Point => {
    const percentX = svgX / VIEWBOX_WIDTH;
    const percentY = (VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT; 
    return {
        x: currentMinX + percentX * currentWidth,
        y: currentMinY + percentY * currentHeight
    };
  };

  // Accurate SVG point from screen coordinates
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    let point = new DOMPoint(clientX, clientY);
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, currentMinX, currentMinY, currentWidth, currentHeight]); 

  // --- Saved Data Preparation ---
  // Pre-calculate positions for rendering and hit-testing
  // Refactored to handle dependency chain (Standard Labels -> Analysis Labels)
  const savedData = useMemo(() => {
    // We mix SavedTrajectories and AnalysisItems into a single render list
    // Standard trajectories first, so Analysis can find them
    const sortedByTime = [...savedTrajectories].sort((a, b) => a.timestamp - b.timestamp);

    // Map to store calculated label positions for lookup
    const processedMap = new Map<string, any>();

    sortedByTime.forEach((t) => {
        if (!t.visible) return;

        const d = pointsToPath(calculateTrajectory(tankPos, t.power, t.angle, t.wind));
        const targetSvg = toSvg(t.target);
        const dx = (t.target.x - tankPos.x).toFixed(1);
        const dy = (t.target.y - tankPos.y).toFixed(1);

        // Standard Positioning
        const originalIndex = savedTrajectories.findIndex(st => st.id === t.id);
        const defaultOffsetPx = { x: 0, y: -(40 + (originalIndex % 5) * 45) };
        const defaultOffsetSvg = { 
            x: defaultOffsetPx.x * pixelScale, 
            y: defaultOffsetPx.y * pixelScale 
        };

        const offset = labelOffsets[t.id] || defaultOffsetSvg;
        const usedOffset = offset;
        const labelPos = { x: targetSvg.x + offset.x, y: targetSvg.y + offset.y };

        const data = { 
           id: t.id, 
           d, 
           power: t.power,
           angle: t.angle, 
           wind: t.wind, 
           dx, dy, 
           targetPos: targetSvg,
           labelPos,
           color: t.color,
           isAnalysis: false,
           offset: usedOffset
        };

        processedMap.set(t.id, data);
    });

    // Process Analysis Items
    analysisItems.forEach((item) => {
        if (!item.visible) return;

        let labelPos = { x: 0, y: 0 };
        let connectorStartPoints = undefined; // [ {x,y}, {x,y} ] - Coordinates of parent right edges
        let usedOffset = { x: 0, y: 0 };

        if (item.parentIds && item.parentIds.length === 2) {
             const p1 = processedMap.get(item.parentIds[0]);
             const p2 = processedMap.get(item.parentIds[1]);

             if (p1 && p2) {
                 // Dynamic Positioning: To the right of parents
                 // Standard Label Half-Width = 85 (Total 170)
                 const p1Right = p1.labelPos.x + (85 * pixelScale);
                 const p2Right = p2.labelPos.x + (85 * pixelScale);

                 // Base position is right of the furthest parent + gap
                 // We add a significant gap to allow for the polyline structure
                 // Reduced gap to keep layout tighter as requested
                 const baseX = Math.max(p1Right, p2Right) + (70 * pixelScale); 
                 const baseY = (p1.labelPos.y + p2.labelPos.y) / 2;

                 connectorStartPoints = [
                     { x: p1Right, y: p1.labelPos.y },
                     { x: p2Right, y: p2.labelPos.y }
                 ];

                 const offset = labelOffsets[item.id] || { x: 0, y: 0 };
                 usedOffset = offset;
                 labelPos = { x: baseX + offset.x, y: baseY + offset.y };
             } else {
                 // Fallback if parents missing
                 const targetSvg = toSvg(item.target);
                 const offset = labelOffsets[item.id] || { x: 0, y: -40 * pixelScale };
                 usedOffset = offset;
                 labelPos = { x: targetSvg.x + offset.x, y: targetSvg.y + offset.y };
             }
        }

        const data = {
            id: item.id,
            power: item.powerDiff, // Reuse power field for Diff
            labelPos,
            color: item.color,
            isAnalysis: true,
            connectorStartPoints,
            offset: usedOffset,
            targetPos: toSvg(item.target) // Just for hit testing proximity if needed
        };
         processedMap.set(item.id, data);
    });

    // Return array: Standard Trajectories followed by Analysis Items (so Analysis renders on top)
    const renderList = [
        ...sortedByTime.map(t => processedMap.get(t.id)),
        ...analysisItems.map(a => processedMap.get(a.id))
    ].filter(Boolean);

    return renderList;

  }, [savedTrajectories, analysisItems, tankPos, zoom, currentMinX, currentMinY, currentWidth, currentHeight, labelOffsets, pixelScale]);

  // --- Interaction Handlers ---

  const handleTouchStart = (e: React.TouchEvent) => {
      if (e.touches.length === 2) {
          e.preventDefault();
          const t1 = e.touches[0];
          const t2 = e.touches[1];

          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          // Calculate centroid relative to container
          const rect = containerRef.current?.getBoundingClientRect();
          if (!rect) return;

          const cx = ((t1.clientX + t2.clientX) / 2) - rect.left;
          const cy = ((t1.clientY + t2.clientY) / 2) - rect.top;

          pinchRef.current = {
              active: true,
              initialDist: dist,
              initialZoom: zoom,
              initialPan: { ...pan },
              centerX: cx / rect.width,
              centerY: cy / rect.height
          };

          // Cancel any active drag/pan
          setDragState(prev => ({ ...prev, mode: 'IDLE' }));
      }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      if (e.touches.length === 2 && pinchRef.current.active) {
          e.preventDefault();
          e.stopPropagation();

          const t1 = e.touches[0];
          const t2 = e.touches[1];
          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          if (pinchRef.current.initialDist > 10 && dist > 10) {
              const ratio = dist / pinchRef.current.initialDist;
              // Larger distance (spread) -> Smaller zoom value (Zoom In/Close up)
              let newZoom = pinchRef.current.initialZoom / ratio;
              newZoom = Math.max(0.25, Math.min(2.5, newZoom));

              // Calculate Pan compensation to zoom towards center
              // Formula: pan_new = pan_old + M * (z_old - z_new)
              const deltaZ = pinchRef.current.initialZoom - newZoom;

              // M_x = MIN_X + CenterX * Height * AR
              const Mx = PHYSICS_CONSTANTS.MIN_X + (pinchRef.current.centerX * baseHeight * aspectRatio);

              // M_y = MIN_Y + (1 - CenterY) * Height
              // Note: CenterY is 0 at top, 1 at bottom. Physics Y is 0 at bottom (relative to MIN_Y).
              const My = PHYSICS_CONSTANTS.MIN_Y + ((1 - pinchRef.current.centerY) * baseHeight);

              const newPanX = pinchRef.current.initialPan.x + (Mx * deltaZ);
              const newPanY = pinchRef.current.initialPan.y + (My * deltaZ);

              setZoom(newZoom);
              setPan({ x: newPanX, y: newPanY });
          }
      }
  };

  const handleTouchEnd = () => {
      pinchRef.current.active = false;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    // If pinch is active, ignore single pointer events
    if (pinchRef.current.active) return;

    if (!svgRef.current) return;
    (e.target as Element).setPointerCapture(e.pointerId);

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);
    const screenPt = { x: e.clientX, y: e.clientY };

    // 1. Check Angle Knob / Area (Only if active)
    const tankSvg = toSvg(tankPos);

    // Visual radius of the knob control (roughly 80px on screen)
    const knobRadius = 80 * pixelScale;
    const distToTank = Math.hypot(clickX - tankSvg.x, clickY - tankSvg.y);

    if (showCurrentTrajectory && distToTank < knobRadius + (10 * pixelScale)) {
        setDragState({ mode: 'KNOB', startScreen: screenPt, startPan: pan });
        return;
    }

    // 2. Check Saved Labels (Top-most first for hitting, so iterate reverse of render order?)
    // savedData is Old -> New (Render Order). 
    // Hit test should be New -> Old (Top -> Bottom).
    for (let i = savedData.length - 1; i >= 0; i--) {
        const item = savedData[i];

        // Define Hitbox size based on type
        // Analysis: 90x24 (Half 45x12)
        // Standard: 170x34 (Half 85x17)
        const halfW = item.isAnalysis ? 45 * pixelScale : 85 * pixelScale;
        const halfH = item.isAnalysis ? 12 * pixelScale : 17 * pixelScale;

        if (
            clickX >= item.labelPos.x - halfW && clickX <= item.labelPos.x + halfW &&
            clickY >= item.labelPos.y - halfH && clickY <= item.labelPos.y + halfH
        ) {
            setDragState({ 
                mode: 'LABEL', 
                startScreen: screenPt, 
                startPan: pan, 
                activeId: item.id
            });
            return;
        }
    }

    // 3. Check Active Target (Only if active)
    const targetSvg = toSvg(target);
    const targetHitRadius = 30 * pixelScale;
    if (showCurrentTrajectory && Math.hypot(clickX - targetSvg.x, clickY - targetSvg.y) < targetHitRadius) {
        setDragState({ mode: 'TARGET', startScreen: screenPt, startPan: pan });
        return;
    }

    // 4. Background -> Pan or Click
    setDragState({ 
        mode: 'AWAIT_PAN_OR_CLICK', 
        startScreen: screenPt, 
        startPan: pan, 
        hasMoved: false
    });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // If pinch active, ignore
    if (pinchRef.current.active) return;

    if (!svgRef.current) return;
    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    // Calculate screen deltas
    const dxScreen = e.clientX - dragState.startScreen.x;
    const dyScreen = e.clientY - dragState.startScreen.y;

    if (dragState.mode === 'KNOB') {
        const tankSvg = toSvg(tankPos);
        // Angle calc
        let newAngle = Math.atan2(-(pointerY - tankSvg.y), (pointerX - tankSvg.x)) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;
        if (newAngle > 180) newAngle = 180; 

        // Snap to integer angle for cleaner UI
        setAngle(Math.round(newAngle));

    } else if (dragState.mode === 'LABEL' && dragState.activeId) {
        const currentItem = savedData.find(sd => sd.id === dragState.activeId);
        if (currentItem && currentItem.offset) {
             const basePosX = currentItem.labelPos.x - currentItem.offset.x;
             const basePosY = currentItem.labelPos.y - currentItem.offset.y;

             let destX = pointerX;
             let destY = pointerY;

             // Snap logic
             if (snapToGrid) {
                 const physPoint = fromSvg(destX, destY);
                 const snappedPhysX = Math.round(physPoint.x);
                 const snappedPhysY = Math.round(physPoint.y);
                 const snappedSvg = toSvg({ x: snappedPhysX, y: snappedPhysY });
                 destX = snappedSvg.x;
                 destY = snappedSvg.y;
             }

             setLabelOffsets(prev => ({
                ...prev,
                [dragState.activeId!]: {
                    x: destX - basePosX,
                    y: destY - basePosY
                }
             }));
        }

    } else if (dragState.mode === 'TARGET') {
        const physicsPoint = fromSvg(pointerX, pointerY);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });

    } else if (dragState.mode === 'PAN' || (dragState.mode === 'AWAIT_PAN_OR_CLICK' && Math.hypot(dxScreen, dyScreen) > 5)) {
        if (dragState.mode === 'AWAIT_PAN_OR_CLICK') {
            setDragState(prev => ({ ...prev, mode: 'PAN', hasMoved: true }));
        }

        const ctm = svgRef.current?.getScreenCTM();
        const scaleX = ctm ? ctm.a : 1; 

        const dxPhys = -dxScreen / (PIXELS_PER_UNIT * scaleX);
        const dyPhys = dyScreen / (PIXELS_PER_UNIT * scaleX);

        setPan({
            x: dragState.startPan.x + dxPhys,
            y: dragState.startPan.y + dyPhys
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    (e.target as Element).releasePointerCapture(e.pointerId);

    if (showCurrentTrajectory && dragState.mode === 'AWAIT_PAN_OR_CLICK' && !dragState.hasMoved) {
        const { x, y } = getSvgPoint(e.clientX, e.clientY);
        const physicsPoint = fromSvg(x, y);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });
    }

    setDragState({ mode: 'IDLE', startScreen: {x:0, y:0}, startPan: {x:0, y:0} });
  };

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = (target.y - tankPos.y).toFixed(2); 

  // Generate Grid Lines
  const gridLines = useMemo(() => {
    const lines = [];
    const startX = Math.floor(currentMinX);
    const endX = Math.ceil(currentMaxX);
    const startY = Math.floor(currentMinY);
    const endY = Math.ceil(currentMaxY);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const axisColor = isNight ? "#94a3b8" : "#475569"; 
    const minorColor = isNight ? "rgba(51, 65, 85, 0.4)" : "rgba(203, 213, 225, 0.6)";
    const textColor = isNight ? "#64748b" : "#94a3b8";

    const strokeW = Math.max(1 * pixelScale, 1); 
    const fontSz = 12 * pixelScale; 

    const useSparseGrid = zoom > 1.5;

    for (let i = startX; i <= endX; i++) {
        const p = toSvg({ x: i, y: 0 }); 
        const x = p.x;
        if (x < -50 * pixelScale || x > VIEWBOX_WIDTH + 50 * pixelScale) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 12 === 0; 

        if (useSparseGrid && !isAxis && !isMajor) continue;

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? strokeW * 2 : strokeW} 
                strokeDasharray={isAxis || isMajor ? "" : `${4 * pixelScale},${2 * pixelScale}`}
            />
        );

        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + (4 * pixelScale)} 
                y={VIEWBOX_HEIGHT - (10 * pixelScale)} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={fontSz}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
                style={{ userSelect: 'none' }}
            >
                {i}
            </text>
        );
    }

    for (let i = startY; i <= endY; i++) {
        const p = toSvg({ x: 0, y: i }); 
        const y = p.y;
        if (y < -50 * pixelScale || y > VIEWBOX_HEIGHT + 50 * pixelScale) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 6 === 0;

        if (useSparseGrid && !isAxis && !isMajor) continue;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? strokeW * 2 : strokeW} 
                strokeDasharray={isAxis || isMajor ? "" : `${4 * pixelScale},${2 * pixelScale}`}
            />
        );

        lines.push(
            <text 
                key={`th-${i}`} 
                x={10 * pixelScale} 
                y={y - (4 * pixelScale)} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={fontSz}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
                style={{ userSelect: 'none' }}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [currentMinX, currentMaxX, currentMinY, currentMaxY, VIEWBOX_WIDTH, VIEWBOX_HEIGHT, isNight, toSvg, pixelScale, zoom]);

  const knobRadius = 80 * pixelScale; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // Dynamic Styles for Wind Widget
  const windWidgetClasses = isNight 
    ? 'bg-slate-800/95 border-slate-600'
    : 'bg-white/95 border-slate-200';

  const windTextClasses = isNight ? 'text-slate-300' : 'text-slate-700';
  const windLabelClasses = isNight ? 'text-slate-500' : 'text-slate-500';
  const windBtnClasses = isNight 
    ? 'bg-slate-700 hover:bg-slate-600 text-white' 
    : 'bg-slate-200 hover:bg-slate-300 text-slate-800';

  const mainColor = isNight ? "#38bdf8" : "#0284c7";

  if (containerSize.width === 0) return <div ref={containerRef} className="w-full h-full" />;

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none`}
    >
      {/* Wind Control Widget */}
      <div 
        onMouseEnter={handleWindEnter}
        onMouseLeave={handleWindLeave}
        className={`absolute top-4 left-1/2 -translate-x-1/2 backdrop-blur rounded-xl border shadow-xl flex flex-col items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isWindExpanded ? 'w-60 p-2' : 'w-auto px-4 py-2 hover:w-60 hover:p-2 cursor-pointer'}`}
      >
        {isWindExpanded ? (
            <>
                <div className={`text-[10px] font-bold ${windTextClasses} mb-1 w-full flex justify-between items-center`}>
                    <span className={`text-[9px] ${windLabelClasses}`}>WEST</span>
                    <span className={`flex items-center gap-1 ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-400') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                        <Wind size={10} />
                        WIND: {Math.abs(wind).toFixed(1)}
                    </span>
                    <span className={`text-[9px] ${windLabelClasses}`}>EAST</span>
                </div>
                <div className="flex items-center w-full gap-2 opacity-100 transition-opacity duration-300 delay-100">
                    <button onClick={() => setWind(Number((wind - 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>-</button>
                    <div className="relative flex-1 h-5 flex items-center mx-1">
                        <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                        <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-sky-500 z-10 relative ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}/>
                    </div>
                    <button onClick={() => setWind(Number((wind + 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>+</button>
                </div>
            </>
        ) : (
             <div className="flex items-center gap-2">
                <Wind size={14} className={wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-500' : 'text-rose-500'} />
                <span className={`text-xs font-bold font-mono ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-500') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {wind.toFixed(1)}
                </span>
            </div>
        )}
      </div>

      {/* Zoom Control Widget */}
      <div 
        onMouseEnter={handleZoomEnter}
        onMouseLeave={handleZoomLeave}
        className={`absolute bottom-4 right-4 backdrop-blur rounded-xl border shadow-xl flex items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isZoomExpanded ? 'w-64 p-3 gap-3' : 'w-24 p-2 gap-2 cursor-pointer hover:w-64 hover:p-3 hover:gap-3'}`}
      >
        {isZoomExpanded ? (
            <>
                <button onClick={() => setZoom(Math.max(0.25, zoom - 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomOut size={12} />
                </button>
                <div className="flex-1 flex flex-col items-center">
                    <div className="flex justify-between w-full text-[10px] font-bold mb-1 opacity-80">
                         <span className={windLabelClasses}>VIEW RANGE</span>
                         <span className={isNight ? 'text-indigo-300' : 'text-indigo-600'}>{(zoom * 100).toFixed(0)}%</span>
                    </div>
                    <input
                        type="range"
                        min="0.25"
                        max="2.5"
                        step="0.1"
                        value={zoom}
                        onChange={(e) => setZoom(Number(e.target.value))}
                        className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                    />
                </div>
                <button onClick={() => setZoom(Math.min(2.5, zoom + 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomIn size={12} />
                </button>
            </>
        ) : (
            <>
                <input
                    type="range"
                    min="0.25"
                    max="2.5"
                    step="0.1"
                    value={zoom}
                    readOnly
                    className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                />
            </>
        )}
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Curve Analysis View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            X: {currentMinX.toFixed(0)} to {currentMaxX.toFixed(0)} | Y: {currentMinY.toFixed(0)} to {currentMaxY.toFixed(0)}
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className={`w-full h-full block touch-none ${
            dragState.mode === 'PAN' ? 'cursor-grabbing' : 
            dragState.mode === 'LABEL' ? 'cursor-move' : 
            dragState.mode === 'TARGET' ? 'cursor-crosshair' : 
            dragState.mode === 'KNOB' ? 'cursor-grab' : 'cursor-grab'
        }`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}

        // Touch Events for Pinch Zoom
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onTouchCancel={handleTouchEnd}

        preserveAspectRatio="none"
      >
        <defs>
            <marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
                <path d="M0,0 L0,6 L9,3 z" fill="#a855f7" />
            </marker>
            <radialGradient id="angleGradient" cx="0.5" cy="0.5" r="0.5">
                <stop offset="0%" stopColor={mainColor} stopOpacity="0.25" />
                <stop offset="100%" stopColor={mainColor} stopOpacity="0" />
            </radialGradient>
            <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
              <feDropShadow dx="0" dy={2 * pixelScale} stdDeviation={2 * pixelScale} floodColor="#000000" floodOpacity="0.3" />
            </filter>
            <filter id="simpleBlur" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation={2 * pixelScale} />
            </filter>
        </defs>

        {/* Grid Lines */}
        {gridLines}

        {/* Saved Trajectories and Labels */}
        {savedData.map((sd) => (
            <g key={sd.id}>
                {/* Only draw path if it's NOT an analysis item */}
                {!sd.isAnalysis && (
                    <path d={sd.d} fill="none" stroke={sd.color} strokeWidth={2 * pixelScale} strokeDasharray={`${5*pixelScale},${5*pixelScale}`} className="opacity-60" />
                )}

                {/* Draw Analysis Connector Lines (Polylines/Manhattan) */}
                {sd.isAnalysis && sd.connectorStartPoints && (
                    <>
                        {sd.connectorStartPoints.map((pt: Point, idx: number) => {
                             // Analysis Label Left Edge is at labelPos.x - 45*scale
                             const endX = sd.labelPos.x - (45 * pixelScale);
                             const endY = sd.labelPos.y;

                             // Start Point (Parent Right Edge)
                             const startX = pt.x;
                             const startY = pt.y;

                             // Fixed Length Tail Calculation
                             // We want the vertical line to be near the label (endX)
                             // elbowX = endX - FixedLength
                             // But we clamp it to be to the right of startX
                             const fixedTail = 20 * pixelScale; 
                             const minLead = 10 * pixelScale;

                             const elbowX = Math.max(startX + minLead, endX - fixedTail);

                             return (
                                 <polyline 
                                    key={idx}
                                    points={`${startX},${startY} ${elbowX},${startY} ${elbowX},${endY} ${endX},${endY}`}
                                    fill="none"
                                    stroke={sd.color}
                                    strokeWidth={1.5 * pixelScale}
                                    strokeDasharray={`${3*pixelScale},${3*pixelScale}`}
                                    strokeLinejoin="round"
                                    opacity="0.6"
                                 />
                             );
                        })}
                    </>
                )}

                <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                     <circle r={sd.isAnalysis ? 3 * pixelScale : 6 * pixelScale} fill="none" stroke={sd.color} strokeWidth={sd.isAnalysis ? 1 * pixelScale : 3 * pixelScale} />
                     <circle r={2 * pixelScale} fill={sd.color} />
                </g>

                {!sd.isAnalysis && (
                    <line 
                        x1={sd.labelPos.x} y1={sd.labelPos.y} 
                        x2={sd.targetPos.x} y2={sd.targetPos.y} 
                        stroke={sd.color} strokeWidth={1.5 * pixelScale} 
                        strokeDasharray={`${4*pixelScale},${2*pixelScale}`}
                        opacity="0.8"
                    />
                )}

                {/* Draggable Label */}
                <g 
                    transform={`translate(${sd.labelPos.x}, ${sd.labelPos.y}) scale(${pixelScale})`} 
                    className="cursor-move group"
                > 

                    {sd.isAnalysis ? (
                        <>
                             {/* Compact Analysis Label Background - Reduced Size */}
                             <rect 
                                x="-45" y="-12" width="90" height="24" rx="4" 
                                fill={isNight ? "#1e293b" : "#ffffff"} 
                                stroke={sd.color} strokeWidth="2" 
                                filter="url(#shadow)"
                            />
                            {/* Decorative Left Edge */}
                            <path 
                                d="M -25 -12 L -41 -12 Q -45 -12 -45 -8 L -45 8 Q -45 12 -41 12 L -25 12 Z" 
                                fill={sd.color} 
                            />

                            <text x="-35" y="4" textAnchor="middle" fill="rgba(255,255,255,0.9)" fontSize="10" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                ΔP
                            </text>

                            {/* Main Value */}
                            <text x="10" y="5" textAnchor="middle" fill={isNight ? "#ffffff" : "#334155"} fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                {sd.power > 0 ? '+' : ''}{sd.power.toFixed(1)}
                            </text>

                            {/* Close Button (Shows on Hover or Touch) */}
                            {onDeleteAnalysis && (
                                <g 
                                    transform="translate(45, -12)" 
                                    className="cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity"
                                    onClick={(e) => {
                                        e.stopPropagation(); // Prevent drag start
                                        onDeleteAnalysis(sd.id);
                                    }}
                                    onPointerDown={(e) => e.stopPropagation()} // Prevent drag start on touch
                                >
                                    <circle cx="0" cy="0" r="8" fill="#ef4444" stroke="white" strokeWidth="1" />
                                    <line x1="-3" y1="-3" x2="3" y2="3" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
                                    <line x1="3" y1="-3" x2="-3" y2="3" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
                                </g>
                            )}
                        </>
                    ) : (
                        <>
                            {/* Standard Label Background - Height 34 */}
                            <rect 
                                x="-85" y="-17" width="170" height="34" rx="6" 
                                fill={isNight ? "#1e293b" : "#ffffff"} 
                                stroke={sd.color} strokeWidth="2" 
                                filter="url(#shadow)"
                            />
                            {/* Custom Left Decorative Shape */}
                            <path 
                                d="M -35 -17 L -79 -17 Q -85 -17 -85 -11 L -85 11 Q -85 17 -79 17 L -35 17 Z" 
                                fill={sd.color} 
                            />
                            {/* Standard Label Layout */}
                            <text x="-60" y="-4" textAnchor="middle" fill="rgba(255,255,255,0.7)" fontSize="8" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                POWER
                            </text>
                            <text x="-60" y="10" textAnchor="middle" fill="white" fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                {sd.power.toFixed(1)}
                            </text>

                            {/* Right Side: Data - Row 1: Angle & Wind */}
                            <text x="-25" y="-3" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>A:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.angle}°</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>W:</tspan> <tspan fontWeight="bold" fill={sd.wind === 0 ? (isNight ? "#94a3b8" : "#64748b") : (sd.wind > 0 ? "#10b981" : "#f43f5e")}>{sd.wind}</tspan>
                            </text>

                            {/* Right Side: Data - Row 2: Coordinates */}
                            <text x="-25" y="9" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>X:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.dx}</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>Y:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.dy}</tspan>
                            </text>
                        </>
                    )}
                </g>
            </g>
        ))}

        {/* Active Elements */}
        {showCurrentTrajectory && (
            <>
                <circle 
                    cx={tankSvg.x} 
                    cy={tankSvg.y} 
                    r={knobRadius} 
                    fill="url(#angleGradient)" 
                    className="cursor-pointer hover:opacity-100 transition-opacity"
                    style={{ opacity: 0.8 }}
                />

                <path d={trajectoryPath} fill="none" stroke={mainColor} strokeWidth={4 * pixelScale} strokeDasharray={`${10*pixelScale},${10*pixelScale}`} className="opacity-80" />

                <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
                    <path d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`} fill="none" stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"} strokeWidth={2 * pixelScale} strokeDasharray={`${4*pixelScale},${4*pixelScale}`}/>

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                        stroke="#dc2626" strokeWidth={8 * pixelScale} strokeLinecap="round" opacity="0.3" filter="url(#simpleBlur)" />

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                        stroke="#dc2626" strokeWidth={3 * pixelScale} strokeLinecap="round" />

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                         stroke="transparent" strokeWidth={20 * pixelScale} strokeLinecap="round" style={{ pointerEvents: 'auto' }} />
                </g>

                <g>
                    <circle 
                        cx={tankSvg.x} 
                        cy={tankSvg.y} 
                        r={18 * pixelScale} 
                        fill={isNight ? "#0f172a" : "#ffffff"} 
                        stroke={mainColor} 
                        strokeWidth={3 * pixelScale} 
                    />
                    <text 
                        x={tankSvg.x} 
                        y={tankSvg.y} 
                        dy={4 * pixelScale} 
                        textAnchor="middle" 
                        fill={mainColor} 
                        fontSize={11 * pixelScale} 
                        fontWeight="bold" 
                        fontFamily="'Varela Round', sans-serif"
                        className="pointer-events-none select-none"
                    >
                        {angle}°
                    </text>
                </g>

                <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
                    <circle r={5 * pixelScale} fill={mainColor} />
                    <circle r={12 * pixelScale} fill="none" stroke={mainColor} strokeWidth={1.5 * pixelScale} opacity="0.6" className="animate-pulse" />

                    {/* Tooltip scaled by pixelScale */}
                    <g transform={`translate(0, -${65 * pixelScale}) scale(${pixelScale})`}>
                        <rect x="-70" y="0" width="140" height="50" rx="6" fill={isNight ? "rgba(15, 23, 42, 0.9)" : "rgba(255, 255, 255, 0.9)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
                        <text x="0" y="20" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="16" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            ({dx}, {dy})
                        </text>
                        <text x="0" y="38" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            Wind: {wind}
                        </text>
                    </g>
                </g>

                {impactSvg && (
                    <circle cx={impactSvg.x} cy={impactSvg.y} r={8 * pixelScale} fill="#fbbf24" stroke="white" strokeWidth={1 * pixelScale} />
                )}
            </>
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useMemo, useState, useEffect } from 'react';
import { Point, PHYSICS_CONSTANTS, SavedTrajectory, AnalysisItem } from '../types';
import { Wind, ZoomIn, ZoomOut, X } from 'lucide-react';
import { calculateTrajectory } from '../services/physicsEngine';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  setZoom: (z: number) => void;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
  snapToGrid: boolean;
  savedTrajectories: SavedTrajectory[];
  analysisItems?: AnalysisItem[]; // New prop for separately managed analysis items
  onDeleteAnalysis?: (id: string) => void; // Handler to delete analysis item
  showCurrentTrajectory: boolean;
}

interface DragState {
    mode: 'IDLE' | 'PAN' | 'TARGET' | 'KNOB' | 'LABEL' | 'AWAIT_PAN_OR_CLICK';
    startScreen: Point;
    startPan: Point; // Physics units
    activeId?: string;
    hasMoved?: boolean;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  setZoom,
  isNight,
  wind,
  setWind,
  snapToGrid,
  savedTrajectories,
  analysisItems = [],
  onDeleteAnalysis,
  showCurrentTrajectory
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  // Track container size for responsive aspect ratio
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

  // Widget Hover States
  const [isWindExpanded, setIsWindExpanded] = useState(false);
  const windTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [isZoomExpanded, setIsZoomExpanded] = useState(false);
  const zoomTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // --- Interaction Logic for Wind Widget ---
  const handleWindEnter = () => {
    if (windTimeoutRef.current) clearTimeout(windTimeoutRef.current);
    setIsWindExpanded(true);
  };

  const handleWindLeave = () => {
    windTimeoutRef.current = setTimeout(() => {
        setIsWindExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };

  // --- Interaction Logic for Zoom Widget ---
  const handleZoomEnter = () => {
    if (zoomTimeoutRef.current) clearTimeout(zoomTimeoutRef.current);
    setIsZoomExpanded(true);
  };

  const handleZoomLeave = () => {
    zoomTimeoutRef.current = setTimeout(() => {
        setIsZoomExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };


  useEffect(() => {
    if (!containerRef.current) return;

    const updateSize = () => {
        if (containerRef.current) {
            const { width, height } = containerRef.current.getBoundingClientRect();
            if (width > 0 && height > 0) {
                setContainerSize({ width, height });
            }
        }
    };

    // Initial size
    updateSize();

    const observer = new ResizeObserver(updateSize);
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  // Viewport State: Pan Offset in Physics Units
  const [pan, setPan] = useState({ x: 0, y: 0 }); 

  // Custom offsets for saved labels (SVG px relative to target)
  const [labelOffsets, setLabelOffsets] = useState<Record<string, Point>>({});

  // Interaction State Machine
  const [dragState, setDragState] = useState<DragState>({ 
      mode: 'IDLE', 
      startScreen: { x: 0, y: 0 }, 
      startPan: { x: 0, y: 0 } 
  });

  // --- Pinch Zoom State ---
  const pinchRef = useRef({
      active: false,
      initialDist: 0,
      initialZoom: 1,
      initialPan: { x: 0, y: 0 },
      centerX: 0.5, // normalized 0-1
      centerY: 0.5  // normalized 0-1
  });

  // --- Viewport Calculations ---
  // We anchor the Vertical range and the Left side (Min X) based on constants + zoom.
  // We expand the Right side (Max X) based on the aspect ratio of the container.

  const aspectRatio = containerSize.height > 0 ? containerSize.width / containerSize.height : 1;

  // Base heights from constants
  const baseHeight = PHYSICS_CONSTANTS.MAX_Y - PHYSICS_CONSTANTS.MIN_Y;

  // Calculate visible range in physics units
  const currentHeight = baseHeight * zoom;
  const currentWidth = currentHeight * aspectRatio;

  const currentMinY = (PHYSICS_CONSTANTS.MIN_Y * zoom) + pan.y;
  const currentMaxY = currentMinY + currentHeight;

  // Anchor Left side to MIN_X
  const currentMinX = (PHYSICS_CONSTANTS.MIN_X * zoom) + pan.x;
  const currentMaxX = currentMinX + currentWidth;

  // Fixed SVG Resolution scaling
  const PIXELS_PER_UNIT = 40; 
  const VIEWBOX_WIDTH = currentWidth * PIXELS_PER_UNIT; 
  const VIEWBOX_HEIGHT = currentHeight * PIXELS_PER_UNIT;

  // --- Scale Factor for UI Elements ---
  // Calculates how many SVG units correspond to 1 screen pixel.
  // This allows us to scale text/UI so they look constant size on screen.
  const pixelScale = useMemo(() => {
    if (containerSize.width <= 0) return 1;
    return VIEWBOX_WIDTH / containerSize.width;
  }, [VIEWBOX_WIDTH, containerSize.width]);

  const toSvg = (p: Point) => {
    const percentX = (p.x - currentMinX) / currentWidth;
    const percentY = (p.y - currentMinY) / currentHeight;
    return {
        x: percentX * VIEWBOX_WIDTH,
        y: VIEWBOX_HEIGHT - (percentY * VIEWBOX_HEIGHT)
    };
  };

  const fromSvg = (svgX: number, svgY: number): Point => {
    const percentX = svgX / VIEWBOX_WIDTH;
    const percentY = (VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT; 
    return {
        x: currentMinX + percentX * currentWidth,
        y: currentMinY + percentY * currentHeight
    };
  };

  // Accurate SVG point from screen coordinates
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    let point = new DOMPoint(clientX, clientY);
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, currentMinX, currentMinY, currentWidth, currentHeight]); 

  // --- Saved Data Preparation ---
  // Pre-calculate positions for rendering and hit-testing
  // Refactored to handle dependency chain (Standard Labels -> Analysis Labels)
  const savedData = useMemo(() => {
    // We mix SavedTrajectories and AnalysisItems into a single render list
    // Standard trajectories first, so Analysis can find them
    const sortedByTime = [...savedTrajectories].sort((a, b) => a.timestamp - b.timestamp);

    // Map to store calculated label positions for lookup
    const processedMap = new Map<string, any>();

    sortedByTime.forEach((t) => {
        if (!t.visible) return;

        const d = pointsToPath(calculateTrajectory(tankPos, t.power, t.angle, t.wind));
        const targetSvg = toSvg(t.target);
        const dx = (t.target.x - tankPos.x).toFixed(1);
        const dy = (t.target.y - tankPos.y).toFixed(1);

        // Standard Positioning
        const originalIndex = savedTrajectories.findIndex(st => st.id === t.id);
        const defaultOffsetPx = { x: 0, y: -(40 + (originalIndex % 5) * 45) };
        const defaultOffsetSvg = { 
            x: defaultOffsetPx.x * pixelScale, 
            y: defaultOffsetPx.y * pixelScale 
        };

        const offset = labelOffsets[t.id] || defaultOffsetSvg;
        const usedOffset = offset;
        const labelPos = { x: targetSvg.x + offset.x, y: targetSvg.y + offset.y };

        const data = { 
           id: t.id, 
           d, 
           power: t.power,
           angle: t.angle, 
           wind: t.wind, 
           dx, dy, 
           targetPos: targetSvg,
           labelPos,
           color: t.color,
           isAnalysis: false,
           offset: usedOffset
        };

        processedMap.set(t.id, data);
    });

    // Process Analysis Items
    analysisItems.forEach((item) => {
        if (!item.visible) return;

        let labelPos = { x: 0, y: 0 };
        let connectorStartPoints = undefined; // [ {x,y}, {x,y} ] - Coordinates of parent right edges
        let usedOffset = { x: 0, y: 0 };
        let stats = { dAngle: '0', dWind: '0', dX: '0', dY: '0' };

        if (item.parentIds && item.parentIds.length === 2) {
             const p1 = processedMap.get(item.parentIds[0]);
             const p2 = processedMap.get(item.parentIds[1]);

             if (p1 && p2) {
                 // Calculate Deltas: First - Second
                 const dAngle = (p1.angle - p2.angle).toFixed(1);
                 const dWind = (p1.wind - p2.wind).toFixed(1);
                 const dX = (parseFloat(p1.dx) - parseFloat(p2.dx)).toFixed(1);
                 const dY = (parseFloat(p1.dy) - parseFloat(p2.dy)).toFixed(1);
                 stats = { dAngle, dWind, dX, dY };

                 // Dynamic Positioning: To the right of parents
                 // Standard Label Half-Width = 85 (Total 170)
                 const p1Right = p1.labelPos.x + (85 * pixelScale);
                 const p2Right = p2.labelPos.x + (85 * pixelScale);

                 // Base position is right of the furthest parent + gap
                 // We add a significant gap to allow for the polyline structure
                 // Reduced gap to keep layout tighter as requested
                 const baseX = Math.max(p1Right, p2Right) + (70 * pixelScale); 
                 const baseY = (p1.labelPos.y + p2.labelPos.y) / 2;

                 connectorStartPoints = [
                     { x: p1Right, y: p1.labelPos.y },
                     { x: p2Right, y: p2.labelPos.y }
                 ];

                 const offset = labelOffsets[item.id] || { x: 0, y: 0 };
                 usedOffset = offset;
                 labelPos = { x: baseX + offset.x, y: baseY + offset.y };
             } else {
                 // Fallback if parents missing
                 const targetSvg = toSvg(item.target);
                 const offset = labelOffsets[item.id] || { x: 0, y: -40 * pixelScale };
                 usedOffset = offset;
                 labelPos = { x: targetSvg.x + offset.x, y: targetSvg.y + offset.y };
             }
        }

        const data = {
            id: item.id,
            power: item.powerDiff, // Reuse power field for Diff
            labelPos,
            color: item.color,
            isAnalysis: true,
            connectorStartPoints,
            offset: usedOffset,
            targetPos: toSvg(item.target), // Just for hit testing proximity if needed
            stats // Store the differences
        };
         processedMap.set(item.id, data);
    });

    // Return array: Standard Trajectories followed by Analysis Items (so Analysis renders on top)
    const renderList = [
        ...sortedByTime.map(t => processedMap.get(t.id)),
        ...analysisItems.map(a => processedMap.get(a.id))
    ].filter(Boolean);

    return renderList;

  }, [savedTrajectories, analysisItems, tankPos, zoom, currentMinX, currentMinY, currentWidth, currentHeight, labelOffsets, pixelScale]);

  // --- Interaction Handlers ---

  const handleTouchStart = (e: React.TouchEvent) => {
      if (e.touches.length === 2) {
          e.preventDefault();
          const t1 = e.touches[0];
          const t2 = e.touches[1];

          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          // Calculate centroid relative to container
          const rect = containerRef.current?.getBoundingClientRect();
          if (!rect) return;

          const cx = ((t1.clientX + t2.clientX) / 2) - rect.left;
          const cy = ((t1.clientY + t2.clientY) / 2) - rect.top;

          pinchRef.current = {
              active: true,
              initialDist: dist,
              initialZoom: zoom,
              initialPan: { ...pan },
              centerX: cx / rect.width,
              centerY: cy / rect.height
          };

          // Cancel any active drag/pan
          setDragState(prev => ({ ...prev, mode: 'IDLE' }));
      }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      if (e.touches.length === 2 && pinchRef.current.active) {
          e.preventDefault();
          e.stopPropagation();

          const t1 = e.touches[0];
          const t2 = e.touches[1];
          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          if (pinchRef.current.initialDist > 10 && dist > 10) {
              const ratio = dist / pinchRef.current.initialDist;
              // Larger distance (spread) -> Smaller zoom value (Zoom In/Close up)
              let newZoom = pinchRef.current.initialZoom / ratio;
              newZoom = Math.max(0.25, Math.min(2.5, newZoom));

              // Calculate Pan compensation to zoom towards center
              // Formula: pan_new = pan_old + M * (z_old - z_new)
              const deltaZ = pinchRef.current.initialZoom - newZoom;

              // M_x = MIN_X + CenterX * Height * AR
              const Mx = PHYSICS_CONSTANTS.MIN_X + (pinchRef.current.centerX * baseHeight * aspectRatio);

              // M_y = MIN_Y + (1 - CenterY) * Height
              // Note: CenterY is 0 at top, 1 at bottom. Physics Y is 0 at bottom (relative to MIN_Y).
              const My = PHYSICS_CONSTANTS.MIN_Y + ((1 - pinchRef.current.centerY) * baseHeight);

              const newPanX = pinchRef.current.initialPan.x + (Mx * deltaZ);
              const newPanY = pinchRef.current.initialPan.y + (My * deltaZ);

              setZoom(newZoom);
              setPan({ x: newPanX, y: newPanY });
          }
      }
  };

  const handleTouchEnd = () => {
      pinchRef.current.active = false;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    // If pinch is active, ignore single pointer events
    if (pinchRef.current.active) return;

    if (!svgRef.current) return;
    (e.target as Element).setPointerCapture(e.pointerId);

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);
    const screenPt = { x: e.clientX, y: e.clientY };

    // 1. Check Angle Knob / Area (Only if active)
    const tankSvg = toSvg(tankPos);

    // Visual radius of the knob control (roughly 80px on screen)
    const knobRadius = 80 * pixelScale;
    const distToTank = Math.hypot(clickX - tankSvg.x, clickY - tankSvg.y);

    if (showCurrentTrajectory && distToTank < knobRadius + (10 * pixelScale)) {
        setDragState({ mode: 'KNOB', startScreen: screenPt, startPan: pan });
        return;
    }

    // 2. Check Saved Labels (Top-most first for hitting, so iterate reverse of render order?)
    // savedData is Old -> New (Render Order). 
    // Hit test should be New -> Old (Top -> Bottom).
    for (let i = savedData.length - 1; i >= 0; i--) {
        const item = savedData[i];

        // Define Hitbox size based on type
        // Analysis & Standard now have same size: 170x34 (Half 85x17)
        const halfW = 85 * pixelScale;
        const halfH = 17 * pixelScale;

        if (
            clickX >= item.labelPos.x - halfW && clickX <= item.labelPos.x + halfW &&
            clickY >= item.labelPos.y - halfH && clickY <= item.labelPos.y + halfH
        ) {
            setDragState({ 
                mode: 'LABEL', 
                startScreen: screenPt, 
                startPan: pan, 
                activeId: item.id
            });
            return;
        }
    }

    // 3. Check Active Target (Only if active)
    const targetSvg = toSvg(target);
    const targetHitRadius = 30 * pixelScale;
    if (showCurrentTrajectory && Math.hypot(clickX - targetSvg.x, clickY - targetSvg.y) < targetHitRadius) {
        setDragState({ mode: 'TARGET', startScreen: screenPt, startPan: pan });
        return;
    }

    // 4. Background -> Pan or Click
    setDragState({ 
        mode: 'AWAIT_PAN_OR_CLICK', 
        startScreen: screenPt, 
        startPan: pan, 
        hasMoved: false
    });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // If pinch active, ignore
    if (pinchRef.current.active) return;

    if (!svgRef.current) return;
    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    // Calculate screen deltas
    const dxScreen = e.clientX - dragState.startScreen.x;
    const dyScreen = e.clientY - dragState.startScreen.y;

    if (dragState.mode === 'KNOB') {
        const tankSvg = toSvg(tankPos);
        // Angle calc
        let newAngle = Math.atan2(-(pointerY - tankSvg.y), (pointerX - tankSvg.x)) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;
        if (newAngle > 180) newAngle = 180; 

        // Snap to integer angle for cleaner UI
        setAngle(Math.round(newAngle));

    } else if (dragState.mode === 'LABEL' && dragState.activeId) {
        const currentItem = savedData.find(sd => sd.id === dragState.activeId);
        if (currentItem && currentItem.offset) {
             const basePosX = currentItem.labelPos.x - currentItem.offset.x;
             const basePosY = currentItem.labelPos.y - currentItem.offset.y;

             let destX = pointerX;
             let destY = pointerY;

             // Snap logic
             if (snapToGrid) {
                 const physPoint = fromSvg(destX, destY);
                 const snappedPhysX = Math.round(physPoint.x);
                 const snappedPhysY = Math.round(physPoint.y);
                 const snappedSvg = toSvg({ x: snappedPhysX, y: snappedPhysY });
                 destX = snappedSvg.x;
                 destY = snappedSvg.y;
             }

             setLabelOffsets(prev => ({
                ...prev,
                [dragState.activeId!]: {
                    x: destX - basePosX,
                    y: destY - basePosY
                }
             }));
        }

    } else if (dragState.mode === 'TARGET') {
        const physicsPoint = fromSvg(pointerX, pointerY);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });

    } else if (dragState.mode === 'PAN' || (dragState.mode === 'AWAIT_PAN_OR_CLICK' && Math.hypot(dxScreen, dyScreen) > 5)) {
        if (dragState.mode === 'AWAIT_PAN_OR_CLICK') {
            setDragState(prev => ({ ...prev, mode: 'PAN', hasMoved: true }));
        }

        const ctm = svgRef.current?.getScreenCTM();
        const scaleX = ctm ? ctm.a : 1; 

        const dxPhys = -dxScreen / (PIXELS_PER_UNIT * scaleX);
        const dyPhys = dyScreen / (PIXELS_PER_UNIT * scaleX);

        setPan({
            x: dragState.startPan.x + dxPhys,
            y: dragState.startPan.y + dyPhys
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    (e.target as Element).releasePointerCapture(e.pointerId);

    if (showCurrentTrajectory && dragState.mode === 'AWAIT_PAN_OR_CLICK' && !dragState.hasMoved) {
        const { x, y } = getSvgPoint(e.clientX, e.clientY);
        const physicsPoint = fromSvg(x, y);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });
    }

    setDragState({ mode: 'IDLE', startScreen: {x:0, y:0}, startPan: {x:0, y:0} });
  };

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = (target.y - tankPos.y).toFixed(2); 

  // Generate Grid Lines
  const gridLines = useMemo(() => {
    const lines = [];
    const startX = Math.floor(currentMinX);
    const endX = Math.ceil(currentMaxX);
    const startY = Math.floor(currentMinY);
    const endY = Math.ceil(currentMaxY);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const axisColor = isNight ? "#94a3b8" : "#475569"; 
    const minorColor = isNight ? "rgba(51, 65, 85, 0.4)" : "rgba(203, 213, 225, 0.6)";
    const textColor = isNight ? "#64748b" : "#94a3b8";

    const strokeW = Math.max(1 * pixelScale, 1); 
    const fontSz = 12 * pixelScale; 

    const useSparseGrid = zoom > 1.5;

    for (let i = startX; i <= endX; i++) {
        const p = toSvg({ x: i, y: 0 }); 
        const x = p.x;
        if (x < -50 * pixelScale || x > VIEWBOX_WIDTH + 50 * pixelScale) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 12 === 0; 

        if (useSparseGrid && !isAxis && !isMajor) continue;

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? strokeW * 2 : strokeW} 
                strokeDasharray={isAxis || isMajor ? "" : `${4 * pixelScale},${2 * pixelScale}`}
            />
        );

        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + (4 * pixelScale)} 
                y={VIEWBOX_HEIGHT - (10 * pixelScale)} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={fontSz}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
                style={{ userSelect: 'none' }}
            >
                {i}
            </text>
        );
    }

    for (let i = startY; i <= endY; i++) {
        const p = toSvg({ x: 0, y: i }); 
        const y = p.y;
        if (y < -50 * pixelScale || y > VIEWBOX_HEIGHT + 50 * pixelScale) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 6 === 0;

        if (useSparseGrid && !isAxis && !isMajor) continue;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? strokeW * 2 : strokeW} 
                strokeDasharray={isAxis || isMajor ? "" : `${4 * pixelScale},${2 * pixelScale}`}
            />
        );

        lines.push(
            <text 
                key={`th-${i}`} 
                x={10 * pixelScale} 
                y={y - (4 * pixelScale)} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={fontSz}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
                style={{ userSelect: 'none' }}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [currentMinX, currentMaxX, currentMinY, currentMaxY, VIEWBOX_WIDTH, VIEWBOX_HEIGHT, isNight, toSvg, pixelScale, zoom]);

  const knobRadius = 80 * pixelScale; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // Dynamic Styles for Wind Widget
  const windWidgetClasses = isNight 
    ? 'bg-slate-800/95 border-slate-600'
    : 'bg-white/95 border-slate-200';

  const windTextClasses = isNight ? 'text-slate-300' : 'text-slate-700';
  const windLabelClasses = isNight ? 'text-slate-500' : 'text-slate-500';
  const windBtnClasses = isNight 
    ? 'bg-slate-700 hover:bg-slate-600 text-white' 
    : 'bg-slate-200 hover:bg-slate-300 text-slate-800';

  const mainColor = isNight ? "#38bdf8" : "#0284c7";

  if (containerSize.width === 0) return <div ref={containerRef} className="w-full h-full" />;

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none`}
    >
      {/* Wind Control Widget */}
      <div 
        onMouseEnter={handleWindEnter}
        onMouseLeave={handleWindLeave}
        className={`absolute top-4 left-1/2 -translate-x-1/2 backdrop-blur rounded-xl border shadow-xl flex flex-col items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isWindExpanded ? 'w-60 p-2' : 'w-auto px-4 py-2 hover:w-60 hover:p-2 cursor-pointer'}`}
      >
        {isWindExpanded ? (
            <>
                <div className={`text-[10px] font-bold ${windTextClasses} mb-1 w-full flex justify-between items-center`}>
                    <span className={`text-[9px] ${windLabelClasses}`}>WEST</span>
                    <span className={`flex items-center gap-1 ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-400') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                        <Wind size={10} />
                        WIND: {Math.abs(wind).toFixed(1)}
                    </span>
                    <span className={`text-[9px] ${windLabelClasses}`}>EAST</span>
                </div>
                <div className="flex items-center w-full gap-2 opacity-100 transition-opacity duration-300 delay-100">
                    <button onClick={() => setWind(Number((wind - 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>-</button>
                    <div className="relative flex-1 h-5 flex items-center mx-1">
                        <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                        <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-sky-500 z-10 relative ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}/>
                    </div>
                    <button onClick={() => setWind(Number((wind + 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>+</button>
                </div>
            </>
        ) : (
             <div className="flex items-center gap-2">
                <Wind size={14} className={wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-500' : 'text-rose-500'} />
                <span className={`text-xs font-bold font-mono ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-500') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {wind.toFixed(1)}
                </span>
            </div>
        )}
      </div>

      {/* Zoom Control Widget */}
      <div 
        onMouseEnter={handleZoomEnter}
        onMouseLeave={handleZoomLeave}
        className={`absolute bottom-4 right-4 backdrop-blur rounded-xl border shadow-xl flex items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isZoomExpanded ? 'w-64 p-3 gap-3' : 'w-24 p-2 gap-2 cursor-pointer hover:w-64 hover:p-3 hover:gap-3'}`}
      >
        {isZoomExpanded ? (
            <>
                <button onClick={() => setZoom(Math.max(0.25, zoom - 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomOut size={12} />
                </button>
                <div className="flex-1 flex flex-col items-center">
                    <div className="flex justify-between w-full text-[10px] font-bold mb-1 opacity-80">
                         <span className={windLabelClasses}>VIEW RANGE</span>
                         <span className={isNight ? 'text-indigo-300' : 'text-indigo-600'}>{(zoom * 100).toFixed(0)}%</span>
                    </div>
                    <input
                        type="range"
                        min="0.25"
                        max="2.5"
                        step="0.1"
                        value={zoom}
                        onChange={(e) => setZoom(Number(e.target.value))}
                        className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                    />
                </div>
                <button onClick={() => setZoom(Math.min(2.5, zoom + 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomIn size={12} />
                </button>
            </>
        ) : (
            <>
                <input
                    type="range"
                    min="0.25"
                    max="2.5"
                    step="0.1"
                    value={zoom}
                    readOnly
                    className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                />
            </>
        )}
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Curve Analysis View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            X: {currentMinX.toFixed(0)} to {currentMaxX.toFixed(0)} | Y: {currentMinY.toFixed(0)} to {currentMaxY.toFixed(0)}
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className={`w-full h-full block touch-none ${
            dragState.mode === 'PAN' ? 'cursor-grabbing' : 
            dragState.mode === 'LABEL' ? 'cursor-move' : 
            dragState.mode === 'TARGET' ? 'cursor-crosshair' : 
            dragState.mode === 'KNOB' ? 'cursor-grab' : 'cursor-grab'
        }`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}

        // Touch Events for Pinch Zoom
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onTouchCancel={handleTouchEnd}

        preserveAspectRatio="none"
      >
        <defs>
            <marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
                <path d="M0,0 L0,6 L9,3 z" fill="#a855f7" />
            </marker>
            <radialGradient id="angleGradient" cx="0.5" cy="0.5" r="0.5">
                <stop offset="0%" stopColor={mainColor} stopOpacity="0.25" />
                <stop offset="100%" stopColor={mainColor} stopOpacity="0" />
            </radialGradient>
            <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
              <feDropShadow dx="0" dy={2 * pixelScale} stdDeviation={2 * pixelScale} floodColor="#000000" floodOpacity="0.3" />
            </filter>
            <filter id="simpleBlur" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation={2 * pixelScale} />
            </filter>
        </defs>

        {/* Grid Lines */}
        {gridLines}

        {/* Saved Trajectories and Labels */}
        {savedData.map((sd) => (
            <g key={sd.id}>
                {/* Only draw path if it's NOT an analysis item */}
                {!sd.isAnalysis && (
                    <path d={sd.d} fill="none" stroke={sd.color} strokeWidth={2 * pixelScale} strokeDasharray={`${5*pixelScale},${5*pixelScale}`} className="opacity-60" />
                )}

                {/* Draw Analysis Connector Lines (Polylines/Manhattan) */}
                {sd.isAnalysis && sd.connectorStartPoints && (
                    <>
                        {sd.connectorStartPoints.map((pt: Point, idx: number) => {
                             // Analysis Label Left Edge is at labelPos.x - 45*scale
                             const endX = sd.labelPos.x - (85 * pixelScale); // Updated half width for larger label
                             const endY = sd.labelPos.y;

                             // Start Point (Parent Right Edge)
                             const startX = pt.x;
                             const startY = pt.y;

                             // Fixed Length Tail Calculation
                             // We want the vertical line to be near the label (endX)
                             // elbowX = endX - FixedLength
                             // But we clamp it to be to the right of startX
                             const fixedTail = 20 * pixelScale; 
                             const minLead = 10 * pixelScale;

                             const elbowX = Math.max(startX + minLead, endX - fixedTail);

                             return (
                                 <polyline 
                                    key={idx}
                                    points={`${startX},${startY} ${elbowX},${startY} ${elbowX},${endY} ${endX},${endY}`}
                                    fill="none"
                                    stroke={sd.color}
                                    strokeWidth={1.5 * pixelScale}
                                    strokeDasharray={`${3*pixelScale},${3*pixelScale}`}
                                    strokeLinejoin="round"
                                    opacity="0.6"
                                 />
                             );
                        })}
                    </>
                )}

                <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                     <circle r={sd.isAnalysis ? 3 * pixelScale : 6 * pixelScale} fill="none" stroke={sd.color} strokeWidth={sd.isAnalysis ? 1 * pixelScale : 3 * pixelScale} />
                     <circle r={2 * pixelScale} fill={sd.color} />
                </g>

                {!sd.isAnalysis && (
                    <line 
                        x1={sd.labelPos.x} y1={sd.labelPos.y} 
                        x2={sd.targetPos.x} y2={sd.targetPos.y} 
                        stroke={sd.color} strokeWidth={1.5 * pixelScale} 
                        strokeDasharray={`${4*pixelScale},${2*pixelScale}`}
                        opacity="0.8"
                    />
                )}

                {/* Draggable Label */}
                <g 
                    transform={`translate(${sd.labelPos.x}, ${sd.labelPos.y}) scale(${pixelScale})`} 
                    className="cursor-move group"
                > 

                    {sd.isAnalysis ? (
                        <>
                             {/* Expanded Analysis Label Background - Matches Standard Size */}
                             <rect 
                                x="-85" y="-17" width="170" height="34" rx="6" 
                                fill={isNight ? "#1e293b" : "#ffffff"} 
                                stroke={sd.color} strokeWidth="2" 
                                filter="url(#shadow)"
                            />
                            {/* Decorative Left Edge */}
                            <path 
                                d="M -35 -17 L -79 -17 Q -85 -17 -85 -11 L -85 11 Q -85 17 -79 17 L -35 17 Z" 
                                fill={sd.color} 
                            />

                            {/* Analysis Label Layout */}
                            <text x="-60" y="-4" textAnchor="middle" fill="rgba(255,255,255,0.8)" fontSize="8" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                DIFF
                            </text>

                            {/* Main Value */}
                            <text x="-60" y="10" textAnchor="middle" fill="white" fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                {sd.power > 0 ? '+' : ''}{sd.power.toFixed(1)}
                            </text>

                            {/* Right Side: Calculated Deltas */}
                             {/* Row 1: Angle & Wind Deltas */}
                             <text x="-25" y="-3" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>ΔA:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.stats?.dAngle}°</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>ΔW:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.stats?.dWind}</tspan>
                            </text>

                            {/* Row 2: X & Y Deltas */}
                            <text x="-25" y="9" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>ΔX:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.stats?.dX}</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>ΔY:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.stats?.dY}</tspan>
                            </text>

                            {/* Close Button (Shows on Hover or Touch) */}
                            {onDeleteAnalysis && (
                                <g 
                                    transform="translate(85, -17)" // Top-right corner relative to center
                                    className="cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity"
                                    onClick={(e) => {
                                        e.stopPropagation(); // Prevent drag start
                                        onDeleteAnalysis(sd.id);
                                    }}
                                    onPointerDown={(e) => e.stopPropagation()} // Prevent drag start on touch
                                >
                                    <circle cx="-10" cy="10" r="8" fill="#ef4444" stroke="white" strokeWidth="1" />
                                    <line x1="-13" y1="7" x2="-7" y2="13" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
                                    <line x1="-7" y1="7" x2="-13" y2="13" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
                                </g>
                            )}
                        </>
                    ) : (
                        <>
                            {/* Standard Label Background - Height 34 */}
                            <rect 
                                x="-85" y="-17" width="170" height="34" rx="6" 
                                fill={isNight ? "#1e293b" : "#ffffff"} 
                                stroke={sd.color} strokeWidth="2" 
                                filter="url(#shadow)"
                            />
                            {/* Custom Left Decorative Shape */}
                            <path 
                                d="M -35 -17 L -79 -17 Q -85 -17 -85 -11 L -85 11 Q -85 17 -79 17 L -35 17 Z" 
                                fill={sd.color} 
                            />
                            {/* Standard Label Layout */}
                            <text x="-60" y="-4" textAnchor="middle" fill="rgba(255,255,255,0.7)" fontSize="8" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                POWER
                            </text>
                            <text x="-60" y="10" textAnchor="middle" fill="white" fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                {sd.power.toFixed(1)}
                            </text>

                            {/* Right Side: Data - Row 1: Angle & Wind */}
                            <text x="-25" y="-3" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>A:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.angle}°</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>W:</tspan> <tspan fontWeight="bold" fill={sd.wind === 0 ? (isNight ? "#94a3b8" : "#64748b") : (sd.wind > 0 ? "#10b981" : "#f43f5e")}>{sd.wind}</tspan>
                            </text>

                            {/* Right Side: Data - Row 2: Coordinates */}
                            <text x="-25" y="9" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>X:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.dx}</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>Y:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.dy}</tspan>
                            </text>
                        </>
                    )}
                </g>
            </g>
        ))}

        {/* Active Elements */}
        {showCurrentTrajectory && (
            <>
                <circle 
                    cx={tankSvg.x} 
                    cy={tankSvg.y} 
                    r={knobRadius} 
                    fill="url(#angleGradient)" 
                    className="cursor-pointer hover:opacity-100 transition-opacity"
                    style={{ opacity: 0.8 }}
                />

                <path d={trajectoryPath} fill="none" stroke={mainColor} strokeWidth={4 * pixelScale} strokeDasharray={`${10*pixelScale},${10*pixelScale}`} className="opacity-80" />

                <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
                    <path d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`} fill="none" stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"} strokeWidth={2 * pixelScale} strokeDasharray={`${4*pixelScale},${4*pixelScale}`}/>

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                        stroke="#dc2626" strokeWidth={8 * pixelScale} strokeLinecap="round" opacity="0.3" filter="url(#simpleBlur)" />

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                        stroke="#dc2626" strokeWidth={3 * pixelScale} strokeLinecap="round" />

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                         stroke="transparent" strokeWidth={20 * pixelScale} strokeLinecap="round" style={{ pointerEvents: 'auto' }} />
                </g>

                <g>
                    <circle 
                        cx={tankSvg.x} 
                        cy={tankSvg.y} 
                        r={18 * pixelScale} 
                        fill={isNight ? "#0f172a" : "#ffffff"} 
                        stroke={mainColor} 
                        strokeWidth={3 * pixelScale} 
                    />
                    <text 
                        x={tankSvg.x} 
                        y={tankSvg.y} 
                        dy={4 * pixelScale} 
                        textAnchor="middle" 
                        fill={mainColor} 
                        fontSize={11 * pixelScale} 
                        fontWeight="bold" 
                        fontFamily="'Varela Round', sans-serif"
                        className="pointer-events-none select-none"
                    >
                        {angle}°
                    </text>
                </g>

                <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
                    <circle r={5 * pixelScale} fill={mainColor} />
                    <circle r={12 * pixelScale} fill="none" stroke={mainColor} strokeWidth={1.5 * pixelScale} opacity="0.6" className="animate-pulse" />

                    {/* Tooltip scaled by pixelScale */}
                    <g transform={`translate(0, -${65 * pixelScale}) scale(${pixelScale})`}>
                        <rect x="-70" y="0" width="140" height="50" rx="6" fill={isNight ? "rgba(15, 23, 42, 0.9)" : "rgba(255, 255, 255, 0.9)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
                        <text x="0" y="20" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="16" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            ({dx}, {dy})
                        </text>
                        <text x="0" y="38" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            Wind: {wind}
                        </text>
                    </g>
                </g>

                {impactSvg && (
                    <circle cx={impactSvg.x} cy={impactSvg.y} r={8 * pixelScale} fill="#fbbf24" stroke="white" strokeWidth={1 * pixelScale} />
                )}
            </>
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

import React, { useState, useEffect, useMemo } from 'react';
import GameCanvas from './components/GameCanvas';
import Controls from './components/Controls';
import { GameMode, Point, PHYSICS_CONSTANTS, ThemeMode, SavedTrajectory, AnalysisItem } from './types';
import { solvePower, calculateTrajectory } from './services/physicsEngine';

// Tank position is fixed at origin for analysis view
const TANK_POS: Point = { x: 0, y: 0 }; 
// Initial target placed in a typical "shot" location (positive X, slight positive Y)
const INITIAL_TARGET: Point = { x: 15, y: 5 };

export const TRAJECTORY_COLORS = [
  '#a855f7', // Purple
  '#ef4444', // Red
  '#22c55e', // Green
  '#3b82f6', // Blue
  '#f97316', // Orange
  '#06b6d4', // Cyan
];

function App() {
  const [mode, setMode] = useState<GameMode>(GameMode.AUTO_AIM);
  const [isNight, setIsNight] = useState(false); // Default to Day mode
  const [zoom, setZoom] = useState(0.7); // Default view range 70%
  const [snapToGrid, setSnapToGrid] = useState(true); // Default to Snap ON
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [showCurrentTrajectory, setShowCurrentTrajectory] = useState(true); 

  // Inputs
  const [angle, setAngle] = useState(65);
  const [wind, setWind] = useState(0);
  const [manualPower, setManualPower] = useState(50);
  const [target, setTarget] = useState<Point>(INITIAL_TARGET);

  // Memory / History
  const [savedTrajectories, setSavedTrajectories] = useState<SavedTrajectory[]>([]);

  // Analysis Items (Managed on Canvas now)
  const [analysisItems, setAnalysisItems] = useState<AnalysisItem[]>([]);

  // Selection State (Shared)
  // Order matters: [FirstSelected, SecondSelected]
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // Derived State
  const [calculatedPower, setCalculatedPower] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  // 0. Theme Sync Effect: Ensure body background matches app theme to prevent "black bars"
  useEffect(() => {
    document.body.className = isNight 
        ? 'bg-slate-950 text-slate-100 overflow-hidden' 
        : 'bg-slate-100 text-slate-900 overflow-hidden';
  }, [isNight]);

  // 1. Logic Loop: Handle Physics Calculation
  useEffect(() => {
    // Relative distance components
    const dist = target.x - TANK_POS.x;
    const height = target.y - TANK_POS.y;

    if (dist <= 0) {
        setError("Target must be to the right of the player");
        setCalculatedPower(null);
        return;
    }

    // Try to solve for power
    const neededPower = solvePower(dist, height, angle, wind);

    if (neededPower === null) {
       setError("Target unreachable with current angle/wind");
       setCalculatedPower(null);
    } else if (neededPower === -99999) {
        setError("Force insufficient (Out of range or strong headwind)");
        setCalculatedPower(null);
    } else {
        setError(null);
        setCalculatedPower(neededPower);

        // If in Auto-Aim, sync manual power for smoother transition
        if (mode === GameMode.AUTO_AIM) {
            // Check bounds
            if (neededPower > 100) {
               setError("Required power exceeds limit (100)");
               setManualPower(100); 
            } else {
               setManualPower(neededPower);
            }
        }
    }
  }, [target, angle, wind, mode]);

  // 2. Logic Loop: Generate Trajectory Points
  const trajectory = useMemo(() => {
    return calculateTrajectory(TANK_POS, manualPower, angle, wind);
  }, [manualPower, angle, wind]);

  // Find where it hits ground or target height
  const impactPoint = useMemo(() => {
      if (trajectory.length === 0) return null;
      return trajectory[trajectory.length - 1];
  }, [trajectory]);

  // --- Memory Functions ---
  const saveCurrentTrajectory = (preferredColor?: string) => {
      const newEntry: SavedTrajectory = {
          id: Date.now().toString(),
          power: manualPower,
          angle: angle,
          wind: wind,
          target: { ...target },
          visible: true,
          color: preferredColor || TRAJECTORY_COLORS[0], 
          timestamp: Date.now()
      };
      setSavedTrajectories(prev => [newEntry, ...prev]);
  };

  const deleteTrajectory = (id: string) => {
      setSavedTrajectories(prev => prev.filter(t => t.id !== id));
      // Also cleanup analysis items that depend on this
      setAnalysisItems(prev => prev.filter(a => !a.parentIds.includes(id)));
      // Cleanup selection
      setSelectedIds(prev => prev.filter(pid => pid !== id));
  };

  const toggleTrajectoryVisibility = (id: string) => {
      setSavedTrajectories(prev => prev.map(t => 
        t.id === id ? { ...t, visible: !t.visible } : t
      ));
  };

  const updateTrajectoryColor = (id: string, newColor: string) => {
    setSavedTrajectories(prev => prev.map(t => {
        if (t.id !== id) return t;
        return { ...t, color: newColor };
    }));
  };

  const toggleColorVisibility = (color: string) => {
      setSavedTrajectories(prev => {
          const group = prev.filter(t => t.color === color);
          if (group.length === 0) return prev;
          const allVisible = group.every(t => t.visible);
          return prev.map(t => {
              if (t.color === color) {
                  return { ...t, visible: !allVisible };
              }
              return t;
          });
      });
  };

  // --- Analysis Functions ---
  const handleToggleSelection = (id: string) => {
      setSelectedIds(prev => {
          if (prev.includes(id)) {
              // Unselect
              return prev.filter(pid => pid !== id);
          } else {
              // Select
              if (prev.length >= 2) {
                  // If we already have 2, shift the oldest one out (First selected becomes the one that remains)
                  return [prev[1], id]; 
              }
              return [...prev, id];
          }
      });
  };

  const handleAnalyze = (id1: string, id2: string) => {
      const t1 = savedTrajectories.find(t => t.id === id1);
      const t2 = savedTrajectories.find(t => t.id === id2);

      if (!t1 || !t2) return;

      // Logic: First Selected (t1) - Second Selected (t2)
      const diffPower = t1.power - t2.power;

      const midX = (t1.target.x + t2.target.x) / 2;
      const midY = (t1.target.y + t2.target.y) / 2;

      const newItem: AnalysisItem = {
          id: `diff-${Date.now()}`,
          powerDiff: diffPower,
          target: { x: midX, y: midY },
          parentIds: [id1, id2],
          visible: true,
          color: '#fbbf24',
      };

      setAnalysisItems(prev => [newItem, ...prev]);
      setSelectedIds([]); // Clear selection after creating Diff
  };

  const deleteAnalysisItem = (id: string) => {
      setAnalysisItems(prev => prev.filter(a => a.id !== id));
  };

  return (
    <div className={`fixed inset-0 w-full h-full flex overflow-hidden transition-colors duration-500 ${isNight ? 'bg-slate-950' : 'bg-slate-100'}`}>
        <style>{`
          ::-webkit-scrollbar-thumb {
            background-color: ${isNight ? '#334155' : '#cbd5e1'};
          }
          ::-webkit-scrollbar-thumb:hover {
            background-color: ${isNight ? '#475569' : '#94a3b8'};
          }
          ::-webkit-scrollbar-track {
            background-color: transparent;
          }
        `}</style>

        <Controls 
            angle={angle}
            setAngle={setAngle}
            wind={wind}
            setWind={setWind}
            power={manualPower}
            setPower={setManualPower}
            mode={mode}
            setMode={setMode}
            target={target}
            tankPos={TANK_POS}
            calculationResult={calculatedPower}
            error={error}
            isNight={isNight}
            setIsNight={setIsNight}
            zoom={zoom}
            setZoom={setZoom}
            snapToGrid={snapToGrid}
            setSnapToGrid={setSnapToGrid}
            onSaveTrajectory={saveCurrentTrajectory}
            onAnalyze={handleAnalyze} 
            savedTrajectories={savedTrajectories}
            onDeleteTrajectory={deleteTrajectory}
            onToggleVisibility={toggleTrajectoryVisibility}
            onUpdateColor={updateTrajectoryColor}
            onToggleColorVisibility={toggleColorVisibility}
            isOpen={isSidebarOpen}
            onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
            showCurrentTrajectory={showCurrentTrajectory}
            onToggleCurrentTrajectory={() => setShowCurrentTrajectory(!showCurrentTrajectory)}
            selectedIds={selectedIds} // Pass down
            onToggleSelection={handleToggleSelection} // Pass down
        />

        <div className="flex-1 relative z-0 h-full w-full min-w-0 p-4 flex flex-col items-center justify-center transition-all duration-300 ease-in-out">
            <div className="w-full h-full max-w-full max-h-[95vh] relative flex items-center justify-center">
                <div className="w-full h-full shadow-2xl rounded-xl overflow-hidden">
                    <GameCanvas 
                        trajectory={trajectory}
                        target={target}
                        tankPos={TANK_POS}
                        onSetTarget={setTarget}
                        impactPoint={impactPoint}
                        angle={angle}
                        setAngle={setAngle}
                        zoom={zoom}
                        setZoom={setZoom}
                        isNight={isNight}
                        wind={wind}
                        setWind={setWind}
                        snapToGrid={snapToGrid}
                        savedTrajectories={savedTrajectories}
                        analysisItems={analysisItems}
                        onDeleteAnalysis={deleteAnalysisItem}
                        showCurrentTrajectory={showCurrentTrajectory}
                        selectedIds={selectedIds} // Pass down
                        onToggleSelection={handleToggleSelection} // Pass down
                        onAnalyze={handleAnalyze} // Pass down for canvas button
                    />
                </div>
            </div>
             <div className={`mt-2 text-sm ${isNight ? 'text-slate-500' : 'text-slate-400'} ${!isSidebarOpen ? 'opacity-50' : 'opacity-100'} transition-opacity text-center px-4`}>
                Click map to move target • Drag angle pointer to aim • Click items to select for Diff
            </div>
        </div>
    </div>
  );
}

export default App;

import React, { useMemo, useState } from 'react';
import { GameMode, Point, SavedTrajectory } from '../types';
import { Wind, Crosshair, Zap, MousePointer2, Sun, Moon, Magnet, Save, Trash2, Eye, EyeOff, Plus, Minus, ChevronRight, ChevronLeft, Activity, Layers, Calculator, CheckCircle2 } from 'lucide-react';
import { TRAJECTORY_COLORS } from '../App';

interface ControlsProps {
  angle: number;
  setAngle: (v: number) => void;
  wind: number;
  setWind: (v: number) => void;
  power: number;
  setPower: (v: number) => void;
  mode: GameMode;
  setMode: (m: GameMode) => void;
  target: Point;
  tankPos: Point;
  calculationResult: number | null;
  error: string | null;
  isNight: boolean;
  setIsNight: (v: boolean) => void;
  zoom: number;
  setZoom: (v: number) => void;
  snapToGrid: boolean;
  setSnapToGrid: (v: boolean) => void;
  // Memory props
  onSaveTrajectory: (color?: string) => void;
  onAnalyze: (id1: string, id2: string) => void; 
  savedTrajectories: SavedTrajectory[];
  onDeleteTrajectory: (id: string) => void;
  onToggleVisibility: (id: string) => void;
  onUpdateColor: (id: string, color: string) => void;
  onToggleColorVisibility: (color: string) => void;
  // Sidebar State
  isOpen: boolean;
  onToggle: () => void;
  // Live Trajectory Toggle
  showCurrentTrajectory: boolean;
  onToggleCurrentTrajectory: () => void;
  // Selection
  selectedIds: string[];
  onToggleSelection: (id: string) => void;
}

const Controls: React.FC<ControlsProps> = ({
  angle,
  setAngle,
  wind,
  setWind,
  power,
  setPower,
  mode,
  setMode,
  target,
  tankPos,
  calculationResult,
  error,
  isNight,
  setIsNight,
  zoom,
  setZoom,
  snapToGrid,
  setSnapToGrid,
  onSaveTrajectory,
  onAnalyze,
  savedTrajectories,
  onDeleteTrajectory,
  onToggleVisibility,
  onUpdateColor,
  onToggleColorVisibility,
  isOpen,
  onToggle,
  showCurrentTrajectory,
  onToggleCurrentTrajectory,
  selectedIds,
  onToggleSelection
}) => {
  const [editingColorId, setEditingColorId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<string | 'ALL'>('ALL');

  const dist = Math.abs(target.x - tankPos.x).toFixed(2);
  const heightDiff = (target.y - tankPos.y).toFixed(2);

  const handleModeToggle = (newMode: GameMode) => {
    setMode(newMode);
    if (newMode === GameMode.AUTO_AIM && calculationResult) {
      setPower(calculationResult);
    }
  };

  const adjustAngle = (delta: number) => {
    setAngle(Math.min(180, Math.max(0, angle + delta)));
  };

  const adjustWind = (delta: number) => {
    setWind(Number((Math.min(150, Math.max(-150, wind + delta))).toFixed(1)));
  };

  const adjustPower = (delta: number) => {
     setMode(GameMode.MANUAL);
     setPower(Number((Math.min(100, Math.max(0, power + delta))).toFixed(1)));
  };

  const handleSave = () => {
    onSaveTrajectory(activeTab === 'ALL' ? undefined : activeTab);
  };

  const handleRunAnalysis = () => {
      if (selectedIds.length === 2) {
          // Pass strict order: First Selected, Second Selected
          onAnalyze(selectedIds[0], selectedIds[1]);
      }
  };

  // Determine which colors are currently used
  const activeColorStats = useMemo(() => {
    const stats: Record<string, { count: number, visibleCount: number }> = {};
    savedTrajectories.forEach(t => {
      if (!stats[t.color]) {
        stats[t.color] = { count: 0, visibleCount: 0 };
      }
      stats[t.color].count++;
      if (t.visible) stats[t.color].visibleCount++;
    });
    return stats;
  }, [savedTrajectories]);

  const displayTrajectories = useMemo(() => {
    let filtered = savedTrajectories;
    if (activeTab !== 'ALL') {
        filtered = savedTrajectories.filter(t => t.color === activeTab);
    }
    // Sort by timestamp for list display
    return [...filtered].sort((a, b) => b.timestamp - a.timestamp);
  }, [savedTrajectories, activeTab]);

  const themeClasses = isNight 
    ? {
      bg: 'bg-slate-900',
      border: 'border-slate-700',
      text: 'text-white',
      subText: 'text-slate-400',
      inputBg: 'bg-slate-700',
      btnBg: 'bg-slate-800 hover:bg-slate-700',
      panelBg: 'bg-slate-800'
    } 
    : {
      bg: 'bg-white',
      border: 'border-slate-200',
      text: 'text-slate-900',
      subText: 'text-slate-500',
      inputBg: 'bg-slate-200',
      btnBg: 'bg-slate-100 hover:bg-slate-200',
      panelBg: 'bg-slate-50'
    };

  return (
    <>
      <div 
        className={`md:hidden fixed inset-0 z-20 bg-black/50 transition-opacity duration-300 ${isOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
        onClick={onToggle}
      />

      <div className={`
        absolute md:relative z-30 flex flex-col h-full border-r ${themeClasses.border} shadow-xl transition-all duration-300 ease-in-out 
        ${isNight ? 'bg-slate-900' : 'bg-slate-50'} 
        ${isOpen ? 'w-80 translate-x-0' : 'w-0 -translate-x-full md:translate-x-0 md:w-0'}
      `}>
        <button
          onClick={onToggle}
          className={`absolute right-0 top-1/2 translate-x-full -translate-y-1/2 p-2 rounded-r-xl border-y border-r ${themeClasses.border} ${themeClasses.bg} ${themeClasses.text} hover:brightness-110 shadow-lg z-50 flex items-center justify-center w-8 h-16 transition-colors duration-300`}
        >
          {isOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
        </button>

        <div className={`w-80 flex flex-col h-full overflow-hidden ${isOpen ? 'opacity-100' : 'opacity-0'} transition-opacity duration-200`}>
          <div className="flex-1 overflow-y-auto p-6 space-y-8">
              <div className="flex justify-between items-start">
                  <div>
                      <h1 className={`text-2xl font-bold ${themeClasses.text} mb-1 flex items-center gap-2`}>
                      <Crosshair className="text-sky-500" />
                      Ballistic Master
                      </h1>
                      <p className={`${themeClasses.subText} text-sm`}>Trajectory Calculation System</p>
                  </div>
                  <button 
                      onClick={() => setIsNight(!isNight)}
                      className={`p-2 rounded-full ${isNight ? 'bg-slate-800 text-yellow-400 hover:bg-slate-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'} transition-colors`}
                  >
                      {isNight ? <Moon size={20} /> : <Sun size={20} />}
                  </button>
              </div>

              <div className={`grid grid-cols-2 gap-2 p-1 ${isNight ? 'bg-slate-800' : 'bg-slate-200'} rounded-lg`}>
                  <button onClick={() => handleModeToggle(GameMode.AUTO_AIM)} className={`flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium transition-all ${mode === GameMode.AUTO_AIM ? 'bg-sky-600 text-white shadow-lg' : `${themeClasses.subText} hover:${themeClasses.text} hover:bg-white/10`}`}>
                  <Zap size={16} /> Auto-Aim
                  </button>
                  <button onClick={() => handleModeToggle(GameMode.MANUAL)} className={`flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium transition-all ${mode === GameMode.MANUAL ? 'bg-orange-600 text-white shadow-lg' : `${themeClasses.subText} hover:${themeClasses.text} hover:bg-white/10`}`}>
                  <MousePointer2 size={16} /> Manual
                  </button>
              </div>

              <div className="space-y-4">
                  <div className={`${isNight ? 'bg-slate-800/50 border-slate-700' : 'bg-slate-50 border-slate-200'} p-4 rounded-lg border`}>
                      <div className="flex justify-between items-center mb-3">
                          <h3 className={`text-xs font-bold ${themeClasses.subText} uppercase tracking-wider`}>Target Data</h3>
                      </div>
                      <div className="flex gap-2 mb-4">
                          <button onClick={() => setSnapToGrid(!snapToGrid)} className={`flex-1 text-xs flex items-center justify-center gap-1 px-2 py-1.5 rounded border transition-colors ${snapToGrid ? 'bg-indigo-600 border-indigo-500 text-white' : `${isNight ? 'bg-slate-900 border-slate-600' : 'bg-white border-slate-300'} ${themeClasses.subText}`}`}>
                              <Magnet size={12} /> {snapToGrid ? 'Snap ON' : 'Snap OFF'}
                          </button>
                           <button onClick={onToggleCurrentTrajectory} className={`flex-1 text-xs flex items-center justify-center gap-1 px-2 py-1.5 rounded border transition-colors ${showCurrentTrajectory ? 'bg-sky-600 border-sky-500 text-white' : `${isNight ? 'bg-slate-900 border-slate-600' : 'bg-white border-slate-300'} ${themeClasses.subText}`}`}>
                              <Activity size={12} /> {showCurrentTrajectory ? 'Live Path ON' : 'Live Path OFF'}
                          </button>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                          <div>
                          <div className={`${themeClasses.subText} text-xs mb-1`}>Distance</div>
                          <div className={`text-xl font-mono ${themeClasses.text}`}>{dist}</div>
                          </div>
                          <div>
                          <div className={`${themeClasses.subText} text-xs mb-1`}>Height Diff</div>
                          <div className={`text-xl font-mono ${themeClasses.text}`}>{heightDiff}</div>
                          </div>
                      </div>
                  </div>
              </div>

              <div className="space-y-6">
                  <div>
                      <div className="flex justify-between items-end mb-2">
                          <label className={`text-sm font-medium ${isNight ? 'text-sky-200' : 'text-sky-600'}`}>Angle</label>
                          <span className={`text-xl font-bold font-mono ${themeClasses.text}`}>{angle}°</span>
                      </div>
                      <div className="flex items-center gap-2">
                          <button onClick={() => adjustAngle(-1)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}><Minus size={16} /></button>
                          <input type="range" min="0" max="180" step="1" value={angle} onChange={(e) => setAngle(Number(e.target.value))} className={`flex-1 h-2 ${themeClasses.inputBg} rounded-lg appearance-none cursor-pointer accent-sky-500`} />
                          <button onClick={() => adjustAngle(1)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}><Plus size={16} /></button>
                      </div>
                  </div>

                  <div>
                      <div className="flex justify-between items-end mb-2">
                          <label className={`text-sm font-medium ${isNight ? 'text-emerald-200' : 'text-emerald-700'} flex items-center gap-1`}><Wind size={14} /> Wind</label>
                          <span className={`text-xl font-bold font-mono ${themeClasses.text}`}>{wind}</span>
                      </div>
                      <div className="flex items-center gap-2 mb-2">
                          <button onClick={() => adjustWind(-0.5)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}><Minus size={16} /></button>
                          <div className="relative pt-1 flex-1">
                              <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className={`w-full h-2 ${themeClasses.inputBg} rounded-lg appearance-none cursor-pointer accent-emerald-500`} />
                              <div className="absolute top-0 left-1/2 w-0.5 h-4 bg-slate-400 -translate-x-1/2 -translate-y-1"></div>
                          </div>
                          <button onClick={() => adjustWind(0.5)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}><Plus size={16} /></button>
                      </div>
                      <div className={`flex justify-between text-xs ${themeClasses.subText} mt-1`}><span>Against (-150)</span><span>0</span><span>With (+150)</span></div>
                  </div>

                  <div className={`transition-opacity duration-300 ${mode === GameMode.AUTO_AIM ? 'opacity-80 pointer-events-none grayscale' : 'opacity-100'}`}>
                      <div className="flex justify-between items-end mb-2">
                          <label className={`text-sm font-medium ${isNight ? 'text-orange-200' : 'text-orange-600'}`}>Power</label>
                          <span className={`text-xl font-bold font-mono ${themeClasses.text}`}>{power.toFixed(1)}</span>
                      </div>
                      <div className="relative flex items-center gap-2">
                          <button onClick={() => adjustPower(-1)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}><Minus size={16} /></button>
                          <div className="flex-1 relative">
                              <input type="range" min="0" max="100" step="0.1" value={power} onChange={(e) => { setPower(Number(e.target.value)); setMode(GameMode.MANUAL); }} className={`w-full h-2 ${themeClasses.inputBg} rounded-lg appearance-none cursor-pointer accent-orange-500`} />
                              {mode === GameMode.AUTO_AIM && (
                                  <div className="absolute inset-0 z-10 flex items-center justify-center">
                                      <span className={`text-xs ${isNight ? 'bg-slate-800 border-sky-900' : 'bg-white border-sky-200'} text-sky-500 px-2 py-0.5 rounded border shadow-sm`}>Auto-Calculated</span>
                                  </div>
                              )}
                          </div>
                          <button onClick={() => adjustPower(1)} className={`p-2 rounded-md ${themeClasses.btnBg} transition-colors ${themeClasses.text}`}><Plus size={16} /></button>
                      </div>
                  </div>
              </div>

              <div>
                  <div className="flex justify-between items-center mb-3">
                      <h3 className={`text-xs font-bold ${themeClasses.subText} uppercase tracking-wider`}>Memory Bank</h3>
                      <div className="flex gap-2">
                        {selectedIds.length === 2 && (
                             <button 
                                onClick={handleRunAnalysis}
                                className="flex items-center gap-1 text-xs text-amber-900 bg-amber-400 hover:bg-amber-300 px-2 py-1 rounded transition-colors shadow-sm font-bold animate-in zoom-in"
                            >
                                <Calculator size={12} /> Diff
                            </button>
                        )}
                        <button 
                            onClick={handleSave}
                            className={`flex items-center gap-1 text-xs text-white px-2 py-1 rounded transition-colors shadow-sm ${activeTab === 'ALL' ? 'bg-purple-600 hover:bg-purple-500' : 'hover:opacity-90'}`}
                            style={{ backgroundColor: activeTab !== 'ALL' ? activeTab : undefined }}
                        >
                            <Save size={12} /> Save
                        </button>
                      </div>
                  </div>

                  <div className="flex items-center gap-2 mb-3 pb-1 overflow-x-auto no-scrollbar">
                      <button onClick={() => setActiveTab('ALL')} className={`flex-shrink-0 w-6 h-6 rounded-full flex items-center justify-center transition-all border-2 ${activeTab === 'ALL' ? `border-slate-400 ${isNight ? 'bg-slate-700' : 'bg-slate-200'} scale-110` : 'border-transparent hover:bg-slate-100/10'}`}>
                          <Layers size={14} className={isNight ? 'text-slate-300' : 'text-slate-600'} />
                      </button>
                      <div className={`h-4 w-px mx-1 ${isNight ? 'bg-slate-700' : 'bg-slate-300'}`}></div>
                      {TRAJECTORY_COLORS.map(color => {
                          const isActive = activeTab === color;
                          const count = activeColorStats[color]?.count || 0;
                          return (
                              <button key={color} onClick={() => setActiveTab(color)} className={`flex-shrink-0 w-6 h-6 rounded-full transition-all border-2 relative group ${isActive ? 'scale-110 shadow-md' : 'opacity-70 hover:opacity-100 hover:scale-105'}`} style={{ backgroundColor: color, borderColor: isActive ? (isNight ? '#fff' : '#000') : 'transparent' }}>
                                  {count > 0 && !isActive && (<span className="absolute -top-1 -right-1 w-2 h-2 rounded-full bg-white border border-slate-300 shadow-sm" />)}
                              </button>
                          );
                      })}
                  </div>

                  {activeTab !== 'ALL' && activeColorStats[activeTab]?.count > 0 && (
                      <div className={`flex items-center justify-between px-2 py-1.5 mb-2 rounded text-[10px] ${isNight ? 'bg-slate-800' : 'bg-slate-100'} animate-in fade-in slide-in-from-top-1`}>
                          <span className={themeClasses.subText}>Group Actions ({activeColorStats[activeTab].count} items)</span>
                          <button onClick={() => onToggleColorVisibility(activeTab)} className="flex items-center gap-1.5 hover:bg-white/10 px-1.5 py-0.5 rounded transition-colors" style={{ color: activeTab }}>
                              {activeColorStats[activeTab].visibleCount === activeColorStats[activeTab].count ? <><Eye size={12} /> Hide All</> : <><EyeOff size={12} /> Show All</>}
                          </button>
                      </div>
                  )}

                  <div className={`max-h-64 overflow-y-auto space-y-2 pr-1 ${isNight ? 'scrollbar-track-slate-800 scrollbar-thumb-slate-600' : ''}`}>
                      {displayTrajectories.length === 0 ? (
                          <div className={`text-xs ${themeClasses.subText} text-center py-8 flex flex-col items-center gap-2 border-2 border-dashed rounded-lg ${isNight ? 'border-slate-800' : 'border-slate-200'}`}>
                              <div className="p-2 rounded-full bg-slate-500/10">
                                  {activeTab === 'ALL' ? <Layers size={16} /> : <div className="w-4 h-4 rounded-full" style={{ backgroundColor: activeTab }} />}
                              </div>
                              <span className="opacity-70">{activeTab === 'ALL' ? 'No saved trajectories' : 'Empty Group'}</span>
                          </div>
                      ) : (
                          displayTrajectories.map(t => (
                              <div 
                                key={t.id} 
                                onClick={() => onToggleSelection(t.id)}
                                className={`p-2 rounded text-xs flex flex-col gap-2 group border transition-all hover:shadow-sm cursor-pointer relative
                                ${selectedIds.includes(t.id) 
                                    ? (isNight ? 'bg-slate-800 border-sky-500 ring-1 ring-sky-500' : 'bg-white border-sky-500 ring-1 ring-sky-500') 
                                    : (isNight ? 'bg-slate-800 border-slate-700' : 'bg-slate-100 border-slate-200')}
                                `}
                              >
                                  <div className="flex items-center justify-between">
                                      <div className="flex items-center gap-2">
                                          {editingColorId === t.id ? (
                                              <div className={`flex items-center gap-1 p-1 rounded-full ${isNight ? 'bg-slate-700' : 'bg-slate-200'} animate-in slide-in-from-left-2 fade-in duration-200`}>
                                                  {TRAJECTORY_COLORS.map(c => (
                                                      <button key={c} onClick={(e) => { e.stopPropagation(); onUpdateColor(t.id, c); setEditingColorId(null); }} className={`w-3 h-3 rounded-full hover:scale-125 transition-transform border border-transparent hover:border-white/50`} style={{ backgroundColor: c }} />
                                                  ))}
                                              </div>
                                          ) : (
                                              <button onClick={(e) => {e.stopPropagation(); setEditingColorId(t.id)}} className="w-4 h-4 rounded-full hover:scale-110 transition-transform ring-2 ring-transparent hover:ring-offset-1 hover:ring-slate-400 shadow-sm" style={{ backgroundColor: t.color }} />
                                          )}

                                          <div className="flex flex-col gap-0.5">
                                            {/* Show visual indicator for selection order */}
                                            {selectedIds.includes(t.id) && (
                                                <div className="text-[9px] font-bold text-sky-500">
                                                    {selectedIds.indexOf(t.id) === 0 ? "1st Selection" : "2nd Selection"}
                                                </div>
                                            )}
                                            <div className="font-mono text-[10px] font-bold" style={{ color: t.color }}>
                                                P:{t.power.toFixed(1)} A:{t.angle}° W:{t.wind}
                                            </div>
                                            <div className={`${themeClasses.subText} text-[10px]`}>
                                                Target: ({t.target.x.toFixed(1)}, {t.target.y.toFixed(1)})
                                            </div>
                                          </div>
                                      </div>

                                      <div className="flex items-center gap-1">
                                          {selectedIds.includes(t.id) && (
                                              <CheckCircle2 size={14} className="text-sky-500 mr-1 animate-in zoom-in" />
                                          )}
                                          <div className="flex items-center gap-1 opacity-60 group-hover:opacity-100 transition-opacity">
                                            <button onClick={(e) => {e.stopPropagation(); onToggleVisibility(t.id)}} className={`p-1 hover:bg-white/10 rounded ${t.visible ? 'text-sky-400' : 'text-slate-500'}`}>
                                                {t.visible ? <Eye size={14} /> : <EyeOff size={14} />}
                                            </button>
                                            <button onClick={(e) => {e.stopPropagation(); onDeleteTrajectory(t.id)}} className="p-1 hover:bg-white/10 rounded text-red-400 hover:text-red-500">
                                                <Trash2 size={14} />
                                            </button>
                                          </div>
                                      </div>
                                  </div>
                              </div>
                          ))
                      )}
                  </div>
              </div>
          </div>
          <div className={`p-6 border-t ${themeClasses.border}`}>
              {error ? (
              <div className="bg-red-500/10 border border-red-500/30 p-3 rounded text-red-500 text-sm flex items-center gap-2">
                  <span className="font-bold">ERROR:</span> {error}
              </div>
              ) : (
                  <div className="flex items-center justify-between text-sm">
                      <span className={themeClasses.subText}>System Status</span>
                      <span className="text-emerald-500 font-mono flex items-center gap-1.5">
                          <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                          READY
                      </span>
                  </div>
              )}
          </div>
        </div>
      </div>
    </>
  );
};

export default Controls;

import React, { useRef, useMemo, useState, useEffect } from 'react';
import { Point, PHYSICS_CONSTANTS, SavedTrajectory, AnalysisItem } from '../types';
import { Wind, ZoomIn, ZoomOut, X, Calculator, Plus } from 'lucide-react';
import { calculateTrajectory } from '../services/physicsEngine';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  setZoom: (z: number) => void;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
  snapToGrid: boolean;
  savedTrajectories: SavedTrajectory[];
  analysisItems?: AnalysisItem[]; // New prop for separately managed analysis items
  onDeleteAnalysis?: (id: string) => void; // Handler to delete analysis item
  showCurrentTrajectory: boolean;
  // Selection
  selectedIds?: string[];
  onToggleSelection?: (id: string) => void;
  onAnalyze?: (id1: string, id2: string) => void;
}

interface DragState {
    mode: 'IDLE' | 'PAN' | 'TARGET' | 'KNOB' | 'LABEL' | 'AWAIT_PAN_OR_CLICK';
    startScreen: Point;
    startPan: Point; // Physics units
    activeId?: string;
    hasMoved?: boolean;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  setZoom,
  isNight,
  wind,
  setWind,
  snapToGrid,
  savedTrajectories,
  analysisItems = [],
  onDeleteAnalysis,
  showCurrentTrajectory,
  selectedIds = [],
  onToggleSelection,
  onAnalyze
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  // Track container size for responsive aspect ratio
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

  // Widget Hover States
  const [isWindExpanded, setIsWindExpanded] = useState(false);
  const windTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [isZoomExpanded, setIsZoomExpanded] = useState(false);
  const zoomTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // --- Interaction Logic for Wind Widget ---
  const handleWindEnter = () => {
    if (windTimeoutRef.current) clearTimeout(windTimeoutRef.current);
    setIsWindExpanded(true);
  };

  const handleWindLeave = () => {
    windTimeoutRef.current = setTimeout(() => {
        setIsWindExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };

  // --- Interaction Logic for Zoom Widget ---
  const handleZoomEnter = () => {
    if (zoomTimeoutRef.current) clearTimeout(zoomTimeoutRef.current);
    setIsZoomExpanded(true);
  };

  const handleZoomLeave = () => {
    zoomTimeoutRef.current = setTimeout(() => {
        setIsZoomExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };


  useEffect(() => {
    if (!containerRef.current) return;

    const updateSize = () => {
        if (containerRef.current) {
            const { width, height } = containerRef.current.getBoundingClientRect();
            if (width > 0 && height > 0) {
                setContainerSize({ width, height });
            }
        }
    };

    // Initial size
    updateSize();

    const observer = new ResizeObserver(updateSize);
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  // Viewport State: Pan Offset in Physics Units
  const [pan, setPan] = useState({ x: 0, y: 0 }); 

  // Custom offsets for saved labels (SVG px relative to target)
  const [labelOffsets, setLabelOffsets] = useState<Record<string, Point>>({});

  // Interaction State Machine
  const [dragState, setDragState] = useState<DragState>({ 
      mode: 'IDLE', 
      startScreen: { x: 0, y: 0 }, 
      startPan: { x: 0, y: 0 } 
  });

  // --- Pinch Zoom State ---
  const pinchRef = useRef({
      active: false,
      initialDist: 0,
      initialZoom: 1,
      initialPan: { x: 0, y: 0 },
      centerX: 0.5, // normalized 0-1
      centerY: 0.5  // normalized 0-1
  });

  // --- Viewport Calculations ---
  // We anchor the Vertical range and the Left side (Min X) based on constants + zoom.
  // We expand the Right side (Max X) based on the aspect ratio of the container.

  const aspectRatio = containerSize.height > 0 ? containerSize.width / containerSize.height : 1;

  // Base heights from constants
  const baseHeight = PHYSICS_CONSTANTS.MAX_Y - PHYSICS_CONSTANTS.MIN_Y;

  // Calculate visible range in physics units
  const currentHeight = baseHeight * zoom;
  const currentWidth = currentHeight * aspectRatio;

  const currentMinY = (PHYSICS_CONSTANTS.MIN_Y * zoom) + pan.y;
  const currentMaxY = currentMinY + currentHeight;

  // Anchor Left side to MIN_X
  const currentMinX = (PHYSICS_CONSTANTS.MIN_X * zoom) + pan.x;
  const currentMaxX = currentMinX + currentWidth;

  // Fixed SVG Resolution scaling
  const PIXELS_PER_UNIT = 40; 
  const VIEWBOX_WIDTH = currentWidth * PIXELS_PER_UNIT; 
  const VIEWBOX_HEIGHT = currentHeight * PIXELS_PER_UNIT;

  // --- Scale Factor for UI Elements ---
  // Calculates how many SVG units correspond to 1 screen pixel.
  // This allows us to scale text/UI so they look constant size on screen.
  const pixelScale = useMemo(() => {
    if (containerSize.width <= 0) return 1;
    return VIEWBOX_WIDTH / containerSize.width;
  }, [VIEWBOX_WIDTH, containerSize.width]);

  const toSvg = (p: Point) => {
    const percentX = (p.x - currentMinX) / currentWidth;
    const percentY = (p.y - currentMinY) / currentHeight;
    return {
        x: percentX * VIEWBOX_WIDTH,
        y: VIEWBOX_HEIGHT - (percentY * VIEWBOX_HEIGHT)
    };
  };

  const fromSvg = (svgX: number, svgY: number): Point => {
    const percentX = svgX / VIEWBOX_WIDTH;
    const percentY = (VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT; 
    return {
        x: currentMinX + percentX * currentWidth,
        y: currentMinY + percentY * currentHeight
    };
  };

  // Accurate SVG point from screen coordinates
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    let point = new DOMPoint(clientX, clientY);
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, currentMinX, currentMinY, currentWidth, currentHeight]); 

  // --- Saved Data Preparation ---
  // Pre-calculate positions for rendering and hit-testing
  // Refactored to handle dependency chain (Standard Labels -> Analysis Labels)
  const savedData = useMemo(() => {
    // We mix SavedTrajectories and AnalysisItems into a single render list
    // Standard trajectories first, so Analysis can find them
    const sortedByTime = [...savedTrajectories].sort((a, b) => a.timestamp - b.timestamp);

    // Map to store calculated label positions for lookup
    const processedMap = new Map<string, any>();

    sortedByTime.forEach((t) => {
        if (!t.visible) return;

        const d = pointsToPath(calculateTrajectory(tankPos, t.power, t.angle, t.wind));
        const targetSvg = toSvg(t.target);
        const dx = (t.target.x - tankPos.x).toFixed(1);
        const dy = (t.target.y - tankPos.y).toFixed(1);

        // Standard Positioning
        const originalIndex = savedTrajectories.findIndex(st => st.id === t.id);
        const defaultOffsetPx = { x: 0, y: -(40 + (originalIndex % 5) * 45) };
        const defaultOffsetSvg = { 
            x: defaultOffsetPx.x * pixelScale, 
            y: defaultOffsetPx.y * pixelScale 
        };

        const offset = labelOffsets[t.id] || defaultOffsetSvg;
        const usedOffset = offset;
        const labelPos = { x: targetSvg.x + offset.x, y: targetSvg.y + offset.y };

        const data = { 
           id: t.id, 
           d, 
           power: t.power,
           angle: t.angle, 
           wind: t.wind, 
           dx, dy, 
           targetPos: targetSvg,
           labelPos,
           color: t.color,
           isAnalysis: false,
           offset: usedOffset
        };

        processedMap.set(t.id, data);
    });

    // Process Analysis Items
    analysisItems.forEach((item) => {
        if (!item.visible) return;

        let labelPos = { x: 0, y: 0 };
        let connectorStartPoints = undefined; // [ {x,y}, {x,y} ] - Coordinates of parent right edges
        let usedOffset = { x: 0, y: 0 };

        if (item.parentIds && item.parentIds.length === 2) {
             const p1 = processedMap.get(item.parentIds[0]);
             const p2 = processedMap.get(item.parentIds[1]);

             if (p1 && p2) {
                 // Dynamic Positioning: To the right of parents
                 // Standard Label Half-Width = 85 (Total 170)
                 const p1Right = p1.labelPos.x + (85 * pixelScale);
                 const p2Right = p2.labelPos.x + (85 * pixelScale);

                 // Base position is right of the furthest parent + gap
                 // We add a significant gap to allow for the polyline structure
                 // Reduced gap to keep layout tighter as requested
                 const baseX = Math.max(p1Right, p2Right) + (70 * pixelScale); 
                 const baseY = (p1.labelPos.y + p2.labelPos.y) / 2;

                 connectorStartPoints = [
                     { x: p1Right, y: p1.labelPos.y },
                     { x: p2Right, y: p2.labelPos.y }
                 ];

                 const offset = labelOffsets[item.id] || { x: 0, y: 0 };
                 usedOffset = offset;
                 labelPos = { x: baseX + offset.x, y: baseY + offset.y };
             } else {
                 // Fallback if parents missing
                 const targetSvg = toSvg(item.target);
                 const offset = labelOffsets[item.id] || { x: 0, y: -40 * pixelScale };
                 usedOffset = offset;
                 labelPos = { x: targetSvg.x + offset.x, y: targetSvg.y + offset.y };
             }
        }

        const data = {
            id: item.id,
            power: item.powerDiff, // Reuse power field for Diff
            labelPos,
            color: item.color,
            isAnalysis: true,
            connectorStartPoints,
            offset: usedOffset,
            targetPos: toSvg(item.target), // Just for hit testing proximity if needed
        };
         processedMap.set(item.id, data);
    });

    // Return array: Standard Trajectories followed by Analysis Items (so Analysis renders on top)
    const renderList = [
        ...sortedByTime.map(t => processedMap.get(t.id)),
        ...analysisItems.map(a => processedMap.get(a.id))
    ].filter(Boolean);

    return renderList;

  }, [savedTrajectories, analysisItems, tankPos, zoom, currentMinX, currentMinY, currentWidth, currentHeight, labelOffsets, pixelScale]);

  // Calculate mid-point for "Create Diff" button if exactly 2 items selected
  const selectionMidPoint = useMemo(() => {
      if (selectedIds.length !== 2) return null;

      const t1 = savedTrajectories.find(t => t.id === selectedIds[0]);
      const t2 = savedTrajectories.find(t => t.id === selectedIds[1]);

      if (!t1 || !t2) return null;

      // Find SVG positions using savedData logic or recalculate
      // Simple recalculate for robustness
      const t1Svg = toSvg(t1.target);
      const t2Svg = toSvg(t2.target);

      // We place the button between the two targets
      return {
          x: (t1Svg.x + t2Svg.x) / 2,
          y: (t1Svg.y + t2Svg.y) / 2
      };

  }, [selectedIds, savedTrajectories, currentMinX, currentMinY, currentWidth, currentHeight]);


  // --- Interaction Handlers ---

  const handleTouchStart = (e: React.TouchEvent) => {
      if (e.touches.length === 2) {
          e.preventDefault();
          const t1 = e.touches[0];
          const t2 = e.touches[1];

          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          // Calculate centroid relative to container
          const rect = containerRef.current?.getBoundingClientRect();
          if (!rect) return;

          const cx = ((t1.clientX + t2.clientX) / 2) - rect.left;
          const cy = ((t1.clientY + t2.clientY) / 2) - rect.top;

          pinchRef.current = {
              active: true,
              initialDist: dist,
              initialZoom: zoom,
              initialPan: { ...pan },
              centerX: cx / rect.width,
              centerY: cy / rect.height
          };

          // Cancel any active drag/pan
          setDragState(prev => ({ ...prev, mode: 'IDLE' }));
      }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      if (e.touches.length === 2 && pinchRef.current.active) {
          e.preventDefault();
          e.stopPropagation();

          const t1 = e.touches[0];
          const t2 = e.touches[1];
          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          if (pinchRef.current.initialDist > 10 && dist > 10) {
              const ratio = dist / pinchRef.current.initialDist;
              // Larger distance (spread) -> Smaller zoom value (Zoom In/Close up)
              let newZoom = pinchRef.current.initialZoom / ratio;
              newZoom = Math.max(0.25, Math.min(2.5, newZoom));

              // Calculate Pan compensation to zoom towards center
              // Formula: pan_new = pan_old + M * (z_old - z_new)
              const deltaZ = pinchRef.current.initialZoom - newZoom;

              // M_x = MIN_X + CenterX * Height * AR
              const Mx = PHYSICS_CONSTANTS.MIN_X + (pinchRef.current.centerX * baseHeight * aspectRatio);

              // M_y = MIN_Y + (1 - CenterY) * Height
              // Note: CenterY is 0 at top, 1 at bottom. Physics Y is 0 at bottom (relative to MIN_Y).
              const My = PHYSICS_CONSTANTS.MIN_Y + ((1 - pinchRef.current.centerY) * baseHeight);

              const newPanX = pinchRef.current.initialPan.x + (Mx * deltaZ);
              const newPanY = pinchRef.current.initialPan.y + (My * deltaZ);

              setZoom(newZoom);
              setPan({ x: newPanX, y: newPanY });
          }
      }
  };

  const handleTouchEnd = () => {
      pinchRef.current.active = false;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    // If pinch is active, ignore single pointer events
    if (pinchRef.current.active) return;

    if (!svgRef.current) return;
    (e.target as Element).setPointerCapture(e.pointerId);

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);
    const screenPt = { x: e.clientX, y: e.clientY };

    // 1. Check Angle Knob / Area (Only if active)
    const tankSvg = toSvg(tankPos);

    // Visual radius of the knob control (roughly 80px on screen)
    const knobRadius = 80 * pixelScale;
    const distToTank = Math.hypot(clickX - tankSvg.x, clickY - tankSvg.y);

    if (showCurrentTrajectory && distToTank < knobRadius + (10 * pixelScale)) {
        setDragState({ mode: 'KNOB', startScreen: screenPt, startPan: pan });
        return;
    }

    // 2. Check Saved Labels (Top-most first for hitting, so iterate reverse of render order?)
    // savedData is Old -> New (Render Order). 
    // Hit test should be New -> Old (Top -> Bottom).
    for (let i = savedData.length - 1; i >= 0; i--) {
        const item = savedData[i];

        // Define Hitbox size based on type
        // Analysis: 90x24 (Half 45x12)
        // Standard: 170x34 (Half 85x17)
        // Analysis now matches standard roughly in hitbox to handle drag easily
        const halfW = item.isAnalysis ? 45 * pixelScale : 85 * pixelScale;
        const halfH = item.isAnalysis ? 17 * pixelScale : 17 * pixelScale;

        if (
            clickX >= item.labelPos.x - halfW && clickX <= item.labelPos.x + halfW &&
            clickY >= item.labelPos.y - halfH && clickY <= item.labelPos.y + halfH
        ) {
            setDragState({ 
                mode: 'LABEL', 
                startScreen: screenPt, 
                startPan: pan, 
                activeId: item.id,
                hasMoved: false
            });
            return;
        }
    }

    // 3. Check Active Target (Only if active)
    const targetSvg = toSvg(target);
    const targetHitRadius = 30 * pixelScale;
    if (showCurrentTrajectory && Math.hypot(clickX - targetSvg.x, clickY - targetSvg.y) < targetHitRadius) {
        setDragState({ mode: 'TARGET', startScreen: screenPt, startPan: pan });
        return;
    }

    // 4. Background -> Pan or Click
    setDragState({ 
        mode: 'AWAIT_PAN_OR_CLICK', 
        startScreen: screenPt, 
        startPan: pan, 
        hasMoved: false
    });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // If pinch active, ignore
    if (pinchRef.current.active) return;

    if (!svgRef.current) return;
    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    // Calculate screen deltas
    const dxScreen = e.clientX - dragState.startScreen.x;
    const dyScreen = e.clientY - dragState.startScreen.y;

    if (dragState.mode === 'KNOB') {
        const tankSvg = toSvg(tankPos);
        // Angle calc
        let newAngle = Math.atan2(-(pointerY - tankSvg.y), (pointerX - tankSvg.x)) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;
        if (newAngle > 180) newAngle = 180; 

        // Snap to integer angle for cleaner UI
        setAngle(Math.round(newAngle));

    } else if (dragState.mode === 'LABEL' && dragState.activeId) {
        // Track movement to distinguish click from drag
        if (Math.hypot(dxScreen, dyScreen) > 5) {
             setDragState(prev => ({ ...prev, hasMoved: true }));

             const currentItem = savedData.find(sd => sd.id === dragState.activeId);
             if (currentItem && currentItem.offset) {
                  const basePosX = currentItem.labelPos.x - currentItem.offset.x;
                  const basePosY = currentItem.labelPos.y - currentItem.offset.y;

                  let destX = pointerX;
                  let destY = pointerY;

                  // Snap logic
                  if (snapToGrid) {
                      const physPoint = fromSvg(destX, destY);
                      const snappedPhysX = Math.round(physPoint.x);
                      const snappedPhysY = Math.round(physPoint.y);
                      const snappedSvg = toSvg({ x: snappedPhysX, y: snappedPhysY });
                      destX = snappedSvg.x;
                      destY = snappedSvg.y;
                  }

                  setLabelOffsets(prev => ({
                     ...prev,
                     [dragState.activeId!]: {
                         x: destX - basePosX,
                         y: destY - basePosY
                     }
                  }));
             }
        }

    } else if (dragState.mode === 'TARGET') {
        const physicsPoint = fromSvg(pointerX, pointerY);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });

    } else if (dragState.mode === 'PAN' || (dragState.mode === 'AWAIT_PAN_OR_CLICK' && Math.hypot(dxScreen, dyScreen) > 5)) {
        if (dragState.mode === 'AWAIT_PAN_OR_CLICK') {
            setDragState(prev => ({ ...prev, mode: 'PAN', hasMoved: true }));
        }

        const ctm = svgRef.current?.getScreenCTM();
        const scaleX = ctm ? ctm.a : 1; 

        const dxPhys = -dxScreen / (PIXELS_PER_UNIT * scaleX);
        const dyPhys = dyScreen / (PIXELS_PER_UNIT * scaleX);

        setPan({
            x: dragState.startPan.x + dxPhys,
            y: dragState.startPan.y + dyPhys
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    (e.target as Element).releasePointerCapture(e.pointerId);

    // Click Detection for Selection (If LABEL clicked but not moved)
    if (dragState.mode === 'LABEL' && !dragState.hasMoved && dragState.activeId) {
        if (onToggleSelection) {
             const item = savedData.find(sd => sd.id === dragState.activeId);
             // Only select SavedTrajectories (not Analysis items) for now, 
             // although logic permits analysis selection, we only need it for Diff generation
             if (item && !item.isAnalysis) {
                onToggleSelection(dragState.activeId);
             }
        }
    }

    if (showCurrentTrajectory && dragState.mode === 'AWAIT_PAN_OR_CLICK' && !dragState.hasMoved) {
        const { x, y } = getSvgPoint(e.clientX, e.clientY);
        const physicsPoint = fromSvg(x, y);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });
    }

    setDragState({ mode: 'IDLE', startScreen: {x:0, y:0}, startPan: {x:0, y:0} });
  };

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = (target.y - tankPos.y).toFixed(2); 

  // Generate Grid Lines
  const gridLines = useMemo(() => {
    const lines = [];
    const startX = Math.floor(currentMinX);
    const endX = Math.ceil(currentMaxX);
    const startY = Math.floor(currentMinY);
    const endY = Math.ceil(currentMaxY);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const axisColor = isNight ? "#94a3b8" : "#475569"; 
    const minorColor = isNight ? "rgba(51, 65, 85, 0.4)" : "rgba(203, 213, 225, 0.6)";
    const textColor = isNight ? "#64748b" : "#94a3b8";

    const strokeW = Math.max(1 * pixelScale, 1); 
    const fontSz = 12 * pixelScale; 

    const useSparseGrid = zoom > 1.5;

    for (let i = startX; i <= endX; i++) {
        const p = toSvg({ x: i, y: 0 }); 
        const x = p.x;
        if (x < -50 * pixelScale || x > VIEWBOX_WIDTH + 50 * pixelScale) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 12 === 0; 

        if (useSparseGrid && !isAxis && !isMajor) continue;

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? strokeW * 2 : strokeW} 
                strokeDasharray={isAxis || isMajor ? "" : `${4 * pixelScale},${2 * pixelScale}`}
            />
        );

        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + (4 * pixelScale)} 
                y={VIEWBOX_HEIGHT - (10 * pixelScale)} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={fontSz}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
                style={{ userSelect: 'none' }}
            >
                {i}
            </text>
        );
    }

    for (let i = startY; i <= endY; i++) {
        const p = toSvg({ x: 0, y: i }); 
        const y = p.y;
        if (y < -50 * pixelScale || y > VIEWBOX_HEIGHT + 50 * pixelScale) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 6 === 0;

        if (useSparseGrid && !isAxis && !isMajor) continue;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? strokeW * 2 : strokeW} 
                strokeDasharray={isAxis || isMajor ? "" : `${4 * pixelScale},${2 * pixelScale}`}
            />
        );

        lines.push(
            <text 
                key={`th-${i}`} 
                x={10 * pixelScale} 
                y={y - (4 * pixelScale)} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={fontSz}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
                style={{ userSelect: 'none' }}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [currentMinX, currentMaxX, currentMinY, currentMaxY, VIEWBOX_WIDTH, VIEWBOX_HEIGHT, isNight, toSvg, pixelScale, zoom]);

  const knobRadius = 80 * pixelScale; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // Dynamic Styles for Wind Widget
  const windWidgetClasses = isNight 
    ? 'bg-slate-800/95 border-slate-600'
    : 'bg-white/95 border-slate-200';

  const windTextClasses = isNight ? 'text-slate-300' : 'text-slate-700';
  const windLabelClasses = isNight ? 'text-slate-500' : 'text-slate-500';
  const windBtnClasses = isNight 
    ? 'bg-slate-700 hover:bg-slate-600 text-white' 
    : 'bg-slate-200 hover:bg-slate-300 text-slate-800';

  const mainColor = isNight ? "#38bdf8" : "#0284c7";

  if (containerSize.width === 0) return <div ref={containerRef} className="w-full h-full" />;

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none`}
    >
      {/* Floating Create Diff Button */}
      {selectionMidPoint && onAnalyze && selectedIds.length === 2 && (
          <div 
             className="absolute z-30 transform -translate-x-1/2 -translate-y-1/2 animate-in zoom-in slide-in-from-bottom-2 fade-in"
             style={{ left: selectionMidPoint.x, top: selectionMidPoint.y }}
          >
              <button 
                onClick={(e) => {
                    e.stopPropagation();
                    onAnalyze(selectedIds[0], selectedIds[1]);
                }}
                className="flex items-center gap-2 px-3 py-1.5 bg-amber-400 text-amber-950 rounded-full shadow-lg font-bold text-xs hover:bg-amber-300 hover:scale-105 transition-all"
              >
                  <Calculator size={14} /> Link / Diff
              </button>
          </div>
      )}

      {/* Wind Control Widget */}
      <div 
        onMouseEnter={handleWindEnter}
        onMouseLeave={handleWindLeave}
        className={`absolute top-4 left-1/2 -translate-x-1/2 backdrop-blur rounded-xl border shadow-xl flex flex-col items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isWindExpanded ? 'w-60 p-2' : 'w-auto px-4 py-2 hover:w-60 hover:p-2 cursor-pointer'}`}
      >
        {isWindExpanded ? (
            <>
                <div className={`text-[10px] font-bold ${windTextClasses} mb-1 w-full flex justify-between items-center`}>
                    <span className={`text-[9px] ${windLabelClasses}`}>WEST</span>
                    <span className={`flex items-center gap-1 ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-400') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                        <Wind size={10} />
                        WIND: {Math.abs(wind).toFixed(1)}
                    </span>
                    <span className={`text-[9px] ${windLabelClasses}`}>EAST</span>
                </div>
                <div className="flex items-center w-full gap-2 opacity-100 transition-opacity duration-300 delay-100">
                    <button onClick={() => setWind(Number((wind - 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>-</button>
                    <div className="relative flex-1 h-5 flex items-center mx-1">
                        <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                        <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-sky-500 z-10 relative ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}/>
                    </div>
                    <button onClick={() => setWind(Number((wind + 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>+</button>
                </div>
            </>
        ) : (
             <div className="flex items-center gap-2">
                <Wind size={14} className={wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-500' : 'text-rose-500'} />
                <span className={`text-xs font-bold font-mono ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-500') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {wind.toFixed(1)}
                </span>
            </div>
        )}
      </div>

      {/* Zoom Control Widget */}
      <div 
        onMouseEnter={handleZoomEnter}
        onMouseLeave={handleZoomLeave}
        className={`absolute bottom-4 right-4 backdrop-blur rounded-xl border shadow-xl flex items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isZoomExpanded ? 'w-64 p-3 gap-3' : 'w-24 p-2 gap-2 cursor-pointer hover:w-64 hover:p-3 hover:gap-3'}`}
      >
        {isZoomExpanded ? (
            <>
                <button onClick={() => setZoom(Math.max(0.25, zoom - 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomOut size={12} />
                </button>
                <div className="flex-1 flex flex-col items-center">
                    <div className="flex justify-between w-full text-[10px] font-bold mb-1 opacity-80">
                         <span className={windLabelClasses}>VIEW RANGE</span>
                         <span className={isNight ? 'text-indigo-300' : 'text-indigo-600'}>{(zoom * 100).toFixed(0)}%</span>
                    </div>
                    <input
                        type="range"
                        min="0.25"
                        max="2.5"
                        step="0.1"
                        value={zoom}
                        onChange={(e) => setZoom(Number(e.target.value))}
                        className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                    />
                </div>
                <button onClick={() => setZoom(Math.min(2.5, zoom + 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomIn size={12} />
                </button>
            </>
        ) : (
            <>
                <input
                    type="range"
                    min="0.25"
                    max="2.5"
                    step="0.1"
                    value={zoom}
                    readOnly
                    className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                />
            </>
        )}
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Curve Analysis View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            X: {currentMinX.toFixed(0)} to {currentMaxX.toFixed(0)} | Y: {currentMinY.toFixed(0)} to {currentMaxY.toFixed(0)}
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className={`w-full h-full block touch-none ${
            dragState.mode === 'PAN' ? 'cursor-grabbing' : 
            dragState.mode === 'LABEL' ? 'cursor-move' : 
            dragState.mode === 'TARGET' ? 'cursor-crosshair' : 
            dragState.mode === 'KNOB' ? 'cursor-grab' : 'cursor-grab'
        }`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}

        // Touch Events for Pinch Zoom
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onTouchCancel={handleTouchEnd}

        preserveAspectRatio="none"
      >
        <defs>
            <marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
                <path d="M0,0 L0,6 L9,3 z" fill="#a855f7" />
            </marker>
            <radialGradient id="angleGradient" cx="0.5" cy="0.5" r="0.5">
                <stop offset="0%" stopColor={mainColor} stopOpacity="0.25" />
                <stop offset="100%" stopColor={mainColor} stopOpacity="0" />
            </radialGradient>
            <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
              <feDropShadow dx="0" dy={2 * pixelScale} stdDeviation={2 * pixelScale} floodColor="#000000" floodOpacity="0.3" />
            </filter>
            <filter id="simpleBlur" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation={2 * pixelScale} />
            </filter>
        </defs>

        {/* Grid Lines */}
        {gridLines}

        {/* Saved Trajectories and Labels */}
        {savedData.map((sd) => (
            <g key={sd.id}>
                {/* Only draw path if it's NOT an analysis item */}
                {!sd.isAnalysis && (
                    <path d={sd.d} fill="none" stroke={sd.color} strokeWidth={2 * pixelScale} strokeDasharray={`${5*pixelScale},${5*pixelScale}`} className="opacity-60" />
                )}

                {/* Selection Ring (Visual Highlight) */}
                {selectedIds.includes(sd.id) && (
                    <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                        <circle r={14 * pixelScale} fill="none" stroke="#38bdf8" strokeWidth={2 * pixelScale} className="animate-pulse" />
                        <circle r={18 * pixelScale} fill="none" stroke="#38bdf8" strokeWidth={1 * pixelScale} strokeDasharray={`${2*pixelScale},${2*pixelScale}`} opacity="0.5" />
                    </g>
                )}

                {/* Draw Analysis Connector Lines (Polylines/Manhattan) */}
                {sd.isAnalysis && sd.connectorStartPoints && (
                    <>
                        {sd.connectorStartPoints.map((pt: Point, idx: number) => {
                             // Analysis Label Left Edge is at labelPos.x - 45*scale
                             const endX = sd.labelPos.x - (45 * pixelScale); // Compact width 90 (half 45)
                             const endY = sd.labelPos.y;

                             // Start Point (Parent Right Edge)
                             const startX = pt.x;
                             const startY = pt.y;

                             // Fixed Length Tail Calculation
                             const fixedTail = 20 * pixelScale; 
                             const minLead = 10 * pixelScale;

                             const elbowX = Math.max(startX + minLead, endX - fixedTail);

                             return (
                                 <polyline 
                                    key={idx}
                                    points={`${startX},${startY} ${elbowX},${startY} ${elbowX},${endY} ${endX},${endY}`}
                                    fill="none"
                                    stroke={sd.color}
                                    strokeWidth={1.5 * pixelScale}
                                    strokeDasharray={`${3*pixelScale},${3*pixelScale}`}
                                    strokeLinejoin="round"
                                    opacity="0.6"
                                 />
                             );
                        })}
                    </>
                )}

                <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                     <circle r={sd.isAnalysis ? 3 * pixelScale : 6 * pixelScale} fill="none" stroke={sd.color} strokeWidth={sd.isAnalysis ? 1 * pixelScale : 3 * pixelScale} />
                     <circle r={2 * pixelScale} fill={sd.color} />
                </g>

                {!sd.isAnalysis && (
                    <line 
                        x1={sd.labelPos.x} y1={sd.labelPos.y} 
                        x2={sd.targetPos.x} y2={sd.targetPos.y} 
                        stroke={sd.color} strokeWidth={1.5 * pixelScale} 
                        strokeDasharray={`${4*pixelScale},${2*pixelScale}`}
                        opacity="0.8"
                    />
                )}

                {/* Draggable Label */}
                <g 
                    transform={`translate(${sd.labelPos.x}, ${sd.labelPos.y}) scale(${pixelScale})`} 
                    className="cursor-move group"
                > 

                    {sd.isAnalysis ? (
                        <>
                             {/* Simplified Analysis Label Background - Compact Size */}
                             <rect 
                                x="-45" y="-12" width="90" height="24" rx="4" 
                                fill={isNight ? "#1e293b" : "#ffffff"} 
                                stroke={sd.color} strokeWidth="2" 
                                filter="url(#shadow)"
                            />
                            {/* Decorative Left Edge */}
                            <path 
                                d="M -25 -12 L -41 -12 Q -45 -12 -45 -8 L -45 8 Q -45 12 -41 12 L -25 12 Z" 
                                fill={sd.color} 
                            />

                            {/* Analysis Label Layout - "DIFF" Badge */}
                            <text x="-35" y="4" textAnchor="middle" fill="rgba(255,255,255,0.9)" fontSize="10" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                DIFF
                            </text>

                            {/* Main Value - Delta Power Only */}
                            <text x="10" y="5" textAnchor="middle" fill={isNight ? "#ffffff" : "#334155"} fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                {sd.power > 0 ? '+' : ''}{sd.power.toFixed(1)}
                            </text>

                            {/* No Right Side Stats */}

                            {/* Close Button (Shows on Hover or Touch) */}
                            {onDeleteAnalysis && (
                                <g 
                                    transform="translate(45, -12)" 
                                    className="cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity"
                                    onClick={(e) => {
                                        e.stopPropagation(); // Prevent drag start
                                        onDeleteAnalysis(sd.id);
                                    }}
                                    onPointerDown={(e) => e.stopPropagation()} // Prevent drag start on touch
                                >
                                    <circle cx="0" cy="0" r="8" fill="#ef4444" stroke="white" strokeWidth="1" />
                                    <line x1="-3" y1="-3" x2="3" y2="3" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
                                    <line x1="3" y1="-3" x2="-3" y2="3" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
                                </g>
                            )}
                        </>
                    ) : (
                        <>
                            {/* Standard Label Background - Height 34 */}
                            <rect 
                                x="-85" y="-17" width="170" height="34" rx="6" 
                                fill={isNight ? "#1e293b" : "#ffffff"} 
                                stroke={sd.color} strokeWidth="2" 
                                filter="url(#shadow)"
                            />
                            {/* Custom Left Decorative Shape */}
                            <path 
                                d="M -35 -17 L -79 -17 Q -85 -17 -85 -11 L -85 11 Q -85 17 -79 17 L -35 17 Z" 
                                fill={sd.color} 
                            />
                            {/* Standard Label Layout */}
                            <text x="-60" y="-4" textAnchor="middle" fill="rgba(255,255,255,0.7)" fontSize="8" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                POWER
                            </text>
                            <text x="-60" y="10" textAnchor="middle" fill="white" fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                {sd.power.toFixed(1)}
                            </text>

                            {/* Right Side: Data - Row 1: Angle & Wind */}
                            <text x="-25" y="-3" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>A:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.angle}°</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>W:</tspan> <tspan fontWeight="bold" fill={sd.wind === 0 ? (isNight ? "#94a3b8" : "#64748b") : (sd.wind > 0 ? "#10b981" : "#f43f5e")}>{sd.wind}</tspan>
                            </text>

                            {/* Right Side: Data - Row 2: Coordinates */}
                            <text x="-25" y="9" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>X:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.dx}</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>Y:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.dy}</tspan>
                            </text>
                        </>
                    )}
                </g>
            </g>
        ))}

        {/* Active Elements */}
        {showCurrentTrajectory && (
            <>
                <circle 
                    cx={tankSvg.x} 
                    cy={tankSvg.y} 
                    r={knobRadius} 
                    fill="url(#angleGradient)" 
                    className="cursor-pointer hover:opacity-100 transition-opacity"
                    style={{ opacity: 0.8 }}
                />

                <path d={trajectoryPath} fill="none" stroke={mainColor} strokeWidth={4 * pixelScale} strokeDasharray={`${10*pixelScale},${10*pixelScale}`} className="opacity-80" />

                <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
                    <path d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`} fill="none" stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"} strokeWidth={2 * pixelScale} strokeDasharray={`${4*pixelScale},${4*pixelScale}`}/>

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                        stroke="#dc2626" strokeWidth={8 * pixelScale} strokeLinecap="round" opacity="0.3" filter="url(#simpleBlur)" />

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                        stroke="#dc2626" strokeWidth={3 * pixelScale} strokeLinecap="round" />

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                         stroke="transparent" strokeWidth={20 * pixelScale} strokeLinecap="round" style={{ pointerEvents: 'auto' }} />
                </g>

                <g>
                    <circle 
                        cx={tankSvg.x} 
                        cy={tankSvg.y} 
                        r={18 * pixelScale} 
                        fill={isNight ? "#0f172a" : "#ffffff"} 
                        stroke={mainColor} 
                        strokeWidth={3 * pixelScale} 
                    />
                    <text 
                        x={tankSvg.x} 
                        y={tankSvg.y} 
                        dy={4 * pixelScale} 
                        textAnchor="middle" 
                        fill={mainColor} 
                        fontSize={11 * pixelScale} 
                        fontWeight="bold" 
                        fontFamily="'Varela Round', sans-serif"
                        className="pointer-events-none select-none"
                    >
                        {angle}°
                    </text>
                </g>

                <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
                    <circle r={5 * pixelScale} fill={mainColor} />
                    <circle r={12 * pixelScale} fill="none" stroke={mainColor} strokeWidth={1.5 * pixelScale} opacity="0.6" className="animate-pulse" />

                    {/* Tooltip scaled by pixelScale */}
                    <g transform={`translate(0, -${65 * pixelScale}) scale(${pixelScale})`}>
                        <rect x="-70" y="0" width="140" height="50" rx="6" fill={isNight ? "rgba(15, 23, 42, 0.9)" : "rgba(255, 255, 255, 0.9)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
                        <text x="0" y="20" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="16" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            ({dx}, {dy})
                        </text>
                        <text x="0" y="38" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            Wind: {wind}
                        </text>
                    </g>
                </g>

                {impactSvg && (
                    <circle cx={impactSvg.x} cy={impactSvg.y} r={8 * pixelScale} fill="#fbbf24" stroke="white" strokeWidth={1 * pixelScale} />
                )}
            </>
        )}
      </svg>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useMemo, useState, useEffect } from 'react';
import { Point, PHYSICS_CONSTANTS, SavedTrajectory, AnalysisItem } from '../types';
import { Wind, ZoomIn, ZoomOut, X, Calculator, Plus } from 'lucide-react';
import { calculateTrajectory } from '../services/physicsEngine';

interface GameCanvasProps {
  trajectory: Point[];
  target: Point;
  tankPos: Point;
  onSetTarget: (p: Point) => void;
  impactPoint: Point | null;
  angle: number;
  setAngle: (a: number) => void;
  zoom: number;
  setZoom: (z: number) => void;
  isNight: boolean;
  wind: number;
  setWind: (w: number) => void;
  snapToGrid: boolean;
  savedTrajectories: SavedTrajectory[];
  analysisItems?: AnalysisItem[]; // New prop for separately managed analysis items
  onDeleteAnalysis?: (id: string) => void; // Handler to delete analysis item
  showCurrentTrajectory: boolean;
  // Selection
  selectedIds?: string[];
  onToggleSelection?: (id: string) => void;
  onAnalyze?: (id1: string, id2: string) => void;
}

interface DragState {
    mode: 'IDLE' | 'PAN' | 'TARGET' | 'KNOB' | 'LABEL' | 'AWAIT_PAN_OR_CLICK';
    startScreen: Point;
    startPan: Point; // Physics units
    activeId?: string;
    hasMoved?: boolean;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  trajectory, 
  target, 
  tankPos, 
  onSetTarget, 
  impactPoint,
  angle,
  setAngle,
  zoom,
  setZoom,
  isNight,
  wind,
  setWind,
  snapToGrid,
  savedTrajectories,
  analysisItems = [],
  onDeleteAnalysis,
  showCurrentTrajectory,
  selectedIds = [],
  onToggleSelection,
  onAnalyze
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  // Track container size for responsive aspect ratio
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

  // Widget Hover States
  const [isWindExpanded, setIsWindExpanded] = useState(false);
  const windTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [isZoomExpanded, setIsZoomExpanded] = useState(false);
  const zoomTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // --- Interaction Logic for Wind Widget ---
  const handleWindEnter = () => {
    if (windTimeoutRef.current) clearTimeout(windTimeoutRef.current);
    setIsWindExpanded(true);
  };

  const handleWindLeave = () => {
    windTimeoutRef.current = setTimeout(() => {
        setIsWindExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };

  // --- Interaction Logic for Zoom Widget ---
  const handleZoomEnter = () => {
    if (zoomTimeoutRef.current) clearTimeout(zoomTimeoutRef.current);
    setIsZoomExpanded(true);
  };

  const handleZoomLeave = () => {
    zoomTimeoutRef.current = setTimeout(() => {
        setIsZoomExpanded(false);
    }, 1500); // 1.5s delay before collapsing
  };


  useEffect(() => {
    if (!containerRef.current) return;

    const updateSize = () => {
        if (containerRef.current) {
            const { width, height } = containerRef.current.getBoundingClientRect();
            if (width > 0 && height > 0) {
                setContainerSize({ width, height });
            }
        }
    };

    // Initial size
    updateSize();

    const observer = new ResizeObserver(updateSize);
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  // Viewport State: Pan Offset in Physics Units
  const [pan, setPan] = useState({ x: 0, y: 0 }); 

  // Custom offsets for saved labels (SVG px relative to target)
  const [labelOffsets, setLabelOffsets] = useState<Record<string, Point>>({});

  // Interaction State Machine
  const [dragState, setDragState] = useState<DragState>({ 
      mode: 'IDLE', 
      startScreen: { x: 0, y: 0 }, 
      startPan: { x: 0, y: 0 } 
  });

  // --- Pinch Zoom State ---
  const pinchRef = useRef({
      active: false,
      initialDist: 0,
      initialZoom: 1,
      initialPan: { x: 0, y: 0 },
      centerX: 0.5, // normalized 0-1
      centerY: 0.5  // normalized 0-1
  });

  // --- Viewport Calculations ---
  // We anchor the Vertical range and the Left side (Min X) based on constants + zoom.
  // We expand the Right side (Max X) based on the aspect ratio of the container.

  const aspectRatio = containerSize.height > 0 ? containerSize.width / containerSize.height : 1;

  // Base heights from constants
  const baseHeight = PHYSICS_CONSTANTS.MAX_Y - PHYSICS_CONSTANTS.MIN_Y;

  // Calculate visible range in physics units
  const currentHeight = baseHeight * zoom;
  const currentWidth = currentHeight * aspectRatio;

  const currentMinY = (PHYSICS_CONSTANTS.MIN_Y * zoom) + pan.y;
  const currentMaxY = currentMinY + currentHeight;

  // Anchor Left side to MIN_X
  const currentMinX = (PHYSICS_CONSTANTS.MIN_X * zoom) + pan.x;
  const currentMaxX = currentMinX + currentWidth;

  // Fixed SVG Resolution scaling
  const PIXELS_PER_UNIT = 40; 
  const VIEWBOX_WIDTH = currentWidth * PIXELS_PER_UNIT; 
  const VIEWBOX_HEIGHT = currentHeight * PIXELS_PER_UNIT;

  // --- Scale Factor for UI Elements ---
  // Calculates how many SVG units correspond to 1 screen pixel.
  // This allows us to scale text/UI so they look constant size on screen.
  const pixelScale = useMemo(() => {
    if (containerSize.width <= 0) return 1;
    return VIEWBOX_WIDTH / containerSize.width;
  }, [VIEWBOX_WIDTH, containerSize.width]);

  const toSvg = (p: Point) => {
    const percentX = (p.x - currentMinX) / currentWidth;
    const percentY = (p.y - currentMinY) / currentHeight;
    return {
        x: percentX * VIEWBOX_WIDTH,
        y: VIEWBOX_HEIGHT - (percentY * VIEWBOX_HEIGHT)
    };
  };

  const fromSvg = (svgX: number, svgY: number): Point => {
    const percentX = svgX / VIEWBOX_WIDTH;
    const percentY = (VIEWBOX_HEIGHT - svgY) / VIEWBOX_HEIGHT; 
    return {
        x: currentMinX + percentX * currentWidth,
        y: currentMinY + percentY * currentHeight
    };
  };

  // Accurate SVG point from screen coordinates
  const getSvgPoint = (clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    let point = new DOMPoint(clientX, clientY);
    const matrix = svgRef.current.getScreenCTM();
    if (matrix) {
        point = point.matrixTransform(matrix.inverse());
    }
    return { x: point.x, y: point.y };
  };

  const pointsToPath = (pts: Point[]) => {
      if (pts.length === 0) return '';
      const start = toSvg(pts[0]);
      let path = `M ${start.x.toFixed(1)} ${start.y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const p = toSvg(pts[i]);
        path += ` L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
      }
      return path;
  };

  const trajectoryPath = useMemo(() => pointsToPath(trajectory), [trajectory, currentMinX, currentMinY, currentWidth, currentHeight]); 

  // --- Saved Data Preparation ---
  // Pre-calculate positions for rendering and hit-testing
  // Refactored to handle dependency chain (Standard Labels -> Analysis Labels)
  const savedData = useMemo(() => {
    // We mix SavedTrajectories and AnalysisItems into a single render list
    // Standard trajectories first, so Analysis can find them
    const sortedByTime = [...savedTrajectories].sort((a, b) => a.timestamp - b.timestamp);

    // Map to store calculated label positions for lookup
    const processedMap = new Map<string, any>();

    sortedByTime.forEach((t) => {
        if (!t.visible) return;

        const d = pointsToPath(calculateTrajectory(tankPos, t.power, t.angle, t.wind));
        const targetSvg = toSvg(t.target);
        const dx = (t.target.x - tankPos.x).toFixed(1);
        const dy = (t.target.y - tankPos.y).toFixed(1);

        // Standard Positioning
        const originalIndex = savedTrajectories.findIndex(st => st.id === t.id);
        const defaultOffsetPx = { x: 0, y: -(40 + (originalIndex % 5) * 45) };
        const defaultOffsetSvg = { 
            x: defaultOffsetPx.x * pixelScale, 
            y: defaultOffsetPx.y * pixelScale 
        };

        const offset = labelOffsets[t.id] || defaultOffsetSvg;
        const usedOffset = offset;
        const labelPos = { x: targetSvg.x + offset.x, y: targetSvg.y + offset.y };

        const data = { 
           id: t.id, 
           d, 
           power: t.power,
           angle: t.angle, 
           wind: t.wind, 
           dx, dy, 
           targetPos: targetSvg,
           labelPos,
           color: t.color,
           isAnalysis: false,
           offset: usedOffset
        };

        processedMap.set(t.id, data);
    });

    // Process Analysis Items
    analysisItems.forEach((item) => {
        if (!item.visible) return;

        let labelPos = { x: 0, y: 0 };
        let connectorStartPoints = undefined; // [ {x,y}, {x,y} ] - Coordinates of parent right edges
        let usedOffset = { x: 0, y: 0 };

        if (item.parentIds && item.parentIds.length === 2) {
             const p1 = processedMap.get(item.parentIds[0]);
             const p2 = processedMap.get(item.parentIds[1]);

             if (p1 && p2) {
                 // Dynamic Positioning: To the right of parents
                 // Standard Label Half-Width = 85 (Total 170)
                 const p1Right = p1.labelPos.x + (85 * pixelScale);
                 const p2Right = p2.labelPos.x + (85 * pixelScale);

                 // Base position is right of the furthest parent + gap
                 // We add a significant gap to allow for the polyline structure
                 // Reduced gap to keep layout tighter as requested
                 const baseX = Math.max(p1Right, p2Right) + (70 * pixelScale); 
                 const baseY = (p1.labelPos.y + p2.labelPos.y) / 2;

                 connectorStartPoints = [
                     { x: p1Right, y: p1.labelPos.y },
                     { x: p2Right, y: p2.labelPos.y }
                 ];

                 const offset = labelOffsets[item.id] || { x: 0, y: 0 };
                 usedOffset = offset;
                 labelPos = { x: baseX + offset.x, y: baseY + offset.y };
             } else {
                 // Fallback if parents missing
                 const targetSvg = toSvg(item.target);
                 const offset = labelOffsets[item.id] || { x: 0, y: -40 * pixelScale };
                 usedOffset = offset;
                 labelPos = { x: targetSvg.x + offset.x, y: targetSvg.y + offset.y };
             }
        }

        const data = {
            id: item.id,
            power: item.powerDiff, // Reuse power field for Diff
            labelPos,
            color: item.color,
            isAnalysis: true,
            connectorStartPoints,
            offset: usedOffset,
            targetPos: toSvg(item.target), // Just for hit testing proximity if needed
        };
         processedMap.set(item.id, data);
    });

    // Return array: Standard Trajectories followed by Analysis Items (so Analysis renders on top)
    const renderList = [
        ...sortedByTime.map(t => processedMap.get(t.id)),
        ...analysisItems.map(a => processedMap.get(a.id))
    ].filter(Boolean);

    return renderList;

  }, [savedTrajectories, analysisItems, tankPos, zoom, currentMinX, currentMinY, currentWidth, currentHeight, labelOffsets, pixelScale]);

  // Calculate mid-point for "Create Diff" button if exactly 2 items selected
  const selectionMidPoint = useMemo(() => {
      if (selectedIds.length !== 2) return null;

      const t1 = savedTrajectories.find(t => t.id === selectedIds[0]);
      const t2 = savedTrajectories.find(t => t.id === selectedIds[1]);

      if (!t1 || !t2) return null;

      // Find SVG positions using savedData logic or recalculate
      // Simple recalculate for robustness
      const t1Svg = toSvg(t1.target);
      const t2Svg = toSvg(t2.target);

      // We place the button between the two targets
      return {
          x: (t1Svg.x + t2Svg.x) / 2,
          y: (t1Svg.y + t2Svg.y) / 2
      };

  }, [selectedIds, savedTrajectories, currentMinX, currentMinY, currentWidth, currentHeight]);


  // --- Interaction Handlers ---

  const handleTouchStart = (e: React.TouchEvent) => {
      if (e.touches.length === 2) {
          e.preventDefault();
          const t1 = e.touches[0];
          const t2 = e.touches[1];

          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          // Calculate centroid relative to container
          const rect = containerRef.current?.getBoundingClientRect();
          if (!rect) return;

          const cx = ((t1.clientX + t2.clientX) / 2) - rect.left;
          const cy = ((t1.clientY + t2.clientY) / 2) - rect.top;

          pinchRef.current = {
              active: true,
              initialDist: dist,
              initialZoom: zoom,
              initialPan: { ...pan },
              centerX: cx / rect.width,
              centerY: cy / rect.height
          };

          // Cancel any active drag/pan
          setDragState(prev => ({ ...prev, mode: 'IDLE' }));
      }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      if (e.touches.length === 2 && pinchRef.current.active) {
          e.preventDefault();
          e.stopPropagation();

          const t1 = e.touches[0];
          const t2 = e.touches[1];
          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          if (pinchRef.current.initialDist > 10 && dist > 10) {
              const ratio = dist / pinchRef.current.initialDist;
              // Larger distance (spread) -> Smaller zoom value (Zoom In/Close up)
              let newZoom = pinchRef.current.initialZoom / ratio;
              newZoom = Math.max(0.25, Math.min(2.5, newZoom));

              // Calculate Pan compensation to zoom towards center
              // Formula: pan_new = pan_old + M * (z_old - z_new)
              const deltaZ = pinchRef.current.initialZoom - newZoom;

              // M_x = MIN_X + CenterX * Height * AR
              const Mx = PHYSICS_CONSTANTS.MIN_X + (pinchRef.current.centerX * baseHeight * aspectRatio);

              // M_y = MIN_Y + (1 - CenterY) * Height
              // Note: CenterY is 0 at top, 1 at bottom. Physics Y is 0 at bottom (relative to MIN_Y).
              const My = PHYSICS_CONSTANTS.MIN_Y + ((1 - pinchRef.current.centerY) * baseHeight);

              const newPanX = pinchRef.current.initialPan.x + (Mx * deltaZ);
              const newPanY = pinchRef.current.initialPan.y + (My * deltaZ);

              setZoom(newZoom);
              setPan({ x: newPanX, y: newPanY });
          }
      }
  };

  const handleTouchEnd = () => {
      pinchRef.current.active = false;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    // If pinch is active, ignore single pointer events
    if (pinchRef.current.active) return;

    if (!svgRef.current) return;
    (e.target as Element).setPointerCapture(e.pointerId);

    const { x: clickX, y: clickY } = getSvgPoint(e.clientX, e.clientY);
    const screenPt = { x: e.clientX, y: e.clientY };

    // 1. Check Angle Knob / Area (Only if active)
    const tankSvg = toSvg(tankPos);

    // Visual radius of the knob control (roughly 80px on screen)
    const knobRadius = 80 * pixelScale;
    const distToTank = Math.hypot(clickX - tankSvg.x, clickY - tankSvg.y);

    if (showCurrentTrajectory && distToTank < knobRadius + (10 * pixelScale)) {
        setDragState({ mode: 'KNOB', startScreen: screenPt, startPan: pan });
        return;
    }

    // 2. Check Saved Labels (Top-most first for hitting, so iterate reverse of render order?)
    // savedData is Old -> New (Render Order). 
    // Hit test should be New -> Old (Top -> Bottom).
    for (let i = savedData.length - 1; i >= 0; i--) {
        const item = savedData[i];

        // Define Hitbox size based on type
        // Analysis: 56x24 (Half 28x12) -> Compact pill
        // Standard: 170x34 (Half 85x17)
        const halfW = item.isAnalysis ? 28 * pixelScale : 85 * pixelScale;
        const halfH = item.isAnalysis ? 12 * pixelScale : 17 * pixelScale;

        if (
            clickX >= item.labelPos.x - halfW && clickX <= item.labelPos.x + halfW &&
            clickY >= item.labelPos.y - halfH && clickY <= item.labelPos.y + halfH
        ) {
            setDragState({ 
                mode: 'LABEL', 
                startScreen: screenPt, 
                startPan: pan, 
                activeId: item.id,
                hasMoved: false
            });
            return;
        }
    }

    // 3. Check Active Target (Only if active)
    const targetSvg = toSvg(target);
    const targetHitRadius = 30 * pixelScale;
    if (showCurrentTrajectory && Math.hypot(clickX - targetSvg.x, clickY - targetSvg.y) < targetHitRadius) {
        setDragState({ mode: 'TARGET', startScreen: screenPt, startPan: pan });
        return;
    }

    // 4. Background -> Pan or Click
    setDragState({ 
        mode: 'AWAIT_PAN_OR_CLICK', 
        startScreen: screenPt, 
        startPan: pan, 
        hasMoved: false
    });
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // If pinch active, ignore
    if (pinchRef.current.active) return;

    if (!svgRef.current) return;
    const { x: pointerX, y: pointerY } = getSvgPoint(e.clientX, e.clientY);

    // Calculate screen deltas
    const dxScreen = e.clientX - dragState.startScreen.x;
    const dyScreen = e.clientY - dragState.startScreen.y;

    if (dragState.mode === 'KNOB') {
        const tankSvg = toSvg(tankPos);
        // Angle calc
        let newAngle = Math.atan2(-(pointerY - tankSvg.y), (pointerX - tankSvg.x)) * (180 / Math.PI);
        if (newAngle < 0) newAngle += 360;
        if (newAngle > 180) newAngle = 180; 

        // Snap to integer angle for cleaner UI
        setAngle(Math.round(newAngle));

    } else if (dragState.mode === 'LABEL' && dragState.activeId) {
        // Track movement to distinguish click from drag
        if (Math.hypot(dxScreen, dyScreen) > 5) {
             setDragState(prev => ({ ...prev, hasMoved: true }));

             const currentItem = savedData.find(sd => sd.id === dragState.activeId);
             if (currentItem && currentItem.offset) {
                  const basePosX = currentItem.labelPos.x - currentItem.offset.x;
                  const basePosY = currentItem.labelPos.y - currentItem.offset.y;

                  let destX = pointerX;
                  let destY = pointerY;

                  // Snap logic
                  if (snapToGrid) {
                      const physPoint = fromSvg(destX, destY);
                      const snappedPhysX = Math.round(physPoint.x);
                      const snappedPhysY = Math.round(physPoint.y);
                      const snappedSvg = toSvg({ x: snappedPhysX, y: snappedPhysY });
                      destX = snappedSvg.x;
                      destY = snappedSvg.y;
                  }

                  setLabelOffsets(prev => ({
                     ...prev,
                     [dragState.activeId!]: {
                         x: destX - basePosX,
                         y: destY - basePosY
                     }
                  }));
             }
        }

    } else if (dragState.mode === 'TARGET') {
        const physicsPoint = fromSvg(pointerX, pointerY);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });

    } else if (dragState.mode === 'PAN' || (dragState.mode === 'AWAIT_PAN_OR_CLICK' && Math.hypot(dxScreen, dyScreen) > 5)) {
        if (dragState.mode === 'AWAIT_PAN_OR_CLICK') {
            setDragState(prev => ({ ...prev, mode: 'PAN', hasMoved: true }));
        }

        const ctm = svgRef.current?.getScreenCTM();
        const scaleX = ctm ? ctm.a : 1; 

        const dxPhys = -dxScreen / (PIXELS_PER_UNIT * scaleX);
        const dyPhys = dyScreen / (PIXELS_PER_UNIT * scaleX);

        setPan({
            x: dragState.startPan.x + dxPhys,
            y: dragState.startPan.y + dyPhys
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    (e.target as Element).releasePointerCapture(e.pointerId);

    // Click Detection for Selection (If LABEL clicked but not moved)
    if (dragState.mode === 'LABEL' && !dragState.hasMoved && dragState.activeId) {
        if (onToggleSelection) {
             const item = savedData.find(sd => sd.id === dragState.activeId);
             // Only select SavedTrajectories (not Analysis items) for now, 
             // although logic permits analysis selection, we only need it for Diff generation
             if (item && !item.isAnalysis) {
                onToggleSelection(dragState.activeId);
             }
        }
    }

    if (showCurrentTrajectory && dragState.mode === 'AWAIT_PAN_OR_CLICK' && !dragState.hasMoved) {
        const { x, y } = getSvgPoint(e.clientX, e.clientY);
        const physicsPoint = fromSvg(x, y);
        let clampedX = Math.max(currentMinX, Math.min(physicsPoint.x, currentMaxX));
        let clampedY = Math.max(currentMinY, Math.min(physicsPoint.y, currentMaxY));
        if (snapToGrid) {
            clampedX = Math.round(clampedX);
            clampedY = Math.round(clampedY);
        }
        onSetTarget({ x: clampedX, y: clampedY });
    }

    setDragState({ mode: 'IDLE', startScreen: {x:0, y:0}, startPan: {x:0, y:0} });
  };

  const tankSvg = toSvg(tankPos);
  const targetSvg = toSvg(target);
  const impactSvg = impactPoint ? toSvg(impactPoint) : null;

  const dx = Math.abs(target.x - tankPos.x).toFixed(2);
  const dy = (target.y - tankPos.y).toFixed(2); 

  // Generate Grid Lines
  const gridLines = useMemo(() => {
    const lines = [];
    const startX = Math.floor(currentMinX);
    const endX = Math.ceil(currentMaxX);
    const startY = Math.floor(currentMinY);
    const endY = Math.ceil(currentMaxY);

    const baseColor = isNight ? "#1e293b" : "#e2e8f0";
    const highlightColor = isNight ? "#64748b" : "#94a3b8";
    const axisColor = isNight ? "#94a3b8" : "#475569"; 
    const minorColor = isNight ? "rgba(51, 65, 85, 0.4)" : "rgba(203, 213, 225, 0.6)";
    const textColor = isNight ? "#64748b" : "#94a3b8";

    const strokeW = Math.max(1 * pixelScale, 1); 
    const fontSz = 12 * pixelScale; 

    const useSparseGrid = zoom > 1.5;

    for (let i = startX; i <= endX; i++) {
        const p = toSvg({ x: i, y: 0 }); 
        const x = p.x;
        if (x < -50 * pixelScale || x > VIEWBOX_WIDTH + 50 * pixelScale) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 12 === 0; 

        if (useSparseGrid && !isAxis && !isMajor) continue;

        lines.push(
            <line 
                key={`v-${i}`} 
                x1={x} y1={0} x2={x} y2={VIEWBOX_HEIGHT} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? strokeW * 2 : strokeW} 
                strokeDasharray={isAxis || isMajor ? "" : `${4 * pixelScale},${2 * pixelScale}`}
            />
        );

        lines.push(
            <text 
                key={`tv-${i}`} 
                x={x + (4 * pixelScale)} 
                y={VIEWBOX_HEIGHT - (10 * pixelScale)} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={fontSz}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
                style={{ userSelect: 'none' }}
            >
                {i}
            </text>
        );
    }

    for (let i = startY; i <= endY; i++) {
        const p = toSvg({ x: 0, y: i }); 
        const y = p.y;
        if (y < -50 * pixelScale || y > VIEWBOX_HEIGHT + 50 * pixelScale) continue;
        const isAxis = i === 0;
        const isMajor = i !== 0 && i % 6 === 0;

        if (useSparseGrid && !isAxis && !isMajor) continue;

        lines.push(
            <line 
                key={`h-${i}`} 
                x1={0} y1={y} x2={VIEWBOX_WIDTH} y2={y} 
                stroke={isAxis ? axisColor : (isMajor ? highlightColor : minorColor)} 
                strokeWidth={isAxis ? strokeW * 2 : strokeW} 
                strokeDasharray={isAxis || isMajor ? "" : `${4 * pixelScale},${2 * pixelScale}`}
            />
        );

        lines.push(
            <text 
                key={`th-${i}`} 
                x={10 * pixelScale} 
                y={y - (4 * pixelScale)} 
                fill={isAxis ? axisColor : textColor} 
                fontSize={fontSz}
                fontWeight={isAxis || isMajor ? "bold" : "normal"}
                opacity={isAxis || isMajor ? 1 : 0.7}
                style={{ userSelect: 'none' }}
            >
                {i}
            </text>
        );
    }
    return lines;
  }, [currentMinX, currentMaxX, currentMinY, currentMaxY, VIEWBOX_WIDTH, VIEWBOX_HEIGHT, isNight, toSvg, pixelScale, zoom]);

  const knobRadius = 80 * pixelScale; 
  const knobRad = (angle * Math.PI) / 180;
  const knobHandleX = tankSvg.x + knobRadius * Math.cos(knobRad);
  const knobHandleY = tankSvg.y - knobRadius * Math.sin(knobRad);

  // Dynamic Styles for Wind Widget
  const windWidgetClasses = isNight 
    ? 'bg-slate-800/95 border-slate-600'
    : 'bg-white/95 border-slate-200';

  const windTextClasses = isNight ? 'text-slate-300' : 'text-slate-700';
  const windLabelClasses = isNight ? 'text-slate-500' : 'text-slate-500';
  const windBtnClasses = isNight 
    ? 'bg-slate-700 hover:bg-slate-600 text-white' 
    : 'bg-slate-200 hover:bg-slate-300 text-slate-800';

  const mainColor = isNight ? "#38bdf8" : "#0284c7";

  if (containerSize.width === 0) return <div ref={containerRef} className="w-full h-full" />;

  return (
    <div 
        ref={containerRef}
        className={`relative w-full h-full ${isNight ? 'bg-slate-900' : 'bg-slate-50'} transition-colors duration-500 rounded-xl overflow-hidden select-none`}
    >
      {/* Floating Create Diff Button */}
      {selectionMidPoint && onAnalyze && selectedIds.length === 2 && (
          <div 
             className="absolute z-30 transform -translate-x-1/2 -translate-y-1/2 animate-in zoom-in slide-in-from-bottom-2 fade-in"
             style={{ left: selectionMidPoint.x, top: selectionMidPoint.y }}
          >
              <button 
                onClick={(e) => {
                    e.stopPropagation();
                    onAnalyze(selectedIds[0], selectedIds[1]);
                }}
                className="flex items-center gap-2 px-3 py-1.5 bg-amber-400 text-amber-950 rounded-full shadow-lg font-bold text-xs hover:bg-amber-300 hover:scale-105 transition-all"
              >
                  <Calculator size={14} /> Link / Diff
              </button>
          </div>
      )}

      {/* Wind Control Widget */}
      <div 
        onMouseEnter={handleWindEnter}
        onMouseLeave={handleWindLeave}
        className={`absolute top-4 left-1/2 -translate-x-1/2 backdrop-blur rounded-xl border shadow-xl flex flex-col items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isWindExpanded ? 'w-60 p-2' : 'w-auto px-4 py-2 hover:w-60 hover:p-2 cursor-pointer'}`}
      >
        {isWindExpanded ? (
            <>
                <div className={`text-[10px] font-bold ${windTextClasses} mb-1 w-full flex justify-between items-center`}>
                    <span className={`text-[9px] ${windLabelClasses}`}>WEST</span>
                    <span className={`flex items-center gap-1 ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-400') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                        <Wind size={10} />
                        WIND: {Math.abs(wind).toFixed(1)}
                    </span>
                    <span className={`text-[9px] ${windLabelClasses}`}>EAST</span>
                </div>
                <div className="flex items-center w-full gap-2 opacity-100 transition-opacity duration-300 delay-100">
                    <button onClick={() => setWind(Number((wind - 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>-</button>
                    <div className="relative flex-1 h-5 flex items-center mx-1">
                        <div className="absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-400 z-0"></div>
                        <input type="range" min="-150" max="150" step="0.5" value={wind} onChange={(e) => setWind(Number(e.target.value))} className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-sky-500 z-10 relative ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}/>
                    </div>
                    <button onClick={() => setWind(Number((wind + 0.5).toFixed(1)))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>+</button>
                </div>
            </>
        ) : (
             <div className="flex items-center gap-2">
                <Wind size={14} className={wind === 0 ? 'text-slate-400' : wind > 0 ? 'text-emerald-500' : 'text-rose-500'} />
                <span className={`text-xs font-bold font-mono ${wind === 0 ? (isNight ? 'text-slate-400' : 'text-slate-500') : wind > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {wind.toFixed(1)}
                </span>
            </div>
        )}
      </div>

      {/* Zoom Control Widget */}
      <div 
        onMouseEnter={handleZoomEnter}
        onMouseLeave={handleZoomLeave}
        className={`absolute bottom-4 right-4 backdrop-blur rounded-xl border shadow-xl flex items-center z-20 transition-all duration-300 ease-in-out overflow-hidden ${windWidgetClasses} ${isZoomExpanded ? 'w-64 p-3 gap-3' : 'w-24 p-2 gap-2 cursor-pointer hover:w-64 hover:p-3 hover:gap-3'}`}
      >
        {isZoomExpanded ? (
            <>
                <button onClick={() => setZoom(Math.max(0.25, zoom - 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomOut size={12} />
                </button>
                <div className="flex-1 flex flex-col items-center">
                    <div className="flex justify-between w-full text-[10px] font-bold mb-1 opacity-80">
                         <span className={windLabelClasses}>VIEW RANGE</span>
                         <span className={isNight ? 'text-indigo-300' : 'text-indigo-600'}>{(zoom * 100).toFixed(0)}%</span>
                    </div>
                    <input
                        type="range"
                        min="0.25"
                        max="2.5"
                        step="0.1"
                        value={zoom}
                        onChange={(e) => setZoom(Number(e.target.value))}
                        className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                    />
                </div>
                <button onClick={() => setZoom(Math.min(2.5, zoom + 0.1))} className={`w-6 h-6 flex items-center justify-center rounded font-bold text-sm ${windBtnClasses}`}>
                    <ZoomIn size={12} />
                </button>
            </>
        ) : (
            <>
                <input
                    type="range"
                    min="0.25"
                    max="2.5"
                    step="0.1"
                    value={zoom}
                    readOnly
                    className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer accent-indigo-500 z-10 ${isNight ? 'bg-slate-700/50' : 'bg-slate-300/50'}`}
                />
            </>
        )}
      </div>

      <div className="absolute top-4 left-4 z-10 pointer-events-none">
        <h2 className={`text-xs font-bold ${isNight ? 'text-slate-500' : 'text-slate-400'} uppercase tracking-widest`}>Curve Analysis View</h2>
        <div className={`text-[10px] ${isNight ? 'text-slate-600' : 'text-slate-400'}`}>
            X: {currentMinX.toFixed(0)} to {currentMaxX.toFixed(0)} | Y: {currentMinY.toFixed(0)} to {currentMaxY.toFixed(0)}
        </div>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        className={`w-full h-full block touch-none ${
            dragState.mode === 'PAN' ? 'cursor-grabbing' : 
            dragState.mode === 'LABEL' ? 'cursor-move' : 
            dragState.mode === 'TARGET' ? 'cursor-crosshair' : 
            dragState.mode === 'KNOB' ? 'cursor-grab' : 'cursor-grab'
        }`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}

        // Touch Events for Pinch Zoom
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onTouchCancel={handleTouchEnd}

        preserveAspectRatio="none"
      >
        <defs>
            <marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
                <path d="M0,0 L0,6 L9,3 z" fill="#a855f7" />
            </marker>
            <radialGradient id="angleGradient" cx="0.5" cy="0.5" r="0.5">
                <stop offset="0%" stopColor={mainColor} stopOpacity="0.25" />
                <stop offset="100%" stopColor={mainColor} stopOpacity="0" />
            </radialGradient>
            <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
              <feDropShadow dx="0" dy={2 * pixelScale} stdDeviation={2 * pixelScale} floodColor="#000000" floodOpacity="0.3" />
            </filter>
            <filter id="simpleBlur" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation={2 * pixelScale} />
            </filter>
        </defs>

        {/* Grid Lines */}
        {gridLines}

        {/* Saved Trajectories and Labels */}
        {savedData.map((sd) => (
            <g key={sd.id}>
                {/* Only draw path if it's NOT an analysis item */}
                {!sd.isAnalysis && (
                    <path d={sd.d} fill="none" stroke={sd.color} strokeWidth={2 * pixelScale} strokeDasharray={`${5*pixelScale},${5*pixelScale}`} className="opacity-60" />
                )}

                {/* Selection Ring (Visual Highlight) */}
                {selectedIds.includes(sd.id) && (
                    <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                        <circle r={14 * pixelScale} fill="none" stroke="#38bdf8" strokeWidth={2 * pixelScale} className="animate-pulse" />
                        <circle r={18 * pixelScale} fill="none" stroke="#38bdf8" strokeWidth={1 * pixelScale} strokeDasharray={`${2*pixelScale},${2*pixelScale}`} opacity="0.5" />
                    </g>
                )}

                {/* Draw Analysis Connector Lines (Polylines/Manhattan) */}
                {sd.isAnalysis && sd.connectorStartPoints && (
                    <>
                        {sd.connectorStartPoints.map((pt: Point, idx: number) => {
                             // Analysis Label Left Edge is at labelPos.x - 28*scale
                             const endX = sd.labelPos.x - (28 * pixelScale); // Compact width 56 (half 28)
                             const endY = sd.labelPos.y;

                             // Start Point (Parent Right Edge)
                             const startX = pt.x;
                             const startY = pt.y;

                             // Fixed Length Tail Calculation
                             const fixedTail = 20 * pixelScale; 
                             const minLead = 10 * pixelScale;

                             const elbowX = Math.max(startX + minLead, endX - fixedTail);

                             return (
                                 <polyline 
                                    key={idx}
                                    points={`${startX},${startY} ${elbowX},${startY} ${elbowX},${endY} ${endX},${endY}`}
                                    fill="none"
                                    stroke={sd.color}
                                    strokeWidth={1.5 * pixelScale}
                                    strokeDasharray={`${3*pixelScale},${3*pixelScale}`}
                                    strokeLinejoin="round"
                                    opacity="0.6"
                                 />
                             );
                        })}
                    </>
                )}

                <g transform={`translate(${sd.targetPos.x}, ${sd.targetPos.y})`}>
                     <circle r={sd.isAnalysis ? 3 * pixelScale : 6 * pixelScale} fill="none" stroke={sd.color} strokeWidth={sd.isAnalysis ? 1 * pixelScale : 3 * pixelScale} />
                     <circle r={2 * pixelScale} fill={sd.color} />
                </g>

                {!sd.isAnalysis && (
                    <line 
                        x1={sd.labelPos.x} y1={sd.labelPos.y} 
                        x2={sd.targetPos.x} y2={sd.targetPos.y} 
                        stroke={sd.color} strokeWidth={1.5 * pixelScale} 
                        strokeDasharray={`${4*pixelScale},${2*pixelScale}`}
                        opacity="0.8"
                    />
                )}

                {/* Draggable Label */}
                <g 
                    transform={`translate(${sd.labelPos.x}, ${sd.labelPos.y}) scale(${pixelScale})`} 
                    className="cursor-move group"
                > 

                    {sd.isAnalysis ? (
                        <>
                             {/* Ultra Compact Analysis Label */}
                             <rect 
                                x="-28" y="-12" width="56" height="24" rx="12" 
                                fill={sd.color} 
                                stroke="white" strokeWidth="1"
                                filter="url(#shadow)"
                            />

                            {/* Main Value */}
                            <text x="0" y="4" textAnchor="middle" fill="white" fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none" style={{ textShadow: '0px 1px 2px rgba(0,0,0,0.2)' }}>
                                {sd.power > 0 ? '+' : ''}{sd.power.toFixed(1)}
                            </text>

                            {/* Close Button - Tiny circle on top right edge */}
                            {onDeleteAnalysis && (
                                <g 
                                    transform="translate(24, -10)" 
                                    className="cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity"
                                    onClick={(e) => {
                                        e.stopPropagation(); // Prevent drag start
                                        onDeleteAnalysis(sd.id);
                                    }}
                                    onPointerDown={(e) => e.stopPropagation()} // Prevent drag start on touch
                                >
                                    <circle cx="0" cy="0" r="6" fill="#ef4444" stroke="white" strokeWidth="1" />
                                    <path d="M-2 -2 L2 2 M2 -2 L-2 2" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
                                </g>
                            )}
                        </>
                    ) : (
                        <>
                            {/* Standard Label Background - Height 34 */}
                            <rect 
                                x="-85" y="-17" width="170" height="34" rx="6" 
                                fill={isNight ? "#1e293b" : "#ffffff"} 
                                stroke={sd.color} strokeWidth="2" 
                                filter="url(#shadow)"
                            />
                            {/* Custom Left Decorative Shape */}
                            <path 
                                d="M -35 -17 L -79 -17 Q -85 -17 -85 -11 L -85 11 Q -85 17 -79 17 L -35 17 Z" 
                                fill={sd.color} 
                            />
                            {/* Standard Label Layout */}
                            <text x="-60" y="-4" textAnchor="middle" fill="rgba(255,255,255,0.7)" fontSize="8" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                POWER
                            </text>
                            <text x="-60" y="10" textAnchor="middle" fill="white" fontSize="14" fontWeight="bold" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                {sd.power.toFixed(1)}
                            </text>

                            {/* Right Side: Data - Row 1: Angle & Wind */}
                            <text x="-25" y="-3" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>A:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.angle}°</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>W:</tspan> <tspan fontWeight="bold" fill={sd.wind === 0 ? (isNight ? "#94a3b8" : "#64748b") : (sd.wind > 0 ? "#10b981" : "#f43f5e")}>{sd.wind}</tspan>
                            </text>

                            {/* Right Side: Data - Row 2: Coordinates */}
                            <text x="-25" y="9" textAnchor="start" fontSize="10" fontFamily="'Varela Round', sans-serif" className="pointer-events-none select-none">
                                <tspan fill={isNight ? "#94a3b8" : "#64748b"}>X:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.dx}</tspan>
                                <tspan dx="8" fill={isNight ? "#94a3b8" : "#64748b"}>Y:</tspan> <tspan fontWeight="bold" fill={isNight ? "#e2e8f0" : "#334155"}>{sd.dy}</tspan>
                            </text>
                        </>
                    )}
                </g>
            </g>
        ))}

        {/* Active Elements */}
        {showCurrentTrajectory && (
            <>
                <circle 
                    cx={tankSvg.x} 
                    cy={tankSvg.y} 
                    r={knobRadius} 
                    fill="url(#angleGradient)" 
                    className="cursor-pointer hover:opacity-100 transition-opacity"
                    style={{ opacity: 0.8 }}
                />

                <path d={trajectoryPath} fill="none" stroke={mainColor} strokeWidth={4 * pixelScale} strokeDasharray={`${10*pixelScale},${10*pixelScale}`} className="opacity-80" />

                <g className="cursor-pointer" style={{ pointerEvents: 'none' }}> 
                    <path d={`M ${tankSvg.x - knobRadius} ${tankSvg.y} A ${knobRadius} ${knobRadius} 0 0 1 ${tankSvg.x + knobRadius} ${tankSvg.y}`} fill="none" stroke={isNight ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"} strokeWidth={2 * pixelScale} strokeDasharray={`${4*pixelScale},${4*pixelScale}`}/>

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                        stroke="#dc2626" strokeWidth={8 * pixelScale} strokeLinecap="round" opacity="0.3" filter="url(#simpleBlur)" />

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                        stroke="#dc2626" strokeWidth={3 * pixelScale} strokeLinecap="round" />

                    <line x1={tankSvg.x} y1={tankSvg.y} x2={knobHandleX} y2={knobHandleY} 
                         stroke="transparent" strokeWidth={20 * pixelScale} strokeLinecap="round" style={{ pointerEvents: 'auto' }} />
                </g>

                <g>
                    <circle 
                        cx={tankSvg.x} 
                        cy={tankSvg.y} 
                        r={18 * pixelScale} 
                        fill={isNight ? "#0f172a" : "#ffffff"} 
                        stroke={mainColor} 
                        strokeWidth={3 * pixelScale} 
                    />
                    <text 
                        x={tankSvg.x} 
                        y={tankSvg.y} 
                        dy={4 * pixelScale} 
                        textAnchor="middle" 
                        fill={mainColor} 
                        fontSize={11 * pixelScale} 
                        fontWeight="bold" 
                        fontFamily="'Varela Round', sans-serif"
                        className="pointer-events-none select-none"
                    >
                        {angle}°
                    </text>
                </g>

                <g transform={`translate(${targetSvg.x}, ${targetSvg.y})`}>
                    <circle r={5 * pixelScale} fill={mainColor} />
                    <circle r={12 * pixelScale} fill="none" stroke={mainColor} strokeWidth={1.5 * pixelScale} opacity="0.6" className="animate-pulse" />

                    {/* Tooltip scaled by pixelScale */}
                    <g transform={`translate(0, -${65 * pixelScale}) scale(${pixelScale})`}>
                        <rect x="-70" y="0" width="140" height="50" rx="6" fill={isNight ? "rgba(15, 23, 42, 0.9)" : "rgba(255, 255, 255, 0.9)"} stroke={isNight ? "#334155" : "#cbd5e1"} strokeWidth="1" />
                        <text x="0" y="20" textAnchor="middle" fill={isNight ? "#e2e8f0" : "#1e293b"} fontSize="16" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            ({dx}, {dy})
                        </text>
                        <text x="0" y="38" textAnchor="middle" fill={isNight ? "#10b981" : "#059669"} fontSize="12" fontWeight="bold" fontFamily="'Varela Round', sans-serif">
                            Wind: {wind}
                        </text>
                    </g>
                </g>

                {impactSvg && (
                    <circle cx={impactSvg.x} cy={impactSvg.y} r={8 * pixelScale} fill="#fbbf24" stroke="white" strokeWidth={1 * pixelScale} />
                )}
            </>
        )}
      </svg>
    </div>
  );
};

