```javascript
  const handleTouchStart = (e: React.TouchEvent) => {
    //  console.log(e.touches.length, "Touch start");
    if (!svgRef.current) return;

    if (e.touches.length === 2) {
      e.preventDefault();

      const [touch1, touch2] = [e.touches[0], e.touches[1]];
      const dist = Math.sqrt(
        Math.pow(touch2.pageX - touch1.pageX, 2) +
          Math.pow(touch2.pageY - touch1.pageY, 2)
      );

      pinchRef.current = {
        active: true,
        initialDist: dist,
        initialZoom: zoom,
        initialPan: pan,
        centroid: {
          x: (touch1.pageX + touch2.pageX) / 2,
          y: (touch1.pageY + touch2.pageY) / 2,
        },
      };

      // Cancel any existing drag/pan action
      cancelDragRef.current?.();
      return;
    }

    if (e.touches.length === 1) {
      // Single touch - start pan
      startPan(e.touches[0].clientX, e.touches[0].clientY);
    }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (!svgRef.current) return;
    e.preventDefault();

    if (pinchRef.current.active && e.touches.length === 2) {
      // Pinch to zoom logic
      const [touch1, touch2] = [e.touches[0], e.touches[1]];
      const dist = Math.sqrt(
        Math.pow(touch2.pageX - touch1.pageX, 2) +
          Math.pow(touch2.pageY - touch1.pageY, 2)
      );

      // Calculate Zoom level change
      const ratio = dist / pinchRef.current.initialDist;
      const newZoom = Math.max(
        0.25,
        Math.min(2.5, pinchRef.current.initialZoom * ratio)
      );

      const centroid = pinchRef.current.centroid;

      const deltaZ = (newZoom - zoom) / zoom;
      const baseWidth = currentWidth * 0.95;
      const baseHeight = currentHeight * 0.95;

      //  const Mx = pinchRef.current.centerX - 100 * deltaZ; //pinchRef.current.centerX * baseWidth;
      //  const My = pinchRef.current.centerY; //  * baseHeight;
      //  My is 0 at bottom
      const Mx =
        pinchRef.current.centerX + (pinchRef.current.centerX - 0) * deltaZ;
      const My =
        PHYSICS_CONSTANTS.MIN_Y +
        (1 - pinchRef.current.centerY) * baseHeight;

      const newPanX = pinchRef.current.initialPan.x + Mx * deltaZ;
      const newPanY = pinchRef.current.initialPan.y + My * deltaZ;

      setZoom(newZoom);
      setPan({ x: newPanX, y: newPanY });
    }
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    pinchRef.current.active = false;
  };
